    ["“圆脸蛋的爱人是我全部的快乐。”"] = "«Любовник с круглыми щеками — все мое счастье».",
    ["“圆脸蛋的爱人是我快乐的全部。”"] = "«Круглолицая возлюбленная — всё моё счастье».",
    ["“大作家”？上周我投给《廷根日报》的短篇又被退稿了，编辑先生的评语是“缺乏必要的戏剧冲突与商业前景”。简单来说，不够爽……真让人头疼……"] = "«Великий писатель»? Рассказ, который я отправил в «Тингенский ежедневный вестник» на прошлой неделе, был снова отклонен, комментарий редактора гласил: «отсутствует необходимый драматический конфликт и коммерческие перспективы». Проще говоря, недостаточно увлекательно... Это действительно головная боль...",
    ["“女神！”如果祂听见，一定会答应。"] = "«Богиня!» Если Она услышит, Она обязательно согласится.",
    ["“如若你想要我的一切……”"] = "«Коль пожелаешь забрать все, чем владею...»",
    ["“尽管你狭长的眼里透出的并非高兴。”"] = "«Хотя то, что видно в твоих узких глазах, не радость».",
    ["“干不了”？ 哈，小子，我花钱……花钱买你来，不是为了听这个的。"] = "«Не можешь»? Ха! Парень, я заплатил... я заплатил за тебя вовсе не для того, чтобы выслушивать подобное!",
    ["“幸运蛋”在……"] = "«Счастливое яйцо» находится в...",
    ["“开膛手杰斯”在你的一顿发力下，终于倒在了地上，不省人事。\n这时，一道较为耳熟的女声和男声从你背后响起……"] = "«Джейс Потрошитель» наконец упал на землю и потерял сознание под вашей силой. \nВ это время сзади тебя послышался относительно знакомый женский голос и мужской голос...",
    ["“愚弄”……时间？"] = "«Одурачить»... время?",
    ["“愚者”先生，我是为了神话织茧而来。"] = "Господин «Шут», я пришёл ради мифического плетения кокона.",
    ["“我十多年的努力现在只剩这个破旧的箱子，这‘投资’可真够划算的。要是我的客户们知道，肯定建议我转行。”"] = "«От моих многолетних усилий остался лишь этот ветхий ящик. Вот это «инвестиция», так выгодно. Узнай об этом мои клиенты, непременно посоветовали бы сменить профессию».",
    ["“我的爱情——”"] = "\"Моя любовь-\"",
    ["“我的脑袋快要爆炸了……仪式魔法、神秘学知识……”"] = "«Моя голова вот-вот взорвется... Ритуальная магия, оккультные знания...»",
    ["“我看见你有金子一般的心。”"] = "«Я вижу, у тебя золотое сердце».",
    ["“正义”小姐，您怎么在这儿？"] = "Мисс Джастис, почему вы здесь?",
    ["“焦糖炸弹”能清洁马桶，这符合你的设想吗？"] = "«Карамельная бомба» способна почистить унитаз, соответствует ли это вашим ожиданиям?",
    ["“爸爸这辈子没给你什么好东西，就这块表是新买的。”"] = "«Папа не дал тебе ничего хорошего в этой жизни, эти часы — единственное, что я купила новой».",
    ["“现在魔改一版更爽更刺激的《基督山伯爵》还不是轻轻松松，因蒂斯人民一定会欲罢不能的。”"] = "«Сейчас переделать на новый лад более забористую и захватывающую версию «Графа Монте-Кристо» — проще простого, народ Интиса точно оторваться не сможет».",
    ["“祂的声音，一直在我的耳边回响……”"] = "«Его голос эхом отдавался в моих ушах...»",
    ["“神话织茧”承载着某些古老存在的形态残影。用灰雾尘埃将它编织完整，你便能短暂借来神明的力量。"] = "«Форма мифического существа» несет в себе остаточные тени некоторых древних существований. Сплетя его из пыли серого тумана, вы можете ненадолго позаимствовать силу Бога.",
    ["“请注视我，注视这卑微的知识追逐者！”"] = "«Пожалуйста, взгляните на меня, взгляните на этого скромного искателя знаний!»",
    ["“赞美……愚者……”"] = "«Хвала... Шуту...»",
    ["“那会使我更欣喜。”"] = "«Это порадовало бы меня еще больше».",
    ["“钻头”出场动画"] = "Анимация входа «Дрель»",
    ["“闪电速递”的口号是——廷根市内，半小时达！"] = "Слоган «Молниеносной доставки» — доставка в пределах Тингена за полчаса!",
    ["……"] = false,
    ["…… "] = false,
    ["…………"] = false,
    ["……不对劲。"] = "...Что-то не так.",
    ["……也好，我很少遇到能说话的人，陪我走走吧。"] = "...Что ж, я редко встречаю тех, с кем можно поговорить. Прогуляйся со мной.",
    ["……也？"] = "...Хм?",
    ["……什么？"] = "...Что?",
    ["……从见到你的第一眼，我就再也挪不开我的视线了。"] = "...С того момента, как я увидел тебя, я уже не мог оторвать глаз.",
    ["……他离开了。"] = "...Он ушел.",
    ["……以后不看了。"] = "...Я больше не буду это смотреть.",
    ["……但您的<P_Yellow>脱发</>太严重了，我实在无能为力。"] = "...Но ваша потеря волос <P_Yellow></> слишком серьезна, я действительно ничего не могу с этим поделать.",
    ["……你一个人全都说完了啊！"] = "...Ты сам все сказал!",
    ["……你为什么觉得我会抓你？"] = "...Почему ты думаешь, что я поймаю тебя?",
    ["……你会驱鬼？"] = "...Ты умеешь изгонять призраков?",
    ["……你继续计划，我自己找。"] = "...Продолжай свой план, я сам поищу его.",
    ["……你这人怎么比老鼠还黑。"] = "...Как ты можешь быть чернее даже крысы?",
    ["……你这是扫地还是打架？发力轻一点，核心要稳……"] = "...Вы подметаете пол или начинаете драку? Используйте меньше силы, сохраняйте устойчивость корпуса...",
    ["……别逼我骂人。"] = "...Не заставляй меня ругаться.",
    ["……勉强的解释。我对美食的态度没有变，我会如实报道今天发现的疑问……但是，你不想证明自己对厨艺的态度没有改变吗……厨王之王？"] = "...Вынужденное объяснение. Мое отношение к изысканной еде не изменилось, я правдиво сообщу о вопросах, которые обнаружил сегодня... но разве вы не хотите доказать, что ваше отношение к кулинарному искусству не изменилось... Король поваров?",
    ["……原来海蒂扔戒指时我心口一痛，是戒指掉进了口袋…… "] = "...Поэтому, когда Хайди бросила кольцо, у меня сжалось сердце, потому что кольцо упало мне в карман...",
    ["……原来真正的笔友是——大叔？！"] = "…Значит, настоящий друг по переписке — дядя?!",
    ["……发生了什么？我怎么会在这里？"] = "...Что случилось? Почему я здесь?",
    ["……可以是可以。"] = "...Это может сработать.",
    ["……可是我爸爸就是不懂。"] = "...Но мой отец просто не понимает.",
    ["……哼，算你倒霉……不对，算你走运。是这样的，这小子非说里面的棺材闹鬼，说什么也不肯碰。"] = "...Хм, не повезло тебе... Нет, наоборот, повезло. Дело в том, что этот парень твердит, что в гробу внутри водятся призраки, и ни за что не хочет к нему прикасаться.",
    ["……唉。"] = "...Вздох.",
    ["……喵。"] = "...Мяу.",
    ["……嗯，没有我爱吃的。"] = "...М-да, ничего из того, что я люблю.",
    ["……女士，我完全理解您，别担心，我会制定完美计划！"] = "...Мисс, я прекрасно вас понимаю, не переживайте: я составлю идеальный план!",
    ["……好吧，我帮你找。"] = "...Хорошо, я помогу тебе его найти.",
    ["……好吧，至少收获了一块肉。"] = "...Ладно, по крайней мере, я получил кусок мяса.",
    ["……好的。"] = "...Хорошо.",
    ["……好，我愿意相信您。我们开始吧，让我想想……"] = "...Хорошо, я готов тебе доверять. Начнем, дайте мне подумать...",
    ["……对不起，我太冲动了。今天我所有的计划都被打破了，这一点都不符合我的计……"] = "...Прости, я был слишком импульсивен. Все мои планы на сегодня разрушены, это не вписывается в мой план...",
    ["……对了，我有个办法。"] = "...Правильно, у меня есть идея.",
    ["……尖尖的，有点像一根手指？等等，它开始扇我了！"] = "...Острый, вроде пальца? Подожди, меня начинает бить!",
    ["……很抱歉，这道菜并不在菜单上，我也很久没做过章鱼了。"] = "...Мне очень жаль, этого блюда нет в меню, да и осьминогов я тоже давно не готовила.",
    ["……很特殊的人。"] = "...Очень особенный человек.",
    ["……快跑。"] = "...Бегать.",
    ["……您最好不要知道。"] = "...Вам лучше этого не знать.",
    ["……感谢你的聆听，休息时间结束，我要继续演奏了。"] = "...Спасибо, что выслушали, перерыв закончился, мне нужно продолжать играть.",
    ["……我为我之前的无礼向您致歉。您是对的……我很佩服。"] = "...Прошу прощения за предыдущую грубость. Ты прав... Я восхищаюсь тобой.",
    ["……我也是。"] = "...Я тоже.",
    ["……我只是一个路过的充满正义感的普通市民。难道说这一切只是一场戏吗？！"] = "...Я всего лишь проходящий мимо обычный гражданин с чувством справедливости. Неужели все это всего лишь игра?!",
    ["……我吗？"] = "...Я?",
    ["……我才是这里的管家。"] = "...Я здесь дворецкий.",
    ["……我是正式送货员，不是学徒送货员。"] = "...Я постоянный курьер, а не курьер-стажёр.",
    ["……我来了。"] = "...Я пришёл.",
    ["……我知道要怎么越狱了，原来这么简单！"] = "...Теперь я знаю, как сбежать из тюрьмы, это на самом деле так просто!",
    ["……我知道，让我一个人呆着吧，{{先生|女士}}。"] = "...Я знаю. Оставьте меня в покое, {{господин|госпожа}}.",
    ["……我送您过去吧，再熟悉的路也可能遇到意外。"] = "...Я провожу тебя, даже на знакомых дорогах случаются аварии.",
    ["……所以，你用愚者福音，交换别人为你完成论文？"] = "...Значит, вы использовали Евангели Шута, чтобы обменять его на других, чтобы завершить свою диссертацию?",
    ["……所以？"] = "...Так?",
    ["……抱歉，我失态了。"] = "...Извини, я потерял самообладание.",
    ["……拜托，该尖叫的人是我吧。"] = "...Пожалуйста, это я должна кричать.",
    ["……既然被你发现了，我就对你坦白吧。"] = "...Раз уж ты это обнаружил, я буду с тобой честен.",
    ["……是啊，我发誓要守护罗塞尔大帝发明的下水道系统。"] = "...Да, я поклялся охранять канализационную систему, изобретенную императором Розеллой.",
    ["……正是隔壁的花店老板娘斯嘉丽！"] = "...Это Скарлетт, владелица цветочного магазина по соседству!",
    ["……比星空更崇高，比永恒更久远的黑夜女神。"] = "...Богиня Вечной Ночи, возвышеннее звёздного неба и древнее вечности.",
    ["……没错，我独自经历了这一切。"] = "...Правильно, я пережил все это один.",
    ["……猎龙城？"] = "...Город Охоты на Драконов?",
    ["……猎龙计划？真要猎龙？"] = "...План «Охота на дракона»? Мы что, правда собираемся охотиться на дракона?",
    ["……献上生命与心脏！大功告成！"] = "...Предложите свою жизнь и сердце! Миссия выполнена!",
    ["……真是精彩，就连我也开始期待后面的情节了，罗塞尔大帝真是讲故事的天才。"] = "...Действительно замечательно, даже я начинаю с нетерпением ждать дальнейшего сюжета, Император Розель действительно гений повествования.",
    ["……真的？你救了我，我……相信你。"] = "...Действительно? Ты спас меня, я... доверяю тебе.",
    ["……算了，利用就利用，回速递站。"] = "...Забудь об этом, позволь им использовать меня обратно на станцию ​​доставки.",
    ["……老子抗议！老子不写了！不！写！了！"] = "...Я протестую! Я больше не пишу! Нет! Письмо! Больше!",
    ["……茜安，你想不想要一间自己的餐厅，光明正大地做菜？"] = "...Сиань, ты хочешь, чтобы в твоем ресторане готовили открыто?",
    ["……虽然不能帮你实现，但我有个游戏，能让你成为大帝，体验万人敬仰的感觉！"] = "...Хотя я не могу сделать это за вас, у меня есть игра, которая позволит вам стать Императором и испытать чувство восхищения тысяч людей!",
    ["……行，不计划。"] = "...Ладно, никакого плана.",
    ["……说得太好了！从“征服”到“敬畏”，这个解读让诗的境界豁然开朗！"] = "...Хорошо сказано! От «Завоевания» до «Трепета» эта интерпретация внезапно проясняет содержание стихотворения!",
    ["……诶？"] = "...А?",
    ["……请问你有没有看见一枚戒指掉在这附近？"] = "...Извините, вы не видели, как здесь упало кольцо?",
    ["……走了？真的走了？"] = "...Ушёл? Правда ушёл?",
    ["……走吧。不过道歉之前，我得先计划好怎么说——"] = "...Пойдем. Но прежде чем извиниться, мне нужно спланировать, как это сказать…",
    ["……这是什么？"] = "...Что это?",
    ["……这样能行吗？"] = "...Это сработает?",
    ["……这里有一行中文批注，是罗塞尔写的：“我看过那么多<P_Yellow>爽文</>，早摸清套路了……”"] = "...Здесь есть строка китайских аннотаций, написанных Розеллой: «Я прочитала так много веб-романов <P_Yellow></>, я давно разобралась в этих клише...»",
    ["……遥远的故乡。或许正暗合了大帝晚年，对某个辉煌却无法回去的过去的深沉怀念。"] = "...Далекий родной город. Возможно, это совпадает с глубокой ностальгией Императора в последние годы его жизни по некоему славному прошлому, к которому он никогда не сможет вернуться.",
    ["……那么比赛正式开始！让我们喊出罗塞尔大帝的名言——"] = "...Итак, состязание официально начинается! Давайте же воскликнем знаменитую фразу императора Роселла: —",
    ["……那群知识走狗觊觎教会的封印物·尤德拉之树，一路追讨到这里。为了阻止他们，我不得不违反规定，让树触碰到了大地……"] = "...Эти прихвостни Знания позарились на церковный Запечатанный Артефакт — Древо Юдры — и преследовали меня до самых этих мест. Чтобы остановить их, мне пришлось нарушить запрет и позволить древу коснуться земли...",
    ["……那走吧，跟我去基地。你救了我，我理应帮你。还有，我叫兰格。"] = "...Тогда пойдем, пойдем со мной на базу. Ты спас меня, я должен помочь тебе. Кроме того, меня зовут Ланге.",
    ["……马桶变得好干净！"] = "...Унитаз стал таким чистым!",
    ["……龙？"] = "...Дракон?",
    ["……？"] = false,
    ["……？不是大哥你……？"] = "...? Не старший брат, ты...?",
    ["《基督山伯爵》不愧是爽文的鼻祖，抄得好爽。"] = "«Граф Монте-Кристо» по праву прародитель «лёгкого чтива», копировать из него — сплошное удовольствие.",
    ["《廷根市老实人报》说我们的安全条例像歌剧院的假胡子——中看不中用。"] = "Газета «Честный человек Тинген» утверждает, что наши правила безопасности подобны накладным бородам в оперном театре: на них приятно смотреть, но они бесполезны.",
    ["《美女与野兽》，署名俨然是罗塞尔·古斯塔夫，你丝毫不感到意外。"] = "«Красавица и чудовище» за подписью Розель Густав ничуть не удивляет.",
    ["【A级动画占位】随着玩家诵念秘文。所有的书籍漂浮了起来，形成了一个实质化的空间入口。"] = "【Заполнитель анимации уровня A】Когда игрок произносит секретный текст, все книги всплывают вверх, образуя материализованный вход в пространство.",
    ["【C级动画占位】玩家通过梦境占卜，看到了一些模糊的画面。"] = "[Заглушка анимации уровня C] Игрок через гадание во сне видит несколько размытых образов.",
    ["【占位】链条底端的黄水晶轻轻动了起来，做出顺时针旋转。"] = "【Заполнитель】Желтый кристалл на конце цепочки плавно движется, вращаясь по часовой стрелке.",
    ["【占位】闪回梦境占卜中温妮失踪前的一幕。"] = "[Плейсхолдер] Флешбэк во сне-гадании к моменту перед исчезновением Винни.",
    ["【演出占位】\n巨大的轰鸣和火光迸发而出，整座监狱灰飞烟灭！\n你自由了！"] = "【Сценарная заглушка】\nРаздался оглушительный грохот, полыхнуло яркое пламя — и вся тюрьма обратилась в пепел!\nВы свободны!",
    ["【灯光慢慢熄灭】可怜的唐泰斯被押送到了伊夫堡——一座立于孤岛上的、专门关押政治犯的重刑监狱。"] = "【Свет медленно гаснет】 Бедного Дантеса препроводили в Замок Иф — тюрьму строгого режима для политических заключенных, расположенную на изолированном острове.",
    ["【灯光慢慢熄灭】时隔十三年，唐泰斯终于完成了复仇，他感到解脱，也感到疲惫。"] = "[Свет медленно гаснет] Спустя тринадцать лет Дантес наконец завершил свою месть. Он почувствовал облегчение, но изнеможение.",
    ["一、二、三——用力！"] = "Раз, два, три — тужься!",
    ["一个人……不是这样。那次行动中，西迦负责引导并稳定人群，伦纳德确保环境安全，我们都很节制地用了一点必要的辅助——当然，那孩子不会察觉。"] = "В одиночку?.. Вовсе нет. В той операции Сика отвечала за направление и успокоение толпы, Леонард следил за безопасностью окружения, и все мы крайне сдержанно оказали необходимую поддержку — разумеется, ребенок ничего не заметил.",
    ["一个和水手有仇的<P_Yellow>贵族青年</>和他联手，作为担保人，把这封信交给了检察官，并重金贿赂了<P_Yellow>检察官</>，让他越过法庭，直接给无辜的水手定罪。"] = "Затаивший злобу на моряка <P_Yellow>молодой дворянин</> вступил с ним в сговор и, выступив поручителем, передал письмо прокурору, щедро подкупив <P_Yellow>прокурора</>, чтобы тот в обход суда самолично вынес приговор невинному моряку.",
    ["一个弱女子和一只大猩猩共处一室，怎么看都是我比较危险吧？"] = "Слабая женщина и гигантская горилла в одной комнате — как ни посмотри, ведь я в опасности, верно?",
    ["一个月后，迪西海湾一家“章鱼主厨餐厅”开业，生意不好不坏。据说，那里的老板是过去的海岸线餐厅主厨——厨王之王库克。"] = "Месяц спустя в заливе Диси открылся ресторан «Шеф-повар Осьминог», и дела там шли ни шатко ни валко. Поговаривали, что его владельцем стал бывший шеф-повар ресторана «Береговая линия» — король кулинаров Кук.",
    ["一个美丽的女人，和一个强壮的男人，多么般配！"] = "Красивая женщина и сильный мужчина – какая идеальная пара!",
    ["一个血月格外明亮的夜晚之后，许多有关“罗塞尔大帝”的旧物出现在廷根市，不断引发非凡事件。\n郡警察厅向值夜者小队转交了案件档案，你正在展开调查……"] = "После ночи, когда Кровавая луна сияла особенно ярко, в Тингене объявилось множество старинных реликвий, связанных с «Императором Розелем», что повлекло за собой череду потусторонних инцидентов.\nДепартамент полиции графства передал материалы дела отряду Ночных Ястребов, и теперь вы ведёте расследование...",
    ["一些较为传统的贵族不大喜欢这首曲子，认为它的编排有些轻浮。但更多人认为它听起来神秘且典雅，正适合在社交场合作为私人对话的伴奏。"] = "Некоторым консервативным аристократам эта мелодия не по душе — они считают её аранжировку легкомысленной. Однако большинству она кажется загадочной и изысканной, идеально подходящей для тихого личного разговора на светском приеме.",
    ["一位……充满魅力的夫人。就连早年的罗塞尔大帝，也为她神魂颠倒。"] = "Очаровательная леди. Даже император Розель в ранние годы был увлечен ею.",
    ["一位曾经是男人的魔女。"] = "Ведьма, которая раньше была мужчиной.",
    ["一切的一切，都要感谢慷慨的“愚者”先生。"] = "Все, все должно быть благодарно великодушному господину Шуту.",
    ["一切都好，亲爱的！你带沃尔特去那边买一份报纸来好吗？好了，快去吧！"] = "Все хорошо, дорогая! Не мог бы ты отвезти Уолтера туда купить газету? Хорошо, продолжай сейчас!",
    ["一半……十八个便士？这恐怕什么都做不了……"] = "Половина... восемнадцати пенсов? Этого ни на что не хватит...",
    ["一只10苏勒？！您不是在开玩笑吧？这镇上的老鼠——"] = "10 солей за одну?! Вы же не шутите? Крысы в этом городке...",
    ["一只叫猫的狗，有趣。"] = "Собака по кличке Кот, интересная.",
    ["一只被诅咒的猿人！"] = "Проклятый обезьяночеловек!",
    ["一周后，你正在广场闲逛……"] = "Через неделю вы гуляете по площади...",
    ["一夜过后……"] = "После одной ночи...",
    ["一天后……"] = "Через день...",
    ["一天，两天……<P_Heart>（小声）</> 他到底去哪里了，什么时候才能回来啊……"] = "День, два... <P_Heart>(Шёпотом)</> Куда же он подевался, когда же он вернётся?..",
    ["一定、一定！"] = "Определенно, определенно!",
    ["一定会向亡者显露纯净的笑容："] = "Обязательно покажу мертвым чистую улыбку:",
    ["一定是哪里有问题，我眼睛瞎了，记忆也瞎了吗？"] = "Должно быть, где-то что-то не так. Мои глаза слепы, но ослепла ли и моя память?",
    ["一定是她，是她在报复我们？"] = "Должно быть, это она. Она мстит нам?",
    ["一定能，我们回迪西海湾！"] = "Обязательно! Мы вернемся в залив Диси!",
    ["一封信笺？落款是卢娜。她人呢？"] = "Примечание? Подписано Луной. Где она?",
    ["一帮穷鬼，没钱别来沾边。"] = "Куча бедняг, не приближайтесь, если у вас нет денег.",
    ["一年前，我的味觉失灵了。医生说成因复杂，也很难根治，我因此失去了工作。从那时起，我就不敢再做菜了……"] = "Год назад я потерял чувство вкуса. Врач сказал, что причина сложна и ее трудно вылечить, поэтому я потерял работу. С тех пор я больше не решаюсь готовить...",
    ["一段时间后……"] = "Через некоторое время……",
    ["一直在你口袋里？"] = "Оно все время было у тебя в кармане?",
    ["一般般。而且你跑步速度很快，不是正常人能做到的。"] = "Это среднее. Кроме того, ты бегаешь очень быстро, что не под силу обычному человеку.",
    ["一起喝！"] = "Давайте выпьем вместе!",
    ["一起进去吧，这件事需要一个了结。"] = "Давай войдем вместе. Этому делу нужен конец.",
    ["三个月。每天一闭眼就是那天的事。"] = "Три месяца. Каждый раз, когда я закрываю глаза, я вспоминаю события того дня.",
    ["三位先生午安，今天请你们来，是想给你们分享一则故事——<P_Yellow>一个倒霉水手的故事</>。"] = "Добрый день, трое господ. Я приглашаю вас сюда сегодня, потому что хочу поделиться с вами историей - <P_Yellow>Историей незадачливого моряка</>.",
    ["三十年前河水在东，三十年后河水在西，不要小瞧贫穷的少年！"] = "Тридцать лет к востоку от реки, тридцать лет к западу от реки, не смотрите свысока на бедного юношу!",
    ["三天前……那个吻……我的心在那一刻已经被您征服。"] = "Три дня назад... этот поцелуй... мое сердце уже было завоевано тобой в тот момент.",
    ["三天前，老师偶然得到了罗塞尔大帝创作<P_Yellow>《伯爵归来》的亲笔手稿</>。"] = "Три дня назад учитель случайно заполучил <P_Yellow>оригинальную рукопись «Возвращения графа»</>, написанную императором Розелем.",
    ["三天后见，卢娜小姐。"] = "Увидимся через три дня, мисс Луна.",
    ["三天后，你收到了警察的消息，犯人入狱，钱财已到位。"] = "Спустя три дня от полиции пришло известие: преступники за решеткой, а украденные деньги возвращены.",
    ["三年前，我意外遭受到一件封印物力量的波及，才变成了这副模样……"] = "Три года назад я случайно попал под воздействие силы одного Запечатанного Артефакта, из-за чего стал таким...",
    ["三点，我们准时进去——放心，事成之后，好处少不了！"] = "В три часа мы входим вовремя. Не волнуйтесь, после дела выгода будет немалая!",
    ["三百回合……"] = "Триста патронов...",
    ["上、课！典籍真的很难编！船长看完我的初稿后就把我送到这里要我深造学业！"] = "Внимание-посещайте занятия! Классику действительно сложно собрать! После того, как капитан прочитал мой первый черновик, он отправил меня сюда продолжать обучение!",
    ["上次有人质疑她用魔法，她气得三天没接那人的单。"] = "В прошлый раз, когда кто-то спросил, использует ли она магию, она так разозлилась, что не выполняла приказы этого человека в течение трех дней.",
    ["上次败在那颗浅褐斑纹蛋上，这次我连蛋壳上的呼吸孔分布都记熟了！"] = "В прошлый раз я проиграл этому светло-коричневому пятнистому яйцу, на этот раз я даже запомнил расположение дыхательных отверстий на скорлупе!",
    ["下一步？"] = "Что дальше?",
    ["下午三点，检查尸体……你们这是在做什么？"] = "Три часа дня, осмотр трупа... Что вы тут делаете?",
    ["下午好！“正义”小姐、“魔术师”小姐、“星星”先生，你们怎么都在？"] = "Добрый день! Мисс «Справедливость», мисс «Фокусник», мистер «Звезда», почему вы все здесь?",
    ["下午好，{{PlayerName}}，我预感到了你会出现。"] = "Добрый день, {{PlayerName}}, предчувствовал, что ты появишься.",
    ["下次有急件，我是不是也可以找你？"] = "Если в следующий раз будет срочная доставка, могу ли я приехать к вам?",
    ["下水道治理就是其中一项举措，这一壮举后来推广至全世界，挽救了无数即将破碎的家庭！"] = "Обустройство канализации стало одной из таких мер; впоследствии этот великий почин перенял весь мир, что спасло от гибели бесчисленное множество семей!",
    ["下水道？"] = "Канализация?",
    ["不——！"] = "Нет-!",
    ["不……"] = "Нет...",
    ["不……不……"] = "Нет... нет...",
    ["不……我不能再沉沦下去了……"] = "Нет... Я не могу тонуть дальше...",
    ["不……这应该是完全没有将肉浸泡过冰水的结果，他应该不会犯这样的错……"] = "Нет... это должно быть результатом того, что мясо вообще не замачивали в ледяной воде, он не должен допускать такой ошибки...",
    ["不、不可能！廷根怎么可能有比我们更时尚的人！"] = "Нет, невозможно! Как может быть в Тингене кто-нибудь более модный, чем мы!",
    ["不一样吗？你难道没送过人，或者更奇怪的东西？"] = "Это другое? Разве вы не доставляли людей или даже более странные вещи?",
    ["不不不，这种东西，不该继续售卖，就该倒进马桶！"] = "Нет-нет-нет, такие вещи больше нельзя продавать, их надо в унитаз выливать!",
    ["不久前我在这遇到您，您也说自己要上厕所。"] = "Я встретил тебя здесь недавно, и ты тоже сказал, что тебе нужно в туалет.",
    ["不了。我怕我一张嘴，你们就跑光了。"] = "Нет. Я боюсь, что как только я открою рот, вы двое убежите.",
    ["不了不了！我改！我重新做人！"] = "Нет, нет! Я изменюсь! Я переверну новый лист!",
    ["不会啊，我绕了几十年了，戴维曾说它像一颗心脏。"] = "Этого не может быть. Я шел вокруг этого десятилетиями. Дэвид однажды сказал, что это похоже на сердце.",
    ["不会有人死，我们快走！"] = "Никто не умрёт, идём скорее!",
    ["不会熄灭！"] = "Оно не погаснет!",
    ["不会，那不是他对待厨艺的态度……我必须对我写的文章负责。我们点一道芥末章鱼，这道菜我印象深刻，如果有问题，我能立刻尝出来。"] = "Нет, это не его отношение к кулинарии... Я должен нести ответственность за написанную статью. Закажем горчичного осьминога, у меня глубокое впечатление от этого блюда, если возникнут проблемы, могу сразу попробовать.",
    ["不信的话，你可以进来看看……"] = "Если не верите, можете зайти и посмотреть...",
    ["不信？告诉你，我可是<P_Yellow>威廉·海默</>——这门课的老师，连卷子都是我出的！"] = "Не верите мне? Позвольте мне сказать вам, я — <P_Yellow> Уильям Хамер </> — преподаватель этого курса, даже экзаменационные работы были написаны мной!",
    ["不可能！没计划就找不到戒指，找不到戒指我的人生就完了——"] = "Невозможный! Без плана я не смогу найти кольцо, а если я не смогу найти кольцо, моя жизнь окончена…",
    ["不可能，我分明是严格按照戏剧规律来创作的，优雅、高贵而理性……这怎么会有问题？"] = "Невозможно! Я творил в строгом соответствии с законами драматургии — изящно, благородно и разумно... Разве здесь может быть ошибка?",
    ["不堪一击，哼哼。"] = "Уязвимый, хм-хм.",
    ["不太对劲。"] = "Что-то не так.",
    ["不好……我计划求婚，海蒂冷傲拒绝。我计划找戒指，戒指在口袋。我扔了你们的结婚戒指， 你们骂都不骂我。"] = "Не ладно... Я планировал сделать предложение, но Хайди холодно отвергла меня. Я планировал найти кольцо, а оно оказалось у меня в кармане. Я выбросила твое обручальное кольцо, а ты меня даже не отругала.",
    ["不好了陛下，因为你的变脸，导致臣民认不出你，接下来解决赶来的士兵，先逃走吧！"] = "О нет, Ваше Величество! Из-за изменения вашего лица ваши объекты не узнают вас. Разберитесь с приближающимися солдатами и сбегите первым!",
    ["不好意思{{先生|女士}}，是我带你进入这里，让你吃到了不干净的食物。"] = "Прости, {{Mr.|Ms.}}, это я привел тебя сюда и заставил есть нечистую пищу.",
    ["不好意思，我不知道你们的关系。你怎么样？"] = "Извините, я не знала о ваших отношениях. Ты в порядке?",
    ["不好，是恶灵……我控制不住了……"] = "Плохо, это злой дух... Я не могу его сдержать...",
    ["不好，有东西想从门外进来……"] = "О нет, что-то пытается проникнуть из-за двери...",
    ["不如先问问，是计划有用，还是找到了有用？"] = "Почему бы сначала не спросить: полезен ли план или полезно найти его?",
    ["不客气。你刚才说的后台，不会是我吧？"] = "Пожалуйста. «Поддержка», о которой вы только что упомянули, это был бы не я, не так ли?",
    ["不对吗？"] = "Разве не так?",
    ["不对，再想想……"] = "Нет, дай мне еще раз подумать...",
    ["不对，根据谢尔敏先生的配方，可乐果只能带来提神效果。"] = "Это неправильно; По рецепту господина Шермина орехи колы оказывают лишь освежающий эффект.",
    ["不属于这个时代的愚者啊"] = "Шут, не принадлежащий этой эпохе",
    ["不必在意，我只是一名观众。"] = "Не обращайте на меня внимания, я всего лишь зритель.",
    ["不想让人看，还贴在这么显眼的地方？"] = "Если вы не хотите, чтобы люди видели, зачем вставлять их на такое видное место?",
    ["不愧是……龙……"] = "Как и ожидалось от... дракона...",
    ["不敢了不敢了！ "] = "Я не посмею, не посмею!",
    ["不是很好玩呢，较为失败的一个游戏。"] = "Это не очень весело. Довольно неудачная игра.",
    ["不是！是、是我有个朋友买过。"] = "Нет! Просто... просто один мой друг покупал такое!",
    ["不是，就这？"] = "Нет, это все?",
    ["不止，他情人也跟来了，还带着半岁的孩子……他情人叫什么来着……凯瑟琳？"] = "Да не только: за ним и любовница увязалась, да еще с полугодовалым ребенком на руках... Как бишь ее звали... Кэтрин?",
    ["不用不用，我就是想起班森缺一条颜色活泼的领带。这样他去赴宴时，或许能显得不那么沉闷。 "] = "Нет-нет, я просто подумала, что Бенсону не помешал бы галстук поярче. Чтобы на банкете он не выглядел таким хмурым.",
    ["不用害怕，他本来是个正常人，却意外遭受某件封印物力量的波及，变成了可怕的猩猩。"] = "Не бойся, изначально он был обычным человеком, но случайно попал под воздействие силы одного из Запечатанных Артефактов и превратился в ужасающую гориллу.",
    ["不用担心，只有你能看到我。在路人眼里，你只是个在水池边自言自语的傻瓜。"] = "Не волнуйся, меня видишь только ты. В глазах прохожих ты просто дурак, разговаривающий сам с собой у фонтана.",
    ["不用谦虚，“梦境行者”的晋升仪式是这样的——"] = "Не скромничай, ритуал продвижения «Сноходца» выглядит так:",
    ["不用，我认得路。"] = "Не надо, я знаю дорогу.",
    ["不瞒你们说，我全身的毛都长得飞快，而且又长又硬，如果不是每天都修剪好几遍，别人都以为我是只刺猬呢。"] = "Не буду скрывать от вас, все волосы на моем теле растут быстро, длинные и жесткие. Если бы я не стриг его несколько раз в день, другие подумали бы, что я ёжик.",
    ["不瞒你说，我就像这道菜，虽然用料丰富，表面看起来也很独特，但味道却一言难尽……"] = "Честно говоря, мне нравится это блюдо. Хотя он содержит богатые ингредиенты и выглядит уникально на первый взгляд, вкус... трудно описать...",
    ["不瞒您说……连老疤脸都嘀咕，说廷根下水道里的老鼠见了您都得立正行礼呐！"] = "Честно говоря... даже Старый Лицо со Шрамом бормочет, что крысам в канализации Тингена приходится стоять по стойке смирно и отдавать честь, когда они видят тебя!",
    ["不知好歹的小混蛋……别在这儿……演可怜！当心我的棍子——"] = "Неблагодарный паршивец... не... веди себя так жалко! Берегись моей палки —",
    ["不知道猎龙帮又在搞什么鬼……还是去看看吧。"] = "Понятия не имею, что опять замышляет банда Драконоборцев... Но лучше сходить проверить.",
    ["不知道这样的故事写出来，那些要名誉的工厂还想不想和你惹上关系……"] = "Интересно, захотят ли те фабрики, которым нужна репутация, продолжать сотрудничать с вами после написания такой истории...",
    ["不知道那老头是怎么回事，死活不承认他这个私生子，还突然发善心，把家产都捐给了济贫院……"] = "Я не знаю, что случилось с этим стариком. Он отказался признать его своим внебрачным сыном, а потом вдруг передумал и пожертвовал все свое имущество в богадельню...",
    ["不确定……不过我有预感，后面还会再见到它的。"] = "Не уверен... но у меня есть предчувствие, что позже мы ещё увидимся с ним.",
    ["不管发生了什么，都不是对孩子实施暴力的理由。"] = "Что бы ни произошло, это не повод применять насилие к ребенку.",
    ["不管多少钱也赎不回我在暗无天日的大牢里咽下的冤屈和折磨，承不起我用自己的血水浇铸、骨头打磨出的复仇之剑。"] = "Никакие деньги не смогут искупить несправедливость и мучения, которые я проглотил в темной тюрьме, и они не смогут выдержать меч мести, который я бросил собственной кровью и отполировал своими костями.",
    ["不管怎么样，我们有必要去一趟梅森工厂。"] = "В любом случае, нам нужно съездить на фабрику Мейсона.",
    ["不管要什么属性，多少点数，我超级属性加点精灵都能一口气全满足，绝对把你打造成最纯正的数值怪！"] = "Независимо от того, какой атрибут или сколько очков вы хотите, я, Эльф Супер-Атрибутов, могу удовлетворить их все сразу, превращая вас в чистейшего числового монстра!",
    ["不行，作为一个有职业操守的剧作家，我绝不会离开自己作品的首演场！"] = "Нет, как профессиональный драматург, я никогда не уйду с премьеры собственного произведения!",
    ["不行，必须遵守我的方式。"] = "Нет, все должно быть по-моему.",
    ["不要……求求你们，不要抢我的票……"] = "Не... пожалуйста, не берите мой билет...",
    ["不要吵了，最近天气干燥，容易上火，可能是肝火太旺了。"] = "Перестаньте спорить. Погода в последнее время сухая, легко воспалиться; возможно, огонь вашей печени слишком силен.",
    ["不要啊！"] = "Нет!",
    ["不要紧，我还能动……<P_Heart>（抬头）</>是你！"] = "Все в порядке, я еще могу двигаться... <P_Heart> (смотрит вверх) </> Это ты!",
    ["不要质疑神使的决定！"] = "Не подвергайте сомнению решение божественного посланника!",
    ["不讨好任何人，帝王的霸气在您的身上显现出来！"] = "Не потворствуйте никому — в вас проявляется господство императора!",
    ["不记得了……我找了三个月了。当时应该就放在桌上……"] = "Не помню... Три месяца ищу. В это время оно должно было лежать на столе...",
    ["不论是男是女，我对你的感觉绝不会变。"] = "Мужчина или женщина — мои чувства к тебе никогда не изменятся.",
    ["不论有没有路牌，有没有红色巨石，有没有优美的雕塑……"] = "Неважно, есть ли указатели, красные валуны или прекрасные статуи...",
    ["不说是吧？我看看，这里离警察局好像不远……"] = "Не разговариваем, да? Посмотрим, кажется, здесь недалеко от полицейского участка...",
    ["不轻信，不花钱，谨防诈骗！"] = "Не будьте доверчивы, не тратьте деньги, остерегайтесь мошенничества!",
    ["不过也很正常，它毕竟算是两百年前的历史文物了。"] = "Но это нормально; в конце концов, это исторический артефакт двухсотлетней давности.",
    ["不过他的精神还没有完全恢复，最近还得休息一段时间。"] = "Однако его разум еще не полностью восстановился, и в последнее время ему придется немного отдохнуть.",
    ["不过你既然已经找到了入口，不妨去那个世界看看，这对你的恢复也有好处。"] = "Однако, поскольку вы уже нашли вход, вы можете взглянуть на этот мир. Это также будет полезно для вашего выздоровления.",
    ["不过你费了这么多功夫抓我，应该不是为了和我谈论教学方式吧。"] = "Но ты приложил столько усилий, чтобы поймать меня, что это должно быть не просто обсуждение со мной методов обучения.",
    ["不过好消息是：右边这瓶药，会治愈您的皮肤。"] = "Но есть и хорошая новость: флакон справа исцелит вашу кожу.",
    ["不过既然你有勇气来这里，说明你有资格成为我们的朋友。"] = "Но раз у тебя хватило смелости прийти сюда, значит, ты достоин быть нашим другом.",
    ["不过还得谢谢你，让我知道带着狒狒“开门”的感觉，老师可不会讲这些……等等。"] = "Но я все равно должен поблагодарить вас за то, что вы рассказали мне, каково это «открыть дверь» перед павианом; учитель не будет учить этим вещам... подождите.",
    ["不过这些都不重要了，等我们成功，钱财和地位都会有。"] = "Но все это уже не имеет значения. Когда мы добьемся успеха, у нас будут и деньги, и статус.",
    ["不过，至少我能面对安迪了，我准备去他的墓前，去……喝一杯。"] = "Однако, по крайней мере, теперь я могу встретиться с Энди. Я собираюсь на его могилу, чтобы... выпить.",
    ["不过，请一定替我谢谢凯尔文。他选的东西很实用，对于一个喜欢写点东西的人来说，没有什么比能随时记录下想法的纸笔更珍贵的礼物了。"] = "Однако, пожалуйста, обязательно поблагодарите Кельвина от меня. Предметы, которые он выбрал, очень практичны; для человека, который любит писать, нет более ценного подарка, чем бумага и ручки, позволяющие в любое время записывать мысли.",
    ["不过，鲁莽泄恨的人，往往只会自己喝下苦酒。"] = "Однако те, кто безрассудно выплескивает свою ненависть, часто в конечном итоге сами пьют горькое вино.",
    ["不错的回答，漂亮的眼神。"] = "Хороший ответ, красивые глаза.",
    ["不限数量，越多越好。"] = "Количество не ограничено, чем больше, тем лучше.",
    ["不需要，孩子。在教堂，你不需要做那些危险的工作。直到杰姆好起来之前，你们都可以安心地呆在这里。"] = "Не надо, малыш. В церкви вам не придется выполнять эту опасную работу. Вы все можете оставаться здесь с миром, пока Джем не поправится.",
    ["不！——如果失去了我的秀发，变成一个秃头，我活着还有什么意义！"] = "Нет! — Если я потеряю свои прекрасные волосы и облысею, какой смысл останется в моей жизни!",
    ["不！不是的！那个吻和他们没有任何关系！"] = "Нет! Это не так! Этот поцелуй не имел к ним никакого отношения!",
    ["不，{{先生|女士}}，我们就是从济贫院被他买走的……我不要回到那样的地方，他们只想着把孩子卖掉，根本不会关心卖给什么样的人！"] = "Нет, {{ Mr. | Ms. } }, он выкупил нас из богадельни... Я не хочу возвращаться в такое место. Они думают только о продаже детей; им вообще плевать, какому человеку их продают!",
    ["不，亲爱的，我是真心爱你的！"] = "Нет, дорогая, я искренне люблю тебя!",
    ["不，你不能沉睡。"] = "Нет, тебе нельзя засыпать.",
    ["不，你的样子很美，艾拉女士。"] = "Нет, вы прекрасно выглядите, мисс Элла.",
    ["不，先生！不要！"] = "Нет, сэр! Не!",
    ["不，多半会被评估定级，成为封印物。幸好它的负面影响并不严重，经过一些处理，也可以完全避免。"] = "Нет, скорее всего его оценят и присвоят уровень, сделав Запечатанным Артефактом. К счастью, его негативное воздействие не так серьёзно, и после некоторой обработки его можно полностью избежать.",
    ["不，我……养了一只很像章鱼的宠物，它就像我的家人一样，所以我不太想烹饪和它很像同类的章鱼，所有用到章鱼的菜品，都从菜单上撤下了。"] = "Нет, я... держу питомца, очень похожего на осьминога. Он для меня как член семьи, поэтому мне не хочется готовить его сородичей. Все блюда из осьминога я убрал из меню.",
    ["不，我不能想起来，我得忘记。下个月，再从山下出发……"] = "Нет, мне нельзя вспоминать... Я должен забыть. В следующем месяце я снова отправлюсь в путь от подножия горы...",
    ["不，我是说那个脏兮兮的搬运工长得和比尔一模一样！"] = "Нет, я имею в виду, что этот грязный носильщик выглядит точно так же, как Билл!",
    ["不，我根本不知道她是谁。"] = "Нет, я понятия не имею, кто она.",
    ["不，污染还没有彻底消失——画的深处还藏着什么东西！"] = "Нет, порча ещё не исчезла полностью — в глубине картины скрывается что-то ещё!",
    ["不，给我一点时间。我需要……冷静一下。一杯酒就好，我保证。"] = "Нет, дай мне минутку. Мне нужно... успокоиться. Просто бокал вина, обещаю.",
    ["不，警局只是戒严，而且下了死命令，只能站岗不能动手，议院治安队的人自己在处理。"] = "Нет, в отделении полиции объявлено военное положение, и они отдали строгий приказ: стоять только на страже, не вмешиваться. Служба безопасности парламента разбирается с этим самостоятельно.",
    ["不，这应该是画中的幻象……我、我被困在了画里？"] = "Нет, это, должно быть, иллюзия внутри картины... Я, я в ловушке картины?",
    ["世界上没有两个完全相同的鸡蛋！"] = "В мире не бывает двух одинаковых яиц!",
    ["丝瓜？不要不要，丝瓜做不好吃的。"] = "Люфы? Нет-нет, приготовленная люфа невкусна.",
    ["两个学生越走越远，消失在街道的尽头……"] = "Двое студентов шли все дальше и дальше и исчезли в конце улицы...",
    ["两位先生，请不要再往前了。"] = "Господа, прошу вас, дальше не ходите.",
    ["两位客人有什么需要吗？可以回到位置上叫我们服务。"] = "Вам что-нибудь нужно, господа? Вы можете вернуться на свои места и позвать нас.",
    ["两位是商人吧？愿不愿意，和我做个生意？"] = "Вы ведь торговцы? Не желаете провернуть со мной одно дельце?",
    ["两年前，我邀请贝儿小姐共度美好的一夜，却狠狠挨了她一巴掌。"] = "Два года назад я пригласил мисс Белль провести вместе чудесную ночь, но меня за это сильно отшлепали.",
    ["丹总是爱说别人闲话，好像最近越来越爱说了，但只是偷偷嘀咕，倒也没有大声宣扬……"] = "Дэн всегда любит посплетничать о других, кажется, в последнее время он это делает чаще, но только бормочет тайно, а не кричит вслух...",
    ["为了回味……您唇上的温度。"] = "Послевкусие... тепло твоих губ.",
    ["为了家人！为了明天！"] = "Для моей семьи! На завтра!",
    ["为了庆祝？"] = "Чтобы отпраздновать?",
    ["为什么不按照约定付工钱？你明知道那是给杰姆救命用的。"] = "Почему вы не выплатили зарплату, как было оговорено? Вы прекрасно знаете, что деньги предназначались для лечения Джема.",
    ["为什么不能？它们的裂纹分岔角度不同，黑点排列，钝端的曲率也有细微差别……这些不都清清楚楚地在那儿吗？ 您不是也看到了吗？"] = "Почему нет? Их рисунок трещин имеет разные углы, расположение черных пятен, кривизна тупого конца тоже имеет тонкие различия... разве это все не ясно? Ты тоже их не видел?",
    ["为什么安慰我……你们的戒指都被我扔了！"] = "Зачем ты меня утешаешь... Я выбросила твои кольца!",
    ["为什么是两份？"] = "Почему две порции?",
    ["为什么是八十和四十……我试试。"] = "Почему сорок и восемьдесят... Попробую.",
    ["为什么要在这里编写，不留在教堂之类的地方？"] = "Зачем писать это здесь, а не оставаться в таком месте, как церковь?",
    ["为什么要对我这么温柔？您是罗塞尔大帝，整个王国最尊贵的人。而我，只是一个一无所有的寡妇……不敢想象人们会怎么编排您。"] = "Почему ты так нежен со мной? Вы — император Розель, самый благородный человек во всем королевстве. А я всего лишь вдова ни с чем... Я не смею представить, как люди будут сплетничать о тебе.",
    ["为什么非得有帽子？"] = "Почему обязательно должна быть шляпа?",
    ["为什么？\n怎么可能？\n这意味着什么？"] = "Почему? \nКак это возможно? \nЧто это значит?",
    ["为什么？仅仅是很久没做过章鱼了吗？还是你对厨艺的态度发生了改变？"] = "Почему? Это только потому, что вы давно не готовили осьминогов? Или ваше отношение к кулинарии изменилось?",
    ["为什么？哦，那当然是为了更好地训练需要我帮助的俱乐部成员了！"] = "Почему? О, разумеется, чтобы лучше тренировать членов клуба, которым нужна моя помощь!",
    ["为猎龙献上生命与心脏！"] = "Отдайте свою жизнь и сердце Охотнику на драконов!",
    ["主宰大海的皇帝"] = "Император, повелевающий морями",
    ["主教他们怎么样了？我们有赢吗？封印物还在吗？"] = "Как там епископ и остальные? Мы победили? Запечатанный Артефакт цел?",
    ["丽贝卡？！你怎么来了？"] = "Ребекка?! Почему ты здесь?",
    ["久经风霜的石像、冥冥之中你有一种对其<P_Yellow>行礼</>的冲动"] = "Потрепанная временем каменная статуя. В глубине души у вас возникает непреодолимое желание <P_Yellow>поклониться</> ей.",
    ["之前和弗莱队长调查廷根中央广场时，曾进入罗塞尔相关的知识空间。难道这里也存在一个知识空间？"] = "Когда я исследовал Центральную площадь Тингена вместе с капитаном Фраем, я вошел в пространство знаний, связанное с Розеллой. Может ли здесь быть пространство знаний?",
    ["之前塔罗学派工匠打造的神奇物品“灵巧之指”能够窃取对方大脑中的念头，可以试试。"] = "Ранее мастера Клуба Таро создали чудесный предмет «Ловкие пальцы», способный похищать мысли из чужого разума. Можно попробовать.",
    ["之前塔罗学派工匠打造的神奇物品“灵巧之指”能够窃取对方大脑中的念头，可以试试偷走他奋斗的想法。"] = "Ранее мастера Клуба Таро создали чудесный предмет «Ловкие пальцы», способный похищать мысли из чужого разума. Можно попробовать выкрасть у него мысль о упорном труде.",
    ["之前安保公司的伦纳德先生帮助过我。听说他还是一位“贵族诗人”，我抄写了诗歌……能帮忙转交吗？ "] = "Раньше мне помогал господин Леонард из охранной компании. Я слышал, что он тоже «благородный поэт», и я скопировал несколько стихов... не могли бы вы помочь мне передать их?",
    ["乌达？"] = "Уда?",
    ["也只有通过这种方式降低考试难度，才会有更多的学生为了学分和文凭，愿意继续选择历史专业。"] = "И только снизив таким образом сложность экзаменов, больше студентов захотят продолжать выбирать историческую специальность ради зачетов и дипломов.",
    ["也告诉其他商人，收老鼠的价码一样。"] = "Скажи и другим торговцам, что цена за крыс прежняя.",
    ["也希望他能一路顺利吧。"] = "Надеюсь, и ему в пути будет сопутствовать удача.",
    ["也有人认为这来自畏罪自杀的埃德萨克王子。对鲁恩来说，他是个罪人，但对于社交界，一位王子痴迷上美丽且神秘的平民，这件事可贡献了不少谈资。"] = "Некоторые также полагают, что оно исходило от князя Эдессака, который покончил жизнь самоубийством, чтобы избежать наказания. Для Лоэна он был грешником, но для круга общения принц, одержимый красивой и загадочной простолюдинкой, породил немало сплетен.",
    ["也没那么厉害。"] = "Он не так уж и силён.",
    ["也算告一段落了。"] = "Я полагаю, что на данный момент это все.",
    ["也许我可以帮你。"] = "Возможно, я смогу вам помочь.",
    ["也许我可以帮您。"] = "Возможно, я смогу вам помочь.",
    ["也许我能帮你把帽子取来？"] = "Может быть, я смогу помочь тебе принести шляпу?",
