    ["什么后勤？"] = "Какая логистика?",
    ["什么工作这么好？"] = "Какая работа такая хорошая?",
    ["什么意思？"] = "Что это значит?",
    ["什么意思？你们截我？别以为拦得住……"] = "Что ты имеешь в виду? Ты меня перехватываешь? Не думай, что сможешь остановить меня...",
    ["什么知识？"] = "Какие знания?",
    ["什么醉汉？该死，现在不是开玩笑的时候，来帮把手！"] = "Какой пьяница? Черт возьми, сейчас не время для шуток. Подойди и помоги мне!",
    ["什么！不要啊——"] = "Что! Нет, не надо...",
    ["什么！这女人疯了吧！"] = "Что! Эта женщина сумасшедшая!",
    ["什么！？观众们不喜欢我的台词？这怎么可能！"] = "Что?! Зрителям не нравятся мои реплики? Да как такое возможно!",
    ["什么？丑陋的大猩猩，有本事上台来，看我不拔光你这畜生的毛！"] = "Что? Уродливая горилла, если у тебя хватит смелости, выходи на сцену! Посмотрим, не выдерну ли я каждый волосок с твоего чудовищного тела!",
    ["什么？你凭什么这么说？"] = "Что? По какому праву ты так говоришь?",
    ["什么？我是市政府派来的监察员里奥，正伪装成流浪汉进行搜查！"] = "Что? Я Лео, инспектор, посланный властями города, в настоящее время замаскированный под бродягу, для проведения обыска!",
    ["什么？！"] = "Что?!",
    ["什么？！你就是老师？那你为什么要卖考试答案？"] = "Что?! Ты учитель? Тогда почему вы продаете ответы на экзамены?",
    ["什么？！让我看看！ 金秋湖……七十年前……"] = "Что?! Дайте-ка подумать! Озеро Золотой Осени... семьдесят лет назад...",
    ["今夜，你与魔女饮酒、共舞，度过良宵……"] = "Сегодня вечером ты выпьешь и потанцуешь с ведьмой, проведя чудесный вечер...",
    ["今天的“幸运蛋”想必大家都看过了，它来自一只身份特殊的鸡，当然我们的工作人员也相当努力，挑选了和“幸运蛋”几乎一模一样的其他蛋！"] = "Наверное, все видели сегодняшнее «Счастливое яйцо»; оно происходит от курицы с особой идентичностью. Конечно, наши сотрудники также немало потрудились, чтобы выбрать и другие яйца, практически идентичные «Счастливому яйцу»!",
    ["今天的夕阳很适合画画。我得回去了，{{先生|女士}}，再见。"] = "Сегодняшний закат идеально подходит для рисования. Я должен вернуться сейчас, {{ Mr. | Ms. }}. До свидания.",
    ["今天的菜是你做的？"] = "Вы приготовили сегодняшние блюда?",
    ["今年生意真难做，你说要是抓老鼠能有钱拿，我把它们全抓了，早发家了。"] = "В этом году торговля идёт туго. Если бы за ловлю крыс платили, я бы давно переловил их всех и разбогател.",
    ["今晚顺。"] = "Это сегодня вечером.",
    ["今晚，让梦成真……好吗？ "] = "Пусть сегодня ночью сон станет явью... хорошо? ",
    ["从今天开始，你就叫<P_Yellow>哈基猿</>吧！"] = "С сегодняшнего дня тебя будут называть <P_Yellow>Haji-Ape</>!",
    ["从此以后，哈基猿就变成了贝儿的头号保镖，总是寸步不离地跟在她身后。"] = "С тех пор Хаджи-Апе стал телохранителем номер один Белль, всегда внимательно следя за ней.",
    ["从此以后，哈基猿就变成了贝儿的头号保镖，永远寸步不离地跟在身后。"] = "С тех пор Хаки-Обезьяна стал главным телохранителем Бель, ни на шаг не отходя от нее.",
    ["从没吃过这么难吃的东西，感觉像臭袜子和馊鸡蛋混在一起发酵了三天三夜，苦涩、酸臭，还有一种令人不安的甜腻 。"] = "Я никогда не ел ничего настолько ужасного. Такое ощущение, будто грязные носки и тухлые яйца бродили вместе три дня и три ночи — горько, кисло и с тревожной сладостью.",
    ["从现在起，我们没有任何关系了。"] = "Отныне нас больше ничего не связывает.",
    ["从那时开始，我就一直呆在这间公寓里，几乎不出门了。"] = "С тех пор я живу в этой квартире и почти не выхожу из дома.",
    ["从那时开始，我就一直待在这间公寓里，几乎不出门了。"] = "С тех пор я живу в этой квартире и почти не выхожу из дома.",
    ["从那时起，我就发誓，早晚有一天，我要出人头地，重新占据她。"] = "С тех самых пор я поклялся, что рано или поздно выбьюсь в люди и верну ее себе.",
    ["他……"] = "Он...",
    ["他、他们跑了！"] = "О... они сбежали!",
    ["他一直那样，一个人在那里画鸡蛋，还会对着鸡蛋说些奇奇怪怪的话……算了不管其他人，今天那一万苏勒一定是我的！"] = "Он всегда такой, сам рисует там яйца, и даже говорит с яйцами странные вещи... Забудьте об остальных, эти десять тысяч солов сегодня должны быть моими!",
    ["他不是去继承家业了么，怎么回来了？"] = "Разве он не унаследовал семейный бизнес? Почему он вернулся?",
    ["他举着盾牌顶在最前面，弹开了所有龙焰。"] = "Он шел впереди всех с поднятым щитом, отражая бушующее пламя дракона.",
    ["他买下了当年那艘“法老号”，翻修之后再次出海了，但没人知道他去了哪里。"] = "Тогда он купил «Фараон», отремонтировал его и снова отправился в плавание, но никто не знает, куда он делся.",
    ["他们不会原谅我了……"] = "Они мне больше не простят...",
    ["他们不讲道理，我也略懂一些拳脚。"] = "Они не слушают разума, а я кое-что знаю о кулачных боях.",
    ["他们应该盯上你很久了，利用了你的善意。"] = "Должно быть, они давно за вами присматривались, пользуясь вашей добротой.",
    ["他们很好。那孩子非常崇拜您，说您一个人控制住马车救下了他，所以他亲手用木料雕刻了这个送给您。"] = "Они очень добрые. Этот ребенок вами очень восхищается и сказал, что вы в одиночку управляли каретой, чтобы спасти его, поэтому он лично вырезал это из дерева в подарок для вас.",
    ["他们总说我们把钱都花在了酒上，但却不知道那是支撑我们工作的圣水！我们没有办法把苏勒从那些工厂主口袋里抠出来，只能用酒来慰藉自己的灵魂！"] = "Вечно нас попрекают тем, что мы спускаем все деньги на выпивку, но они и понятия не имеют, что для нас это святая вода, дающая силы батрачить! Нам не вытрясти лишнего соли из карманов этих фабрикантов, так что остаётся лишь топить тоску в стакане, спасая свою душу!",
    ["他们明明只需要花很少的钱，就可以改善我们的工作环境。可实际上，他们更愿意把钱花在亮晶晶的珠宝上！"] = "Они явно могли бы улучшить нашу рабочую среду, потратив очень мало денег. Но на самом деле они скорее потратят эти деньги на блестящие украшения!",
    ["他们正是需要努力工作的年纪，是时候偷走他们懒惰的念头。"] = "Они находятся в том возрасте, когда им нужно много работать. Пришло время украсть их ленивые мысли.",
    ["他们溜得还真快……"] = "Они, конечно, быстро ускользнули...",
    ["他们看起来很幸福，遗憾得到弥补，想念得到回应……我差点不想醒来。"] = "Они выглядят такими счастливыми: сожаления восполнены, тоска получила ответ... Я чуть не захотел не просыпаться.",
    ["他们要是讲道理，我就讲道理。"] = "Если они разумны, то и я буду разумным.",
    ["他们说你在盥洗室消失了，现在情况怎么样？"] = "Они сказали, что ты пропал в туалете, как сейчас ситуация?",
    ["他们都说我疯了！"] = "Они все говорят, что я сумасшедший!",
    ["他们都过上了好日子，似乎全然忘记了那个被他们扔进大牢的水手……"] = "Все они прожили хорошую жизнь, казалось бы, совершенно забыв о матросе, которого бросили в темницу...",
    ["他去了贝克兰德挣钱，可能要很久才能回来。"] = "Он поехал в Баклунд на заработки; может пройти много времени, прежде чем он сможет вернуться.",
    ["他听说你是一位“大作家”，特意准备了纸笔，希望你能用它们写出更好的作品。"] = "Он услышал, что вы «великий писатель», поэтому специально приготовил бумагу и ручки, надеясь, что вы сможете с их помощью написать еще лучшие произведения.",
    ["他告诉我，穿上这双经过仪式的舞鞋，所有人都会爱上我。"] = "Он сказал мне, что если я надену эти ритуальные танцевальные туфли, все в меня влюбятся.",
    ["他在学院里的权力很大，我怕他直接开除我，我的人生会被毁掉的！"] = "У него много власти в колледже. Боюсь, он меня просто выгонит, и моя жизнь будет разрушена!",
    ["他在码头那边，不知道怎么惹来了警察！"] = "Он в доках, не знаю, как он спровоцировал полицию!",
    ["他好像准备要跳下去了，该如何调整他的情绪？"] = "Кажется, он готов прыгнуть вниз, как мне настроить его настроение?",
    ["他对我说，以后他死了，就葬在这里，像雪一样融化。"] = "Он сказал мне, что после смерти его похоронят здесь, он растает, как снег.",
    ["他怎么这么……"] = "Как он мог быть таким...",
    ["他昨天晚上在黑荆棘地下的宁静室待了一整夜，似乎在调查什么，还搬了张办公桌过去。"] = "Вчера он провел всю ночь в спальне Чанисских ворот. Кажется, он что-то расследует и даже передвинул туда стол.",
    ["他曾经在议会厅里给刚认识的女仆写情诗，甚至还在宫廷里当着贵族的面与他的妻子调情……但即便这样的罗塞尔，在她面前也只能俯首称臣。"] = "Однажды он написал любовные стихи горничной, которую только что встретил в зале парламента, и даже флиртовал с женой на глазах у дворцовой знати... Но даже такая Розель могла только преклониться перед ней.",
    ["他本来就一直仰慕罗塞尔大帝，特别是最近他缺乏灵感，迟迟写不出满意的作品……"] = "Он всегда восхищался императором Расселом, особенно в последнее время, потому что ему не хватало вдохновения и он не мог писать удовлетворительные произведения...",
    ["他生病那年，我背他上来过，他最后一次坐在花丛中。"] = "В тот год, когда он заболел, я перенес его сюда. Это был последний раз, когда он сидел в цветочном кластере.",
    ["他真的会改吗？"] = "Он действительно изменится?",
    ["他真的那么干过……的确，他比以前好多了。换作平时，他绝不可能退让一步。"] = "Он делал это раньше... Действительно, он лучше, чем раньше. Обычно он никогда не делал ни шагу назад.",
    ["他称自己为……L先生。"] = "Он назвал себя... мистер Л.",
    ["他自己摔倒的，咱们可看得清清楚楚。"] = "Он упал сам; мы видели это ясно.",
    ["他葬在山上风景最好的地方，这是我们年轻时的约定。"] = "Он похоронен в месте с лучшим видом на гору. Это было наше обещание, когда мы были молоды.",
    ["他说了什么？"] = "Что он сказал?",
    ["他说的“主人”恐怕正在里面举行仪式。我们要赶快进去阻止他！"] = "«Мастер», о котором он упомянул, вероятно, проводит внутри ритуал. Мы должны пойти и немедленно остановить его!",
    ["他说自己快要长大了，又高兴又难过。"] = "Он сказал, что растет, и ему одновременно радостно и грустно.",
    ["他走之前是这么说的——"] = "Перед уходом он сказал так:",
    ["他还有个小小的愿望，希望我能拍一张你使用这些创作时的照片。"] = "У него также есть небольшое желание: он надеется, что я смогу сфотографировать вас, используя их для своей творческой работы.",
    ["令人惊叹！上周，东区的捷西先生轻信该团伙的投资理念，三天掏钱七次，共被骗500镑！"] = "Удивительный! На прошлой неделе г-н Джесси из Восточного округа наивно поверил в инвестиционную философию банды. Он платил деньги семь раз за три дня, и в общей сложности у него украли 500 фунтов!",
    ["以你的序列，最好别有这种危险的念头，不然——嗯，谁的信？"] = "Учитывая вашу Последовательность, таких опасных мыслей лучше не иметь, иначе… хм, чье это письмо?",
    ["以前都不知道他上班，要走这么远。"] = "Раньше я и не знала, что ему приходится ходить так далеко на работу.",
    ["以后这套拳法就叫——<P_Yellow>我要你鼠</>！拳法！"] = "Отныне это боевое искусство будет называться — <P_Yellow>, я хочу тебя, крыса, </>! Боевые искусства!",
    ["以后这棵树会长得比我高吗？"] = "Это дерево вырастет выше меня?",
    ["休伯特先生曾在会议中提出削减廷根下水道治理投入的方案。"] = "Г-н Хьюберт однажды предложил на собрании план по сокращению финансирования управления канализацией Тингена.",
    ["休伯特贪污？！"] = "Хьюберт растратчик?!",
    ["休息？那是教授的专利。"] = "Отдых? Это привилегия профессора.",
    ["优秀的帝王往往能平衡臣子之间的力量，曾经的你正是被臣子在两肋插了一刀。这次，你打算怎么做？"] = "Мудрый император всегда умеет балансировать между силами своих подданных. В прошлом приближенные вонзили тебе нож в спину. Что же ты намерен делать на этот раз?",
    ["伙计，你终于想通了。"] = "Дружище, ты наконец-то образумился.",
    ["会不会是临时买的，有些仓促，所以相比之前肉质差了一点？"] = "Может быть, оно было куплено на месте, немного в спешке, поэтому качество мяса стало хуже, чем раньше?",
    ["会的，会比我高，比你高，比我们都更高哩！"] = "Вырастут! Будут выше меня, выше тебя, выше всех нас!",
    ["会的，医生会治好他，相信他一定会好起来的。"] = "Он это сделает. Доктор его вылечит. Поверьте, что он обязательно поправится.",
    ["会的，祂会宽恕一切。"] = "Она простит, Она все простит.",
    ["会说话的猫……你是一名真正的观众？"] = "Говорящий кот... ты настоящий Зритель?",
    ["会说话还能劈人的水池？去看看吧。"] = "Бассейн, который умеет говорить и ещё и молниями разит? Пойдём взглянем.",
    ["伟、伟大的罗塞尔大帝。"] = "Великий Император Розель.",
    ["伟大的阿罗德斯大人。"] = "Великий мистер Арродес.",
    ["伟大的风暴之神"] = "Великий Бог Штормов",
    ["伤害市民？讲什么笑话！我得帮那位女士，没时间耽误了。"] = "Навредить горожанам? Что за вздор! Я должен помочь той даме, нельзя терять ни минуты.",
    ["伦纳德先生，没打扰你休息吧？有位叫莉娅的姑娘托我给你带点东西，感谢你之前的帮助。 "] = "Господин Леонард, я не помешал вашему отдыху? Девушка по имени Лия просила передать вам кое-что в знак благодарности за прежнюю помощь. ",
    ["伦纳德刚出完任务回来，我正好要去找他，可以帮你转交。 "] = "Леонард только что вернулся с задания, я собираюсь его найти и могу помочь тебе передать это.",
    ["伯爵先生，下午好。"] = "Добрый день, граф.",
    ["伯爵先生，您这样还不如开枪杀死我。失去贵族的荣誉，对我来说比死亡更加可怕。"] = "Господин граф, с вашей стороны милосерднее было бы пристрелить меня. Потерять дворянскую честь для меня страшнее самой смерти.",
    ["伯爵先生，求求您……求求您……放过我……"] = "Господин граф, умоляю вас... умоляю... пощадите меня...",
    ["伯爵先生，请问这个故事的结局是什么？"] = "Граф, а чем закончится эта история?",
    ["伯爵大人，您千万不能这么做，这会让因蒂斯海洋银行马上破产的！"] = "Ваше сиятельство граф, вы ни в коем случае не должны так поступать! Это немедленно приведет Океанский банк Интиса к банкротству!",
    ["伯爵阁下，您难道发现了……"] = "Ваше сиятельство, неужели вы обнаружили...",
    ["估计一小时差不多，就按时间算。我们这就出发？ "] = "Примерно часа должно хватить, давайте по времени. Отправимся?",
    ["伴随一声猴叫，卡门的下半身如闪电般归去。"] = "Под аккомпанемент обезьяньего крика нижняя часть тела Кармен возвращается, как молния.",
    ["似乎没能领悟格斗的要诀，再仔细观察一下吧……"] = "Кажется, ты не усвоил основы боя; давайте понаблюдаем внимательнее...",
    ["但与此同时，内心那个疯狂的、冲动的我，却在期待今晚再次见到您……再次，触碰您……我一定是疯了！"] = "Но в то же время сумасшедший, импульсивный я внутри с нетерпением ждет возможности снова увидеть тебя сегодня вечером... снова прикоснуться к тебе... Должно быть, я сошла с ума!",
    ["但事实是，这种自负让我卡进墙里，还让我忘记，“学徒”是需要向老师虚心学习的。"] = "Но правда в том, что из-за этого высокомерия я застрял в стене и забыл, что «Ученику» нужно смиренно учиться у своего учителя.",
    ["但你压根算不上强壮，你这种弱鸡连给贝儿小姐提鞋的资格都没有。"] = "Но ты совсем не сильный. Такой слабак, как ты, не способен даже завязать шнурки на туфлях мисс Белль.",
    ["但你只是今天比我时尚，只允许你今天坐在这里！"] = "Но ты выглядишь моднее меня только сегодня, так что сидеть здесь тебе разрешено только сегодня!",
    ["但你这样的弱鸡，连给贝儿小姐提鞋的资格都没有。"] = "Но такой слабак, как ты, не достоин мисс Бель даже шнурки завязывать.",
    ["但回到这里，我总是会想起克莱恩第一天入职的情景。"] = "Но возвращаясь сюда, я всегда думаю о сцене первого дня Клейна на работе.",
    ["但在我学会说话，并劝她改掉拖稿的习惯后，她就把我丢出窗户让我去学习一下人类的说话艺术。"] = "Но после того, как я научился говорить и убеждал ее отказаться от привычки откладывать рукописи, она выбросила меня в окно, чтобы я научился искусству человеческой речи.",
    ["但坟墓怎么会没有呢？我亲手安葬了戴维，亲手刻的墓志铭……"] = "Но как могло не быть могилы? Я похоронил Давида своими руками и сам вырезал эпитафию...",
    ["但如今，我在这里遇见了你这样的恶魔，我就没理由放过你，让你去夺走更多无辜者的性命！"] = "Но теперь, когда я встретил здесь такого дьявола, как ты, у меня нет причин отпускать тебя и забирать еще больше невинных жизней!",
    ["但如果你的心已做好准备，那么女神会看到你的虔诚。"] = "Но если ваше сердце готово, тогда Богиня увидит ваше благочестие.",
    ["但幸好，这条路是明亮的。"] = "Но, к счастью, эта дорога светлая.",
    ["但愿如此……我会烧掉我的手稿，重新回到被斥为“粗俗”的褶皱里，写一部真正动人的作品，到时候再请你也来一起观赏。"] = "Я надеюсь на это... Я сожгу свои рукописи и вернусь к тем местам, которые считались «вульгарными», чтобы написать по-настоящему трогательное произведение. Когда это время придет, я приглашу вас посмотреть его вместе.",
    ["但我不理解，{{先生|女士}}，你不认为爱情只是命运的捉弄吗？怎么会有一见钟情这样荒谬的事，让人愿意为陌生人付出一切呢？"] = "Но я не понимаю, {{мистер|мисс}}, тебе не кажется, что любовь - это просто игра судьбы? Как может существовать такая абсурдная вещь, как любовь с первого взгляда, которая заставляет людей отдать все ради незнакомца?",
    ["但我们老大是谁啊，凯文·斯托克，他当然不能退。"] = "Но кто наш босс? Кевин Сток! Конечно же, он не мог отступить.",
    ["但我太虚弱了，他无法听见我的声音。"] = "Но я был слишком слаб, и он не мог услышать мой голос.",
    ["但我已经给太多人带来了痛苦！"] = "Но я причинил боль слишком многим людям!",
    ["但我并没有从启蒙教起的时间。"] = "Но у меня нет времени учить вас основам.",
    ["但我真的可以使用这个封印物吗？我是不是应该靠自己的力量，守护大家？"] = "Но можно ли мне по-настоящему использовать этот Запечатанный Артефакт? Не стоит ли мне защищать всех собственными силами?",
    ["但承载神明的力量，需要直面祂的注视。这近乎直视神——你的精神将承受巨大的冲击。稍有松懈，便可能迷失在呓语之中。"] = "Но для того, чтобы нести силу божества, необходимо смотреть прямо в глаза Ее взору. Это почти то же самое, что смотреть прямо на бога: ваш дух выдержит огромное воздействие. Если вы расслабитесь хоть немного, вы можете потеряться в шепоте.",
    ["但是今天，你让我意识到了问题，时代早已经变了，戏剧也该跟着变化。"] = "Но сегодня вы заставили меня осознать проблему: времена давно изменились, и драма должна меняться вместе с ними.",
    ["但是刻骨的仇恨他一刻也没有忘怀，经过多年的仔细调查，他已经查明了真相，找到了陷害自己的仇人。"] = "Однако он ни на миг не забывал о глубоко въевшейся ненависти. Спустя годы тщательных расследований он докопался до истины и отыскал врагов, которые его подставили.",
    ["但是它的副作用无法避免，您的皮肤会开始龟裂变色，就像年久失修的墙皮。"] = "Но его побочные эффекты неизбежны. Ваша кожа начнет трескаться и менять цвет, как старая, заброшенная штукатурка на стенах.",
    ["但是我敢说，你有当演员的天赋，你不仅满足我所有要求，而且你眼神里的故事感一定能打动观众，这一切肯定是女神的安排。"] = "Но я осмелюсь сказать, что у тебя есть актерский талант. Вы не только соответствуете всем моим требованиям, но и ощущение истории в ваших глазах обязательно тронет публику. Должно быть, это задумано Богиней.",
    ["但是杰姆说，他以后都没办法跟我一起工作了，这不只是因为生病……"] = "Но Джем сказал, что больше не сможет со мной работать, и дело не только в болезни...",
    ["但是，我可不想表现得像个卷毛狒狒一样！"] = "Но я вовсе не хочу выглядеть как кудрявый бабуин!",
    ["但是，明明所有考卷都是我亲自印刷，直到考试当天都是用火漆密封的。我调查了很久，也没搞清楚原题是怎么泄露出去的！"] = "Однако все экзаменационные работы были распечатаны мной лично и запечатаны сургучной печатью до дня экзамена. Я долго исследовал, но так и не понял, как произошла утечка оригинальных вопросов!",
    ["但梅丽莎人呢？我还想看看她读大学后有没有长高呢，希望不要比我高太多。"] = "Но где Мелисса? Я все еще хочу посмотреть, стала ли она выше после окончания университета; Надеюсь, она не намного выше меня.",
    ["但此时他的心情远比海浪更汹涌澎湃……"] = "Но в этот момент его настроение куда более бурное, чем морские волны...",
    ["但每份调查报告都写着“无法复现故障”，您不觉得这很蹊跷吗？"] = "Но в каждом отчете о расследовании говорится, что «невозможно воспроизвести неисправность». Вам не кажется это подозрительным?",
    ["但要记住，作为“守护者”，比起怎么“愚弄”时间，更重要的是找到要守护的对象和决心。"] = "Но помни: как «Хранителю» тебе важнее не то, как «обмануть» время, а найти то, что нужно оберегать, и решимость это делать.",
    ["但该死的，她成功勾起了我——作为“罗塞尔大帝”的兴趣。 "] = "Но, черт возьми, она успешно возбудила мой интерес — как «Император Розель».",
    ["但这个尝试非常危险，所以你将在我们的注视下进行。 "] = "Но эта попытка очень опасна, поэтому вы будете действовать под нашим присмотром.",
    ["但这也太夸张了，马西莫甚至叫库克为“厨王之王”！"] = "Но это уже явный перебор: Массимо даже назвал Кука «королём всех поваров»!",
    ["但这儿的确是我家，你是怎么进来的？"] = "Но это действительно мой дом. Как вы попали?",
    ["但这对认真努力的学生来说并不公平，投机取巧的学生以后也不会对历史学有贡献。"] = "Но это несправедливо по отношению к прилежным студентам, а те, кто ищет легких путей, в будущем не внесут никакого вклада в историю.",
    ["但这里明明是<P_Yellow>男厕所</>！你为什么会出现在这里？"] = "Но это явно мужской туалет <P_Yellow></>! Почему ты здесь?",
    ["低语声、轻叹声、衣物窸窣声……"] = "Шепот, тихие вздохи, шорох одежды...",
    ["住手！你在干什么？"] = "Останавливаться! Что ты делаешь?",
    ["作为人类的“我”去世后，非凡特性和书中的知识结合，诞生了现在的“我”。"] = "После того, как человеческое «я» скончалось, характеристики Потустороннего объединились со знаниями из книг, породив нынешнее «я».",
    ["作为学徒，我本想用点“特别的方式”穿墙取个宝箱， 结果……如你所见，把自己卡住了。 帮我出来，宝箱和钥匙都归你！"] = "Будучи учеником, я хотел использовать «особый метод», чтобы пройти через стену и получить сундук с сокровищами, но… как видите, я застрял. Помогите мне, и сундук с сокровищами и ключ станут вашими!",
    ["作为最高保密等级，“0”级封印物的搜索传达一直都只有模糊的信息。这点，你应该很清楚。"] = "Поскольку это самый высокий уровень безопасности, поиск запечатанного артефакта 0-го уровня всегда давал лишь смутную информацию. Вам должно быть очень ясно об этом.",
    ["作家小姐提供了刚登上杂志的小说，作为下午茶读物。"] = "Госпожа Автор принесла только что вышедший в журнале роман для чтения за послеполуденным чаем.",
    ["作物种是种出来了，但又被吃掉了……这样算耕种成功吗？"] = "Урожай посадили, но его снова съели... Считается ли это успешным сельским хозяйством?",
    ["你……"] = "Ты...",
    ["你……也行吧，反正里面也没有值钱东西。<P_Heart>（掏出一把旧钥匙）</>给你。你小心点。"] = "Ты... ну ладно, внутри всё равно нет ничего ценного. <P_Heart> (вытаскивает старый ключ) </> Вот. Будь осторожен.",
    ["你……你根本就没想要杰姆活下去！"] = "Ты... ты вообще не хотел, чтобы Джем выжил!",
    ["你……你能带我回家吗？"] = "Ты... ты можешь отвести меня домой?",
    ["你、你仰慕我……"] = "Ты, ты восхищаешься мной...",
    ["你、你仰慕我……我、我倾慕你，这间花店甜似蜜！"] = "Ты, ты восхищаешься мной... Я, я восхищаюсь тобой, этот цветочный магазин сладок, как мёд!",
    ["你、你你……搞偷袭！这不公平！  "] = "Ты, ты, ты... играешь грязно! Это несправедливо!",
    ["你、你干什么？小心我去叫打黑拳的兄弟……"] = "Ч-что ты делаешь? Осторожно, я позвоню своим братьям, которые занимаются подпольным боксом...",
    ["你、你怎么进来的？！门不是锁着吗……"] = "Как, как ты попал?! Разве дверь не была заперта?..",
    ["你、你没死？"] = "Ты... ты не умер?",
    ["你、你这个平民竟敢这么对我说话，好大的胆子！"] = "Ты, простолюдин, как ты смеешь так со мной разговаривать! Какая смелость!",
    ["你不仅非法剥削童工，还涉嫌虐待儿童。杰姆的病，还有道奇身上的伤就是最好的证据。"] = "Вы не только незаконно эксплуатируете детский труд, но и подозреваетесь в жестоком обращении с детьми. Болезнь Джема и травмы Доджа — лучшее тому подтверждение.",
    ["你不介意吗？"] = "Вы не против?",
    ["你不找海蒂女士，却急着找一枚戒指？"] = "Вы не ищете мисс Хайди, но торопитесь найти кольцо?",
    ["你不是疯子，卢娜。你只是个诚实面对自己的女人。"] = "Ты не сумасшедшая, Луна. Ты просто женщина, которая честна сама с собой.",
    ["你不是说你记得很清楚吗！"] = "Разве ты не говорил, что помнишь это очень ясно!",
    ["你不止不能抓光，还得养它们！那才是铁饭碗。"] = "Их мало поймать всех, их ещё надо растить! Вот это надёжная работа.",
    ["你不用担心，她不会被抓走，安全也有保障。"] = "Вам не стоит волноваться, ее не арестуют, и ее безопасность гарантирована.",
    ["你不知道？她和史密斯离婚了！听说那些房子她分了一半，现在还是我们的房东。这下租金总是她自己拿着了吧。"] = "Вы не знали? Она развелась со Смитом! Я слышал, что ей досталась половина этих домов, так что она по-прежнему наша хозяйка. По крайней мере, теперь она будет собирать арендную плату.",
    ["你为什么不直接去投诉？学院会受理的。"] = "Почему бы вам просто не подать жалобу? Колледж с этим справится.",
    ["你为它留下了一顿饱餐，一方屋檐，与一夜安眠。"] = "Ты оставил ему сытный обед, крышу над головой и ночь для сна.",
    ["你也是来看病的吗？"] = "Ты тоже пришел к врачу?",
    ["你也这样认为？"] = "Вы тоже так думаете?",
    ["你什么意思！"] = "Что ты имеешь в виду!",
    ["你仔细看了我的文章！没错，不仅如此，油量也经过了严密配比，既美味又健康！"] = "Вы внимательно прочтите мою статью! Все верно, мало того, количество масла еще и строго пропорционально, что делает его одновременно вкусным и полезным!",
    ["你以为这样就能够动摇我的这颗心了吗？"] = "Как думаешь, сможешь потрясти этим мое сердце?",
    ["你们……还想去猎龙吗？"] = "Ты... все еще хочешь поохотиться на дракона?",
    ["你们不在乎，那就扔了！"] = "Если вам все равно, то выбросьте это!",
    ["你们做得很好，该进行下一步了。"] = "Вы хорошо поработали, пора переходить к следующему шагу.",
    ["你们去猎龙城干什么？"] = "Зачем ты собираешься в Город Охоты на Драконов?",
    ["你们可以学点别的，做个学徒，或者……随便什么。以你们的聪明和勤劳，不会挨饿的。"] = "Ты можешь научиться чему-то еще, стать учеником или... кем угодно. С вашим умом и трудолюбием вы не останетесь голодными.",
    ["你们在我的后厨干什么？"] = "Что ты делаешь на моей кухне?",
    ["你们在找懂得驱鬼的人吗？我正好有些了解。"] = "Вы ищете того, кто умеет изгонять духов? Я как раз немного в этом разбираюсь.",
    ["你们的人生没有计划吗？！这样也不是大事吗？！"] = "В твоей жизни нет плана?! Разве это не имеет большого значения?!",
    ["你们的价格是？"] = "Какова ваша цена?",
    ["你们的底价是？"] = "Какова ваша базовая цена?",
    ["你们的结婚戒指丢了！还不是大事？！"] = "Ваше обручальное кольцо потеряно! И это не так уж важно?!",
    ["你们看！我搞到了他们三年前的航线图！据说“黄金梦想号”在某个神秘岛屿埋藏了无法估量的宝藏！"] = "Смотреть! Я получил их карту маршрутов трехлетней давности! Говорят, что «Золотая мечта» закопала на загадочном острове неисчислимые сокровища!",
    ["你们知道？谢谢你，丽贝卡，也谢谢弗莱队长。"] = "Вы знали? Спасибо, Ребекка, и спасибо, капитан Фрай.",
    ["你们要干什么？票是我买到的。"] = "Что ты делаешь? Я купил этот билет.",
    ["你们认识？"] = "Вы знаете друг друга?",
    ["你们说的毒药，是“焦糖炸弹”？"] = "Яд, о котором вы упомянули, — «Карамельная бомба»?",
    ["你们还有店歌？"] = "У вас есть даже песня заведения?",
    ["你们这些强盗，把马车还回来！"] = "Разбойники, верните карету!",
    ["你仰慕我，我倾慕你，这间花店甜似蜜！来，试试看！"] = "Ты восхищаешься мной, я восхищаюсь тобой, этот цветочный магазин сладок, как мёд! Давай, попробуй!",
    ["你会后悔的，不信咱们走着瞧！"] = "Вы пожалеете об этом, просто подождите и увидите!",
    ["你保护了这只美人鱼，我想，她也会很乐意帮你晋升。"] = "Ты защитил эту русалку, и, думаю, она с радостью поможет тебе с повышением.",
    ["你冲进盥洗室，畅快地进行了一番代谢废物行为。"] = "Вы врываетесь в уборную и с великим облегчением справляете естественные потребности.",
    ["你刚才怎么不说！"] = "Почему ты не сказал этого прямо сейчас!",
    ["你别怕，我是黑夜教会派来保护你的。"] = "Не бойся, меня прислала Церковь Вечной Ночи, чтобы защищать тебя.",
    ["你别误会，我可不是怕打针。"] = "Не пойми меня неправильно, я вовсе не боюсь уколов.",
    ["你到底是什么？！"] = "Что ты вообще такое?!",
    ["你去那个棺材里的尸体上找找，那是我们的卧底，刚归队就死了，他身上应该有线索。"] = "Обыщи тело в том гробу. Это был наш тайный агент, погибший сразу после возвращения в отряд. При нем должны быть улики.",
    ["你又受伤了？"] = "Тебе снова больно?",
    ["你叫什么？"] = "Как вас зовут?",
    ["你可以先准备一下，我带你去拿。"] = "Можешь пока подготовиться, я отведу тебя за ним.",
    ["你可以这么理解。之前的经历可能让你对这些东西变得敏感。"] = "Вы могли бы понять это и так. Возможно, ваш предыдущий опыт сделал вас чувствительным к этим вещам.",
    ["你向谢尔敏说明了饮料令人腹泻的情况。"] = "Вы объясняете Шермину, что напиток вызывает диарею.",
    ["你听到了什么？"] = "Что ты услышал?",
    ["你听见病人的惨叫声了吗？这家诊所很不对劲。"] = "Вы слышали крик пациента? Что-то не так с этой клиникой.",
    ["你听过罗塞尔写的诗歌吗？“爱情是一只自由鸟，任谁都无法驯服。”"] = "Вы слышали стихотворение, написанное Розеллой? «Любовь — вольная птица, ее никто не приручит».",
    ["你呢，也许能从你进来的地方出去？"] = "А вы? Может быть, ты сможешь уйти оттуда, откуда пришел?",
    ["你和我都清楚，这和章鱼产地关系不大，是处理肉的方式有问题。"] = "И ты, и я прекрасно понимаем: дело вовсе не в том, откуда осьминог, а в том, как разделывают мясо.",
    ["你喜欢臭臭的东西？"] = "Вам нравятся вонючие вещи?",
    ["你回来了。污染清除了？"] = "Ты вернулся. Искажение устранена?",
    ["你在哪里搞到的？他们的航线图怎么会落到你手上？是真的吗？"] = "Откуда ты это взял? Как их карта маршрутов могла попасть к вам в руки? Это правда?",
    ["你在哪？"] = "Где ты?",
    ["你在害怕吗？"] = "Вы боитесь?",
    ["你在干什么？"] = "Что ты делаешь?",
    ["你在找什么？"] = "Что Вы ищете?",
    ["你在找神父爷爷吗？他不在这里。这里只有我，一直是我在跟你说话……"] = "Вы ищете отца? Его здесь нет. Есть только я; это я всегда говорил с тобой...",
    ["你在看什么？"] = "На что ты смотришь?",
    ["你在说什么！什么牺牲！该死，清醒一点！这里发生了什么！"] = "О чем ты говоришь! Какие жертвы! Черт возьми, просыпайся! Что здесь произошло!",
    ["你在这个世界还有牵挂，还有未完成的事。"] = "В этом мире тебя ещё что-то держит, у тебя остались незавершённые дела.",
    ["你在这个世界还有牵挂，还有未完成的事。\n你必须醒来。"] = "В этом мире тебя ещё что-то держит, у тебя остались незавершённые дела.\nТы должен проснуться.",
    ["你头上连帽子都没有。帽子都没有的人，不会知道鸽子在哪。"] = "У тебя даже шапки на голове нет. Люди без шляп не будут знать, где находятся голуби.",
    ["你好……“焦糖炸弹”是出了什么问题吗？"] = "Привет... что-то не так с \"Карамельной бомбой\"?",
    ["你好像对食物很有研究。"] = "Кажется, вы много исследуете еду.",
    ["你好，刚刚似乎有尖叫从这边传来？"] = "Здравствуйте, крик только что раздался с этой стороны?",
    ["你好，店长，是你研发了“焦糖炸弹”吗？"] = "Привет, Лавочник, ты разработал «Карамельную бомбу»?",
    ["你好，我刚才品尝了“焦糖炸弹”，味道真不错，请问是你自己制作的吗？"] = "Здравствуйте, я только что попробовала «Карамельную бомбу», очень приятный вкус. Могу я спросить, вы сами это сделали?",
    ["你好，我想要一束百合。"] = "Здравствуйте, я бы хотел букет лилий.",
    ["你好，我想要最新款，最昂贵的戒指。"] = "Здравствуйте, я хочу самое новое и самое дорогое кольцо.",
    ["你好，我是阿霍瓦郡警察厅的警员。关于史蒂芬男爵的案件，我需要了解一些情况。"] = "Здравствуйте, я офицер полицейского управления округа Ава. Мне нужно разобраться в некоторой информации по делу барона Стефана.",
    ["你好，特邀观众。"] = "Здравствуйте, специальный гость.",
    ["你好，请问你有见到可疑的人吗？"] = "Здравствуйте, вы не видели подозрительных людей?",
    ["你好？"] = "Привет?",
    ["你家住哪儿？我送你回去。"] = "Где ты живешь? Я провожу тебя.",
    ["你对茜安做了什么？它是无辜的！"] = "Что ты сделал с Цианом? Она невиновна!",
    ["你将信件投入命运咖啡厅的邮箱，很快就和“正义”小姐约定好了见面时间。"] = "Ты опускаешь письмо в почтовый ящик Кафе Судьбы и вскоре договариваешься о времени встречи с госпожой «Справедливость».",
    ["你将发生的事告诉了杰西。"] = "Вы рассказали Джесси о случившемся.",
    ["你小时候来过这里吗？"] = "Вы были здесь, когда были ребенком?",
    ["你尝尝看！"] = "Попробуйте!",
    ["你就是“内部资料”的神秘卖家吧！"] = "Вы, должно быть, таинственный продавец «инсайдерской информации»!",
    ["你就是黑荆棘安保公司的人？听说你们经常处理一些……特别的案子。"] = "Вы из охранной компании «Черный шиповник»? Я слышал, вы частенько беретесь за... особые дела.",
    ["你就说好不好看吧？"] = "Просто скажите мне, это хорошо или нет?",
    ["你就说，哥们的功能牛不牛吧？"] = "Скажи честно, разве возможности твоего приятеля не круты?",
    ["你居然是个魔女，你骗了我，我不能接受！"] = "Ты на самом деле ведьма, ты солгала мне, я не могу этого принять!",
    ["你帮了我，当然要为你买单。"] = "Ты мне помог, конечно, мне придется за тебя заплатить.",
    ["你应该用<P_Yellow>更新鲜、更有意思</>的方式来吸引学生感兴趣。"] = "Вам следует использовать <P_Yellow> более свежие и интересные способы </>, чтобы привлечь интерес студентов.",
    ["你应该用大家都<P_Yellow>能听懂、好理解</>的方式来讲历史课。"] = "Вы должны преподавать историю так, чтобы каждый <P_Yellow> мог легко понять и усвоить </>.",
    ["你很关注{{PlayerName}}，{{他|她}}究竟是什么人？"] = "Ты уделяешь столько внимания {{PlayerName}}... Кто {{он такой|она такая}} на самом деле?",
    ["你很够意思，我没看错人，接下来我要去调查三个地方。"] = "Ты надежный человек. Я не ошибся в тебе. Далее я собираюсь исследовать три места.",
    ["你怎么了？"] = "Что с тобой не так?",
    ["你怎么了？身体不舒服吗？"] = "В чем дело? Вы плохо себя чувствуете?",
    ["你怎么了？需要帮忙吗？"] = "Что с тобой случилось? Вам нужна помощь?",
    ["你怎么像我老师似的！不行，我还是出不来！"] = "Почему ты ведешь себя как мой учитель! Нет, я все еще не могу выбраться!",
    ["你怎么就剩一个头了？"] = "Почему ты теперь просто голова?",
    ["你怎么敢直呼他的名字？请尊称他为，伟大的罗塞尔大帝。"] = "Как ты смеешь обращаться к нему по имени? Пожалуйста, обращайтесь к нему с уважением как к Великому Императору Розелле.",
    ["你怎么突然醒悟了？"] = "С чего это ты вдруг прозрел?",
    ["你怎么能用这种态度跟我说话，你以前不是这样的。"] = "Как ты можешь говорить со мной с таким отношением? Раньше ты не был таким.",
    ["你想把我抓走，关在黑暗的地底？"] = "Вы хотите арестовать меня и запереть в темной темнице?",
    ["你才是猪！"] = "Ты свинья!",
    ["你才是那个临时演员？那这位是……"] = "Ты настоящий временный актер? Тогда кто это...",
    ["你打开门，请拉蒂兹进来了。"] = "Вы открываете дверь и приглашаете Ладис войти.",
    ["你打算怎么办？ 这上面写的看起来是你和他们的约定。"] = "Что вы планируете делать? То, что здесь написано, похоже на соглашение между вами и ими.",
    ["你把自己锁起来，是想让他知道打不开的感觉？"] = "Вы заперлись, чтобы дать ему понять, каково это, когда ты не можешь что-то открыть?",
    ["你拍了这么多张照片，帮一只乌鸦收集灵性痕迹。你有没有好奇过……是谁让那只灵体乌鸦活到这时候的？"] = "Вы сделали так много фотографий, помогая вороне собирать следы духовности. Вам когда-нибудь было интересно... кто до сих пор поддерживал жизнь этой вороне-духу?",
    ["你换了身衣服？"] = "Ты переоделся?",
    ["你救不了他。"] = "Ты не смог его спасти.",
    ["你救了我，也知道我的秘密了，对吗？"] = "Ты спас меня, и теперь ты знаешь мой секрет, верно?",
    ["你明白什么了？喂！"] = "Что ты понимаешь? Привет!",
    ["你是……"] = "Ты...",
    ["你是……艾拉？"] = "Ты... Элла?",
    ["你是不是也被那张纸骗过来的？该死，我就该在看到那张纸的时候一把火把它烧掉！"] = "Вас тоже обманул этот листок бумаги? Черт побери, мне следовало сжечь этот листок бумаги, как только я его увидел!",
    ["你是个警察？"] = "Ты полицейский?",
    ["你是做什么的？为什么这么晚还在外面转？"] = "Что вы делаете? Почему ты все еще так поздно?",
    ["你是卫生监察员，那我是谁？"] = "Вы санитарный инспектор? Тогда кто я?",
    ["你是否希望自己的伴侣不是人类？"] = "Хотелось ли бы вам, чтобы ваш спутник жизни был не человеком?",
    ["你是否想要摆脱身上污秽的污染？"] = "Хотите избавиться от грязной порчи на своем теле?",
    ["你是在哪里听见的声音？ "] = "Где вы услышали звук?",
    ["你是水箱里的那只章鱼！"] = "Ты тот осьминог в резервуаре с водой!",
    ["你是说……菜不是他做的？作为主厨，也许他不需要亲自上灶台做菜？"] = "Ты имеешь в виду... еду готовил не он? Ему как шеф-повару, может быть, не нужно готовить лично?",
    ["你是说，她发现了我们作假，却依旧离开了？"] = "Ты имеешь в виду, что она обнаружила, что мы притворяемся, но все равно ушла?",
    ["你是说，崔佛警官让你用“共感手铐”来压制非凡者失控吗？"] = "Вы хотите сказать, что офицер Тревор попросил вас использовать «Наручники Эмпатии», чтобы подавить потерю контроля Потусторонним?",
    ["你是谁！？为什么躺在我的床上！"] = "Кто ты!? Почему ты лежишь в моей постели!",
    ["你是那个醉汉？"] = "Ты такой пьяница?",
    ["你是马西莫，那个美食评论家？"] = "Вы Массимо, тот кулинарный критик?",
    ["你是？"] = "Кто ты?",
    ["你最多也就出了一半的力，还想要全部的钱？做梦！对了，你的铲子呢？"] = "Вы сделали максимум половину работы и хотите получить все деньги? Мечтайте! Кстати, где твоя лопата?",
    ["你服下魔药后，会进入潜意识为你编织的美梦，那里的一切都令人沉迷，但你得走出来。"] = "Приняв зелье, ты попадёшь в прекрасный сон, сплетённый твоим подсознанием. Там всё затягивает, но тебе нужно выбраться.",
    ["你来了。收到那封信的人，都有着被女神眷顾的灵魂。"] = "Вы пришли. Все те, кто получает это письмо, имеют души, пользующиеся благосклонностью Богини.",
    ["你来了？刚好跟着我！"] = "Ты здесь? Просто следуй за мной!",
    ["你来决定吧，要和谁走？"] = "Решай сам, с кем пойдёшь?",
    ["你来得很快，再往前走就是那位卧底的祖宅了。"] = "Ты быстро добрался. Чуть дальше впереди — родовое поместье того самого тайного осведомителя.",
    ["你没事吧！"] = "С тобой все в порядке!",
    ["你没有伤害别人，危险的其实是你自己。"] = "Ты никому не причинил вреда; на самом деле в опасности находитесь вы.",
    ["你没有取得路人的信任，再试试吧。"] = "Вы не завоевали доверие прохожего, попробуйте еще раз.",
    ["你没有计划……为什么也能找到方向？"] = "У тебя нет плана... почему ты можешь найти направление?",
    ["你没有错过。曾经的你，已经回来过了。 "] = "Вы не пропустили это. Ты из прошлого уже вернулся.",
    ["你没错，但你敢相信吗？他装病这么久，却直到入狱检查时，才发现自己真的身患重疾！"] = "Ты не виноват, но поверишь ли? Он так долго притворялся больным, что лишь на тюремном медосмотре выяснилось: он и вправду неизлечимо болен!",
    ["你没错，该团伙在地下市场购买了能迷惑人心的违禁香水，就算是女神来也会被蒙蔽！"] = "Вы правы, банда купила на подземном рынке запрещенные духи, которые могут сбить с толку людей, даже Богиня будет обманута!",
    ["你现在不在厂里。你在街上。路灯很亮，风很凉。你活着，你没事。"] = "Вы сейчас не на заводе. Вы находитесь на улице. Уличные фонари яркие, ветер прохладный. Ты жив, с тобой все в порядке.",
    ["你用自己的能力帮助别人，这不是坏事。"] = "Использовать свои способности для помощи другим – это неплохо.",
    ["你的主人也是非凡者吗？委托你收集素材的人也是她？"] = "Ваш владелец тоже из Потустороннего? Это она поручила вам собирать материалы?",
    ["你的即兴表演违背了戏剧的情节发展，请重新选择。"] = "Ваша импровизация нарушает развитие сюжета пьесы, пожалуйста, выберите еще раз.",
    ["你的同伴们，还有你说的封印物，都一直留在金秋湖，一直庇护这片大地。"] = "Ваши спутники и упомянутый вами Запечатанный Артефакт остались на озере Золотой Осени, всегда защищая эту землю.",
    ["你的意思是，这道菜不是库克自己做的？"] = "Вы имеете в виду, что это блюдо приготовил не сам Кук?",
    ["你的意思是？"] = "Что ты имеешь в виду?",
    ["你的损失。"] = "Ваша потеря.",
    ["你的故事，是我见过最明亮的太阳。"] = "Твоя история — самое яркое солнце, которое я когда-либо видел.",
    ["你的数值增加了！（+1体力+1臣民怨气）"] = "Ваша статистика увеличилась! (+1 Выносливость, +1 Негодование субъекта)",
    ["你的数值增加了！（+1社交+1臣民怨气）"] = "Ваша статистика увеличилась! (+1 Социальное, +1 Недовольство субъекта)",
    ["你的数值增加了！（+1魅力+1臣民怨气）"] = "Ваша статистика увеличилась! (+1 Очарование, +1 Негодование субъекта)",
    ["你的数值增加了！（+2臣民怨气）"] = "Ваша статистика увеличилась! (+2 негодование субъекта)",
    ["你的警察证呢？我只相信眼睛见到的，没有证件证明身份，你才是可疑的人吧。"] = "Где твой полицейский значок? Я верю только тому, что вижу своими глазами. Без значка, подтверждающего вашу личность, вы подозрительны, не так ли?",
    ["你的计划里也没有海蒂扔戒指这一条。"] = "В твоем плане тоже не было пункта о том, что Хайди выбросит кольцо.",
    ["你的记忆？ "] = "Твои воспоминания?",
    ["你的选择，让廷根工厂区发生了微妙的变化。"] = "Ваш выбор привел к незначительным изменениям на территории завода Тинген.",
    ["你的闪电速度，来源于学徒途径的能力。"] = "Твоя молниеносная скорость проистекает из способностей Пути Ученика.",
    ["你的饮料大受欢迎，已经很厉害了。"] = "Ваш напиток очень популярен, это уже впечатляет.",
    ["你看上去已经知道“0”级封印物的危险性了。"] = "Кажется, вы уже знаете об опасности запечатанного артефакта 0-го уровня.",
    ["你看到了不该看的东西！"] = "Ты увидел то, чего видеть не следовало!",
    ["你看起来有些……憔悴。里面发生了什么？"] = "Ты выглядишь немного... изможденным. Что там произошло?",
    ["你真的很纯粹。"] = "Вы действительно чисты.",
    ["你真的想买“内部资料”吗？"] = "Вы действительно хотите купить «инсайдерские материалы»?",
    ["你真的是神使？！"] = "Ты правда ангел? !",
    ["你着迷般紧盯着马桶深处，脑海一阵眩晕，栽入其中，失去了意识。"] = "Вы одержимо смотрите в глубину унитаза, на ваше сознание накатывает волна головокружения, и вы падаете в него, теряя сознание.",
    ["你瞎了吗？没看到有人在清扫烟囱？"] = "Ты ослеп? Не видишь, что тут чистят дымоход?",
    ["你瞧，老东西，咱们的结婚戒指又丢了。算了，过几天再找。"] = "Смотри, старик, наше обручальное кольцо снова потерялось. Ничего, мы поищем его через несколько дней.",
    ["你知不知道这一天我经历了什么？！我制定找戒指计划，翻遍了花海，趴在地上找了一天，还扔了他们的结婚戒指，而我的戒指一直在我口袋里！"] = "Вы хоть представляете, через что я сегодня прошел?! Я запланировала найти кольцо, обыскала все цветочное поле, целый день ползала по земле и даже выбросила их обручальное кольцо, а мое кольцо все время было у меня в кармане!",
    ["你知道有人在等你。"] = "Ты знаешь, что тебя кто-то ждёт.",
    ["你知道有人在等你。\n城市的居民，黑荆棘的大家，结伴而行的朋友……"] = "Ты знаешь, что тебя кто-то ждёт.\nЖители города, все в «Чёрном Терновнике», друзья, идущие вместе с тобой...",
    ["你终于来了！快快快，去那边，还好赶上了！"] = "Наконец-то ты здесь! Быстрее, скорее иди туда — какое счастье, что успел!",
    ["你终于来了，情况还好吗？"] = "Ты наконец здесь. Как ситуация?",
    ["你终于来了？"] = "Ты наконец пришел?",
    ["你给我等着！"] = "Просто подожди!",
    ["你要从灵界召唤出人头鸟妖，和它签订契约，取得一根尾羽，然后在足够强烈的喜悦或愤怒情绪里服下魔药。"] = "Тебе нужно вызвать из Мира Духов гарпию, заключить с ней контракт, получить одно хвостовое перо, а затем принять зелье в состоянии достаточно сильной радости или гнева.",
    ["你见过她未婚夫？"] = "Вы видели ее жениха?",
    ["你觉得呢？"] = "Что вы думаете?",
    ["你觉得这对吗？"] = "Как вы думаете, это правильно?",
    ["你觉得，以他们的随性程度，会在意你的行为吗？"] = "Как вы думаете, учитывая, насколько они спокойны, их вообще будут волновать ваши действия?",
    ["你认得他？"] = "Вы его знаете?",
    ["你该休息了，再这样下去你会得病的。"] = "Тебе следует отдохнуть. Если будешь продолжать в том же духе, ты заболеешь.",
    ["你说得对。<P_Heart>（叹气）</>不管怎么样，这是唯一的办法了。"] = "Ты прав. <P_Heart>(Вздох)</> В любом случае, это единственный выход.",
    ["你说的有道理，我自己也知道这不是解决根本问题的方法。"] = "То, что вы сказали, имеет смысл, я сам знаю, что это не способ решения фундаментальной проблемы.",
    ["你说的这个朋友，不会就是你自己吧！"] = "Этот друг, о котором ты говоришь, разве это не ты сам!",
    ["你说的那个该死的“主人”到底是谁？"] = "Кто именно этот чертов «Мастер», о котором ты говоришь?",
    ["你说的那场战争都结束了，现在大地教会和知识教会没有冲突，不过在鲁恩，知识教会不能像大地教会一样修建教堂和传教。"] = "Война, о которой вы упомянули, окончена. Сейчас между Церковью Земли и Церковью Знания нет конфликта, но в Лоэне Церковь Знания не может строить церкви или проповедовать, как Церковь Земли.",
    ["你说的马桶，不会是切斯庄园的……"] = "Тот туалет, о котором вы упомянули, случайно не тот, что в Шахматном поместье...",
    ["你还不知道吗？美食家马西莫写了篇文章，带火了这里的主厨库克，我们都是来尝味道的。"] = "Вы еще не знаете? Гурман Массимо написал статью, которая сделала шеф-повара Кука хитом. Мы все здесь, чтобы попробовать еду.",
    ["你还不符合这里的着装要求，下次再来吧。"] = "Здесь еще не соблюден дресс-код. Приходите в следующий раз.",
    ["你还没看这篇《厨王之王》吗？这可是马西莫最好的作品！"] = "Вы еще не читали этого «Короля поваров»? Это лучшая работа Массимо!",
    ["你还真是崇拜罗、伟大的罗塞尔大帝啊。"] = "Ты и впрямь боготворишь Ро... великого императора Розелля.",
    ["你这个人，比我这把老骨头还爱管闲事。"] = "Ты, ты ещё более назойлив, чем мои старые кости.",
    ["你这个疯子……为了廷根市其他人的安危，不管是作为值夜者，还是普通市民，我都要阻止你！"] = "Ты сумасшедший... Ради безопасности других жителей Тингена, будь то Ночной Ястреб или обычный гражданин, я остановлю тебя!",
    ["你这是谋杀！"] = "Это убийство!",
    ["你这样活着，也是在被慢慢毁掉啊。"] = "Живя так, ты тоже медленно разрушаешься.",
    ["你这段时间似乎被章鱼控制了，不过现在没事了。"] = "Кажется, какое-то время тобой управлял осьминог, но теперь с тобой все в порядке.",
    ["你这表里不一的伪君子，我就是要看你众叛亲离，让你的妻子和儿女都以你为耻，让你变成颜面尽丧的流浪汉。"] = "Ты, двуликий лицемер, я намерен увидеть, как тебя все бросят, чтобы твоя жена и дети постыдились тебя и превратили тебя в опозоренного бродягу.",
    ["你这贪婪善妒的守财奴，我就是要你失去积攒一生的财富，变成身无分文的穷光蛋。"] = "Ты, жадный и ревнивый скряга, я хочу, чтобы ты потерял богатство, накопленное за всю жизнь, и стал нищим нищим.",
    ["你这造型倒是挺别致……行吧，怎么找？"] = "Твоя поза совершенно уникальна... хорошо, как мне ее найти?",
    ["你都知道了？"] = "Вы знали?",
    ["你重生了，重生在还没有被罢黜的前三个月，这一次，你将拿回属于你的一切。"] = "Вы возродились, возродились за три месяца до того, как вас свергли. На этот раз вы вернете все, что вам принадлежит.",
    ["你需要快速提升实力，与体内污秽的力量抗争，确实得想办法绕过这个限制。"] = "Тебе нужно быстро повысить силу, чтобы бороться со скверной внутри тела. Придётся найти способ обойти это ограничение.",
    ["你，你……"] = "Ты, ты...",
    ["你，你的脸……"] = "Ты, твое лицо...",
    ["你，是来聆听福音之人？"] = "Вы здесь, чтобы слушать Евангелие?",
    ["你，这位结实的先生！你踩到法阵了！"] = "Эй, вы, крепкий господин! Вы наступили на магический круг!",
    ["你？"] = "Ты?",
    ["侍者来了，我们先把时间让给食物。"] = "Официант здесь, давайте сначала оставим время на еду.",
    ["信。我写给她的信。她没收到就走了，我要找到烧给她。"] = "Письмо. Письмо, которое я написал ей. Она ушла, не успев получить его, и мне нужно найти его, чтобы сжечь для нее.",
    ["信在哪？我可以帮你找找。"] = "Где письмо? Я могу помочь поискать его.",
    ["倒是维尔斯这胆小鬼睡得和婴儿一样……不行，给我起来！"] = "Один лишь Уэллс, этот трус, спит как младенец... Нет, так не пойдет, вставай!",
    ["假死？"] = "Мнимая смерть?",
    ["做完了？算你运气好……你的三苏勒，拿去。"] = "Закончили? Считайте, вам повезло... Вот ваши три соли, держите.",
    ["做得好！仅仅出于嫉妒就要把别人置于死地，愿太阳把这阴暗丑恶的灵魂化为灰烬！"] = "Отличная работа! Довести кого-либо до смерти из одной лишь ревности — пусть солнце превратит в пепел эту темную и безобразную душу!",
    ["做得很好，你已经明白了晋升的意义，去完成仪式吧。"] = "Отлично, ты уже понял смысл продвижения. Иди и завершай ритуал.",
    ["停下，{{先生|女士}}……请原谅我的鲁莽，但您暂时不能靠近这里。"] = "Стоп, {{ Mr. | Ms. }}... Прошу прощения за грубость, но подходить к этому месту пока нельзя.",
    ["停，我的戒指是路边小摊最廉价的，上面有红色的玻璃。我弄丢戒指时，常常去松鼠窝旁的花丛晒太阳。"] = "Стоп, у меня кольцо самое дешевое, из придорожного ларька, с красным стеклом. Когда я потеряла кольцо, то часто ходила загорать в цветочные кусты у беличьего гнезда.",
    ["像一只飞蛾看着火焰，明知会被灼伤，却忍不住靠近。陛下，您知道，您有多危险吗？"] = "Словно мотылек, летящий на пламя: знает, что сгорит, но не может не приблизиться. Ваше Величество, вы хоть знаете, насколько опасны?",
    ["像戏剧的观众那样，去观察那个世界。如果你愿意尝试做些什么，也许还能给某人带来救赎。"] = "Наблюдайте за этим миром, как зритель в театре. Если вы готовы попытаться что-то сделать, возможно, вы даже сможете принести кому-то спасение.",
    ["像是一个梦？"] = "Как сон?",
    ["像蚂蚁一样……谁都能踩一脚……"] = "Как муравьи... на нас может наступить любой...",
    ["先为唐尼占卜去哪的结果？"] = "Сначала погадать о том, куда направился Донни?",
    ["先噔，噔蹬蹬蹬，然后噔噔噔噔噔。"] = "Сначала Дэн, Дэн Дэн Дэн Дэн, затем Дэн Дэн Денг Дэн Дэн.",
    ["先回去休息吧，你需要好好睡一觉。 "] = "Ступай пока отдохни, тебе нужно хорошенько выспаться.",
    ["先回营地吧，《猎龙宣言》还在那里，不能弄丢。"] = "Давайте сначала вернемся в лагерь, «Манифест охоты на драконов» все еще там, мы не можем его потерять.",
    ["先找个隐蔽的地方藏起来，等他带来内部资料，有了证据再抓他。"] = "Сначала найдите тайное место, где можно спрятаться, подождите, пока он принесет инсайдерские материалы, а затем поймайте его, как только у меня будут доказательства.",
    ["先生/女士，先生/女士？"] = "Сэр/госпожа, сэр/госпожа?",
    ["先生……"] = "Сэр...",
    ["先生……教堂里，有需要清扫的烟囱吗？"] = "Сэр... в соборе есть дымоходы, которые нужно почистить?",
    ["先生们，女士们。我宣布新的拳王已经诞生！"] = "Дамы и господа, объявляю, что родился новый чемпион по боксу!",
    ["先生，我是市政府派来的卫生监察员，请问下水道的出口在哪里？"] = "Сэр, я санитарный инспектор, посланный городским правительством. Могу я спросить, где выход из канализации?",
    ["先生，我还有问题需要询问。"] = "Сэр, у меня еще есть вопросы.",
    ["先生，来看看新鲜的丝瓜吧！"] = "Сэр, приходите посмотреть на эти свежие люфы!",
    ["先生，看在梅塞苔丝的面子上，我赠给你一句忠告！"] = "Сэр, ради Мерседеса, я дам вам совет!",
    ["先生，警局接到报案，休伯特·切斯议员家的马桶发生了异常故障？"] = "Сэр, в полицейский участок поступило сообщение о ненормальной неисправности туалета в доме советника Хьюберта Чейза?",
    ["先生，请您收回这句话，我虽然不是贵族，荣誉却同样不容侵犯。"] = "Сэр, пожалуйста, отзовите это заявление. Хоть я и не аристократ, моя честь столь же неприкосновенна.",
    ["先生，这条观光路线大约需要一小时。按时间算一小时2苏勒，超过后每刻加6便士。如果按里程，城里是一公里4便士。您看哪种合适？ "] = "Сэр, этот обзорный маршрут займет около часа. По времени это 2 суле в час, а за каждые последующие четверть часа — 6 пенсов. Если по расстоянию, то в городе 4 копейки за километр. Как вы думаете, что лучше?",
    ["先生，这，这和说好的不一样……"] = "Сэр, это не то, о чем мы договорились...",
    ["先生，需要帮助吗？"] = "Сэр, вам нужна помощь?",
    ["光记样子可不够，我这半个月都在研究不同光线下蛋壳的反光规律——早晨的斜射光和午后的顶光，会让同一枚蛋看起来截然不同。"] = "Просто запомнить внешний вид недостаточно. Последние полмесяца я изучал картины отражения яичной скорлупы при разном освещении. Косой свет утром и верхний свет днем ​​заставят одно и то же яйцо выглядеть совершенно по-другому.",
    ["克莱恩在匆忙间跳上了马车。"] = "Клейн торопливо вскочил в карету.",
    ["克莱恩早上特地去斯林太太那里买了新鲜出炉的蛋糕，尝尝看。"] = "Клейн рано утром специально сходил к миссис Слин за свежеиспечённым пирогом. Попробуйте.",
    ["入口在最高的地方。"] = "Вход находится на самой высокой точке.",
    ["全场陷入短暂的寂静，随即……"] = "Вся сцена погружается в недолгую тишину, а затем...",
    ["全廷根肠胃的守护者——"] = "Хранитель желудков всего Тингена...",
    ["全抓了？你这人不会赚钱，难怪生意做不走。"] = "Всех поймали? Ты не умеешь зарабатывать, неудивительно, что дело не идёт.",
    ["全抓光了，老鼠没了，谁还在意？你那生意做一次就到头了。"] = "Всех выловили, крыс больше нет, кому теперь есть дело? Твоё дело закончится после одного раза.",
    ["全职女儿。"] = "Полноценная дочь.",
    ["八十！八十！"] = "Восемьдесят! Восемьдесят!",
    ["兰斯特公爵、索顿公爵、米勒子爵……他们送来昂贵的礼物，在各种场合纠缠我。"] = "Герцог Ланстер, герцог Сотон, виконт Миллер... они присылают дорогие подарки и приставают ко мне по разным поводам.",
    ["兰斯特公爵，您弄疼我了……"] = "Герцог Ланкастер, вы меня обидели...",
    ["关于这场仪式的内容，我不做太多介绍，很快您就可以观看整个过程。"] = "Что касается содержания этого ритуала, я не буду вдаваться в подробности. Совсем скоро вы сможете наблюдать за всем процессом.",
    ["关你什么事？这家伙是我……是我买下来的，我想干什么，就干什么！"] = "Что тебе до этого? Этот парень... куплен мной, я могу делать все, что захочу!",
    ["兴奋。光是想象您读信时的表情……我就浑身发热。"] = "Взволнованный. Просто представив выражение твоего лица, когда ты читаешь письмо... мне становится жарко и тревожно.",
    ["其实也没怎么跑，只是演一演，嘿嘿。"] = "На самом деле, я особо не бегал, просто играл, хе-хе.",
    ["其实作为剧作家，在创作时陷入情绪波动是很正常的，但是像老师这样严重的癔症，真是从未听说过。"] = "Вообще-то, для драматурга нормально испытывать эмоциональные колебания во время творчества, но о такой сильной истерике, как у учителя, я еще не слышал.",
    ["其实到这一段后会进位面并冲出一堆狗来汪汪汪咬你，但因为功能还没好所以先写在这里看一下，看到这句话你就当作已经被狗咬死了吧！"] = "Собственно, после этого отрезка вы зайдете в самолет и к вам бросится стая собак, которые будут вас лаять и кусать, но так как функция еще не готова, то пишу ее пока здесь. Если вы видите это предложение, просто предположите, что вас уже загрызли собаки!",
    ["其实我二十五岁之后才知道，原来我们家在贝克兰德有好几处房产，家里人从来不喝廉价咖啡，出门走两步就是秩序之钟。"] = "На самом деле я только в двадцать пять узнал, что у нашей семьи есть несколько объектов недвижимости в Баклунде, и моя семья никогда не пьет дешевый кофе, а всего в двух шагах от дома есть Часы Порядка.",
    ["其实我们没有正式委托过他们，也付不起委托金……但他们都在我们需要的时候帮了大忙，我们只想表达一点心意。"] = "На самом деле, мы официально их не заказывали и не можем позволить себе комиссионные... но все они нам очень помогли, когда нам это было нужно, и мы просто хотим выразить немного своего сердца.",
    ["其实我是阿霍瓦郡警察厅的便衣警员，有人说这边出现了连环凶案的杀手，我来抓捕。"] = "На самом деле я детектив под прикрытием из полицейского управления округа Авва. Кто-то сообщил, что в этом районе находится серийный убийца, и я здесь, чтобы произвести арест.",
    ["其实，我丈夫去世后，我一度以为自己的心也死了。"] = "На самом деле, после того как мой муж скончался, я однажды подумала, что мое сердце тоже умерло.",
    ["其实，我是个<P_Yellow>男人</>……一个变成<P_Yellow>魔女</>的男人。"] = "На самом деле я <P_Yellow> мужчина</>...человек, который стал <P_Yellow> ведьмой</>.",
    ["具体计划是什么？"] = "Каков конкретный план?",
    ["再不滚，我把你这破扫帚折了。"] = "Если не заблудишься, я сломаю твою сломанную метлу.",
    ["再听到“我的猫趴在打字机上不让我写作”这种糟糕的借口，我真的会忍不住给编辑发电报，举报她过去所有的拖稿理由。"] = "Если я снова услышу это ужасное оправдание «моя кошка лежит на пишущей машинке и не дает мне писать», я действительно не смогу не отправить телеграмму редактору, чтобы сообщить обо всех ее прошлых оправданиях за срыв сроков.",
    ["再告诉您一个秘密。那晚吻了您之后，我一个人又喝了三杯温热的酒。"] = "Открою вам еще один секрет: в тот вечер, поцеловав вас, я в одиночестве выпил еще три бокала подогретого вина.",
    ["再次感谢您的慷慨！ 和我一起乘火车前往家园吧！"] = "Еще раз спасибо за вашу щедрость! Поехали со мной на поезде к нам домой!",
    ["再深一点，根才扎得稳！"] = "Глубже, чтобы корни могли укрепиться!",
    ["再见啦，温暖的{{先生|女士}}！"] = "До свидания, теплый {{мистер|мисс}}!",
    ["再说一句试试？！"] = "Скажи это еще раз, если осмелишься?!",
    ["写完那个写这个，写完这个写那个……狗屎，写到什么时候是个头……"] = "Пишу это после этого, пишу это после этого... черт, когда же это когда-нибудь закончится...",
    ["冰山中将的船？我听过一些传闻。"] = "Корабль Айсберг-Адмирала? Я слышал некоторые слухи.",
    ["冷静点，女士。你家在哪里？"] = "Успокойтесь, мисс. Где твой дом?",
    ["冷静！想想你的使命！你来到这里是为了什么！"] = "Успокойся! Вспомни о своей миссии! Зачем ты пришел сюда?!",
    ["准备好了，动手吗？"] = "Готовы, сделаем ход?",
    ["准备好接受挑战了吗？"] = "Готовы принять испытание?",
    ["几十年前，我从我的老师那里学会了所有传统戏剧的技巧，现在，我也把这些教给我的学徒。"] = "Несколько десятилетий назад я перенял все тонкости классического театрального мастерства у своего учителя, а ныне передаю их своим подмастерьям.",
    ["几天后——"] = "Несколько дней спустя—",
    ["几天后。"] = "Несколько дней спустя.",
    ["几年前没有机会，也没有勇气来看他走过的这条路。"] = "Несколько лет назад у меня не было ни возможности, ни смелости взглянуть на путь, который он прошел.",
    ["凯尔文，西迦女士很喜欢你的礼物，不过她说自己现在可算不上什么“大作家”——她最近一篇稿子刚被《廷根日报》的编辑退了回来，正发愁呢。"] = "Кельвин, госпоже Сиге очень нравится ваш подарок, но она сказала, что сейчас ее нельзя считать «великим писателем» — ее последняя рукопись была только что отклонена редактором «Тинген Дейли», и она очень этим обеспокоена.",
    ["凯尔文？那个机灵但有点莽撞的小伙子。看来那个平安符咒派上用场了，没事就好，这是？ "] = "Кельвин? Этот умный, но немного безрассудный молодой человек. Кажется, предохранительный талисман пригодился. Хорошо, что с ним все в порядке. Это?",
    ["凯瑟琳的孩子和史密斯先生没有关系，她心里有一直忘不了的初恋……"] = "Ребенок Кэтрин не имеет ничего общего с мистером Смитом; в ее сердце есть первая любовь, которую она никогда не сможет забыть...",
    ["出来了还不高兴，需要我把你塞回去吗？"] = "Выбрался — и все равно недоволен? Может, запихнуть тебя обратно?",
    ["出来！我知道你躲在里面！"] = "Публично заявить! Я знаю, что ты там прячешься!",
    ["出现了新线索……奇怪的琴声，还有济贫院的尸体……"] = "Появилась новая подсказка... странная музыка гармошки и труп в богадельне...",
    ["出门在外当打手，看家护院做保镖，都是非常可靠的选择！"] = "Будь то бандит, когда вы находитесь вне дома, или телохранитель, защищающий ваш дом, все это очень надежный выбор!",
    ["切，趁早滚远点，我们不想看到你。"] = "Тц, заблудись, пока можешь. Мы не хотим тебя видеть.",
    ["刚刚“开门”的时候，我听到了狗叫一样的声音，原来是这头狒狒，可恶！"] = "Когда я только что использовал «Открытую дверь», я услышал звук, похожий на лай собаки; это оказался этот бабуин, блин!",
    ["刚刚我看到了……你也用占卜？ "] = "Я только что увидел... ты тоже гадаешь?",
    ["刚刚是我鲁莽了，今天吃得很开心，帮我谢谢库克！"] = "Я только что был безрассуден. Мне сегодня понравилась еда; пожалуйста, поблагодари Кука от меня!",
    ["刚刚有个怪物，我差点就没命了！你事先可没说有这个！"] = "Только что был монстр, я чуть не погиб! Вы не упомянули, что он будет!",
    ["刚刚的一切……是梦……"] = "Всё сейчас... было сном...",
    ["刚才说的这些，都记住了吗？"] = "Ты помнишь все, что я только что сказал?",
    ["刚那里人多，来这边说。"] = "Там было слишком много народу, отойдем сюда.",
    ["初次见面，容我自我介绍一下，我是本校学术诚信办公室的萨姆，正在调查一起性质恶劣的<P_Yellow>考试舞弊案</>。"] = "Приятно познакомиться, позвольте представиться. Я Сэм из школьного отдела академической честности, и я расследую серьезный случай мошенничества на экзамене <P_Yellow> с </>.",
    ["初级评鉴已经全部通过，你对穿搭的理解比大多数人都要出色。你已获取中级会员的资格，去试试更高层次的品鉴吧。"] = "Вы прошли все первичные оценки. Вы разбираетесь в одежде лучше, чем большинство людей. Вы получили квалификацию промежуточного членства. Идите и попробуйте оценки более высокого уровня.",
    ["别……别说话！"] = "Не... не говори!",
    ["别再叫我陛下了！该死，我差点忘了……我的任务是找到并消灭你这个\n“魔女”！ "] = "Хватит звать меня Вашим Величеством! Проклятье, я чуть не забыл... Моё задание — найти и уничтожить тебя, эту «Демоницу»!\n",
    ["别动！老实点！"] = "Не двигайся! Вести себя!",
    ["别害怕，我陪你一起回去。"] = "Не бойся, я провожу тебя обратно.",
    ["别废话！一个月五镑，拿来！"] = "Не говорите глупостей! Пять фунтов в месяц, сдайте!",
    ["别怕，来我这里……"] = "Не бойся, приди ко мне...",
    ["别急，茜安指挥，库克和我照做，我们一起把这道菜做出来！"] = "Спокойно: Сиан командует, а мы с Куком делаем. Вместе мы приготовим это блюдо!",
    ["别想进来……"] = "Даже не думай заходить...",
    ["别慌，集中精神想穿墙的感觉！"] = "Не паникуйте, сконцентрируйтесь и подумайте об ощущениях, когда вы проходите сквозь стену!",
    ["别抗拒，她在等你。"] = "Не сопротивляйся, она ждет тебя.",
    ["别抵赖了，看看花台上是什么？"] = "Не отрицайте, посмотрите, что стоит на подставке для цветов?",
    ["别担心，咖啡厅有一本《灵界生物指南》，里面记录了人头鸟妖的详细资料，就在那边。"] = "Не волнуйся, в кафе есть «Путеводитель по существам Мира Духов», там подробно описаны гарпии, он вон там.",
    ["别担心，善良的野生非凡者不应被关在地下。"] = "Не волнуйтесь, добрые дикие Потусторонние не должны быть заперты под землей.",
    ["别担心，我去帮你追回来，他往哪个方向去了？"] = "Не переживай, я догоню его и все верну. В какую сторону он побежал?",
    ["别担心，我可能知道为什么，你还有多余材料吗？我们一起改良一下配方？"] = "Не волнуйтесь, возможно, я знаю почему. Есть ли у вас дополнительные материалы? Давайте вместе улучшим формулу?",
    ["别担心，施佩尔先生说他从罗塞尔大帝的手稿得到了灵感，准备创作出更爽更刺激的故事。"] = "Не волнуйтесь, г-н Шпеер сказал, что его вдохновила рукопись императора Розеля, и он готовится создать более захватывающую и стимулирующую историю.",
    ["别担心，这条路我很熟很熟，闭上眼睛都能走。"] = "Не волнуйтесь, я знаю эту дорогу очень, очень хорошо. Я мог бы пройти его с закрытыми глазами.",
    ["别激动，至少你的屁股还在。"] = "Не волнуйтесь. По крайней мере, твоя задняя часть все еще цела.",
    ["别灰心，我之前看到金秋湖的商店有卖弗萨克烈酒，至少烈酒的问题能解决。 "] = "Не расстраивайтесь. Ранее я видел, что в магазине на озере Золотая Осень продаются спиртные напитки Фейсак. По крайней мере, проблему крепких спиртных напитков можно решить.",
    ["别理这个人，咱们走！"] = "Не обращайте внимания на этого человека, поехали!",
    ["别白费力气，你因诈骗罪被逮捕了！"] = "Не тратьте силы, вы арестованы за мошенничество!",
    ["别看我现在这样，其实祖上很风光，我们家族……唔……"] = "Не смотри на меня так сейчас; на самом деле мои предки были очень славными. Наша семья... хм...",
    ["别管这些，莉莉脾气很倔，问就说抄近路，走得快。"] = "Не волнуйся об этом, у Лили упрямый характер. Если вы спросите, она просто скажет, что выбирает короткие пути и ходит быстро.",
    ["别计划了。"] = "Перестаньте планировать.",
    ["别说对不起，烟囱已经疏通了，工具没了也可以再找，人没事才是最重要的。"] = "Не говори «извини». Дымоход уже очищен, и инструменты можно заменить. Ваша безопасность – это самое главное.",
    ["别走，“焦糖炸弹”……"] = "Не уходи, «Карамельная бомбочка»...",
    ["别问我，今天是我最后一天上班，在珠宝店干没前途。"] = "Не спрашивайте меня, сегодня мой последний день на работе. У работы в ювелирном магазине нет будущего.",
    ["别问我，我当时正伪装成维修工进行调查，结果突然晕倒，突然出现在这里，我什么都不知道。"] = "Не спрашивай меня. Я был замаскирован под ремонтника, проводящего расследование, когда внезапно потерял сознание и появился здесь. Я ничего не знаю.",
    ["到了！你看，墓碑很新，我一直打理得很好。"] = "Мы здесь! Посмотрите, надгробие совсем новое. Я всегда поддерживал его в хорошем состоянии.",
    ["到底……到底要怎么样，才能让故事继续……"] = "Как... как мне, черт возьми, продолжить историю...",
    ["到底丢到哪里了……"] = "Где же я его потерял...",
    ["到时候我会提前把东西放在<P_Yellow>花台</>上面，你按时来取。"] = "Я заранее разложу предметы на подставку для цветов <P_Yellow> </>, чтобы вы пришли за ними вовремя.",
    ["前天夜晚，一次无比普通的如厕后。"] = "Позапрошлой ночью, после самого обычного похода в уборную.",
    ["前往黑荆棘安保公司门外？好古怪的留言，还没有署名……"] = "Подойти ко входу в охранную компанию Чёрный Чертополох? Какое странное сообщение, а оно даже не подписано...",
    ["前提是，她得给我这个原谅她的机会。"] = "То есть при условии, что она даст мне возможность простить ее.",
    ["力气不小，可惜用错了地方。"] = "У тебя есть сила, но, к сожалению, ты используешь ее не там, где нужно.",
    ["办事路过。信收到了，弗莱队长让我给你说明一下。"] = "Я здесь по делам мимоходом. Письмо получено, капитан Фрай попросил меня все тебе объяснить.",
    ["加入值夜者小队，在廷根参与处理非凡案件……也许是一个不错的选择。"] = "Присоединиться к отряду «Ночные ястребы» и участвовать в рассмотрении чрезвычайных дел в Тингене… возможно, это хороший выбор.",
    ["加油啊神使大人……"] = "Так держать, Лорд Посланник...",
    ["动、动手？动什么手？偷窃还是抢劫？"] = "Сделать, сделать шаг? Что за ход? Кража или грабеж?",
    ["动手！"] = "Сделайте это!",
    ["勇敢的鲱鱼以优雅的姿态凝视着星空，仿佛在回忆狂暴海上的风浪。"] = "Отважная селедка в изящной позе смотрит на звездное небо, словно напоминая ветер и волны Берсеркового моря.",
    ["医生，只要你能治好我的病，多少钱我都愿意出。"] = "Доктор, если вы сможете вылечить мою болезнь, я готов заплатить любую сумму денег.",
    ["医生，拜托你，想想办法吧！"] = "Доктор, пожалуйста, подумайте над решением!",
    ["十分感谢，教会和我都会铭记你的帮助。你可以直呼我的名字，“烈焰”达尼兹——糟糕，狗屎，我还在通缉令上 ，你不会举报我吧？"] = "Большое спасибо. И Церковь, и я будем помнить о вашей помощи. Можешь называть меня по имени «Пылающий» Даниц — ох, черт, черт, я все еще в розыске. Вы не будете сообщать обо мне, не так ли?",
    ["十镑？二十镑？哈哈，你还真是贪心……给你五十镑，马上给我滚，永远不要出现在我的面前！"] = "Десять фунтов? Двадцать фунтов? Ха-ха, ты очень жадный... Я дам тебе пятьдесят фунтов, уходи немедленно и никогда больше не появляйся передо мной!",
    ["十镑？二十镑？小子，你还真贪心……给你五十金镑，马上给我滚，永远不要出现在我的面前！"] = "Десять фунтов? Двадцать фунтов? Малыш, ты очень жадный... Я дам тебе пятьдесят золотых фунтов, уходи немедленно и никогда больше не появляйся передо мной!",
    ["南大陆并不避讳谈论这些奇怪生物，我在那见过一些，只是没想到这里也有。"] = "На Южном континенте не боятся говорить о подобных чудищах. Я встречал там парочку, но никак не думал обнаружить их здесь.",
    ["博物馆里的第三纪石雕，美则美矣，却再也听不见血脉的搏动。"] = "Каменные изваяния Третьей эпохи в музее хоть и прекрасны, но в них больше не услышать биения крови.",
    ["占卜一下马桶是不是入口吧。"] = "Стоит погадать, не является ли унитаз тайным входом.",
    ["占卜？哦，那只是帮我保持专注的旧习惯。"] = "Гадание? О, это просто старая привычка, которая помогает мне оставаться сосредоточенным.",
    ["卡住了？那正好，我时间多，可以慢慢看。"] = "Застрявший? Это прекрасно, у меня много времени, я могу смотреть медленно.",
    ["卡门恍然大悟，下一秒便从墙的另一面被“吐”了出来。"] = "Кармен внезапно это понимает, и в следующую секунду его «выплевывают» с другой стороны стены.",
    ["卡门把宝箱塞给你，火速离开了，背影充满了窘迫。"] = "Кармен пихает вам сундук с сокровищами и поспешно уходит со смущенной спиной.",
    ["卡门的下半身在他的惊叫中一闪而逝……"] = "Нижняя часть тела Кармен вспыхивает и исчезает среди его криков...",
    ["卡门被“噗”地一声推了出来，一屁股坐在地上，浑身是灰。"] = "Кармен вылетела с хлопком и приземлилась задом на землю, вся в пыли.",
    ["卡门身形一闪，像褪色的影子般从墙里渗了出来。"] = "Фигура Кармен мелькает, просачиваясь из стены, словно увядшая тень.",
    ["卡门，你试过带着活物穿墙吗？"] = "Кармен, ты пробовала пройти сквозь стену, неся на руках живое существо?",
    ["卡门，其实我对你是有一些失望的，当初把你从墙里拔出来，是希望你能拼一把，快速成长起来……"] = "Кармен, вообще-то я в тебе немного разочарован. Когда я вытащил тебя из стены, это было потому, что я надеялся, что ты сможешь выложиться на полную и быстро вырасти...",
    ["卡门，火车轨道上发“戏法大师”的晋升材料了！"] = "Кармен, рекламные материалы для \"Мастер Трикстер\" уже на железнодорожных путях!",
    ["卢娜衣物褪下，香肩半露。轻纱帷幔随风飘动，遮住了床上的身影。"] = "Одежда Луны соскользнула, полуобнажив ее благоухающие плечи. Полупрозрачные шторы развевались на ветру, скрывая фигуру на кровати.",
    ["卢娜！别再躲着我了！"] = "Луна! Хватит прятаться от меня!",
    ["卢娜，叫我卢娜。就像月亮属于天空，今晚的卢娜属于您。"] = "Луна, зови меня Луна. Как луна принадлежит небу, так и сегодняшняя Луна принадлежит тебе.",
    ["即便我们都老去了，那些约定依旧会以其他形式延续下去。 "] = "Даже когда мы состаримся, эти обещания продолжат жить в иных формах. ",
    ["厂里锅炉炸了。我工友就在我旁边……<P_Heart>（声音发抖）</>铁水浇下来，他半边身子都没了。但他没死透。他还抓着我的手，跟我说了几句话。"] = "Котел на заводе взорвался. Мой коллега был рядом со мной... <P_Heart> (Голос дрожит) </> Расплавленное железо лилось вниз, и половина его тела исчезла. Но он не был совсем мертв. Он все еще держал меня за руку и говорил мне несколько слов.",
    ["厕所也许是一个不错的餐饮场所……"] = "Туалет может быть хорошим местом для обеда...",
    ["原来你很早以前就认识他……为什么不告诉他？"] = "Значит, вы его давно знаете... Почему вы ему не сказали?",
    ["原来如此……他们还希望拍一张您和这个木雕的合影，那孩子特别想看到您收到它时的样子。"] = "Понятно... Они тоже надеялись сфотографировать тебя с этой резьбой по дереву; ребенку особенно хотелось увидеть вашу реакцию, когда вы его получили.",
    ["原来如此，矫健而有力的动作下，还隐藏了利爪，这就是——猫猫大摆拳！"] = "Вот оно что, под ловкими и мощными движениями скрываются острые когти — это же... Кошачий Могучий Взмах!",
    ["原来如此，确实是警察先生。说到可疑……刚刚我似乎听到有尖叫从那边传来。"] = "Я понимаю. Вы действительно полицейский. Кстати о подозрительности... Кажется, я только что услышал крик, доносившийся оттуда.",
    ["原来就是你，敢和猎龙帮作对的家伙。"] = "Так это был ты, парень, который осмелился выступить против банды охотников на драконов.",
    ["原来是这样，警官，请随我来。"] = "Я понимаю. Офицер, пожалуйста, следуйте за мной.",
    ["原来是这样，那——"] = "Вот оно что... Тогда...",
    ["原来那个叫奇异果……等等，你是谁？为什么会出现在这里？"] = "Итак, эту штуку назвали странным фруктом... Подожди, а ты кто? Почему ты здесь?",
    ["去吧。仪式即将开始。记住——锚定自己，别被深渊吞没。"] = "Идти. Ритуал вот-вот начнется. Помните: закрепите себя, не позволяйте бездне поглотить вас.",
    ["去吧，道奇。祝你一切顺利！"] = "Продолжай, Додж. Я желаю вам всего наилучшего!",
    ["去廷根的黑夜大教堂，祂的教宗——阿里安娜，在等你。"] = "Сходите в собор Святой Селены в Тингене; Ее Папа, Арианна, ждет вас.",
    ["去警局取回被骗的钱吧。"] = "Идите в полицейский участок и заберите украденные мошенниками деньги.",
    ["又出现了……这些字……"] = "Снова появились... эти слова...",
    ["又有一张纸条？"] = "Еще одна записка?",
    ["又缓缓垂下头来，让思绪飘向遥远的故乡。"] = "И медленно опустил голову, позволяя мыслям унестись к далекому родному городу.",
    ["又！到！黑！夜！"] = "Его! Ночь! Снова!",
    ["反驳的就是你，你这头因蒂斯猪！"] = "Я с тобой спорю, свинья Интис!",
    ["发生了什么事？他经常这样对你？"] = "Что случилось? Часто ли он обращается с тобой подобным образом?",
    ["发生什么事了？"] = "Что случилось?",
    ["发生什么事情了？"] = "Что произошло?",
    ["变成字的告解很多很多，可告解室很小很小，装不下它们，它们就会悄悄跑掉……"] = "Исповедей, обратившихся в слова, так много, а исповедальня такая крошечная, что не может вместить их все... вот они и сбегают тайком...",
    ["另一扇，你往后走几步就能看到。"] = "А другую увидишь, если сделаешь пару шагов назад.",
    ["另外，请原谅我的冒昧，女士。陛下的原话是——“真正的金子，不怕火的锤炼”。"] = "И ещё, пожалуйста, простите мою самонадеянность, миледи. Первоначальные слова Императора были такими: «Истинное золото не боится закалки огнем».",
    ["只不过——想要我出手，前提是看你的诚意足不足。"] = "Однако, если вы хотите, чтобы я действовал, необходимо убедиться, что ваша искренность достаточна.",
    ["只好牺牲一些令人愉悦的气泡了……"] = "Придется пожертвовать некоторыми приятными пузырьками...",
    ["只拿一点点，一点点就好……"] = "Просто возьми немного, немного, это нормально...",
    ["只是以为你们几个是我的熟人，看来是我认错了。"] = "Я просто думал, что вы, ребята, мои знакомые. Кажется, я ошибся.",
    ["只是工作……贴这儿能招揽更多客户。"] = "Это просто работа... размещение здесь привлечет больше клиентов.",
    ["只是昨晚？"] = "Только вчера вечером?",
    ["只是普通的纸条，没什么特别的……"] = "Обычные заметки, ничего особенного...",
    ["只是没想到，会有人愿意替一个扫地的出头。"] = "Я просто не ожидал, что кто-то захочет вступиться за уборщицу.",
    ["只有最强壮的人，才有资格占有贝儿小姐。"] = "Только самый сильный человек способен овладеть Мисс Белль.",
    ["只有这个。"] = "Только это.",
    ["只有这样，那些不听课的学生为了应付考试，才会在“内部资料”中学到一点点历史知识。"] = "Только так те студенты, что не слушают на лекциях, ради сдачи экзамена усвоят хоть крупицу исторических знаний из этих «внутренних материалов».",
    ["只能先出去看看了。"] = "У меня нет другого выбора, кроме как пойти и посмотреть.",
    ["只要不用再装那些告解，去装什么都行，怎么都行……<P_Heart>（怯生生）</> 女神……会宽恕我的想法吗？"] = "Пока мне больше не придется хранить эти признания, я буду хранить что угодно, что угодно... <P_Heart> (робко) </> Простит ли Богиня мои мысли?",
    ["只要不让他们仔细检查棺材，目的就达成了。总比什么都不做更有希望。"] = "Если они не станут тщательно осматривать гроб, цель будет достигнута. Это всё же лучше, чем ничего не делать.",
    ["只要主人晋升成为炼金术士，我们就能获得一切！"] = "Как только господин продвинется до Алхимика, мы получим все сполна!",
    ["只要你开口，哪怕脱掉全身的毛，变成一只下锅的鹌鹑，我也心甘情愿。"] = "Если вы спросите, даже если мне придется сбросить всю шерсть и превратиться в перепела, готового к горшку, я бы сделал это охотно.",
    ["只要你能让他们对正门松懈，我就能抓住这个机会。"] = "Если тебе удастся отвлечь их охрану у главных ворот, я не упущу этот шанс.",
    ["只要爸爸真的做到，我就不生爸爸的气了。"] = "Пока папа действительно это делает, я больше не буду на него злиться.",
    ["叫吧，大声叫吧，就算叫破喉咙，也不会有人——"] = "Кричи, кричи так громко, как только можешь. Даже если ты будешь кричать до тех пор, пока у тебя не перебьется горло, никто не будет…",
    ["可、可是……那你怎么可能真的分辨出来？ "] = "Н-но... тогда как же их отличить?",
    ["可不是吗！她们又哭又笑地聊了一夜，我就听见斯嘉丽大喊了一声“那就让山姆见鬼去吧！”，和梅兰妮一起坐上马车离开了。"] = "Держу пари! Они проговорили всю ночь, плача и смеясь. Я только что услышал крик Скарлетт: «Тогда отпусти Сэма к черту!», и она уехала с Мелани в карете.",
    ["可以把我送到列车站吗？我……快赶不上车了。"] = "Вы можете отвезти меня к железнодорожной станции? Я... я собираюсь опоздать на поезд.",
    ["可以睁眼了。"] = "Теперь ты можешь открыть глаза.",
    ["可以，那就麻烦你记录下这个时刻。"] = "Хорошо, тогда, пожалуйста, запишите этот момент.",
    ["可你知道，不会有新的帽子了。"] = "Но знаешь, новой шапки не будет.",
    ["可你身上……没有人类的气息……"] = "Но у тебя... нет человеческого запаха...",
    ["可她拒绝了我，还把戒指朝我扔过来……我当时胸口一痛，回过神来戒指已经不见了！"] = "Но она отвергла меня и бросила в меня кольцо... В этот момент я почувствовал боль в груди, а когда очнулся, кольца уже не было!",
    ["可库克买来章鱼后，我还是无法克服烹饪同类的心理障碍，只能用别的肉替代。"] = "Но после того, как Кук купил осьминога, я все еще не мог преодолеть психологический барьер приготовления ближнего, поэтому мне пришлось использовать вместо него другое мясо.",
    ["可怕！他们看见老鼠，简直就像见到了仇人！"] = "Ужасно! Они видят мышь так, словно увидели заклятого врага!",
    ["可怜的水手，在自己的订婚仪式上被警察突然逮捕，扔进了不见天日的监牢……"] = "Бедный моряк был внезапно арестован полицией во время собственной помолвки и брошен в темную, темную тюрьму...",
    ["可恶……下面应该怎么办……"] = "Блин... что мне теперь делать...",
    ["可恶的开膛手杰斯，今晚我将为你的凶行画上句号！"] = "Проклятый Потрошитель Джейс, сегодня ночью я положу конец твоим злодеяниям!",
    ["可恶，难道真的是他……时间紧迫，我先去那边看看，谢谢你提供的消息！"] = "Черт возьми, неужели это действительно он... Время уходит. Я пойду проверю там. Спасибо за информацию!",
    ["可惜了，如果能重新调整一下细节，也许会是另一种结果。"] = "Жаль. Если бы подправить пару деталей, исход мог быть совсем иным.",
    ["可惜，我还以为有机会赚一笔呢。"] = "Жаль, а я-то думал, что смогу неплохо заработать.",
    ["可我不甘心……我们那么辛苦才凑齐了路费。"] = "Но я не смирилась... Мы так старались накопить на дорогу.",
    ["可我患了绝症，生命即将结束……"] = "Но у меня неизлечимая болезнь, и моя жизнь подходит к концу...",
    ["可我还有份资料……有关各种正神教会典籍和公文的……"] = "Но у меня все еще есть документ... касающийся Священных Писаний и официальных документов различных православных церквей...",
    ["可是……"] = "Но...",
    ["可是……在福音庇护下，我的政府雇员考试的确高分通过了……"] = "Но... под покровом Евангелия я действительно сдал экзамен на государственного служащего на высокие оценки...",
    ["可是大海很危险……据说海上最可怕的，甚至不是狂风暴雨，而是那些看不见的东西。 "] = "Но море опасно... Говорят, что самое страшное на море - это даже не бури, а те невидимые существа.",
    ["可是工厂门口排满了铁十字街来的新伙计，我们不努力的话，随时可能会失去这份工作。"] = "Но у ворот завода полно новых работяг с улицы Железного Креста. Если не будем стараться, в любой миг потеряем эту работу.",
    ["可是老板说要把棺材送进火葬炉——"] = "Но хозяин сказал отправить гроб в печь крематория...",
    ["可是这里的确没有路牌，也许是被什么破坏了。"] = "Но дорожного знака здесь действительно нет. Возможно, его чем-то разрушили.",
    ["可是，我应该怎么找到她呢？"] = "Но как мне ее найти?",
    ["可是，老大说……"] = "Но босс сказал...",
    ["可疑的人？说实话，很少有人半夜在这条路出现，你看起来很面生，倒不如说你更像是那种可疑的人。"] = "Подозрительные личности? Честно говоря, глухой ночью здесь почти никто не ходит. Лицо у тебя незнакомое, так что ты сам больше всех похож на подозрительного типа.",
    ["可老汤姆说他亲眼见过！黄金梦想号经过时，连汹涌的海浪都会静止！"] = "Но Старый Том сказал, что видел это собственными глазами! Когда «Золотая мечта» проходила мимо, даже бушующие морские волны затихали!",
    ["可能是廷根章鱼的产地和南方不同，所以味道不完全一样。"] = "Возможно, происхождение осьминога Тинген отличается от южного, поэтому и вкус не совсем тот.",
    ["可能是我一时疏忽，我这两天感冒了。"] = "Должно быть, это моя оплошность, я эти пару дней простужен.",
    ["可要是赚不到钱，杰姆会死的。{{先生|女士}}，他会死的，我该怎么办……"] = "Но если я не смогу зарабатывать деньги, Джем умрет. {{ Mr. | Ms. }}, он умрет, что мне делать...",
    ["可这种天气上山很危险，而且积雪的路很不好走。"] = "Но подниматься на гору в такую ​​погоду очень опасно, а по заснеженной дороге очень трудно идти.",
    ["可长大就意味着钻不进那些小烟囱了。除了洗烟囱，我们什么都不会呀，雷克斯先生不会白养我们，长大了就意味着……没有用了。"] = "Но взросление означает, что мы больше не можем помещаться в эти маленькие дымоходы. Мы больше ничего не умеем, кроме чистки дымоходов. Мистер Рекс не будет поддерживать нас бесплатно, а взросление означает... быть бесполезным.",
    ["史密斯太太的车祸是故意的，她主动撞到马车轮上，想换点补偿留给自己的孩子。史密斯先生也是为躲私生子的抚养费才回家装好人……"] = "Автомобильная авария миссис Смит была преднамеренной; она бросилась в колеса кареты, надеясь получить какую-нибудь компенсацию за своих детей. Мистер Смит также вернулся домой только для того, чтобы сыграть хорошего парня, чтобы не платить алименты на своего внебрачного ребенка...",
    ["叽里咕噜说什么呢，我怎么一点没听懂？"] = "Чего ты там бубнишь? Я вообще ничегошеньки не понял!",
    ["吁——"] = "Бу-",
    ["各位都清楚，我们的业务非常特殊，但接下来这件东西，我保证谁也没有见过。"] = "Все знают, что наш бизнес особенный, но я гарантирую, что этот следующий товар никто никогда не видел.",
    ["各位，我现在要使用一些机密探案方式，请各位不要打扰。"] = "Ребята, мне нужно сейчас использовать некоторые конфиденциальные методы расследования. Пожалуйста, не беспокойте меня.",
    ["同一个地方……所以“孤独不可怕”那句话……是他自己的体会。谢谢您！ "] = "То же самое место... так что фраза \"одиночество не страшно\"... была его собственным опытом. Спасибо!",
    ["同时，他的博学多识和风度翩翩也让因蒂斯的贵族们折服，结识了许多上流社会的大人物。"] = "В то же время его эрудиция и изящная манера поведения покорили дворян Интиса, позволив ему завести знакомства со многими видными деятелями высшего общества.",
    ["同时，这也能让我学习更多人类的说话艺术。"] = "В то же время это позволяет мне больше узнать о человеческом искусстве разговора.",
    ["后厨不能进人，不好意思，请你们离开。"] = "Никому не разрешается находиться на кухне, извините, пожалуйста, уходите.",
    ["后来你们一起将杰斯送进了医院。好在他只是昏迷过去了，并没有受到严重伤害。\n布朗团长很欣赏你的演技，他认为你是未来剧团的璀璨明星，邀请你加入他们。\n但你拒绝了这番好意，毕竟，你只是一个路过的有正义感的普通市民。"] = "Позже вы вместе доставили Джесса в больницу. К счастью, он просто потерял сознание и не получил тяжёлых травм.\nРуководитель труппы Браун пришёл в восторг от твоей актёрской игры: он счёл тебя будущей сияющей звездой труппы и пригласил присоединиться к ним.\nНо ты вежливо отклонил предложение — в конце концов, ты лишь случайный неравнодушный горожанин с обострённым чувством справедливости.",
    ["后来的一个冬天，有人从远方来，把一小块太阳放进她手心。"] = "Позже, однажды зимой, кто-то пришел издалека и положил ей на ладонь маленький кусочек солнца.",
    ["后来，听说那个年轻人真的和收银姑娘在一起了。\n他逢人就说，那天有个奇怪的人给他唱了首歌，难听极了，但他确实不害怕了。"] = "Позже говорили, что тот юноша и впрямь начал встречаться с девушкой за кассой.\nОн каждому встречному рассказывал, как в тот день странный незнакомец спел ему песню: пел ужасно фальшиво, но страх как рукой сняло.",
    ["后面是厨房，二位是不是迷路了？"] = "Кухня находится сзади. Вы двое потерялись?",
    ["后面，我被怪物吞下了……?"] = "Позже меня проглотило чудовище...?",
    ["向“愚者”先生祈祷。祂会指引你接下来的路。"] = "Помолитесь господину «Шуту». Он укажет вам путь вперед.",
    ["吓死我了，原来奶奶是想捡垃圾。"] = "Ты напугал меня до смерти, поэтому бабушка просто хотела собрать мусор.",
    ["听清楚了，学校北边有个废弃很久的<P_Yellow>报刊亭</>，窗户是用报纸糊住的。"] = "Слушайте внимательно, на северной стороне школы стоит давно заброшенный газетный киоск <P_Yellow> </>, а окна заклеены газетами.",
    ["听男仆说，早上有修理工过来，他有诊断出故障理由吗？"] = "Я услышал от камердинера, что сегодня утром приходил ремонтник. Выяснил ли он причину неисправности?",
    ["听着，卢娜。我是罗塞尔·古斯塔夫，我征服过王国，改变过历史。 "] = "Послушай, Луна. Я Розель Густав, я покоряла королевства и меняла историю.",
    ["听着，这间屋子不干净，“它”就在外面。"] = "Слушай, в этой комнате грязно. «Оно» находится прямо снаружи.",
    ["听着，道奇，天黑之前没收拾完的话……给我等着！"] = "Слушай, Додж, если ты еще не закончил уборку до наступления темноты... подожди!",
    ["听说……"] = "Я слышал...",
    ["听说她船上有个图书馆，里面的书会自己翻页！"] = "Я слышал, что на ее корабле есть библиотека, и книги внутри сами по себе переворачивают страницы!",
    ["听说最近常有人用马桶藏匿物品，会不会是因为扔东西堵住了？"] = "Я слышал, что люди часто используют туалет, чтобы спрятать вещи. Может ли это быть потому, что его блокируют бросанием вещей?",
    ["听说过一些，我记得他是个珠宝匠……"] = "Я слышал о нем. Я помню, он был ювелиром...",
    ["听说这内部资料卖的比印刷成本还便宜，我还以为是骗子，没想到竟然真的有用。"] = "Я слышал, что эти инсайдерские материалы продавались дешевле, чем стоимость печати. Я думал, что это мошенничество, но не ожидал, что они действительно принесут пользу.",
    ["听说这家诊所药到病除。"] = "Я слышал, что эта клиника очень эффективна.",
    ["听说这里有人想看小丑？"] = "Я слышал, кто-то здесь хочет увидеть клоуна?",
    ["听说龙肉是辣味的，真的吗？"] = "Говорят, мясо дракона острое, это правда?",
    ["听起来不是什么困难的事情。"] = "Звучит не так уж и сложно.",
    ["听起来不错，怎么体验？"] = "Звучит отлично. Как мне это пережить?",
    ["听起来不错，那看来我们是时候回去了。"] = "Звучит отлично. Кажется, нам пора возвращаться.",
    ["听起来的确很奇怪。"] = "Это звучит очень странно.",
    ["听，它又来了！快……必须堵住门！"] = "Слушай, оно снова приближается! Быстро... надо заблокировать дверь!",
    ["呃……"] = "Эм-м-м...",
    ["呃……可以这么说。请问发生了什么？"] = "Э-э... можно и так сказать. Позвольте спросить, что случилось?",
    ["呃……对不起，我从小就很胆小。"] = "Э-э... извини, я был робким с детства.",
    ["呃……特别是啤酒！恶龙酒吧的啤酒已经到了难以下咽的程度！"] = "Э-э... особенно пиво! Пиво в баре ««Злой Дракон»» стало несъедобным!",
    ["呃……贝克兰德？"] = "Э-э... Бэкланд?",
    ["呃……这些旧衣服，实在是不够体面，不管是去中央广场逛逛，还是去教堂祷告……"] = "Э-э... эта старая одежда действительно недостаточно прилична, будь то прогулка по Центральной площади или поход в церковь помолиться...",
    ["呃……这要求好奇怪……"] = "Э-э... эта просьба такая странная...",
    ["呃……钢琴声？"] = "Э-э... фортепианная музыка?",
    ["呃……面板店的面包……太贵了，我们甚至买不起……缝衣针，还有别的什么……"] = "Э-э... хлеб из панельного цеха... слишком дорогой, нам его даже не по карману... иголки швейные, и что еще...",
    ["呃，我的头——"] = "Ох, моя голова—",
    ["告解五分钟，闲聊三小时。<P_Heart>（伸懒腰）</> 我居然还听了三个小时……"] = "Пять минут признаний, три часа сплетен. <P_Heart> (Растягивается) </> На самом деле я слушал три часа...",
    ["呜……"] = "Ууу...",
    ["呜呜……{{先生|女士}}，我该怎么办？"] = "Соб... {{Mr.|Ms.}}, что мне делать?",
    ["呜呜，我会报答你的，但是先让我回去洗裤子吧……"] = "Ууууу, я отплачу тебе, но позволь мне сначала вернуться и постирать штаны...",
    ["呵……您赢了。但您永远忘不了……昨晚的滋味。"] = "Хех... ты выиграл. Но ты никогда не забудешь... вкус прошлой ночи.",
    ["呵呵，你不懂，你这种小喽啰根本不懂！"] = "Ха-ха, тебе не понять! Такой мелкой сошке, как ты, этого никогда не понять!",
    ["呵呵，这些少爷，说些好话，就能把工厂里的女孩们骗得晕头转向。"] = "Хе-хе, эти молодые мастера, просто сказав несколько приятных слов, могут обмануть девушек на фабрике до головокружения.",
    ["呵，现在什么人都敢妄谈艺术。"] = "Хех, нынче любой осмеливается говорить чушь об искусстве.",
    ["呼——舒服多了。"] = "Уф, намного лучше.",
    ["呼……终于停了，感觉脑子清醒多了。"] = "Фух... наконец-то прекратилось, голова стала намного яснее.",
    ["呼！来个猪油炸蔬菜、伊斯奥、两个猪肉馅饼、两杯甜冰茶。"] = "Уф! Дайте мне жареные овощи на сале, Исао, два пирога со свининой и два стакана сладкого чая со льдом.",
    ["呼，呼……得救了。谢、谢谢你啊……"] = "Уф, уф... Я спасен. Т-спасибо...",
    ["呼，看来成功瞒过去了！"] = "Уф, похоже, нам удалось ее обмануть!",
    ["和墓园那里的感觉类似，有什么东西藏在这里。"] = "Подобно ощущению на кладбище, здесь что-то спрятано.",
    ["和罗塞尔有关的女士……不可抗拒的魅力……难道……"] = "Дама, родственница Розеллы... непреодолимое обаяние... неужели...",
    ["和野兽？"] = "А Зверь?",
    ["咪咪，喵喵……今天又没逮到老鼠？"] = "Мими, мяу-мяу... Опять сегодня мышку не поймал?",
    ["咳、咳，来源不重要……总有一天，我要扬帆起航，去追寻海上的宝藏。悬赏我的赏金该是多少镑呢？哈哈哈……"] = "Кхе-кхе... Источник не важен... Настанет день, и я подниму паруса, чтобы отправиться на поиски морских сокровищ! Интересно, сколько фунтов назначат за мою голову? Ха-ха-ха...",
    ["咳咳……{{先生|女士}}，我回来了，我到出口了……"] = "Кхе-кхе... {{сэр|мадам}}, я вернулся, я у самого выхода...",
    ["咳咳……休想让我们出卖兄弟！"] = "Кхм-кхм... Даже не думай, что мы предадим братьев!",
    ["咳咳……我没事的！可是，刚刚我敲开堵死的煤灰的时候，烟就涌了出来，我只能赶紧往回……"] = "Кашель, кашель... Я в порядке! Но сейчас, когда я разбил застрявшую копоть, дым повалил наружу, и мне пришлось торопиться назад...",
    ["咳咳咳——"] = "Кашель, кашель, кашель —",
    ["咳！没问题，只是这活儿挺麻烦，我们得先做点准备，您这边……"] = "Кхм! Без проблем, только работа хлопотная, нам надо сперва подготовиться, а вы пока...",
    ["咳，有什么事吗，{{PlayerName}}？"] = "Кхм, что-то случилось, {{PlayerName}}?",
    ["哇——！恭喜你，美丽的小姐，相信它一定会给你意想不到的回报。"] = "Ух ты-! Поздравляю, прекрасная леди. Я верю, что это обязательно принесет вам неожиданную прибыль.",
    ["哇呀——"] = "А-а-ай! —",
    ["哇！维克多学长说得对，这真是太酷了！"] = "Ого! Старшекурсник Виктор был прав, это просто потрясающе!",
    ["哇！这么多钱，我要是唐泰斯的话，嘿嘿……嘿嘿……"] = "Ух ты! Столько денег, если бы я был Дантесом, хе-хе... хе-хе...",
    ["哇，他看起来挺温和的嘛！不知道西迦女士会不会也这么亲切…… "] = "Вау, он кажется довольно нежным! Интересно, будет ли госпожа Сига такой же доброй...",
    ["哇，要动真格的了！"] = "Ого, все становится серьезно!",
    ["哈利，你们后厨的卫生根本不达标，我要重写一篇文章，让大众知道真相！"] = "Гарри, санитарные условия на твоей кухне никуда не годятся! Я перепишу статью, чтобы все узнали правду!",
    ["哈哈——看看你这副可怜的模样，真是滑稽。"] = "Ха-ха, посмотри на свое жалкое состояние, это действительно комично.",
    ["哈哈哈哈——荣誉？穷鬼的荣誉，简直是第五纪以来最大的笑话！"] = "Ха-ха-ха-ха, честь? Честь бедняка — просто самая большая шутка со времен Пятой Эпохи!",
    ["哈哈哈哈……主人……是啊……主人是谁呢？是我？还是你？哈哈哈哈……"] = "Ха-ха-ха... Мастер... да... кто такой Мастер? Это я? Или это ты? Ха-ха-ха...",
    ["哈哈哈，没错，就是这样！震撼人心的逆转即将出现！"] = "Ха-ха-ха, это точно! Вот-вот произойдет шокирующий разворот!",
    ["哈哈，对，我们要上厕所。"] = "Хаха, да, нам нужно в ванную.",
    ["哈哈，尝起来很棒对吧？我家祖传的秘方，你在因蒂斯都找不到这么香的精酿。"] = "Хаха, отличный вкус, правда? Это секретный рецепт моей семьи; Такого ароматного крафтового напитка вы не найдете больше нигде в Интисе.",
    ["哈哈，还是看他们聊天有趣。"] = "Ха-ха, всё же интереснее смотреть, как они болтают.",
    ["哈基猿……虽然不知道是什么意思，但我喜欢这个名字。"] = "Хаджи-Обезьяна... хотя я не знаю, что это значит, но мне нравится это имя.",
    ["哈基猿不再多说，大口大口地吃完了桌上所有东西，吃得干干净净。"] = "Хаки-обезьяна больше ничего не говорит, поедая все, что есть на столе, большими глотками, пока оно не станет полностью чистым.",
    ["哈基猿挺身而出让贝儿热泪盈眶，这一刻，贝儿的心里忽然生出莫名的情愫……"] = "То, что Хаджи-Апе вышел вперед, вызвало слезы на глазах Белль. В этот момент в ее сердце вдруг выросла необъяснимая привязанность...",
    ["哈基猿这番话让贝儿热泪盈眶，两人心里也不知不觉生出了莫名的情愫……"] = "Слова Харки Апе вызвали слезы на глазах Белль, и у них двоих неосознанно возникло необъяснимое чувство...",
    ["哈基猿，为了我，你竟然愿意放弃自己的头发吗？"] = "Хаджи-Апе, ради меня ты действительно готов отказаться от своих волос?",
    ["哈基猿，你这家伙……"] = "Хаджи-Обезьяна, ты парень...",
    ["哈基猿，谢谢你……有你在，真的好有安全感！"] = "Хаджи-Обезьяна, спасибо... С тобой я чувствую себя в такой безопасности!",
    ["哈基猿，谢谢你，有你在，真的好有安全感。"] = "Хаджи-Апе, спасибо. С тобой здесь я действительно чувствую себя в безопасности.",
    ["哈维，这两位是来找戒指的。"] = "Харви, эти двое пришли искать кольцо.",
    ["哈！难怪质检公司代表把安全预算叫“给机器喂素食”……之后怕是要提议给锅炉喂馅饼来减少事故了！"] = "Ха! Неудивительно, что представитель компании по контролю качества называет бюджет безопасности «кормлением машины вегетарианской пищей»… Боюсь, они предложат кормить котлы пирогами рядом, чтобы уменьшить количество несчастных случаев!",
    ["哈，难怪他们总慷慨发言说那些机械是“信仰装置”——原来是因为这些装置能带来不少便士啊！"] = "Ха, неудивительно, что они всегда щедро заявляют, что эти машины являются «устройствами веры» — оказывается, это потому, что эти устройства могут принести немало денег!",
    ["哎呀，也不是什么大事，反正戒指也是随便买的。"] = "О, в любом случае это не имеет большого значения; кольцо было куплено случайно.",
    ["哎呀，我可不能说，你要自己弄明白。"] = "О боже, я не могу сказать. Вы должны разобраться в этом сами.",
    ["哎呀，真的不愿意唱吗？大家都唱了哦？"] = "О боже, ты правда не хочешь петь? Все остальные пели, понимаешь?",
    ["哎呦！"] = "Ой!",
    ["哎哟——撞到我了！我的腿动不了了！赔钱！五苏勒！ "] = "Ой, ты наткнулся на меня! Моя нога не двигается! Плати! Пять соло!",
    ["哎哟……"] = "Ой...",
    ["哎哟！怎么这么远，我、我还没碰到他……"] = "Ой! Как это могло быть так далеко? Я даже не прикасался к нему...",
    ["哎哟，我的头——大哥，我是被鬼魂惩罚了吗？"] = "Ох, голова... Старший брат, меня наказал призрак?",
    ["哎哟，自己摔的还怪地不平？ "] = "Ой, ты упал сам и винишь в этом неровную землю?",
    ["哎算了！{{先生|女士}}，您要注意安全，尽量拖住他，我马上就去最近的警局寻求帮助！"] = "О, забудь об этом! {{Mr.|Ms.}}, пожалуйста, будь осторожен и попытайся остановить его. Я немедленно пойду в ближайший полицейский участок за помощью!",
    ["哎！你的东西！"] = "Привет! Ваши вещи!",
    ["哎，刚才没说完呢……"] = "Эй, ты не закончил то, что сказал ранее...",
    ["哎，我还想看看能不能从马桶里掏出巨大老鼠呢！"] = "Эй, я все еще хотел посмотреть, смогу ли я вытащить гигантскую крысу из унитаза!",
    ["哟，这不是我的结婚戒指吗！上周从衣柜底下摸出来，塞到梅格的盒子里了。"] = "Эй, это ли не мое обручальное кольцо! На прошлой неделе я вытащил его из-под шкафа и сунул в коробку Мэг.",
    ["哥哥的同事们很照顾我，伦纳德先生和弗莱先生帮我找到了。但……"] = "Коллеги моего брата очень заботливы; Мистер Леонард и мистер Фрай помогли мне их найти. Но...",
    ["哦、那个、我是黑荆棘的员工，替伦纳德先生来接待你。我、我看过你的相片。"] = "О, это я сотрудник Чёрный Чертополох, здесь, чтобы принять вас от имени мистера Леонарда. Я... я видел твое фото.",
    ["哦对了，正好我还认识一位知名作家，这样的题材，她一定会感兴趣。"] = "О да, я случайно знаю известного писателя. Ей определенно будет интересна такая тема.",
    ["哦当然！我是埃德温。"] = "О, конечно! Я Эдвин.",
    ["哦！阁下，我恳请您收起那如北风般刺骨的讥诮，我们眼眸中闪烁的真情即使是特伦索斯特王朝遗留下最璀璨的明珠也无法与之媲美！"] = "Ой! Сэр, я умоляю вас оставить этот сарказм, резкий, как северный ветер. Истинные чувства, мелькающие в наших глазах, не могут сравниться даже с самыми яркими жемчужинами, оставленными после себя династией Трунсёст!",
    ["哦，原来是全职女儿啊……嗯？！"] = "Ой, так это полноценная дочь... Хм?!",
    ["哦，是我的书啊。十分感谢，竟然劳动您帮忙取来。"] = "О, это моя книга. Большое спасибо, не могу поверить, что я побеспокоил вас помочь мне получить это.",
    ["哦，没有。咳咳……我想自己转转，你们先走吧。"] = "О, нет. Кхе-кхе... Я бы один погулял, вы все вперед.",
    ["哦，管得挺宽，跟码头上的海鸥似的。"] = "О, ты очень любопытный, как чайки в доках.",
    ["哦，被您看到了啊。真正的我。"] = "О, так ты это видел. Настоящая я.",
    ["哦？在找我吗？"] = "Ой? Ты ищешь меня?",
    ["哦？看来你收到了那封信……美与毁灭的命运的确眷顾着你。"] = "Ой? Кажется, ты получил это письмо... Судьба красоты и разрушения искренне благоволит тебе.",
    ["哪个正常人会这么说话？太夸张了吧！"] = "Какой нормальный человек будет так говорить? Это слишком преувеличено!",
    ["哪天的什么事？"] = "В какой день, что произошло?",
    ["哪有像你这样的神使，而且还在这里写……《愚者圣典》？"] = "Где есть такой божественный посланник, как ты, да еще ты пишешь здесь... «Книгу Шута»?",
    ["哪来的警察？还有……艾德！"] = "Откуда взялась полиция? И... Эд!",
    ["哭什么？还不是自找的！"] = "О чем ты плачешь? Ты сам виноват в этом!",
    ["哼……小心我连你一起收拾！"] = "Хм... берегись, а то я и с тобой расправлюсь!",
    ["哼……算你厉害……"] = "Хм... ты выиграл...",
    ["哼！不过是另一种取巧的解读罢了。真正的知音，需要的是能与大帝未尽的思绪共鸣！"] = "Хм! Это просто еще одна умная интерпретация. Настоящая вторая половинка должна уметь найти отклик в незавершенных мыслях Императора!",
    ["哼！什么乱七八糟的，这是诗社，不是什么隐秘存在研究会！"] = "Хм! Что за чушь. Это поэтический клуб, а не общество по изучению скрытых существований!",
    ["哼，一群不自量力的蠢货。"] = "Хм, кучка дураков, которые не знают своего места.",
    ["哼，何止是懂？谦逊地说，整个鲁恩王国比我了解历史的人，最多不超过六个！"] = "Хм, больше, чем просто понять? Честно говоря, во всем Королевстве Лоэн не более шести человек, которые знают об истории больше, чем я!",
    ["哼，看我们现在把你嘴给揍烂！"] = "Хм, давай посмотрим, как мы сейчас разобьем тебе рот!",
    ["哼，还不知道这些钱会流到谁手里呢……"] = "Хм, еще неизвестно, в чьих руках осядут эти деньги...",
    ["哼，那可未必，人往往越顺遂，就越有可能乐极生悲，不信你们瞧——"] = "Хм, это не обязательно так. Люди часто переживают несчастье, когда дела идут слишком гладко. Если вы мне не верите, посмотрите…",
    ["唉……只是为了让学生多学点罢了！"] = "Эх... это просто для того, чтобы студенты узнали немного больше!",
    ["唉……唉……唉……<P_Heart>（连绵的叹息声不绝于耳）</>"] = "Вздох... вздох... вздох... <P_Heart> (непрерывный, непрерывный вздох) </>",
    ["唉……我喊了无数遍，从不会有人回应我。"] = "Эх... Я кричал бесчисленное количество раз, и никто мне так и не ответил.",
    ["唉……既然如此，我还有最后一个办法。"] = "Эх... В таком случае у меня есть последнее решение.",
    ["唉……真不知道该怎么做，才能让学生们真正愿意学习历史呢……"] = "Эх... Я правда не знаю, что сделать, чтобы ученики действительно захотели изучать историю...",
    ["唉……自从罗塞尔大帝引领了因蒂斯的改革之后，蒸汽机和股票就一跃成为全大陆的重心，学生们都想学工程或者金融，那才是能赚钱的专业。"] = "Эх... с тех пор, как император Розель возглавил реформы в Интисе, паровые двигатели и запасы стали центром внимания всего континента. Все студенты хотят изучать инженерное дело или финансы, поскольку именно эти профессии могут приносить деньги.",
    ["唉……这可怎么办呢？这些书不能堆在这呀。"] = "Эх... и что же теперь делать? Нельзя ведь сваливать эти книги здесь.",
    ["唉，我刚才仔细检查了一遍，您的情况不容乐观啊……"] = "Эх, я только что внимательно проверил, ваша ситуация не оптимистична...",
    ["唉，既然如此，这里有两瓶特效药，是我独家研制的，或许可以帮到你。"] = "Эх, раз уж так, вот два флакона особого снадобья по моему собственному рецепту. Быть может, они тебе помогут.",
    ["唐格拉尔先生，我决定放弃对南大陆铁路项目的投资，并且取走在因蒂斯海洋银行的所有存款。"] = "Господин Данглар, я решил отказаться от инвестиций в железнодорожный проект Южного континента и вывести все свои вклады из Интис Ocean Bank.",
    ["唐泰斯改头换面后，不仅购买了大片土地和庄园，受封伯爵。还投资基金和股票。成为了特里尔的大银行家。"] = "Сменив облик, Дантес не только скупил обширные земли с поместьями и был пожалован графским титулом, но и вложился в фонды и акции, превратившись в крупного банкира Трира.",
    ["唔……哎呀，我可不是那种随便的女人……我想我需要更多的爱。"] = "Хм... о боже, я не такая случайная женщина... Думаю, мне нужно больше любви.",
    ["唔……唔…………你这该死的、听不懂人话的癞蛤蟆！"] = "Хм... хм... ты чертова жаба, которая не понимает человеческой речи!",
    ["唔……库克……快跑……"] = "Ух... Кук... беги...",
    ["唤醒所有的石像再回来找我吧"] = "Разбуди все каменные статуи и возвращайся, чтобы найти меня.",
    ["唱得真好，这是你要的花！愿你邂逅甜蜜与浪漫！"] = "Ты так хорошо пела, это тот цветок, который ты хотела! Пусть вам встретится сладость и романтика!",
    ["啊——"] = "Ах…",
    ["啊——<P_Heart>（男人的惨叫声）</>"] = "Ах——<P_Heart> (мужской крик)</>",
    ["啊——！"] = "Ах!",
    ["啊——！！"] = "Ах-!!",
    ["啊……因蒂斯？"] = "Ах... Интис?",
    ["啊……那名可怜的男爵，也是被爱情杀死的呢。"] = "Ах... бедного барона тоже убила любовь.",
    ["啊我知道我知道，大人物总有些不能说的事情要做，是我没有想到这一点。"] = "А, знаю, знаю, у важных персон всегда найдутся дела, о которых нельзя распространяться... Это я сглупил, не подумал.",
    ["啊！——\n一声尖叫让床上两个人完全惊醒。"] = "Ах! ——\nКрик полностью разбудил двоих человек на кровати.",
    ["啊！！啊！！！"] = "А-а!! А-а-а!!!",
    ["啊，是吗？我没有注意到……不过既然您这么有心……"] = "Ах, это так? Я не заметил... но раз ты такой задумчивый...",
    ["啊？"] = "Хм?",
    ["啊？ 原来她也会被退稿？那我上次文法课没及格是不是也没那么丢人了！"] = "А? Так ее рукописи тоже заворачивают? Значит, мой незачет по грамматике не такой уж и позор!",
    ["啊？但这好像不是老师的风格，这么写能行吗？"] = "Ах? Но, похоже, это не в стиле учителя. Будет ли так писать?",
    ["啊？我的计划里没有这一条！"] = "А? Этого не было в моём плане!",
    ["啧，忏悔了半天，就忏悔出一堆阴沟里的老鼠来。"] = "Тск, после столь долгого признания они смогли признаться только в стае крыс в сточной канаве.",
    ["啧，谁知道他摇身一变，成了那个什么鲁伯特男爵的私生子？换做是你，你走路也得鼻孔朝天！"] = "Тск, кто знал, что он вдруг окажется внебрачным сыном этого барона Руперта? Если бы это был ты, ты бы тоже ходил, задрав нос!",
    ["喂——"] = "Привет-",
    ["喂——你俩还没订婚呢，就净说这样肉麻的话，真让人作呕！"] = "Эй, вы еще даже не помолвлены, а уже говорите такие слащавые вещи, это отвратительно!",
    ["喂，刚才让你喊动手已经很给你面子了，你现在还要反驳我？"] = "Эй, я уже дал тебе лицо, крича «сделай ход» раньше, а теперь ты собираешься со мной спорить?",
    ["喂，哥们，手轻点！"] = "Эй, приятель, успокойся!",
    ["善后。"] = "Очиститесь.",
    ["喏 ，就是它们！还有谁比这些小家伙更懂鱼呢？要是连它们都能被吸引，那说明我这配方是真成功了！ "] = "Вот они! Кто знает рыбу лучше, чем эти маленькие ребята? Если даже их удастся привлечь, значит, моя формула действительно удалась!",
    ["喔——"] = "Ву-",
    ["喝下这瓶醒神花露，它能帮你稳定心神。"] = "Выпейте эту бутылку Росы сладкой ночи; это поможет вам стабилизировать свой разум.",
    ["喝药之前，我得先去洗个手！"] = "Прежде чем выпить лекарство, мне нужно пойти вымыть руки!",
    ["喵……"] = "Мяу...",
    ["喵喵……喵喵喵……喵……"] = "Мяу-мяу... мяу-мяу-мяу... мяу...",
    ["嗯……"] = "Хм...",
    ["嗯……前往古堡可能会带来一定的危险。"] = "Хм... поход в древний замок может таить в себе некоторую опасность.",
    ["嗯……前往金秋湖获得的不像是好结果。"] = "Хм... поход на озеро Золотой Осени, похоже, не принес хорошего результата.",
    ["嗯……就叫<P_Yellow>《魔女与野兽》</>吧！"] = "Хм... назовем его <P_Yellow>《Ведьма и чудовище》</>!",
    ["嗯……廷根？"] = "Хм... Тинген?",
    ["嗯……我仔细观察了一下，您的这只宠物，毛发乌黑浓密有光泽，品质万里挑一，是完美的植发原料。"] = "Хм... Я внимательно наблюдал. У этого вашего питомца густая, блестящая, угольно-черная шерсть. Его качество — один на миллион — идеальный материал для пересадки волос.",
    ["嗯……我们有一个充满故事的八音盒。"] = "Хм... у нас есть музыкальная шкатулка, полная историй.",
    ["嗯……没错。就当它是一个秘密吧！"] = "Хм... Верно. Пусть это будет секретом!",
    ["嗯……那样另类的幽默，也能算是一种说话的艺术吧。"] = "Хм... такой альтернативный юмор тоже можно считать формой разговорного искусства.",
    ["嗯……非要说的话，我感觉老师的癔症发作是有规律的。"] = "Хм... если честно, я чувствую, что истерические эпизоды учительницы имеют закономерность.",
    ["嗯。就像你能认出今天和昨天见到的同一个人，虽然光线、表情可能不同。我只不过……认的是鸡蛋。"] = "Хм. Точно так же, как вы можете узнать того же человека, которого видели сегодня, так же, как видели вчера, хотя освещение и выражение лица могут быть разными. Я просто... узнал в этом яйцо.",
    ["嗯哼。传闻，罗塞尔是个不折不扣的……收藏家。他曾说过，“我能抗拒一切，除了美女的诱惑。 ”"] = "Угу. Ходят слухи, что Розель была заядлым... коллекционером. Однажды он сказал: «Я могу противостоять всему, кроме искушения со стороны красивых женщин».",
    ["嗯嗯，剪刀……然后呢？"] = "Мм-ммм, ножницы... а потом?",
    ["嗯！掌握了人头鸟妖的习性和召唤咒文，感觉有底气了很多。"] = "Да! Теперь я знаю повадки гарпии и заклинание её призыва, чувствую себя гораздо увереннее.",
    ["嗯！莉莉守护市民，我们来守护“闪电莉莉”！"] = "Хм! Лилия охраняет горожан, а мы будем охранять «Молниевую Лилию»!",
    ["嗯，{{PlayerName}}今天的工作已经处理完了。"] = "Да, {{PlayerName}} закончил(а) сегодняшнюю работу.",
    ["嗯，他们也有非常易于辨认的口头禅，称赞彼此<P_Yellow> 幽默，风趣，会说笑</> 。"] = "Ну, а еще у них есть очень узнаваемая крылатая фраза, в которой они хвалят друг друга за <P_Yellow> юмор, веселье и умение шутить </> .",
    ["嗯，他来了吗？"] = "Да, он здесь?",
    ["嗯，你做得很好。"] = "Да, ты отлично справился.",
    ["嗯，先找弗莱队长聊聊。"] = "Да, давай сначала поговорим с капитаном Фраем.",
    ["嗯，想起来就找找，结果捡了一堆别人的戒指。"] = "Да так, как вспомню — ищу, а в итоге нашел кучу чужих колец.",
    ["嗯，我正在排查廷根最近发生的案件。"] = "Да, я расследую недавние дела в Тингене.",
    ["嗯，晋升仪式失败了。但那个“主人”似乎另有其人……"] = "Хм, ритуал продвижения провалился. Но этот «хозяин», похоже, кто-то другой...",
    ["嗯，看来“戏法大师”的配方短时间也用不上了，我们一起看看吧。"] = "Хм, похоже, рецепт «Мастера Трюков» в ближайшее время нам не понадобится, давайте взглянем на него вместе.",
    ["嗯，确实是魔女才有的能力。我需要仔细调查这幅画。"] = "Хм, это действительно способность, которой может обладать только ведьма. Мне нужно внимательно изучить эту картину.",
    ["嗯，艾丝黛拉女士的说法，似乎更值得探讨……"] = "Хм, точка зрения мисс Эстеллы кажется более стоящей изучения...",
    ["嗯，这也是她给我喝下魔药的原因。"] = "Да, именно поэтому она заставила меня выпить зелье.",
    ["嗯，里埃尔还在等，对吗？那个笨蛋。"] = "Хм, Риэль все еще ждет, да? Этот дурак.",
    ["嗯，锁着。但我有一些……还在学习中的技巧。"] = "Да, он был заперт. Но у меня есть некоторые... методы, которым я все еще учусь.",
    ["嗯？……但是话又说回来，年轻人，你对当<P_Yellow>主演</>有兴趣吗？"] = "Хм?...Но опять же, молодой человек, вы заинтересованы в том, чтобы стать ведущим актером <P_Yellow> </>?",
    ["嗯？怎么了？"] = "Хм? В чем дело?",
    ["嗯？有人在聊天……"] = "Хм? Кто-то болтает...",
    ["嗯？还剩下一些柠檬汁和白醋，不能浪费，也加进去好了！"] = "Хм? Еще осталось немного лимонного сока и белого уксуса, нельзя выбрасывать их, можно добавить!",
    ["嗯？那位美丽的女士呢？"] = "Хм? Где эта красивая дама?",
    ["嗯？那是……刚刚的学生？"] = "Хм? Это... тот студент, который только что был?",
    ["嗯？！"] = "Хм?!",
    ["嘘，不要说话。"] = "Тсс, не говори.",
    ["嘘，别告诉其他人，他们会吃醋的……"] = "Тс-с, только никому не говори, а то остальные обзавидуются...",
    ["嘘，我只想安静地享用食物。餐厅老板哈利刚刚就在附近，我怕他认出我。"] = "Тсс, я просто хочу спокойно насладиться едой. Хозяин ресторана Гарри был совсем рядом, боюсь, он меня узнает.",
    ["嘘，我就快邂逅我的爱人了！"] = "Тсс, я скоро встречусь со своим возлюбленным!",
    ["嘤——"] = "Эх…",
    ["嘤嘤！"] = "Всхлип!",
    ["嘶，我学过，但还真没试过。"] = "Хисс, я это изучал, но никогда не пробовал.",
    ["嘿{{先生|女士}}！尝尝会咬人舌头的饮料吗？只要1便士，比甜冰茶够劲，比姜汁啤酒清爽！"] = "Привет, {{Mr.|Ms.}}! Хотите попробовать напиток, который кусает язык? Всего 1 пенс, более пикантный, чем сладкий чай со льдом, и более освежающий, чем имбирное пиво!",
    ["嘿伙计，放轻松，人休息是合法的。"] = "Эй, приятель, расслабься. Отдых легален.",
    ["嘿！你有没有什么无法达成的愿望难以满足？有没有不能完成的夙愿耿耿于怀？来吧，我这儿有各种各样的游戏，能让你体验不一样的人生！"] = "Привет! Есть ли у вас нереализованные желания, которые трудно удовлетворить? Есть ли сожаления, которые тяготят ваше сердце? Да ладно, у меня здесь есть всевозможные игры, которые позволят вам окунуться в другую жизнь!",
    ["嘿，你听说过“黄金梦想号”吗？他们说那艘船的船帆在月光下会变成水晶！"] = "Эй, ты слышал о «Золотой мечте»? Говорят, паруса этого корабля под луной превращаются в хрусталь!",
    ["噔噔噔噔噔？"] = "Дэн Дэн Денг Дэн Дэн?",
    ["噢……你好，真希望我的屁股能和我一起到场……"] = "Ох... привет, мне бы очень хотелось, чтобы моя задница приехала со мной...",
    ["噢是的，就是那边。"] = "О да, это было прямо там.",
    ["噢，为什么，明明只是人群中的一人，但我却被你深深地吸引了。"] = "О, почему, хотя ты всего лишь один в толпе, ты меня глубоко привлекаешь.",
    ["噢，你好！我在这等我丈夫呢，他离开小镇去打工，应该这几天就回来。"] = "О, привет! Я жду здесь мужа. Он уехал из маленького городка на работу и должен вернуться через несколько дней.",
    ["噢，当然没问题，这就为您进行面容调整——"] = "О, конечно, без проблем. Я прямо сейчас проведу для вас коррекцию лица—",
    ["噢，是的！我的笔记本被风吹散了，书页飘得到处都是。 "] = "О да! Мой блокнот растрепало ветром, и страницы разлетелись повсюду. ",
    ["噢，有新的受害者？……"] = "О, новая жертва?...",
    ["嚷什么，不是还有动静吗？真要是死在里面，麻烦的可是我，哼……"] = "О чем ты кричишь? Неужели еще нет движения? Если он действительно там умрет, неприятности будут у меня, хм...",
    ["四十！四十！"] = "Сорок! Сорок!",
    ["回去吧，你得向那对老夫妻道歉。"] = "Возвращайся. Тебе нужно извиниться перед теми стариками.",
    ["回廷根？就这么回去？"] = "Вернуться в Тинген? Просто вернуться вот так?",
    ["回答一下这些问题如何？也许，我们能再见面……"] = "Как насчет того, чтобы ответить на эти вопросы? Возможно, мы сможем встретиться снова...",
    ["因为我今天终于摸到光啦！而且还有了新故事！"] = "Потому что сегодня я наконец прикоснулся к свету! И у меня новая история!",
    ["因为我有事情要向你坦白。"] = "Потому что мне есть в чем тебе признаться.",
    ["因为那是丈夫送我的最后一枚戒指，我清楚记得花纹。"] = "Потому что это было последнее кольцо, которое подарил мне муж, и я отчетливо помню его узор.",
    ["因为，我也是“焦糖炸弹”的忠实追随者。"] = "Потому что я тоже преданный поклонник «карамельных бомбочек».",
    ["因他而死去的无辜居民，也能安息了。"] = "Невинные жители, погибшие из-за него, также могут покоиться с миром.",
    ["因蒂斯的蒸汽与机械之神教会有“0”级封印物出逃，去向未知。“红手套”将在鲁恩境内展开排查。"] = "Запечатанный артефакт 0-го уровня из Церкви Бога пара и машин в Интисе сбежал, и его местонахождение неизвестно. «Красные перчатки» проведут расследование в Лоэне.",
    ["因蒂斯的蒸汽与机械之神教会有一件“0”级封印物出逃，目前不确定是否逃至鲁恩境内。"] = "Запечатанный артефакт 0-го ранга из Церкви Бога пара и машин в Интисе сбежал. В настоящее время неизвестно, сбежал ли он в Лоен.",
    ["团结就是力量！"] = "В единстве — сила!",
    ["团队……原来是大家的力量！我会转告弟弟的，这张照片我们会好好保存的。谢谢您！ "] = "Команда... так что в этом была сила каждого! Я скажу брату, мы хорошо сохраним это фото. Спасибо!",
    ["困境都只是逆袭的前奏，来吧！主角的外挂是时候登场了！"] = "Трудности – лишь прелюдия к возвращению. Ну давай же! Пришло время появиться читу главного героя!",
    ["在一个血月格外明亮的夜晚，廷根突然出现了大量有关\"罗塞尔大帝\"的知识，历史课本，杂志，报纸，似乎都回到了一百多年前，罗塞尔最辉煌的那个时刻。"] = "В ночь, когда кровавая луна была исключительно яркой, в Тингене внезапно появилось большое количество знаний об «Императоре Розелле». Учебники истории, журналы и газеты, казалось, вернулись более чем на сто лет назад, к моменту величайшей славы Розеллы.",
    ["在一阵强光中，你感受到了脚下流动的知识洪流，历史中的廷根浮现在上空，被洪流裹挟着的你们来到蒸汽革命时代的廷根，你失去了意识。 "] = "Во вспышке яркого света вы почувствовали, как поток знаний течет под вашими ногами. Тинген в истории появился в небе над головой, и вас унесло потоком в Тинген в эпоху паровой революции, и вы потеряли сознание.",
    ["在仰望星空派的见证下，美女与野兽最终走到了一起。"] = "На глазах у Пирога, смотрящего на звезды, красавица и чудовище наконец встретились.",
    ["在偷听吗，年轻人？"] = "Подслушиваете, молодой человек?",
    ["在我们看来，这只是普通的马桶故障，怎么会劳烦警官过来？"] = "По-нашему, это обычный засор в уборной — с чего бы ради этого беспокоить полицию?",
    ["在我心里，历史不仅仅是一门学科，更是一种美德，我只是……太想让所有人都拥有它了，哪怕我知道我的方法是错的。"] = "В моем сердце история – это не просто предмет, а добродетель. Я просто... слишком сильно хотел, чтобы все обладали им, хотя и знал, что мои методы неправильны.",
    ["在我手上，就不是烧火棍了。"] = "В моих руках это уже не будет огненная кочерга.",
    ["在我眼里，你虽然是男人，却比所有女人都更有魅力。"] = "В моих глазах, хоть ты и мужчина, ты привлекательнее любой женщины.",
    ["在月光下翩翩起舞，在芬芳中窥见真实——这便是我们的艺术。"] = "Грациозно танцевать под луной, разглядеть истину среди аромата – это наше искусство.",
    ["在沙龙里，我以为你是个纯真的艺术爱好者。"] = "В салоне я думал, что ты невинный любитель искусства.",
    ["在爱情里，喜悦和激情的背后，往往伴随着相应的痛苦。"] = "В любви за радостью и страстью часто стоит соответствующая боль.",
    ["在知识空间内，文字具有妙用，先带走！"] = "В сфере знаний текст имеет замечательное применение, возьмите его в первую очередь!",
    ["在穷人扎堆的地盘……济贫院，那里有一具尸体，对，有一具尸体！"] = "Там, где ютятся бедняки... в работном доме! Там труп, да, там настоящий труп!",
    ["在蜂蜜炖猪肠的见证下，美女与野兽最终走到了一起。"] = "Свиные кишки, тушеные в меду, показали, что красавица и чудовище наконец сошлись воедино.",
    ["在这个喧嚣的世界里，人和灵都被烦恼折磨，被恐惧束缚，被秘密困扰。"] = "В этом шумном мире люди и духи терзаются тревогами, скованы ужасом и обеспокоены тайнами.",
    ["在这座城市的表象之下，隐藏着无数秘密，而我们便是那些追寻美丽与真实的人。"] = "Под поверхностью этого города скрыты бесчисленные тайны, и мы — те, кто стремится к красоте и истине.",
    ["在这！我刚把它们包好。"] = "Здесь! Я только что закончил их заворачивать.",
    ["在那之前，你大概已经鼻青脸肿了。要试试吗？"] = "До этого вы, вероятно, уже будете в синяках и побоях. Хотите попробовать?",
    ["在非凡世界里，从来不存在真正意义上的“意外”，而是一个个精心谋划的“巧合”。"] = "В «Необыкновенном мире» нет такой вещи, как настоящая «случайность», а есть серия тщательно спланированных «совпадений».",
    ["在马桶和盥洗盆的见证下，美女与野兽最终走到了一起。"] = "В унитазе и умывальнике красота и чудовище наконец встретились.",
    ["坐下动作复原"] = "Сидеть восстановлено",
    ["埃德温先生，我找到方向了，跟我走！"] = "Мистер Эдвин, я нашел направление, следуйте за мной!",
    ["埃德温把梅格夫人的戒指狠狠扔了出去。"] = "Эдвин яростно отбрасывает кольцо миссис Мэг.",
    ["塔罗学派是什么"] = "Что такое Клуб Таро?",
    ["塔罗学派是贝尔纳黛创建的用以学习进步的地方"] = "Клуб Таро — это место, основанное Бернадетт для обучения и прогресса.",
    ["夏洛特为什么又拒绝了我的邀请，难道她很讨厌我？"] = "Почему Шарлотта снова отклонила мое приглашение? Она меня ненавидит?",
    ["外面？公寓的前后门守着一胖一瘦两个家伙，三点一到，就要进来查看。"] = "Снаружи? У переднего и заднего входов квартиры стоят двое — толстый и худой. Ровно в три часа они зайдут проверить.",
    ["多亏了你，人质才能安全撤离。"] = "Благодаря вам заложники смогли благополучно эвакуироваться.",
    ["多亏了内部资料，这辈子第一次拿满分，恐怕也是最后一次了……"] = "Благодаря инсайдерским материалам я впервые в жизни получил высший балл, и боюсь, что он будет последним...",
    ["多彩的鲜花，心形的小路……天上还有浪漫的热气球。"] = "Яркие цветы, дорожки в форме сердечек... и романтические воздушные шары в небе.",
    ["夜里我加班，看见那个男人，之后怪物就来了……后面……"] = "Я работал сверхурочно ночью и увидел этого человека, а потом появился монстр... позже...",
    ["够了！你们两个合起伙来羞辱我！"] = "Достаточно! Вы двое сговорились, чтобы унизить меня!",
    ["够了，你这个魔女！"] = "Хватит, ведьма!",
    ["大、大哥，怎么感觉有点冷？"] = "Б-брат, почему-то немного холодно?",
    ["大主教说，我必须把丰收祭司的魔药彻底消化才够资格上战场，但离开伦堡后我们一路奔波，根本没有时间耕种土地。"] = "Архиепископ сказал, что я должен полностью переварить зелье Жреца Жреца, чтобы быть готовым к бою, но после того, как мы покинули Ленбург, мы суетились, и у нас не было времени обрабатывать землю.",
    ["大哥，地上这些符号是什么？"] = "Брат, что это за знаки на земле?",
    ["大家不要急，买丝瓜就可送丝瓜汤食谱，都来看看吧！"] = "Все, не торопитесь. Купите люфу и получите рецепт супа из люфы, приходите и посмотрите!",
    ["大家伙，你叫什么名字？"] = "Большой парень, как тебя зовут?",
    ["天呐！你的裤子破了个大洞，狒狒要啃你的屁股了！"] = "Боже правый! У тебя на штанах огромная дыра, павиан сейчас откусит тебе задницу!",
    ["天哪，{{他|她}}说得好像更有道理！"] = "Боже мой, с {{he|she}} это звучит еще более разумно!",
    ["天啊……我做了什么……这里太热了，我需要去露台透透气。"] = "Боже мой... что я наделала... здесь слишком жарко, мне нужно выйти на террасу подышать воздухом.",
    ["天空变成了洪流……少女突然消失不见……"] = "Небо превратилось в поток... девушка вдруг исчезла...",
    ["太不对劲了！我居然为存在严重卫生问题的餐厅撰写文章！老板必须给我一个答复！等等，还是不对劲……库克怎么会把厨房搞成这样，他经历了什么……"] = "Это слишком неправильно! На самом деле я написал статью для ресторана с серьезными проблемами гигиены! Босс должен дать мне ответ! Подождите, все еще не так... Как Кук мог сделать кухню такой? Через что он прошел...",
    ["太厉害了吧……"] = "Это слишком удивительно...",
    ["太厉害了！"] = "Это потрясающе!",
    ["太可恶了！警官，我觉得我又可以了，这附近还有一些没有搜查的地方，你愿意帮帮我吗？"] = "Как презренно! Офицер, думаю, я смогу сделать это снова. Поблизости еще есть места, которые еще не обыскали. Вы готовы мне помочь?",
    ["太好了莉娅！伦纳德先生能喜欢你的礼物真是太好了。 "] = "Это здорово, Лия! Замечательно, что мистеру Леонарду понравился ваш подарок.",
    ["太好了！今天的丝瓜都卖完了！"] = "Отлично! Сегодня все люфы распроданы!",
    ["太好了！谢谢你！我家很好找，就是离湖边最近的那间小屋！"] = "Большой! Спасибо! Мой дом легко найти; это маленький коттедж, ближайший к берегу озера!",
    ["太好了！谢谢您，弗莱队长！"] = "Замечательно! Спасибо вам, капитан Фрай!",
    ["太好了！那就先买烈酒吧，种子的事情……以后再想办法吧。"] = "Большой! Тогда давай сначала купим спиртное. Что касается семян... разберемся позже.",
    ["太好了，我忽然发现你就很符合我的要求，而且你眼神里的故事感一定能打动观众，这简直是女神的恩赐。"] = "Отлично, я вдруг понял, что вы идеально соответствуете моим требованиям, и ощущение истории в ваших глазах обязательно тронет аудиторию. Это просто подарок Богини.",
    ["太好了，终于有人能听到了……或许是来自大地的启示……赞美万物的母亲……"] = "Прекрасно, наконец-то меня кто-то услышал... Возможно, это откровение от земли... Слава Матери Всего Сущего...",
    ["太好喝了，很鲜美！"] = "Это очень вкусно, сытно!",
    ["太巧了，我们几个都曾在勒塞尔港生活过，认识不少水手，您快讲讲吧。"] = "Какое совпадение. Мы все жили в Порт-Лезеле и знали многих моряков. Пожалуйста, расскажите нам эту историю.",
    ["太感谢了！你可以先去校门口的<P_Yellow>公告板</>附近调查看看，那里经常有很多学生，期待你的好消息！"] = "Большое спасибо! Вы можете начать расследование возле доски объявлений <P_Yellow> </> у ворот школы; там часто бывает много студентов. Ждем ваших хороших новостей!",
    ["太感谢了！另外……能不能请您拍一张她看到礼物时的照片？ 她思考时手指轻点下巴，读到有趣句子时眼里闪过的那点光……那种通透的感觉，特别帅。"] = "Большое спасибо! И ещё... не могли бы вы сфотографировать ее, когда она увидит подарок? Ее пальцы постукивают по подбородку, когда она думает, маленький огонек, который вспыхивает в ее глазах, когда она читает интересное предложение… такое ощущение прозрачности особенно круто.",
    ["太感谢了！这些书页应该就在金秋湖附近，拜托你了！"] = "Большое спасибо! Эти страницы должны быть возле озера Золотой Осени, я рассчитываю на вас!",
    ["太感谢了，莉莉。双倍运费，全靠你了！"] = "Огромное спасибо, Лили. Удвойте стоимость доставки, все зависит от вас!",
    ["太感谢你了！你简直是{{丝瓜国王|丝瓜女王}}，今晚回去我也要煮一碗丝瓜汤喝。"] = "Большое спасибо! Ты просто {{ King of Loofah| Queen of Loofah}}, я собираюсь приготовить тарелку супа из люфы сегодня вечером, когда вернусь.",
    ["太感谢你了！给，这是说好的钥匙，宝箱归你了。"] = "Большое спасибо! Вот, как и было обещано, вот ключ, сундук с сокровищами ваш.",
    ["太棒了，这就是我想要的！"] = "Это здорово, это то, чего я хочу!",
    ["太燃了，就该让这些总拿鼻孔看人的贵族知道，我们普通人也要守护自己的荣誉！"] = "Это так жгуче! Мы должны дать понять этим дворянам, которые всегда смотрят свысока, что мы, простые люди, тоже хотим беречь свою честь!",
    ["太精彩了，我的心脏从第一幕开始就一直悬着，到现在才放下来。"] = "Это было великолепно. Мое сердце висело на волоске с первого акта, и только сейчас окончательно успокоилось.",
    ["太解气了！就是有太多这样的官老爷，我们的生活才会这么不幸！"] = "Так приятно! Именно потому, что таких чиновников слишком много, наша жизнь такая несчастная!",
    ["太诡异了！镜子在飞！它还会问问题！"] = "Это слишком странно! Зеркало летает! И оно задает вопросы!",
    ["太阳在一个又一个人手中传递，黑夜渐渐亮了起来。"] = "Солнце переходило от одного человека к другому, и темная ночь постепенно прояснялась.",
    ["太难了……除非您能找到一个毛发极其旺盛，而且头发品质完美的姑娘，我就可以为您做植发手术。"] = "Это слишком сложно... если только ты не найдешь девушку с чрезвычайно пышными волосами и идеальным качеством волос, тогда я смогу сделать тебе операцию по пересадке волос.",
    ["夫人，孩子需要冷静一下。您和先生先到远处等等，我在这里守着，顺便想想别的办法。"] = "Сударыня, ребенку нужно успокоиться. Отойдите с мужем подальше и подождите там, а я пока посторожу здесь и заодно подумаю, как поступить.",
    ["夫人，您的戒指来了！"] = "Мэм, ваше кольцо здесь!",
    ["失去的一切……我懂了，我体会到观众心里熊熊燃烧的激情和渴望了，这才是戏剧的真谛！"] = "Все потеряно... Я понимаю, я испытал жгучую страсть и желание в сердцах зрителей. Вот истинный смысл драмы!",
    ["头好晕……"] = "У меня так кружится голова...",
    ["头好疼……这里是什么地方？"] = "Голова раскалывается... Что это за место?",
    ["头有点痛……撞到脑袋了？"] = "Голова немного болит... Я что, головой ударился?",
    ["奇怪的廷根，奇怪的警察，等明天再看看他找我做什么。"] = "Странный Тинген, странная полиция; Завтра посмотрю, чего он от меня хочет.",
    ["奇怪，刚才我为什么这么焦虑？"] = "Странно, почему я так волновалась сейчас?",
    ["奇怪，库克为什么看起来心神不定，用灵视看看吧。"] = "Странно, почему Кук выглядит беспокойным? Давайте посмотрим духовным зрением.",
    ["奇怪，我刚刚为什么还在工作，现在明明是休息时间。"] = "Странно, почему я только что работал, когда явно пора отдыхать?",
    ["奇怪，明明之前聊这些能提神的，怎么现在越聊越困……"] = "Странно, раньше я бодрился, болтая об этих вещах, но почему, чем больше мы говорим, я становлюсь все более сонным...",
    ["奇迹真的发生了！之前的实验数据怎么都不合格，这次一下就成功了！"] = "Чудо действительно произошло! Предыдущие экспериментальные данные ни разу не были проверены, но на этот раз это удалось сразу!",
    ["奈特喜欢偷东西，他不缺钱，他是心理因素没法管住手，不过他承诺偷到手玩几天再给人送回去……"] = "Найт любит воровать вещи. У него нет недостатка в деньгах; это психологическая проблема, он не может контролировать свои руки, но обещает украсть их, поиграть с ними несколько дней, а потом отправить обратно...",
    ["女士们先生们，激动人心的时刻到了！"] = "Дамы и господа, настал волнующий момент!",
    ["女士们，先生们，欢迎来到<P_Yellow>施佩尔先生的灵感剧院</>！"] = "Дамы и господа, добро пожаловать в <P_Yellow>, Театр Вдохновения г-на Шпеера </>!",
    ["女士们，先生们，请睁大你们的双眼——"] = "Дамы и господа, пожалуйста, откройте глаза широко…",
    ["女士，你看起来很困扰。"] = "Леди, вы выглядите обеспокоенной.",
    ["女士，您忘了您的手帕！"] = "Мадам, вы забыли свой носовой платок!",
    ["女孩捧着那块太阳，感受它的温度，记住它的模样。"] = "Девушка держала кусочек солнца, чувствовала его температуру и запоминала его внешний вид.",
    ["女神啊……老师把店交给我的时候，我就说我做不到了……"] = "Богиня... Когда учитель передавал лавку мне, я же говорил, что не справлюсь...",
    ["女神啊！她应该参加短跑比赛，而不是当送货员！"] = "Богиня! Она должна участвовать в спринтерском забеге, а не работать курьером!",
    ["女神啊，你说这话真是拯救了这个街道。{{PlayerName}}，你有什么办法避开正面？"] = "Моя Богиня, твои слова действительно спасли эту улицу. {{PlayerName}}, есть ли у тебя способ избежать лобовой конфронтации?",
    ["女神啊，这么多订单，先送哪个呢？"] = "Богиня, столько заказов... Какой же доставить первым?",
    ["女神看中你，令你获得了系统，也就是我本人，能够让你拥有更大的助力。"] = "Богиня полюбила тебя и позволила тебе получить систему, которой является я, и которая может оказать тебе большую помощь.",
    ["奶奶说，她这辈子最幸福的事，就是得到了那些种子。"] = "Бабушка говорила, что самым счастливым событием в ее жизни было получение этих семян.",
    ["奶奶说，这些南瓜的种子是很久很久以前，一位远游归来的朋友送给她的。那位旅人还带来了一种很特别的烈酒配方，现在全金秋湖都在卖呢！"] = "Бабушка рассказала, что эти тыквенные семечки ей подарила давным-давно подруга, вернувшаяся из дальнего путешествия. Этот путешественник также привез особенный рецепт спиртного, который теперь продается по всему озеру Золотой Осени!",
    ["她……她说黑荆棘总会让她想起她的哥哥，所以就不进来了。"] = "Она... она сказала, что Чёрный Терн всегда напоминает ей о брате, поэтому не зайдёт.",
    ["她、她收下了！她说她也注意我很久了！"] = "Она... она приняла его! Сказала, что тоже давно за мной наблюдает!",
    ["她一直念叨六只鸽子。 "] = "Она все бормочет про шесть голубей.",
    ["她为我讲述了一个爱情故事，以弥补我情感经历上的空缺——解释一下，我不认为这是缺陷。"] = "Она рассказала мне историю любви, чтобы восполнить пробел в моем эмоциональном опыте — чтобы объяснить, я не думаю, что это недостаток.",
    ["她从未见过光，但她知道，光一定存在。因为妈妈说过，世界上最温暖的东西，就是太阳。"] = "Она никогда не видела света, но знала, что он должен существовать. Потому что моя мама говорила, что самое теплое на свете — это солнце.",
    ["她听说你是位“贵族诗人”，特意抄了诗集，觉得这样才配得上你的身份。"] = "Она прослышала, что ты «поэт-дворянин», и специально переписала сборник стихов, сочтя, что лишь такое подобает твоему положению.",
    ["她和山姆在一起是因为——"] = "Она была с Сэмом, потому что…",
    ["她对每个人说：“这是别人给我的，现在它也是你的了。”"] = "Она говорила каждому: «Мне это подарили, а теперь оно принадлежит и тебе».",
    ["她就是闪电莉莉，“闪电速递”头牌送货员！"] = "Она — Молния Лили, лучший курьер «Молниеносного экспресса»!",
    ["她往这边走了？"] = "Она шла сюда?",
    ["她怎么会知道这些？"] = "Откуда ей это знать?",
    ["她把这些都记在心里，想着：总有一天，我会摸到太阳的。"] = "Она хранила все это в своем сердце, думая: «Однажды я прикоснусь к солнцу».",
    ["她是工厂的一名女工，工厂的少爷邀请她去参加舞会。"] = "Она была простой работницей на фабрике, а хозяйский сынок пригласил ее на бал.",
    ["她是谁？"] = "Кто она?",
    ["她是谁？为什么认为是她在报复你们？"] = "Кто она? Как ты думаешь, почему она тебе мстит?",
    ["她说她会前往东区书店，穿着深棕色的衣服，接过我递来的信物百合。"] = "Она сказала, что пойдет в книжный магазин в Восточном округе, одетая в темно-коричневую одежду, и возьмет жетон с лилией, который я ей вручил.",
    ["她走了……不是说走过花海的心形小路，就能邂逅爱人吗？我走了一个月也没人爱上我！"] = "Она ушла... разве не говорили, что если пройти по тропинке в форме сердца через море цветов, то встретишь своего возлюбленного? Я гуляю уже месяц и никто в меня не влюбился!",
    ["好……但我还有其他事，只能帮你排一会。"] = "Ладно... но у меня есть другие дела, я могу помочь тебе лишь на время.",
    ["好、好的！"] = "Хорошо, хорошо!",
    ["好。"] = "Хорошо.",
    ["好主意——"] = "Хорошая идея-",
    ["好久不见了，备受赞誉的名侦探阁下。"] = "Давно не виделись, мой высоко оцененный детектив.",
    ["好了！莉莉，能帮我把信送到佐特兰街2号吗？"] = "Хорошо! Лили, ты можешь помочь мне доставить письмо на Зутленд-стрит, 2?",
    ["好了，从现在起，让我来当告解室，而你是来向我做告解的。"] = "Хорошо, с этого момента позволь мне исповедоваться, а ты можешь исповедоваться мне.",
    ["好了，我还有点事，等拿到了，我再来接你。"] = "Ладно, у меня ещё есть дела. Как закончу, вернусь за тобой.",
    ["好像不对，再想想是敲几下来着？"] = "Это кажется неправильным, дайте мне подумать еще раз, сколько было ударов?",
    ["好像不对，暗号是什么来着？"] = "Кажется, не то... Какой там был пароль?",
    ["好像是男盥洗室传出的声音……刚才怎么没听见？不管了，去看看！"] = "Похоже, шум доносится из мужского туалета... почему я не услышал его только сейчас? Ничего, пойдем проверим!",
    ["好像是男盥洗室传出的声音……男就男吧，我得去看看！"] = "Похоже, шум доносится из мужского туалета... ну, это мужской туалет, надо пойти проверить!",
    ["好像是这个方向……"] = "Кажется, в этом направлении...",
    ["好像没有反应……"] = "Кажется, нет ответа...",
    ["好可怕！我的皮肤和我的秀发一样珍贵，绝对不容有失！"] = "Как ужасно! Моя кожа так же драгоценна, как и волосы, ее ни в коем случае нельзя терять!",
    ["好可怜，你以后就跟着我吧，我带你出门。"] = "Как жаль, теперь ты должен следовать за мной, я тебя выведу.",
    ["好吧……<P_Heart>（他刚才说木桩？这里没有什么木桩？）</>"] = "Хорошо... <P_Heart>(Он только что упомянул деревянный столб? Здесь нет деревянных столбов?)</>",
    ["好吧……劳烦你去帮我打探一下，听听观众都怎么说，拜托了。"] = "Хорошо... Пожалуйста, идите и помогите мне разобраться, послушайте, что говорит публика, пожалуйста.",
    ["好吧。"] = "Отлично.",
    ["好吧我承认，我就是想炫一下技，没想到……咳咳、我还有急事！再见！"] = "Ладно, признаюсь, я просто хотел блеснуть своими умениями, не ожидал... кашель-кхе, у меня срочное дело! До свидания!",
    ["好吧，其实我……是官方非凡者……"] = "Ладно, вообще-то я... официальный Потусторонний...",
    ["好吧，大帝保佑你，祝我们都能早日下班。"] = "Хорошо, да благословит вас Император. Надеюсь, мы оба сможем уйти с работы пораньше.",
    ["好吧，我去看看怎么回事。"] = "Ладно, пойду посмотрю, что случилось.",
    ["好吧，我承认你有坐在这里的资格了。"] = "Хорошо, я признаю, что у вас есть все необходимое, чтобы сидеть здесь.",
    ["好吧，我来叫醒他。"] = "Ладно, я его разбужу.",
    ["好吧，我现在就上台去。"] = "Хорошо, я сейчас выйду на сцену.",
    ["好吧，那我再回去优化一下，希望下次能再请你体验。"] = "Хорошо, тогда я вернусь и оптимизирую его. Я надеюсь пригласить вас испытать это снова в следующий раз.",
    ["好多文字和知识，涌进了我的大脑……"] = "Столько слов и знаний хлынуло ко мне в голову...",
    ["好多知识钻进了我的大脑！"] = "Столько знаний врезалось в мой мозг!",
    ["好心肠的闪电莉莉，二十五分钟赶到睡莲小镇，有什么魔法吗？"] = "Добросердечная Молниеносная Лили, прибывающая в Город Водяных Лилий через двадцать пять минут, здесь замешано какое-то волшебство?",
    ["好快！谢谢，我帮你整理快递吧。"] = "Так быстро! Спасибо, позвольте мне помочь вам организовать посылки.",
    ["好痛！"] = "Это больно!",
    ["好的……您自己小心，下山比上山更难……"] = "Хорошо... Берегите себя. Спуститься с горы труднее, чем подняться...",
    ["好的。<P_Heart>（好香，病人可以喷这么多香水吗……）</>"] = "ОК. <P_Heart> (Он так хорошо пахнет, может ли пациент носить столько духов...) </>",
    ["好的，先生。停驻的时间会一并计入车费，请您知晓。"] = "Очень хорошо, сэр. Время ожидания будет включено в стоимость проезда, обратите внимание.",
    ["好的，再见！感谢您的热心！愿你拥有美好的一天！"] = "Хорошо, до свидания! Спасибо за ваш энтузиазм! Пусть у вас будет чудесный день!",
    ["好的，您的红葡萄酒。另外，这是一位女士让我转交给您的。 "] = "Хорошо, твое красное вино. Кроме того, это мне дала одна женщина, чтобы передать вам.",
    ["好看吗？想让您看到不一样的我。"] = "Красиво? Хотелось показать вам себя с другой стороны.",
    ["好软的肚子……嗯，小狗，把钱收好。"] = "Такой мягкий пузик... Хм, щенок, убери деньги.",
    ["好酒量！来，我们几个好好喝一顿！"] = "Отличная переносимость алкоголя! Приходите, выпьем хорошенько!",
    ["好香！猪油炸蔬菜居然一点也不油腻。"] = "Такой ароматный! Жареные на сале овощи совершенно не жирные.",
    ["好！交给我吧！"] = "Хорошо! Предоставь это мне!",
    ["好！唱得好！这是你要的花！愿你邂逅甜蜜与浪漫！"] = "Хороший! Хорошо спел! Это тот цветок, который ты хотел! Пусть вам встретится сладость и романтика!",
    ["好！我们……赌一次！"] = "Хорошо! Давайте... рискнем!",
    ["好！我们回去重新开始，不到成功那一刻，猎龙的火焰不会熄灭！"] = "Хороший! Мы вернемся и начнем все сначала. До момента успеха пламя драконьей охоты не угаснет!",
    ["好！绕后！拍尾巴！"] = "Хороший! Круг позади! Хлопок хвостом!",
    ["好，你先忙。"] = "Хорошо, сначала займись делом.",
    ["好，我帮你。有什么线索吗？<P_Heart>（让他这样半截身子露在外面，吓到别人总不是个办法。）</>"] = "Хорошо, я помогу тебе. Есть какие-нибудь подсказки? <P_Heart>(Оставить его с открытой половиной тела наверняка кого-то напугает.)</>",
    ["好，我永远会记住这个故事的……"] = "Здорово, я запомню эту историю навсегда...",
    ["好，我知道了。快去吧，别超时了！"] = "Хорошо, я понимаю. Давай, не опаздывай!",
    ["好，爸爸给你记……"] = "Хорошо, папа тебе это запишет...",
    ["好，看起来精神不错。"] = "Хорошо, выглядишь бодрым.",
    ["好，跟上去偷听一下吧……"] = "Ладно, проследим за ними и подслушаем...",
    ["如今只需1万苏勒，您就可以成为这个庄园新的主人。"] = "Теперь всего за 10 000 суле вы можете стать новым владельцем этой усадьбы.",
    ["如你所见，这子弹是警局专用的。我现在根本不敢相信内部的人。"] = "Как видите, эта пуля является эксклюзивной для полицейского управления. Я не могу сейчас доверять никому внутри.",
    ["如您所见，我的主人是一名议员，怎么会和马桶有关……嗯。"] = "Как видите, мой хозяин — советник. Как он мог быть связан с туалетом... хм.",
    ["如您所见，老师的精神状态……不是很正常。"] = "Как видите, психическое состояние учителя... не очень нормальное.",
    ["如果不是爱国卫生运动，我的奶奶恐怕早就死于鼠疫，更别说生下我的父母了。"] = "Если бы не кампания по патриотической гигиене, моя бабушка, скорее всего, умерла бы от чумы, не говоря уже о том, чтобы родить моих родителей.",
    ["如果不是生计困难，我不会让茜安帮忙。"] = "Если бы не финансовые трудности, я бы не позволил Циану помочь.",
    ["如果你坚持，那么可以留下，亲眼见证这次实验，我相信你会改变想法。"] = "Если настаиваешь, можешь остаться и увидеть этот эксперимент собственными глазами. Уверен, ты передумаешь.",
    ["如果你怕了，可以回头，这毕竟是我自己的案子。"] = "Если ты боишься, ты можешь повернуть назад. В конце концов, это мой собственный случай.",
    ["如果你想追寻更多真相，“红手套”随时欢迎你。"] = "Если вы хотите узнать больше правды, Красные Перчатки всегда рады вам.",
    ["如果你愿意，我们今后还可以一起研读这本书，亲身体会其中的真谛。"] = "Если вы желаете, мы можем вместе изучить эту книгу в будущем и лично ощутить ее истинный смысл.",
    ["如果你有任何疑问或困惑，阿罗德斯就在这里，回答你的一切问题。"] = "Если у вас есть какие-либо вопросы или замешательство, Арродес здесь, чтобы ответить на все ваши вопросы.",
    ["如果你真的不介意，就吃完这道菜，向我证明你的心意吧。"] = "Если тебе правда всё равно, доешь это блюдо и докажи искренность своих чувств.",
    ["如果你觉得老身是邪神，也可以转告附近的教会。当然，馈赠也就归他们了。"] = "Если вы думаете, что я Злой Бог, вы также можете сообщить об этом в ближайшую церковь. Конечно, подарок тогда будет принадлежать им.",
    ["如果可以的话……能不能拍一张弗莱队长收到礼物时的照片？不用特意摆什么姿势，平常的样子就好。他不说话站在那里时，有种让人特别安心的感觉。"] = "Если возможно... не могли бы вы сфотографировать капитана Фрая, когда он получит подарок? Не нужно позировать, просто он как обычно. Когда он стоит и молчат, у него возникает такое чувство, что люди чувствуют себя особенно непринужденно.",
    ["如果您不介意的话，用这顶帽子为我母亲表演吧。"] = "Если вы не возражаете, пожалуйста, используйте эту шляпу, чтобы выступить перед моей мамой.",
    ["如果我注定要死去，没有见过她美丽的容颜将成为我最大的遗憾！"] = "Если мне суждено умереть, то не увидеть ее прекрасного лица будет моим величайшим сожалением!",
    ["如果我的主人能像您一样有效率，我将原谅她上次拿我当借口拖稿的事情。"] = "Если бы моя хозяйка была столь же исполнительна, как вы, я бы простил ей то, что в прошлый раз она прикрывалась мной, чтобы отложить сдачу рукописи.",
    ["如果我被带走关起来，那些人怎么办？"] = "Если меня заберут и посадят в тюрьму, что будет с этими людьми?",
    ["如果提前察觉，或许能避免不必要的牺牲。"] = "Если мы обнаружим это на ранней стадии, возможно, нам удастся избежать ненужных жертв.",
    ["如果是罗塞尔大帝，此时他会怎么做？"] = "Если бы это был император Розель, что бы он сделал в этот момент?",
    ["如果有个方便去那个俱乐部的人就好了。"] = "Если бы только был кто-то, кто мог бы легко пойти в этот Клуб.",
    ["如果有人翻至最后一页，会讶异地发现一则叛逆的《魔女与野兽》，那是你曾一时兴起书写的戏仿之作。"] = "Если кто-то перелистнет последнюю страницу, он будет удивлен, обнаружив мятежную «Ведьму и чудовище», пародию, которую вы написали по прихоти.",
    ["如果没有人再提出反对，就请新郎新娘在这份婚书上签字，缔结正式婚约。"] = "Если ни у кого нет дальнейших возражений, пожалуйста, попросите жениха и невесту подписать этот брачный контракт, чтобы заключить официальную помолвку.",
    ["如果警察找上门，我就说你是我养的宠物，怎么样？"] = "Если полиция придет к двери, я просто скажу, что ты мой питомец, как насчет этого?",
    ["妈妈……"] = "Мама...",
    ["妈妈，爸爸会在下一辆车上吗？"] = "Мама, а папа будет в следующем вагоне?",
    ["娜拉·柯莱呀！"] = "Нара Колли!",
    ["娜拉·柯莱！你别跑！"] = "Нара Колли! Не беги!",
    ["学校还在缩减历史系的研究预算，现在我的学生数量还没有五年前的一半多。"] = "Школа все еще урезает бюджет на исследования исторического факультета, и сейчас количество моих студентов даже не вдвое меньше того, что было пять лет назад.",
    ["它……它真的很温暖。就像冬天的壁炉，像爸爸的手。"] = "Оно... оно такое теплое. Словно камин зимой, словно папина рука.",
    ["它不适合继续留在这里，等等会有同事过来处理。"] = "Оставаться здесь нецелесообразно. Коллеги приедут разобраться в ближайшее время.",
    ["它们的每片羽毛都闪烁着自由的光辉！"] = "Каждое их перо сияет блеском свободы!",
    ["它刚刚说晋升？看来背后真的有非凡者在搞鬼。"] = "Там только что говорилось о продвижении? Кажется, за этим действительно стоит Потусторонний, создающий проблемы.",
    ["它只是晕倒了……你是自愿被它控制的？那你怎么会失去神智呢？"] = "Оно просто потеряло сознание... оно вами управлялось добровольно? Тогда как можно потерять рассудок?",
    ["它已经在了。"] = "Оно уже здесь.",
    ["它怎么像是在关心库克……先去看看库克的情况吧。"] = "Почему кажется, что он беспокоится о Куке... Сначала мне нужно пойти проверить Кука.",
    ["它改变不了仪式本身，更给不了你想守护他人的决心。"] = "Он не изменит самого ритуала и не даст тебе решимости защищать других.",
    ["它最后的气息，是从站台方向传来的……"] = "Его последняя аура донеслась со стороны платформы...",
    ["它正在成型。但还差最后一步——神明的祝福。"] = "Оно обретает форму. Но не хватает последнего шага: благословения божества.",
    ["它每次只会用力撞一扇门，每次会撞击<P_Yellow>不一样</>的门，上次，是<P_Yellow>壁炉</>旁边的那扇门……"] = "Оно каждый раз с силой бьется лишь в одну дверь, и каждый раз в <P_Yellow>другую</>. В прошлый раз это была дверь возле <P_Yellow>камина</>...",
    ["它源自一个隐秘的地方——廷根的<P_Yellow>集体潜意识世界</>。"] = "Оно берёт начало в тайном месте — <P_Yellow>мире коллективного подсознания</> Тингена.",
    ["它由值夜者正式成员轮换看守，里面至少还有两位教会内部的看守者，以及数不清的陷阱，千万不要随意靠近它，否则会沾染厄运。"] = "Его охраняют сменяющиеся официальные члены Ночного Ястреба, внутри есть как минимум два внутренних церковных стража, а также бесчисленное множество ловушек. Не подходите к нему случайно, иначе вас ждет неудача.",
    ["它的力量在没有封印的情况下，足以毁灭一个国家、甚至整个世界。"] = "Без запечатывания его силы достаточно, чтобы уничтожить страну или даже весь мир.",
    ["它说……是的。"] = "Там было сказано... да.",
    ["它都没有嘴，要怎么说话？"] = "У него даже рта нет, как он может говорить?",
    ["它里面分为几个区域，保存着一定序列的魔药配方和各种神奇材料，临时关押着异端、异种、邪教徒和隐秘组织成员。"] = "Он разделен на несколько зон, в которых хранятся формулы зелий определенных последовательностей и различные магические материалы, а также временно содержатся еретики, мутанты, культисты и члены тайных организаций.",
    ["它？撞门？"] = "Это? Стучать в дверь?",
    ["完美的底片。说实话，和你一起的这十四天，比我预想的更有意思。"] = "Идеальные негативы. Честно говоря, эти четырнадцать дней с тобой оказались интереснее, чем я ожидал.",
    ["完美！太完美了！"] = "Идеальный! Слишком идеально!",
    ["完美！太完美了！就连这些飞过的鸽子……"] = "Идеальный! Слишком идеально! Даже эти голуби пролетают...",
    ["完美！太完美了！简直让人想振臂喊出……"] = "Идеальный! Слишком идеально! Так и хочется поднять руки и закричать...",
    ["完蛋了，杰斯他……我是真的在打，不是演戏……"] = "Конец... Джесс, он... Я ведь правда дрался, а не притворялся...",
    ["实际上，我们在研究某种……炼金仪式，准确来说，是复现《赫密斯文典》记载的灵数映射仪式。"] = "На самом деле мы исследуем некий... алхимический ритуал. Точнее, это повторение ритуала картирования духовных чисел, записанного в «Кодексе Гермеса».",
    ["寄快递吗？价格公道，快到离谱！"] = "Отправляете посылку? Справедливая цена, быстрая до возмутительной степени!",
    ["对……刚刚他们突然冲过来抢车，还喊着猎龙啊荣耀啊之类的话……"] = "Да... только сейчас они вдруг бросились хватать карету, выкрикивая что-то вроде охоты на драконов и славы...",
    ["对。{{先生|女士}}，你是有钱生活的那种人。"] = "Да. { { Mr. | Ms. } }, вы из тех людей, которые живут богатой жизнью.",
    ["对不起，我的笔友，我的宝贝，我的甜心，我的小百合……"] = "Прости, мой друг по переписке, мое сокровище, моя возлюбленная, моя маленькая лилия...",
    ["对了……地上这些花……"] = "Кстати... эти цветы на земле...",
    ["对了！可以写信问“星星”先生！弗莱队长应该能联系上他！"] = "Точно! Можно написать господину «Звезде»! Капитан Фрай наверняка сможет с ним связаться!",
    ["对了，伦纳德叮嘱我，把那束塞维亚菊交给梅丽莎，你帮我们带给她吧。"] = "Кстати, Леонард просил меня передать Мелиссе тот букет севийских ромашек. Не могли бы вы отвезти их к ней для нас?",
    ["对了，你在护送过程中有没有发现什么异常？比如她提到过“玫瑰天堂”或者一个叫“邦尼”的名字？"] = "Кстати, ничего необычного во время сопровождения вы не заметили? Например, упоминала ли она «Розовый рай» или имя «Бонни»?",
    ["对了，你说你是愚者的信徒，既然也来了……"] = "Кстати, ты сказал, что веришь в Шута, и раз уж ты тоже пришел...",
    ["对了，她想留一张你收到礼物时的照片作纪念。"] = "Кстати, она хочет сохранить на память фотографию, на которой ты получаешь подарок.",
    ["对了，我想起来了！"] = "Точно, теперь я вспомнил!",
    ["对了，我昨天看见房东太太，她身子可算恢复了，之前强撑着也要做告解，真不容易。"] = "Кстати, я вчера видел хозяйку. Ее здоровье наконец поправилось. Ей было нелегко, учитывая, что она настояла на том, чтобы пойти на исповедь, даже когда едва держалась.",
    ["对了，队长。春夜沙龙的主人维拉夫人，她可能是个非凡者。 "] = "Кстати, капитан. Владелица салона «Весенняя ночь», миссис Вера, возможно, она из Потустороннего.",
    ["对历史学有兴趣、有热情的学生越来越少了，就算有天赋的学生也不愿意学历史。"] = "Студентов, искренне увлеченных историей, становится все меньше, и даже одаренная молодежь не желает посвящать себя этой науке.",
    ["对呀！你把太阳给了我，我也要把故事送给你！"] = "Это верно! Ты подарил мне солнце, а я хочу подарить тебе эту историю!",
    ["对啊！看你也是从盥洗室来到这里……我还以为警察知情呢。"] = "Ага! Учитывая, что ты тоже пришел сюда из туалета... Я думал, полиция об этом знает.",
    ["对对对，史密斯太太这次车祸可不轻啊。我听说赔了一大笔保险？"] = "Да-да, автокатастрофа миссис Смит была весьма серьёзной. Я слышал, они получили огромную страховую выплату?",
    ["对面的第二棵树下有个树洞，你把钱放进去，再回来找我。"] = "Под вторым деревом напротив есть нора, положите туда деньги и возвращайтесь, чтобы найти меня.",
    ["对，努力变强，从头再来！"] = "Правильно, упорно трудитесь, чтобы стать сильнее и начать все сначала!",
    ["对，库克可是现在廷根最受欢迎的主厨！"] = "Да, Кук сейчас самый популярный шеф-повар в Тингене!",
    ["对，我们绝不会说出他跟老大去了猎龙城的！"] = "Правильно, мы никогда не скажем вам, что он отправился в Город Охоты на Драконов вместе с боссом!",
    ["对，我的钱包又被……哎哟……"] = "Да, мой кошелёк снова... ай...",
    ["对，是有这么个地方。不过，他们给的“启示”有时候可比车费还让人琢磨不透。说到车费，车夫，我们这趟怎么算？ "] = "Да, есть такое место. Однако «откровения», которые они дают, иногда более загадочны, чем стоимость проезда. Говоря о стоимости проезда, водитель, как нам рассчитать эту поездку?",
    ["对，等你很久了。我就是开膛手杰斯，该开工了。"] = "Верно, заждался я тебя. Я и есть Потрошитель Джесс, пора за работу.",
    ["封印物，只是一个让你更快变强的媒介。"] = "Запечатанный Артефакт — лишь средство, помогающее вам быстрее стать сильнее.",
    ["将污水排出，或许能解决问题……"] = "Слив канализации может решить проблему...",
    ["尊敬的{{先生|女士}}，打扰您片刻，不知您是否对历史与艺术情有独钟？我手头有一处极其独特的庄园，正寻找一位有缘人愿意继承它的故事。"] = "Уважаемый {{Mr.|Ms.}}, простите на минутку. Интересно, есть ли у вас особая любовь к истории и искусству? У меня есть чрезвычайно уникальное поместье, и я ищу человека, которому суждено унаследовать его историю.",
    ["尊敬的女士和先生，请容我荣幸地为各位介绍，享誉廷根的原创料理——"] = "Уважаемые дамы и господа, позвольте мне иметь честь представить вам авторскую кухню, знаменитую в Тингене—",
    ["尊敬的阿罗德斯大人，我有一些问题想请教一下"] = "Уважаемый г-н Арродес, у меня есть несколько вопросов, которые я хотел бы задать.",
    ["小可怜，我很想教教你什么叫时尚……"] = "Бедняжка, мне очень хочется научить тебя, что такое мода...",
    ["小女孩每天都在黑夜里摸索前行。她摸过粗糙的石墙，摸过柔软的花瓣，摸过冰冷的雨水。"] = "Маленькая девочка каждый день на ощупь пробиралась сквозь тьму. Она касалась шершавых каменных стен, нежных лепестков цветов и ледяных капель дождя.",
    ["小姑娘，你在找什么吗？"] = "Маленькая девочка, ты что-то ищешь?",
    ["小柯莱……真的种出了最大的南瓜。 "] = "Маленький Колли... действительно вырастил самую большую тыкву.",
    ["小狗装死动作复原"] = "Действие щенка восстановлено",
    ["就你这点钱，连给我的盥洗室翻修都不够用。"] = "Этих твоих грошей не хватит даже на ремонт моей уборной.",
    ["就像罗塞尔大帝说过的——“所有罪恶的行为总有一天会发现，即使地上所有的泥土把它们遮掩！”"] = "Как говорил император Рассел – «Все злые дела однажды будут раскрыты, даже если вся грязь на земле их покроет!»",
    ["就像罗塞尔大帝说过的那样——"] = "Как сказал император Розель:",
    ["就在此处，将织茧与灰雾尘埃融合。我会为你打开历史的帷幕。"] = "Вот здесь соедините кокон с серой туманной пылью. Я приоткрою для вас завесу истории.",
    ["就在这里，我记得……不，我不记得了，我记错了吗？"] = "Это вот здесь, я помню... Нет, не помню. Я запомнил это неправильно?",
    ["就当我是今天的特别摄影师。听说前面十三天都是别人给你拍照，最后一天，换个角度，给自己也拍一张？"] = "Просто считайте меня сегодняшним специальным фотографом. Я слышал, что другие фотографировали тебя последние тринадцать дней. В последний день почему бы не сменить ракурс и не взять себе такой?",
    ["就把它留在这里吧，说不定还会有人写出更精彩的故事！"] = "Давайте оставим это здесь. Возможно, кто-то другой напишет еще более гениальную историю!",
    ["就是你吃了我种的奇异果吧。难怪刚才感受到，有一部分力量被分走了。"] = "Так это ты съел странный фрукт, который я посадил. Неудивительно, что сейчас я почувствовал, как часть моей силы утекает.",
    ["就是坐下吗？"] = "_\n\nПросто сесть?",
    ["就是它！谢谢！我能用完美的姿态迎接他了！ "] = "Вот и все! Спасибо! Могу поприветствовать его в идеальном состоянии!",
    ["就是这个！多谢……愿大地保佑你。"] = "Оно самое! Благодарю... Да благословит тебя Мать-Земля.",
    ["就是这里了，卢娜应该在等着我。"] = "Это место; Луна должна ждать меня.",
    ["就是这间。老威廉一个人住，死了三个月了。每天晚上都能听见翻东西的声音，窸窸窣窣的，像有人在找什么。吓死人了，现在房子也租不出去！"] = "Это эта комната. Старый Уильям жил здесь один и уже три месяца как умер. Каждую ночь слышен звук роющихся вещей, шорох, как будто кто-то что-то ищет. Это ужас, а теперь дом даже сдать нельзя!",
    ["就是那阵晃动，不是您做的吗？"] = "Это ведь было то сотрясение, разве не вы его устроили?",
    ["就是，这次可一根手指头都没碰你。 "] = "Точно, в этот раз я даже пальцем к тебе не прикоснулся.",
    ["就没有两全其美的办法吗？！"] = "Неужели нет способа получить лучшее из обоих миров?!",
    ["就算找不到宝藏，在月光下使舵，喝着烈朗齐 ，唱着水手歌，想想也美滋滋的……"] = "Даже если не найду сокровищ, стоять у штурвала под лунным светом, пить леланчи и распевать матросские песни — от одной мысли на душе сладко...",
    ["就算离开了这里，我们又能去哪儿呢？我们什么都不会，长得又瘦又小，没有工厂想要这样的孩子。"] = "Даже если мы уйдем отсюда, куда мы сможем пойти? Мы ничего делать не умеем, мы худые и маленькие, и ни одна фабрика не хочет таких детей.",
    ["就要还了，我是想让他知道，不是要找的戒指都能找回来。"] = "Я собирался вернуть их; Я просто хотел, чтобы он знал, что не каждое кольцо, которое ты ищешь, можно найти.",
    ["就这些。"] = "Вот и все.",
    ["尸体变成了什么东西？文字？"] = "Во что превратился труп? Текст?",
    ["山姆发现后，在后面那个追哟……"] = "Сэм погнался за ними, когда узнал...",
    ["山姆知道自己能继承亿万财产后，打算抛下梅兰妮和斯嘉丽另寻新欢……"] = "После того, как Сэм узнал, что может унаследовать миллиарды, он планировал бросить Мелани и Скарлетт и найти новую возлюбленную...",
    ["山姆都摔成这样了，还傻笑呢……"] = "Сэм так сильно упал, но все еще улыбается...",
    ["工作，拿钱。不工作，没钱……我的规矩就这么简单，简单到……连你这种塞满煤灰的小脑袋瓜都听得懂！"] = "Работай, получай деньги. Не работай, нет денег... мои правила настолько просты, настолько просты, что... даже такая маленькая голова, как твоя, наполненная угольной пылью, сможет их понять!",
    ["工厂区夜晚，温妮正在和一位穿着优雅的男人交谈，男人只有背影，并看不清脸。"] = "Ночью в заводском районе Винни разговаривает с элегантно одетым мужчиной. Мужчину видно только сзади, и его лицо не видно четко.",
    ["工厂污水是瘟疫的源头？"] = "Являются ли заводские сточные воды источником чумы?",
    ["工厂里最近运了几批货。每次数量不多，送到了廷根各处。"] = "Недавно на завод поступило несколько партий. Количество каждый раз было небольшим, и их рассылали по всему Тингену.",
    ["工厂里的粉尘在伤害我们的肺，夺走我们的生命，但那些工厂主呢？他们只关心我们请病假会不会影响工期！"] = "Пыль на фабрике вредит нашим легким и уносит жизни, а как насчет владельцев фабрик? Их волнует только то, повлияет ли наш больничный на период строительства!",
    ["左边吧，我是左撇子，用左手杀人习惯一些。"] = "Левый. Я левша, поэтому больше привык убивать левой рукой.",
    ["左边的这瓶药可以让您的头顶恢复勃勃生机，头发就像春天的藤蔓一样疯长。"] = "Флакон с лекарством слева может вернуть вашей коже головы жизненную силу, и ваши волосы начнут буйно расти, как лозы весной.",
    ["巨龙出没……"] = "Появление дракона...",
    ["差点忘了跟你道别！"] = "Чуть не забыл попрощаться!",
    ["已经逃出非凡力量生效的范围了吗……"] = "Избежал ли он действия силы Потустороннего?",
    ["希望他能顺利毕业，不用再重做实验数据了。"] = "Я надеюсь, что он сможет успешно закончить учебу, не переделывая свои экспериментальные данные.",
    ["帕利诺，我找到了。 原来……金秋湖就是你的家乡。 "] = "Палино, я нашел это. Итак... Озеро Золотая Осень - ваш родной город.",
    ["帮我个忙，拿着它去街上走一圈，帮我看看大家——特别是那些最挑剔的美食家们——对它是什么反应？ "] = "Сделайте мне одолжение, выведите его на прогулку на улицу и помогите мне посмотреть, как все, особенно самые привередливые гурманы, на него отреагируют?",
    ["帮我烧了这封信吧，她都收不到了。"] = "Помогите мне сжечь это письмо; она все равно не сможет его получить.",
    ["帮我转达库克，两个人做菜的确比一个人做菜要更快更稳，味道也的确没受影响。"] = "Скажите Куку, что приготовление пищи вдвоём действительно происходит быстрее и стабильнее, чем в одном, и на вкус это не влияет.",
    ["干嘛这么惊讶，我不过是一本普普通通会发光会写字的书……真正值得赞叹的是罗塞尔大帝笔下的世界，那个丰富多彩、让人沉迷的广阔天地！"] = "Почему так удивлен? Я всего лишь обычная книга, которая светится и пишет... Что действительно достойно восхищения, так это мир, написанный императором Розеллой, — этот богатый, красочный и огромный мир, который сводит людей с ума!",
    ["年轻人，你眼睛是不是有问题？什么都看不见。"] = "Молодой человек, у вас что-то с глазами? Вы ничего не видите.",
    ["年轻人，我还要陪戴维一整天，谢谢你陪我到这里。"] = "Молодой человек, мне еще придется сопровождать Дэвида целый день. Спасибо, что сопровождали меня здесь.",
    ["年轻人，身手不错。不过……其实你不必出手的。"] = "Молодой человек, хорошие движения. Однако... на самом деле вам не пришлось вмешиваться.",
    ["年轻人，还好吗？"] = "Молодой человек, с вами все в порядке?",
    ["并且，它每隔一段时间就会试图撞门进来！"] = "И время от времени он пытается протаранить дверь, чтобы войти!",
    ["库克不对劲，他的气场看起来并不健康；身上一点做饭痕迹都没有，却在灶台留下了鼻涕？"] = "Кук не прав, его аура выглядит нездоровой; на нем нет следов готовки, а сопли на плите оставил?",
    ["库克先生！"] = "Мистер Кук!",
    ["库克先生，我是慕名而来，想请您做一道芥末章鱼。"] = "Мистер Кук, я пришел сюда по репутации, хочу попросить вас приготовить горчичного осьминога.",
    ["库克总会在章鱼完全熟透之前分五次浸泡冰水，这会让肉有种奇妙的韧劲。但这道芥末章鱼……肉的韧劲消失了，肉质也很奇怪……"] = "Кук всегда пять раз вымачивает осьминога в ледяной воде, прежде чем он полностью приготовится, что придает мясу прекрасную жевательную способность. Но этот горчичный осьминог... мясо пропало, текстура тоже очень странная...",
    ["库克状态有点……"] = "Состояние Кука какое-то...",
    ["库克肯定有些本事，不然怎么来海岸线餐厅不久就成了主厨呢！"] = "Повар должен обладать некоторыми навыками, иначе как бы он мог стать шеф-поваром вскоре после прибытия в ресторан «Береговая линия»!",
    ["库克非常尊重食物，绝不可能让厨房不干净，可能有什么误会？"] = "Повар очень уважает еду и никогда не допустит, чтобы на кухне было нечисто. Может ли быть какое-то недоразумение?",
    ["库克！“厨王之王”！居然能碰到你本人！"] = "Кук! Сам «Король кулинаров»! Поверить не могу, что встретил вас собственной персоной!",
    ["库克，你等一下。"] = "Кук, подожди минутку.",
    ["库克，好久不见。"] = "Кук, давно не виделись.",
    ["库克，重新做一道芥末章鱼！马西莫女士的报道如果发出去，我们都得完蛋！拿出你的水平来，只有满足了马西莫的味蕾，她才可能会放过我们！"] = "Кук, переделай осьминога с васаби! Если статья мисс Массимо выйдет в печать, нам всем крышка! Покажи все свое мастерство: только если угодишь ее тонкому вкусу, она, быть может, пощадит нас!",
    ["库克？我是马西莫，门口那篇文章，是我写给你的，你看了吗？"] = "Готовить? Я Массимо. Эту статью у двери я написал для тебя. Вы прочитали это?",
    ["应该不存在这个机会。她很恐惧与外界的接触，明明是那么害怕寂寞的人……"] = "Такой возможности, вероятно, не существует. Она очень боится контакта с внешним миром, хотя она такой одинокий человек...",
    ["应该就是这个水池。"] = "Это должен быть этот фонтан.",
    ["应该就是这里。"] = "Это должно быть место.",
    ["底片我留一张，另一张给你。诡节快乐。明年或许我们还会再见的。"] = "Один негатив я оставлю, а другой для вас. С Днем Ползучего. Возможно, мы встретимся снова в следующем году.",
    ["店歌——起——"] = "Гимн заведения — запе-вай!",
    ["废弃的报刊亭……应该就是这里。"] = "Заброшенный газетный киоск... вот он.",
    ["廷根才不可能，不然我们肯定知道——我想起来了，萨拉姐姐说过，这和王子殿下有关！王子好像叫……埃德披萨？"] = "Тинген невозможен, иначе мы бы точно знали — теперь я помню, сестра Сара сказала, что это как-то связано с Его Высочеством Принцем! Принца вроде бы зовут... Эде-пицца?",
    ["开锁的技艺本来就不是用来证明自己多厉害的，我常常这样告诉自己。"] = "Искусство взлома замков вовсе не для того, чтобы доказывать своё превосходство — я часто напоминаю себе об этом.",
    ["弄丢了？那就再扣一半。"] = "Потеряли? Затем вычтите еще половину.",
    ["弗莱队长——“星星”先生！您也在这里？"] = "Капитан Фрай — господин «Звезда»! Вы тоже здесь?",
    ["弗莱队长说过，某些非凡物品可以创造出异常空间，那份手稿或许就有这种能力。"] = "Капитан Фрай однажды сказал, что некоторые запечатанные артефакты могут создавать ненормальные пространства; возможно, эта рукопись обладает такой способностью.",
    ["弗莱队长通常在办公室，我可以帮你转交。 "] = "Капитан Фрай обычно в офисе, и я могу передать это вам.",
    ["弗莱队长！你怎么突然出现了？"] = "Капитан Фрай! Почему ты вдруг появился?",
    ["弗莱队长！美人鱼在二楼的房间里，没有受到任何伤害。"] = "Капитан Фрай! Русалка в комнате на втором этаже, ей не причинили никакого вреда.",
    ["弗莱！这三个人，两个小孩子，一个工作狂，你管管他们！"] = "Фрай! Эти трое — двое детей и один трудоголик, присмотри за ними!",
    ["弗莱，人我就先借走一会儿。"] = "Фрай, я ненадолго одолжу этих людей.",
    ["弗雷德先生，是否有人往马桶里扔过垃圾？"] = "Мистер Фред, кто-нибудь выбрасывал мусор в унитаз?",
    ["弗雷德先生，麻烦你们先离开。"] = "Мистер Фред, пожалуйста, уходите первым.",
    ["当一个东西你观察了几千遍，它自然会在你心里留下声音。这不是疯狂，{{先生|女士}}，这只是一种……熟悉。"] = "Когда вы наблюдаете что-то тысячи раз, это естественным образом оставляет голос в вашем сердце. Это не безумие, {{Mr.|Ms.}}, это просто... знакомство.",
    ["当时，龙从天上冲下来，张开血盆大口，喷出的火焰能把钢铁熔化！"] = "В это время дракон бросился с неба, открыл свою окровавленную пасть, и распыленный им огонь мог расплавить сталь!",
    ["当然"] = "Разумеется",
    ["当然不是……其实，我也是人类。"] = "Конечно нет... вообще-то я тоже человек.",
    ["当然不是！其实，我也是人类……至少曾经是。"] = "Конечно, нет! На самом деле я тоже человек... по крайней мере, раньше.",
    ["当然了亲爱的，只要我们在一起，没有什么困难是不能解决的。"] = "Конечно, моя дорогая. Пока мы вместе, нет такой трудности, которую мы не смогли бы преодолеть.",
    ["当然可以。"] = "Конечно.",
    ["当然可以。我叫{{PlayerName}}。"] = "Конечно. Меня зовут {{PlayerName}}.",
    ["当然可以！跟我来！"] = "Конечно! Подписывайтесь на меня!",
    ["当然可以，乐意效劳。"] = "Конечно, я был бы рад помочь.",
    ["当然是因为市议员休伯特涉嫌贪污，而证据极有可能就藏匿在下水道中！"] = "Конечно же, потому что член городского совета Хьюберт подозревается в коррупции, а улики с высокой вероятностью спрятаны в канализации!",
    ["当然是真的。队长问我失踪案的跟进报告写完没有，我说快了，其实连标题都没写。"] = "Конечно, это правда. Капитан спросил, написал ли я отчёт по делу о пропавших, я ответил, что почти, а на самом деле даже заголовка не написал.",
    ["当然没有！我只送拿得动的订单，我可背不动你。"] = "Конечно, нет! Я доставляю только те заказы, которые могу нести, я не могу нести тебя на спине.",
    ["当然知道，他是殡仪馆新来的学徒，跟外面不是一伙。"] = "Конечно знаю, он новый ученик в похоронном бюро и не из той компании, что снаружи.",
    ["当然！"] = "Конечно!",
    ["当然！<P_Heart>（鞠躬）</>廷根最好的小丑，即将为你带来最盛大的表演！"] = "Конечно! <P_Heart> (Кланяется) </> Лучший клоун Тингена собирается показать вам грандиозное представление!",
    ["当然，如果他同意的话。"] = "Конечно, если он согласится.",
    ["当然，如果她同意的话。"] = "Конечно, если она согласится.",
    ["当然，我愿意！"] = "Конечно, я готов!",
    ["当然，给你打折！不对……"] = "Конечно, я сделаю вам скидку! Нет, подожди...",
    ["影响是什么？"] = "Каковы последствия?",
    ["往哪儿跑？这破屋子连个后门都没有。"] = "Куда бежать? В этой жалкой лачуге даже чёрного хода нет.",
    ["待会儿你看准机会也冲上去，看能不能发现什么。"] = "Позже выжди удобный момент и тоже бросайся вперед — вдруг удастся что-то разузнать.",
    ["很多年前库克说过，人们至少要在美食面前保持诚实，我希望他没有忘记自己说过的话。"] = "Много лет назад Кук сказал, что люди должны быть честными хотя бы в отношении еды. Надеюсь, он не забыл, что сказал.",
    ["很好，不过学校现在查的这么严，不知道那个神秘卖家还在不在那里，你可以去碰碰运气。"] = "Очень хорошо, но в школе сейчас настолько строго проверяют, что я не знаю, там ли еще тот загадочный продавец. Можешь пойти попытать удачу.",
    ["很好，准备完成，可以开演了。"] = "Очень хорошо, подготовка завершена. Мы можем начать представление.",
    ["很好，接下来要布置道具。"] = "Отлично, теперь нужно расставить реквизит.",
    ["很好，罗塞尔大帝在成为执政官后，开始推广讲卫生，预防、减少以至消灭疾病，提高健康水平的运动。"] = "Очень хорошо. Став консулом, император Розель начал продвигать кампанию, направленную на то, чтобы уделять особое внимание гигиене, предотвращать, уменьшать и даже искоренять болезни, а также улучшать стандарты здравоохранения.",
    ["很好，让我来解决这区区黄金马桶。"] = "Очень хорошо, позвольте мне разобраться с этим простым золотым унитазом.",
    ["很快……就能结束了吧……<P_Heart>（声音渐息）</>"] = "Скоро... все закончится, да... <P_Heart> (голос затихает) </>",
    ["很接近之前的味道，但还是不太对……"] = "Очень близко к прежнему вкусу, но всё же не то...",
    ["很有力量的观点。不过，总觉得其中似乎少了一丝……韵味？"] = "Очень сильная точка зрения. Однако мне кажется, что ему не хватает немного... шарма?",
    ["很特别的非凡者，如果将来有机会见到她……"] = "Совершенно особенная Потусторонняя, если есть шанс увидеть ее в будущем...",
    ["很精致的帽子。你父母一定很珍惜它。 "] = "Очень изысканная шляпа. Твои родители, должно быть, этим дорожили.",
    ["很高兴认识你，你叫什么名字？"] = "Приятно познакомиться. Как вас зовут?",
    ["得了吧，谁祖上没风光过，现在呢，你当你的珠宝匠，我当我的码头工……"] = "Забудьте, чьи предки не были славными? Теперь ты твой ювелир, а я мой докер...",
    ["得去把门堵住！"] = "Мне нужно пойти заблокировать дверь!",
    ["心理诊疗非常顺利，我已经治好了他的癔症。"] = "Психологическое лечение прошло очень гладко. Я вылечил его истерию.",
    ["忍着点，我直接把你推出去！"] = "Потерпите, я вас прямо вытолкну!",
    ["快了……就要成功了……这些都是必要的牺牲……"] = "Почти у цели... успех вот-вот... все это необходимые жертвы...",
    ["快来不及了！开膛手杰斯马上要杀人了，你快去吧！"] = "Нет времени! Джек Потрошитель собирается кого-то убить, идите быстрее!",
    ["快看！“闪电莉莉”出现了！"] = "Смотреть! «Молниевая Лилия» появилась!",
    ["快，趁温热再泡一次冰水，然后开始调味，再静置十五分钟…… "] = "Быстро замочите его еще раз в ледяной воде, пока он еще теплый, затем начните приправлять его и оставьте на пятнадцать минут...",
    ["忽然有字了！这本书会自己写字？！"] = "Внезапно появился текст! Эту книгу можно написать самой?!",
    ["忽略掉废稿上的无数的“狗屎”"] = "Игнорируя бесчисленную «ерунду» по выброшенным черновикам.",
    ["怎么不会！镇上老鼠比人多，我不得赚翻了？"] = "Как это не будет! В городке крыс больше, чем людей — разве я не разбогатею?",
    ["怎么不吃？吃完和我回家坐坐，我妻子昨天说，想让你听听她新练习的曲子。"] = "Почему не ешь? Доешь и пойдём ко мне домой, посидим. Жена вчера говорила, что хочет, чтобы ты послушал пьесу, которую она недавно разучила.",
    ["怎么不知不觉就说出了这句话……"] = "И как это я умудрился брякнуть такое, сам не заметив...",
    ["怎么了梅丽莎？"] = "Что случилось, Мелисса?",
    ["怎么了，我的陛下？"] = "Что случилось, мое Величество?",
    ["怎么了，神使大人？"] = "Что случилось, Лорд Посланник?",
    ["怎么了，陛下？爱情是不分性别的，昨晚您不是很享受吗？"] = "Что случилось, Ваше Величество? Любовь не знает пола. Разве тебе не было весело вчера вечером?",
    ["怎么了？"] = "В чем дело?",
    ["怎么了？我脸上的妆花了吗？"] = "В чем дело? Мой макияж испорчен?",
    ["怎么了？觉得哪里不好吃吗？"] = "В чем дело? Думаете, это невкусно?",
    ["怎么会呢？你再看看，上面写着“追风雪的人”。"] = "Как такое могло быть? Посмотрите еще раз, там написано «Snow Chaser».",
    ["怎么会没有？它从崖壁伸出来，上面还有许愿涂鸦。"] = "Как могло не быть? Он торчит из скалы, и на нем есть граффити с загадыванием желаний.",
    ["怎么会这样，我明明已经补上了台词，演出应该继续才对！"] = "Как же так... Я ведь восполнил реплику, представление должно было продолжиться!",
    ["怎么办！？演出马上就要开始了，竟然发生了这种事情……"] = "Что я должен делать!? Спектакль вот-вот начнется, и вот такая вещь действительно произошла...",
    ["怎么办？我现在还动不了。而且我没办法……不，茜安，你可以的！"] = "Что же делать? Я все еще не могу пошевелиться. И я бессильна... Нет, Сиан, ты сможешь!",
    ["怎么可能是因蒂斯！姐姐说因蒂斯人说的话和我们不一样呀！而且这个曲子多快乐！听起来就是我们鲁恩的。"] = "Как это мог быть Интис! Сестра сказала, что язык, на котором говорят жители Интиса, отличается от нашего! И эта штука такая счастливая! Звучит так, будто это из нашего Лоэна.",
    ["怎么可能！"] = "Как это возможно!",
    ["怎么听起来像水手们喝多了编的故事……"] = "Как это похоже на историю, выдуманную пьяными моряками...",
    ["怎么回事，感觉有气流在胃部翻滚……肚子……好疼……"] = "Что происходит? Я чувствую, как потоки воздуха крутятся у меня в животе... в животе... так больно...",
    ["怎么回事？"] = "Что происходит?",
    ["怎么样？我导演得还不错吧。"] = "Как это было? Я неплохо это срежиссировал, не так ли?",
    ["怎么样？有收获吗？"] = "Ну как? Есть успехи?",
    ["怎么样？闪电莉莉就是这个速度！"] = "Как насчет этого? Молния Лили такая быстрая!",
    ["怎么这么快，太鲁莽了，现在还不是叫警察的时候吧……"] = "Почему так быстро? Слишком безрассудно. Наверное, еще не время звонить в полицию...",
    ["怎么，失望了？"] = "Что, разочарован?",
    ["怎么，看不惯？"] = "Что, не нравится то, что видишь?",
    ["怕……"] = "Испуганный...",
    ["怕什么？我又不会做什么恶作剧，至少现在不会。"] = "Чего ты боишься? Я не буду шалить, по крайней мере, не сейчас.",
    ["怕她拒绝。怕我说错话。怕她笑我。怕……什么都怕。"] = "Боюсь, она откажется. Боюсь, я скажу что-то не то. Боюсь, она будет надо мной смеяться. Боюсь... всего боюсь.",
    ["急死我了，快让演出继续！"] = "Я умираю от беспокойства, поторопитесь и пусть спектакль продолжается!",
    ["怪不得这里被称为“<P_Yellow>廷根最难以下咽的餐厅</>”！"] = "Неудивительно, что это место называют «<P_Yellow>, самый несъедобный ресторан в Тингене, </>»!",
    ["总之，{{先生|女士}}，您愿意为了这个八音盒出多少钱？"] = "В любом случае, {{Сэр | Мадам}}, сколько вы готовы заплатить за эту музыкальную шкатулку?",
    ["总之，免费试骑，欢迎体验！"] = "В любом случае, бесплатные пробные поездки, приглашаем вас испытать их!",
    ["总之，接受福音，完成我的任务。"] = "В общем, прими благую весть и выполни моё поручение.",
    ["总之，谢谢你！下周六我们第一次约会，你要不要来当见证人？"] = "В любом случае спасибо тебе! В следующую субботу у нас первое свидание, не хочешь прийти и поддержать нас?",
    ["总有一天，我要让所有人都知道我的名字——艾玛·莱克汉姆！像艾德雯娜女士那样，成为海上传奇的一部分！"] = "Однажды я сообщу всем мое имя — Эмма Ларшам! Как и мисс Эдвина, я стану частью морских легенд!",
    ["总有办法……父亲说过，这四个字不能放在计划里。"] = "Всегда есть выход... Отец сказал, что эти четыре слова никогда не должны быть частью плана.",
    ["恐惧吧、忏悔吧，在生不如死中度过每一天吧！"] = "Бойтесь, покайтесь и проводите каждый день в судьбе хуже смерти!",
    ["恭喜。"] = "Поздравляю.",
    ["恭喜你，你已经学会了这个问答游戏。"] = "Поздравляем, вы изучили эту игру вопросов и ответов.",
    ["恭喜恭喜！这是你的奖金。"] = "Поздравляю, поздравляю! Это твоя премия.",
    ["您……"] = "Вы...",
    ["您……您说的对，也许我从一开始就不该指望雷克斯。一旦我们没了用，他就会头也不回地抛弃我们……"] = "Ты... ты прав. Возможно, мне не следовало с самого начала рассчитывать на Рекса. Как только мы перестанем быть полезными, он бы бросил нас, не задумываясь...",
    ["您。只要您。您的手好烫……还是我太烫了？"] = "Ты. Только ты. У тебя такие горячие руки... или мне слишком жарко?",
    ["您不能在街上这样拦人。什么鸽子，我可以帮您找。 "] = "Нельзя так останавливать людей на улице. Какие бы голуби ни были, я могу помочь вам их найти.",
    ["您也很厉害，我是真的被吓到了。"] = "Вы тоже очень сильны, я правда испугался.",
    ["您也觉得……我是个轻浮的女人？ "] = "Вы тоже думаете... Я легкомысленная женщина?",
    ["您会变魔术？请跟我来。"] = "Ты умеешь творить магию? Пожалуйста, пойдем со мной.",
    ["您先离开让他冷静一下。我在这里守着，万一有事我马上叫您。而且……<P_Heart>（低声）</>有些话，可能不方便当着父母的面说。"] = "Вам лучше пока уйти и дать ему успокоиться. Я останусь здесь и пригляжу за ним, а если что-то случится, сразу же позову вас. К тому же... <P_Heart>（шепотом）</> кое-что, возможно, не стоит говорить при родителях.",
    ["您可以称呼我为“波洛”。"] = "Вы можете называть меня «Пуаро».",
    ["您好，{{先生|女士}}。"] = "Здравствуйте, {{господин|госпожа}}.",
    ["您好？闪电速递，加急文件！"] = "Привет? Молния Экспресс, срочный документ!",
    ["您如果想帮忙，可以去她家喊她女儿过来。广场后面第二条巷子，门口种着月桂树的那家。 "] = "Если вы хотите помочь, вы можете пойти к ней домой и позвать ее дочь. Это дом во втором переулке за площадью, у входа посажен лавр.",
    ["您怎么知道！就是那个！"] = "Как ты узнал! Это тот самый!",
    ["您愿意支付的价格是？"] = "Какую цену вы готовы заплатить?",
    ["您是执掌好运的黄黑之王"] = "Ты король желтого и черного, приносящий удачу.",
    ["您是灰雾之上的神秘主宰"] = "Вы — таинственный владыка над серым туманом",
    ["您是米莉安太太的女儿？她在广场上拦人。可能需要您去接她一下。"] = "Вы дочь миссис Мириам? Она останавливает людей на площади. Возможно, тебе придется забрать ее.",
    ["您是说这其中另有隐情？"] = "Вы хотите сказать, что за этим стоит скрытая история?",
    ["您是隐秘之母，厄难与恐惧的女皇，安眠和寂静的领主"] = "Ты — Мать Сокрытия, Императрица Бедствий и Ужасов, Повелитель Сна и Тишины.",
    ["您有家室了，我不想做那样的女人。"] = "У тебя есть семья, я не хочу быть такой женщиной.",
    ["您满意就太好了！您放心，之后我们会好好注意后厨卫生。"] = "Я так рада, что ты доволен! Не волнуйтесь, с этого момента мы будем очень внимательно относиться к кухонной гигиене.",
    ["您满脸写着正直，不知道能不能帮我购买戒指和花束，替我回绝我的笔友？"] = "Ваше лицо полно целостности. Интересно, не могли бы вы помочь мне купить кольцо и букет и отказаться от моего друга по переписке?",
    ["您现在需要点单吗？"] = "Вам нужно сделать заказ сейчас?",
    ["您的丈夫……还活着啊……"] = "Ваш муж... еще жив...",
    ["您的丈夫已经……"] = "Ваш муж уже...",
    ["您的心理价格是？"] = "Какова ваша психологическая цена?",
    ["您的戒指也丢了？"] = "Твоё кольцо тоже потерялось?",
    ["您的结婚戒指一直没找到，就因为没制定好计划！让我来！"] = "Ваше обручальное кольцо до сих пор не нашлось лишь потому, что у вас не было четкого плана! Предоставьте это мне!",
    ["您的预期是？"] = "Чего вы ожидаете?",
    ["您真是……太善良了！如果可以，您能先替我代付购物的钱吗？出来得匆忙，我必须回去取钱包……我会在这里等您！"] = "Вы действительно... слишком добры! Если возможно, не могли бы вы сначала оплатить для меня покупки? Я вышел в спешке и должен вернуться за бумажником... Я буду ждать тебя здесь!",
    ["您真是太善良了！如果可以，您能先替我代付购物的钱吗？出来得匆忙，我必须回去取钱包……我会在这里等您！"] = "Вы действительно слишком добры! Если возможно, не могли бы вы сначала оплатить для меня покупки? Я вышел в спешке и должен вернуться за бумажником... Я буду ждать тебя здесь!",
    ["您瞧，运营方式都一样，投币开锁，随处可还，但车各有千秋。"] = "Видите ли, принцип работы один и тот же: вставить монетку, чтобы разблокировать, вернуться куда угодно, но у каждого велосипеда свои достоинства.",
    ["您确定要靠近吗？这具尸体……死得很不安详。"] = "Вы уверены, что хотите подойти ближе? Этот труп... умер не мирной смертью.",
    ["您认识她？"] = "Ты знаешь ее?",
    ["您让我知道，我的心还活着。"] = "Ты заставил меня понять, что мое сердце все еще живо.",
    ["您还满意吗？这批只是样品，我们还在镇上养了好几个鼠群。"] = "Вы довольны? Это лишь образец, в городе мы выращиваем ещё несколько крысиных стай.",
    ["想！"] = "Да!",
    ["想！我想摆脱污染，找到一切的答案！"] = "Да! Я хочу избавиться от Искажения и найти ответ на все вопросы!",
    ["意料之中的选择！毕竟没有人能够抵挡得住魔女的魅力……我这就为您召唤魔女，陛下。"] = "Ожидаемый выбор! Ведь никто не сможет устоять перед чарами ведьмы... Я сейчас призову для вас ведьму, Ваше Величество.",
    ["愚者信仰虽然算正神信仰，在水手群体里也很流行。但身为学生，不应该靠神明来解决课业问题，跟我去风纪处写检查！"] = "Хотя вера Шута считается верой в истинное божество и довольно популярна среди моряков, будучи студентом, вам не следует полагаться на богов в решении своих академических задач. Пойдем со мной в Дисциплинарный отдел, чтобы написать саморефлексию!",
    ["感冒？那灶台上的那些不会是……"] = "Простуда? Тогда те штуки на плите не были бы...",
    ["感受到了吗？它在为您跳动。"] = "Ты чувствуешь это? Оно бьется для тебя.",
    ["感受怎么样？"] = "Как ощущения?",
    ["感谢你协助我的工作。"] = "Благодарю за помощь в моей работе.",
    ["感谢你帮助我演完了这出戏剧。拜你所赐，我现在有了不少新的心得和灵感……"] = "Спасибо, что помогли мне закончить эту пьесу. Благодаря вам у меня появилось много новых идей и вдохновения...",
    ["感谢你这段时间的帮助，我要给你一份足够丰厚的回报。"] = "Спасибо за вашу помощь в это время. Я хочу дать вам достаточно щедрое вознаграждение.",
    ["感谢您的帮助，{{先生|女士}}。这是一点见面礼，期待我们的再会。"] = "Спасибо за помощь, {{ Mr. | Ms. }}. Это небольшой знак признательности, с нетерпением ждем нашей следующей встречи.",
    ["感谢您的指正。看来，我在背诵陛下的格言时，还不够用心。"] = "Спасибо за исправление. Кажется, я был недостаточно старателен, декламируя изречения Императора.",
    ["感谢您的聆听！"] = "Спасибо, что выслушали!",
    ["感谢您的配合，我们的演出顺利完成了！"] = "Благодарим за содействие, наше представление прошло успешно!",
    ["感谢您！好心的{{先生|女士}}。"] = "Спасибо! Вид {{ Mr. | Ms. }}.",
    ["愿女神庇佑，踏踏实实完成研究工作总能毕业的！"] = "Пусть Богиня защитит меня; Если я буду стабильно работать над своими исследованиями, я обязательно закончу обучение!",
    ["愿黑夜庇护你。迷途的灵魂，终会在这里找到归宿。"] = "Пусть Вечная Ночь защитит тебя. Заблудшие души рано или поздно найдут здесь свое пристанище.",
    ["成功"] = "Успех",
    ["成功了。"] = "Успех.",
    ["成功进入空间了！这里……是下水道？我记得，我被马桶排水口“冲”了下来？"] = "Удалось проникнуть внутрь! Это что... канализация? Если не ошибаюсь, меня только что буквально «смыло» через унитаз?!",
    ["我……"] = "Я...",
    ["我……就在你眼前……年轻人，可否帮老身一个忙——"] = "Я... прямо перед тобой... Молодой человек, не окажете старухе услугу?...",
    ["我……忘记了。"] = "Я... забыл.",
    ["我……我不知道。酒精确实给了我勇气，让我做了这辈子最疯狂的事。当着所有人的面吻您，然后像个懦夫一样逃走。"] = "Я... я не знаю. Алкоголь и правда придал мне храбрости, чтобы совершить самый безумный поступок в моей жизни: поцеловать вас на глазах у всех, а потом сбежать как трус.",
    ["我……我了解孩子们的脾气，也许我能帮忙。"] = "Я... я знаю детские нравы, может, смогу помочь.",
    ["我……我听您的，我愿意相信您。"] = "Я... я тебя послушаю. Я готов доверять тебе.",
    ["我……我是用了些特别的方法。你是纯粹的观察？"] = "Я... я использовал некоторые особые методы. Вы просто наблюдаете?",
    ["我……我还要忏悔最后一件事……<P_Heart>（顿了顿）</> 我有时候会想，我能不能不当告解室，去当别的什么东西……"] = "Мне... мне осталось покаяться в одном... <P_Heart> (Пауза) </> Иногда я задаюсь вопросом, могу ли я не быть исповедником, а вместо этого быть кем-то другим...",
    ["我、我不是！什么资料！？"] = "Я, я нет! Какие материалы!?",
    ["我、我叫迈尔斯，他是卡兰，我们是附近的学生……"] = "Я, я Майлз, он Калан, мы студенты из близлежащих районов...",
    ["我、我想过短暂热烈的一生，而不是漫长无聊的一生。"] = "Я хочу прожить короткую и страстную жизнь, а не длинную и скучную.",
    ["我一定忽略了什么……再回后厨看看。"] = "Должно быть, я что-то пропустил... Вернусь на кухню и посмотрю еще раз.",
    ["我一定要拿回它！"] = "Я должен вернуть его!",
    ["我不会错过任何一次他们的纪念日。"] = "Я никогда не пропущу ни одного их юбилея.",
    ["我不敢。我在这坐了俩小时了，腿都是软的。"] = "Я не смею. Я сижу здесь уже два часа, а ноги у меня желеобразные.",
    ["我不是这个意思，只是想知道真相。"] = "Я не это имел в виду, я просто хочу узнать правду.",
    ["我不知道它之前是什么味道，但这一道非常美味！"] = "Не знаю, каким он был на вкус раньше, но это очень вкусно!",
    ["我不走！我自己的儿子，我自己……"] = "Я никуда не пойду! Мой собственный сын, я сама...",
    ["我为了多赚些钱给杰姆治病，只能一个人出来工作。但我一个人应付不来……就像刚才，差点摔死在烟囱里……"] = "Чтобы заработать денег на лечение Джема, мне приходится работать в одиночку. Но один я не справляюсь... вот как только что — чуть не разбился насмерть в трубе...",
    ["我也不知道……是那些字，越来越多，挤在一起就会变成那样。"] = "Я тоже не знаю... это те слова, их становится все больше и больше, и когда они сжимаются, они становятся такими.",
    ["我也同样没想着放你离开。既然今夜这一幕被你瞧见了，那就把命也留下来吧！"] = "Я тоже не собираюсь тебя отпускать. Раз уж вы видели эту сцену сегодня вечером, то сохраните и свою жизнь!",
    ["我也很难想象，她会就这样离开。"] = "Мне также трудно представить, что она просто так уйдет.",
    ["我也想起来了，哼哼。而且，我还记得王子不叫埃德披萨，叫埃哟萨克！"] = "Я тоже это вспомнил, хм. Более того, я до сих пор помню, что принца звали не Эд Пицца, а Эйосак!",
    ["我也有个朋友，急需一份内部资料！"] = "Еще у меня есть друг, которому срочно нужна копия инсайдерских материалов!",
    ["我也要谢谢您。虽然我还是很怕，但至少今天知道，那不是真的闹鬼，都是自己吓唬自己。"] = "Я тоже хочу вас поблагодарить. Мне всё ещё очень страшно, но теперь я хотя бы знаю, что это не настоящее привидение, я просто сам себя пугал.",
    ["我也觉得，真没劲……"] = "Я чувствую то же самое, это так скучно...",
    ["我了解了，接下来我要对施佩尔先生展开非常私密的心理诊疗，请你暂时回避，并且保证不让任何人进入这个房间。"] = "Я понимаю. Далее я проведу частную психологическую консультацию для г-на Шпеера. Пожалуйста, отойдите на минутку и убедитесь, что никто не вошел в эту комнату.",
    ["我今天的计划——九点，热气球升空。九点一刻，到达花海最佳求婚位置。九点半，求婚，海蒂感动落泪。九点四十五，为海蒂戴上戒指……"] = "Мой план на сегодня — 9:00, взлет воздушного шара. 8:15, прибытие в лучшее место среди цветочного моря. 8:30, предложение, Хайди тронута до слез. 8:45, надень кольцо Хайди...",
    ["我今天跑了三十多单，腿都跑断了——"] = "Я сегодня выполнил тридцать заказов, ноги сломаны...",
    ["我从来没告诉过任何人，包括我的家人……"] = "Я никогда никому не говорил, даже своей семье...",
    ["我从马桶穿越到了下水道消灭老鼠解开谜题最后击败了垃圾之主找到了黄金马桶见到罗塞尔大帝找到贪污证据从马桶里穿越了回来。"] = "Я прошел из туалета в канализацию, уничтожил крыс, решил головоломки, наконец победил Повелителя мусора, нашел золотой унитаз, встретил императора Розеллу, нашел доказательства порчи и вернулся через туалет.",
    ["我们一定会回来的！"] = "Мы обязательно вернемся!",
    ["我们不畏惧命运的捉弄，因为每一次不幸，都是一场华丽的变身。"] = "Мы не боимся насмешек судьбы, ведь всякая беда – великолепное преображение.",
    ["我们之后请顾客品尝一下，顺势卖出丝瓜，购买者可以获得食谱怎么样！"] = "Как насчет того, чтобы предложить клиентам попробовать его позже, а затем продавать люфу, пока мы этим занимаемся? Покупатели могут получить рецепт!",
    ["我们以美为名，在暗影中编织自己的网络。"] = "Мы плетем свою собственную сеть в тени во имя красоты.",
    ["我们去碰碰运气，看安迪有没有留下些什么线索。"] = "Давайте испытаем удачу и посмотрим, оставил ли Энди какие-нибудь подсказки.",
    ["我们又没买过，怎么可能知道！？"] = "Мы их не покупали, откуда нам знать!?",
    ["我们可以演一场驱鬼的戏码，告诉他们你的灵魂不安息，触碰你的尸体会招来诅咒。"] = "Мы можем разыграть представление с изгнанием духов и сказать им, что твоя душа не обрела покоя, а прикосновение к твоему телу навлечет проклятие.",
    ["我们在红石头上刻过愿望，还画过丑陋的涂鸦……"] = "Мы вырезали на красном камне свои желания и даже рисовали уродливые граффити...",
    ["我们在追查到这里时，品鉴会已经开始了，增援还在赶来的路上。"] = "Когда мы выследили их здесь, дегустационная вечеринка уже началась, а подкрепление еще в пути.",
    ["我们守的货，真是美人鱼？这得值多少金镑啊。"] = "Груз, который мы охраняем, — и правда русалка? Сколько же золотых фунтов она стоит.",
    ["我们将蒂亚开除的那天晚上，看不见的怪物就出现了。"] = "В ту ночь, когда мы уволили Тию, появился невидимый монстр.",
    ["我们拼了命地工作，却只能拿到少得可怜的薪水。那些可怜的苏勒，甚至无法让我们支付房租，买一点点食物！"] = "Мы работаем до смерти, но получаем лишь жалко маленькую зарплату. Этих бедных суле нам не хватает даже на то, чтобы заплатить за квартиру и купить немного еды!",
    ["我们无法生活！除非……除非铁十字街的那些蔬菜可以更便宜点……"] = "Мы не можем жить! Если только... если овощи на Айрон-Кросс-стрит не станут дешевле...",
    ["我们早就布置好了，专门捕猎学徒的！"] = "Мы уже это настроили; это специально для охотничьих учеников!",
    ["我们是在向盥洗室之主祈祷，祂很厉害的！经常腹泻的朋友都知道，祂能让肠胃恢复健康！"] = "Мы молимся Господу Туалета; Он очень мощный! Друзья, у которых часто бывает понос, знают, что Он может восстановить здоровье пищеварительного тракта!",
    ["我们本来可以直接抢，但却愿意付你一便士。"] = "Мы могли бы просто ограбить вас, но были готовы заплатить вам копейку.",
    ["我们来向神忏悔，祈求祂宽恕我们的罪孽。"] = "Мы приходим покаяться перед Богом и молиться, чтобы Он простил наши грехи.",
    ["我们没多少时间了，一定要赶在他们之前查清楚。"] = "У нас мало времени, нужно выяснить все раньше них.",
    ["我们现在还能到哪里去呢？"] = "Куда мы можем пойти сейчас?",
    ["我们留在这里……变成这样……只为了阻止尤德拉的荒芜……"] = "Мы останемся здесь... и станем такими... лишь для того, чтобы остановить запустение Йодры...",
    ["我们相信，死亡不是终结，而是另一种安宁的开始。"] = "Мы верим, что смерть — не конец, а начало иного покоя.",
    ["我们知道黑荆棘的各位平时很忙，直接上门可能太打扰了……而且我们准备的都不是什么贵重东西，怕反而显得失礼……"] = "Мы знаем, что сотрудники «Черного терновника» всегда заняты, и явиться лично было бы верхом бестактности... К тому же наши подарки совсем не дорогие, мы боялись показаться невежливыми...",
    ["我们结婚了吗？好像没有……你认识了阿斯兰……"] = "Мы женаты? Кажется, нет... Вы познакомились с Асланом...",
    ["我们绝不会说出老大最重要的猎龙计划的！"] = "Мы никогда не расскажем вам о самом важном плане босса по охоте на драконов!",
    ["我们老大说了，被猎龙帮征用，是马车的荣幸。"] = "Наш босс сказал, что быть реквизированным бандой охотников на драконов — это честь для кареты.",
    ["我们行走在生与死的边界，为失眠者带来安宁，为亡者吟唱诗歌，为秘密守口如瓶。"] = "Мы идём по границе между жизнью и смертью, принося покой бессонным, поём усопшим стихи и храним тайны.",
    ["我们要罢工！我们值得更好！值得更多！"] = "Мы должны нанести удар! Мы заслуживаем лучшего! Мы заслуживаем большего!",
    ["我们要罢工！没有良心的工厂主配不上我们这些勤劳的工人！"] = "Мы хотим нанести удар! Недобросовестные фабриканты недостойны нас, трудолюбивых работников!",
    ["我们这些人就算从早干到晚，周薪也不过是20苏勒。"] = "Такие, как мы, пашут с утра до ночи, а получают всего 20 соли в неделю.",
    ["我们这条街的人都认识她——米莉安太太。以前挺和善的一个老太太，这几年越来越糊涂了，看见戴帽子的就说人家帽子里藏了鸽子，非让人家放出来。"] = "Ее знают все на этой улице. Мириам. Раньше она была очень доброй старушкой, но в последние годы она становится все более и более растерянной. Всякий раз, когда она видит кого-то в шляпе, она говорит, что они прячут в ней голубей, и настаивает, чтобы их выпустили.",
    ["我们都不是龙的对手，刚才没被它杀掉已经很走运了。"] = "Мы не ровня дракону. Уже повезло, что нас это не убило только что.",
    ["我们需要……呃……新的酒吧，否则就没法工作！因为口渴……或者是别的什么……"] = "Нам нужен... э-э... новый бар, иначе мы не сможем работать! Из-за жажды... или чего-то еще...",
    ["我们需要新衣服……也许可以来点不一样的颜色，最好是能在阳光下闪闪发光的那些！"] = "Нам нужна новая одежда...может быть, разных цветов, желательно блестящая на солнце!",
    ["我会努力的，“正义”小姐！"] = "Я постараюсь, госпожа «Справедливость»!",
    ["我会处理好一切，你只需要说“愿意”。"] = "Я со всем справлюсь, вам нужно только сказать «Я сделаю».",
    ["我会帮你记录这个故事，你想让它叫什么名字呢？"] = "Я помогу вам записать эту историю, как бы вы ее назвали?",
    ["我会成为伟大的猎龙人·凯文，成就伟大的荣耀！"] = "Я стану великим охотником на драконов Кевином, добьющимся великой славы!",
    ["我会把每一枚金币都铸成复仇的子弹，让陷害我的恶棍付出代价！"] = "Я брошу каждую золотую монету в пулю мести и заставлю злодеев, которые меня подставили, заплатить цену!",
    ["我会把证据交给警察厅，把你这贪污渎职、冤枉好人的检察官扔进大牢，让你在那里度过你的下半辈子！"] = "Я передам улики в полицейское управление и упеку тебя, продажного прокурора-клятвопреступника, оклеветавшего невиновного, за решётку, где ты и проведёшь остаток своих дней!",
    ["我会把那些硬得像石头的煤灰敲下来。没有他，我担心自己找不到出路……"] = "Я сбиваю эту твёрдую, как камень, сажу. Без него я боюсь, что не найду выхода...",
    ["我会替你转达的。"] = "Я передам это вам.",
    ["我会给你编织一场美梦，一场模拟梦境，你需要尝试自己醒来，这样真的服用魔药时，你就有准备了。"] = "Я сплету для тебя прекрасный сон, имитацию сновидения. Тебе нужно попытаться проснуться самому, тогда, когда ты по-настоящему примешь зелье, ты будешь готов.",
    ["我会配合的，什么都交代，只要别抓我。"] = "Я буду сотрудничать, я вам все расскажу, только не арестовывайте меня.",
    ["我会隐匿行踪，慢慢筹划……待我归来之时，便是真相大白、罪恶覆灭之日！"] = "Я буду скрывать свои следы и медленно планировать... Когда я вернусь, это будет день, когда правда откроется и зло будет уничтожено!",
    ["我做的求婚计划没有用！我做的找戒指计划没有用！上学做的学习计划没有用，锻炼计划没有用……"] = "План предложения, который я составил, был бесполезен! План найти кольцо оказался бесполезным! Учебный план, который я составил для школы, был бесполезен, план упражнений был бесполезен...",
    ["我先喝！"] = "Я выпью первым!",
    ["我再试试去和他谈谈吧。如果他坚持不松口，你有什么打算？"] = "Я попробую еще раз поговорить с ним. А если он продолжит упрямиться, что ты планируешь делать?",
    ["我写了遗书，如果今晚您还不回应我，我就追随您到画中的世界！"] = "Я написал предсмертную записку. Если ты не ответишь мне сегодня вечером, я последую за тобой в мир живописи!",
    ["我写封信给队长，请他多留意你的安全。"] = "Я напишу письмо капитану и попрошу его позаботиться о вашей безопасности.",
    ["我准备好了，“星星”先生！"] = "Я готов, господин «Звезда»!",
    ["我准备好了，章鱼焯水过程中要浸泡五次冰水……从前我就是这么做这道菜的。"] = "Я готов. В процессе бланширования осьминога нужно пять раз замочить в ледяной воде. Я так раньше готовила это блюдо.",
    ["我出5000金镑。"] = "Я даю 5000 золотых фунтов.",
    ["我出600金镑！"] = "Даю 600 золотых фунтов!",
    ["我出650金镑！"] = "Я даю 650 золотых фунтов!",
    ["我刚刚听到“0”级封印物出逃……廷根会有危险吗？"] = "Я только что узнал, что запечатанный артефакт Последовательности 0 сбежал... Будет ли Тинген в опасности?",
    ["我刚刚在树上对地面使用了我们学徒的“开门”，结果卡住了。现在还有一个不知名的东西在戳我的屁股……"] = "Я только что сидел на дереве и применил наше Ученическое «Отпирание дверей» к земле, и в итоге застрял. А теперь еще какая-то непонятная штука тычет меня прямо в задницу...",
    ["我刚刚透过门缝已经看到了全部的做菜过程，你们配合得不错。"] = "Я только что видел весь процесс приготовления через щель в двери, вы двое хорошо сотрудничали.",
    ["我努力过了，但还是出不去，唉。总卡在墙上，我都怀疑我不是做“学徒”的料……"] = "Я очень старался, но все равно не могу выбраться, увы. Я вечно прижимаюсь к стенке и даже сомневаюсь, что мне не суждено быть «учеником»…",
    ["我去找老板请辞。"] = "Я пойду попрошу начальника уйти в отставку.",
    ["我去看看马西莫的反应。"] = "Пойду взгляну на реакцию Массимо.",
    ["我又怎么会沦落到做政府雇员，在下水道搜查？这不符合罗塞尔大帝的美学！"] = "Как я мог превратиться в государственного служащего, обыскивающего канализацию? Это не соответствует эстетике императора Рассела!",
    ["我反对！"] = "Я возражаю!",
    ["我发誓，我从未做过这些事情。"] = "Клянусь, я никогда не делал подобных вещей.",
    ["我只想留在廷根，保护好这里。"] = "Я просто хочу остаться в Тингене и защитить это место.",
    ["我只是一面镜子，陛下。人是不能要求镜子分辨美丑的，除非你会和小动物说话，并且有红润的嘴唇、媲美白雪的肌肤，还有7个矮仆从……"] = "Я всего лишь зеркало, Ваше Величество. Люди не могут попросить зеркало отличить красоту от уродства, если только вы не умеете разговаривать с маленькими животными, не имеете красных губ, кожи, сравнимой с белым снегом, и семи слуг-гномов...",
    ["我只是帮你排队，不用这么麻烦。"] = "Я просто помог вам встать в очередь, не нужно таких проблем.",
    ["我只是想和大帝一样做个英雄，如果我不想做这个英雄，就不会接下这份工作，如果我不接下这份工作……"] = "Я просто хотел быть героем, как Император. Если бы я не хотел быть этим героем, я бы не согласился на эту работу. Если бы я не согласился на эту работу...",
    ["我只是想知道真相。"] = "Я просто хотел знать правду.",
    ["我只是想送快递而已，我只是想帮助别人……"] = "Я просто хотел развозить посылки, просто хотел помогать людям...",
    ["我只是路过，没打算吃东西。"] = "Я просто прохожу мимо, есть не собираюсь.",
    ["我只能涉血前进，向着地狱，去听那些魔鬼的话，从不相信所谓的“良心”。"] = "Я могу только идти сквозь кровь в ад, слушая слова демонов, никогда не веря в так называемую «совесть».",
    ["我只能认为这个人是被诅咒，或者被控制了，总之这不合常理。"] = "Я могу только думать, что этот человек проклят или находится под контролем. Короче говоря, это неразумно.",
    ["我叫{{PlayerName}} 。你还有东西要买吗？我可以帮你提购物袋。"] = "Меня зовут {{PlayerName}}. Вам нужно купить что-нибудь еще? Я могу помочь донести пакеты.",
    ["我叫{{PlayerName}}。"] = "Меня зовут {{PlayerName}}.",
    ["我叫乌莎，是大地教会的修士，因为一些原因被分配来这里负责后勤。"] = "Меня зовут Уша, я монах Церкви Вечной Ночи, назначенный сюда по определенным причинам ответственным за логистику.",
    ["我叫米勒，是个证券经纪人。三天前，我撞见了一场黑帮交易，被人追杀。我花了二十个金镑让殡仪馆老板帮我脱身。"] = "Меня зовут Миллер, я биржевой брокер. Три дня назад я наткнулся на сделку банды, и теперь меня преследуют. Я заплатил владельцу похоронного бюро двадцать золотых фунтов, чтобы он помог мне скрыться.",
    ["我可以帮你买戒指和花束，替你回绝笔友。"] = "Я могу помочь тебе купить кольцо и букет и отказаться от твоего друга по переписке.",
    ["我可以有幸知道你的名字吗？"] = "Могу ли я иметь честь знать ваше имя?",
    ["我可以试试看操控老鼠，从餐厅侧门潜入，在里面制造点混乱。等你们听到骚乱声，就可以开展行动。"] = "Я могу попытаться управлять мышами, проникнуть через боковую дверь ресторана и создать внутри хаос. Как только вы услышите шум, вы можете принять меры.",
    ["我可没疯！全是血！血流从黑雾中流得满地都是！"] = "Я не сумасшедший! Это все кровь! Кровь текла по земле из черного тумана!",
    ["我听到声音，以为是闹鬼了，根本不敢靠近……"] = "Я услышал звук и решил, что это призрак, поэтому вообще не решался подойти...",
    ["我听到斯嘉丽说她根本不喜欢山姆，她只是想让梅兰妮甩掉那个讨厌的男人……"] = "Я слышала, как Скарлетт сказала, что Сэм ей совсем не нравится, она просто хотела, чтобы Мелани бросила этого надоедливого мужчину...",
    ["我听泰瑞说，你又欺负他了？他的钱包……"] = "Я слышал от Терри, что ты снова издевался над ним? Его кошелек...",
    ["我听说过，有些人被带走了，就再也没有回来。"] = "Я слышал, что некоторые люди, которых увезли, так и не вернулись.",
    ["我和卡兰最近沉迷一种神圣的毒药……这种液体味道甜蜜，口感就像三千朵烟花在嘴里炸开，让人忍不住喝了又喝，喝了又喝，喝了又喝……"] = "Мы с Каланом недавно пристрастились к священному яду... эта жидкость на вкус сладкая, а текстура подобна трем тысячам фейерверков, взрывающихся во рту, и невозможно перестать пить ее, и пить, и пить...",
    ["我和我哥哥杰姆为雷克斯先生工作，就是清洗烟囱。"] = "Мой брат Джем и я работаем на мистера Рекса, чистим дымоходы.",
    ["我哪会这个！饮料都是由东区那家罗森的民俗草药店供货。喏，店长正好来送货了，就是这位谢尔敏先生，伟大的药剂师！"] = "Откуда мне знать, как это сделать! Все напитки поставляются из лавки народных трав Лоусона в Восточном округе. Смотри, лавочник только что пришел доставить товар; это господин Шермин, великий фармацевт!",
    ["我喜欢诚实面对自己欲望的人。"] = "Мне нравятся люди, которые честны в своих желаниях.",
    ["我回来了……"] = "Я вернулся...",
    ["我在。"] = "Я здесь.",
    ["我在下水道击败了垃圾之主，见证了爱国卫生运动，取得了珍贵的黄金马桶！"] = "Я победил Повелителя мусора в канализации, стал свидетелем Патриотической кампании за здоровье и получил драгоценный золотой унитаз!",
    ["我在恶龙酒馆的通道入口等你，我会给你报酬，以及免费演出。相信我，你一定会想听。"] = "Я буду ждать тебя у входа в проход таверны «Злой Дракон». Я дам тебе награду и устрою бесплатное выступление. Поверь мне, ты обязательно захочешь это услышать.",
    ["我在找光！"] = "Я ищу свет!",
    ["我堵错门了吗……他、他怎么了？"] = "Я ошибся дверью... Что, что с ним случилось?",
    ["我多想买下最昂贵的戒指，最鲜艳的花朵赴约……可这太不负责任了，我必须让她忘了我！"] = "Мне так хочется купить к свиданию самое дорогое кольцо и самые яркие цветы... но это было бы слишком безответственно. Я должен заставить ее забыть меня!",
    ["我太着急，把铲子掉在里面了，剩下的煤灰也没来得及铲出来……对不起……"] = "Я так спешил, что уронил лопату внутрь, и не успел вычистить остатки сажи... Простите...",
    ["我女儿。她嫁到南方去了，我说要写信告诉她一件事。信写好了，没寄出去她就没了。"] = "Моя дочь. Она вышла замуж и переехала на юг. Я сказал, что напишу ей кое-что. Письмо было написано, но она скончалась прежде, чем я успел его отправить.",
    ["我好像……也没那么怕把自己写的诗拿给别人看了。下次，我想把我新写的那首诗也一起送给伦纳德先生！"] = "Кажется, я... больше не боюсь показывать другим стихи, которые написала. В следующий раз я хочу подарить только что написанное стихотворение мистеру Леонарду!",
    ["我好像……忘记了。"] = "Кажется, я... забыл.",
    ["我好像做了个很长的梦…… "] = "Такое ощущение, что мне приснился очень длинный сон...",
    ["我学到了很多……关于罗塞尔大帝的“知识”。"] = "Я многое узнал... о «знаниях» императора Розеллы.",
    ["我对这个故事感到十分的困惑，可是她讲完后再也没有出现……我去过贝克兰德，她们说在埃德萨克的宴会曾见过类似的人，但王子早已经死了。"] = "Меня очень смущает эта история, но она так и не появилась после того, как закончила ее рассказывать... Я был в Баклунде, и там сказали, что видели кого-то похожего на банкете Эдера, но принц уже давно умер.",
    ["我将为你赐予祝福、驱除邪灵、降下奇迹，相应的，你要付出一定的报偿。"] = "Я буду даровать вам благословения, отгонять злых духов и совершать чудеса, и соответственно вам придется выплатить определенную сумму компенсации.",
    ["我就是想让他知道……不是什么锁都应该被打开的。"] = "Я просто хочу дать ему понять... далеко не каждый замок следует открывать.",
    ["我就说！怎么样？你是猪你是猪你是鲁恩小花猪——"] = "Я говорил тебе! Как насчет этого? Ты свинья, ты свинья, ты маленький ленский поросенок...",
    ["我已经和总部沟通过了，美人鱼需要休养，会在廷根多停留几天。"] = "Я уже связался со штаб-квартирой: русалке нужно восстановиться, и она задержится в Тингене ещё на несколько дней.",
    ["我已经回答了你的问题，接下来轮到我提问了。"] = "Я уже ответил на твой вопрос. Теперь моя очередь спрашивать.",
    ["我已经很用力了！"] = "Я уже стараюсь изо всех сил!",
    ["我已经得到女神的启示，祂将赐福于你，许可你使用祂存于历史中的力量。"] = "Богиня дала мне откровение: Она благословит тебя и позволит использовать Её силу, хранящуюся в истории.",
    ["我希望您能帮我发掘这座城市里更多的幽默，我会给您相应的报酬。"] = "Я надеюсь, вы поможете мне отыскать больше поводов для смеха в этом городе, и я щедро вознагражу вас.",
    ["我店里所有加急订单，她总能提前送达！"] = "Все срочные заказы из моей лавки она неизменно доставляет раньше срока!",
    ["我弟弟被弗莱队长从失控的马车前救下。为了表达感谢，他用攒下的木料做了个木雕，他说队长就像故事里的英雄。"] = "Моего брата спас капитан Фрай из вышедшего из-под контроля экипажа. Чтобы выразить свою благодарность, он вырезал из сэкономленной древесины резьбу, сказав, что капитан подобен герою из сказки.",
    ["我很荣幸。看来女神也支持我们的选择，为我们送来了帮手。"] = "Для меня большая честь. Кажется, Богиня тоже поддержала наш выбор и послала нам помощницу.",
    ["我得到了一件礼物，一份来自家族的遗产，现在需要全力研究。"] = "Я получил дар, наследство от своей семьи, и теперь мне нужно изо всех сил его изучать.",
    ["我得把这两个孩子带走。"] = "Я беру с собой этих двоих детей.",
    ["我循着灰雾的气息而来，遵循伟大主人的嘱托来帮你。"] = "Я пришел по запаху серого тумана, следуя указанию великого мастера помочь вам.",
    ["我必须实现这些约定，但我不记得把东西放哪了，或许……那些东西已经随着我的记忆一起遗失了。 "] = "Я должен выполнить эти договоренности, но не помню, куда положил вещи. Возможно... эти вещи затерялись вместе с моей памятью.",
    ["我必须找到它们，那是我唯一的记忆。"] = "Я должен их найти; они мои единственные воспоминания.",
    ["我必须要坚持下去，绝不会放弃——"] = "Я должен упорствовать, я никогда не сдамся…",
    ["我怀疑他身上有什么重要证据，治安队和警局在联合灭口！"] = "Я подозреваю, что у него есть на него какие-то важные улики. Силы безопасности и полиция работают вместе, чтобы заставить его замолчать!",
    ["我怎么在这里休息？！我应该忙碌起来，为了家人，为了明天！"] = "Почему я здесь отдыхаю?! Завтра я должен быть занят ради своей семьи!",
    ["我怎么知道！"] = "Откуда мне знать!",
    ["我患有间歇性失忆症，每天醒来都会忘记昨天的事。 "] = "Страдаю периодической амнезией, каждый день просыпаясь, забываю, что произошло вчера.",
    ["我想他不会介意这点，毕竟这个错误同您一样美丽。"] = "Я не думаю, что он будет возражать против того, что, в конце концов, эта ошибка так же прекрасна, как и ты.",
    ["我想到个东西，正好能帮上你。"] = "Я придумал одну вещь, которая как раз может тебе помочь.",
    ["我想向您请教一下，刚刚那段对话在人类的语言范畴内，是否能算有趣？"] = "Я хотел бы вас спросить, в рамках человеческого языка, можно ли считать интересным тот разговор, который только что произошел?",
    ["我想它是在回复我的疑问，我那时很困惑……"] = "Я думаю, это был ответ на мой вопрос. Я тогда очень растерялся...",
    ["我想守住廷根，大家生活的街道，在这里经历的每一天。"] = "Я хочу защитить Тинген: улицы, на которых все живут, и каждый день, прожитый здесь.",
    ["我想确认一件事。不过放心，如果我有恶意，刚刚就不会救你们。"] = "Я хочу кое-что прояснить. Но не волнуйтесь: замышляй я недоброе, я бы не стала вас спасать.",
    ["我想统治世界。"] = "Я хочу править миром.",
    ["我想让他做回那个有点粗鲁，又笑得很温和的男人。"] = "Я хочу, чтобы он снова стал тем человеком, который был немного грубым, но с нежной улыбкой.",
    ["我想起来了，你是上次那个……动手的……"] = "Теперь я помню, ты тот, что в прошлый раз... тот, кто сражался...",
    ["我想这个八音盒应该符合您的描述。"] = "Я думаю, что эта музыкальная шкатулка должна соответствовать вашему описанию.",
    ["我愿意……我愿意！"] = "Я... я буду!",
    ["我愿意为您吞下一千根银针，只乞求您的垂怜。"] = "Я готов проглотить ради вас тысячу серебряных игл, лишь бы заслужить вашу милость.",
    ["我愿意！"] = "Я готов!",
    ["我才是您最忠诚的奴仆！我已经三天三夜没有合眼，只为多看您一眼！"] = "Я твой самый верный слуга! Я не смыкал глаз три дня и три ночи, лишь бы еще раз взглянуть на тебя!",
    ["我把米勒送上马车了，在他到港口之前应该没什么阻碍了。"] = "Я посадил Миллера в карету. До порта ему, наверное, уже ничто не помешает.",
    ["我拉你上来！"] = "Я подниму тебя!",
    ["我拒绝，像你这种自以为是的家伙，我才没兴趣呢。"] = "Я отказываюсь. Меня не интересует такой самодовольный человек, как ты.",
    ["我摸过了石墙的粗糙、雨的冰凉、花瓣的柔软……但是光是什么样的呢，我怎么也摸不到。"] = "Я прикасался к шероховатости каменных стен, к холоду дождя, к мягкости лепестков... но что такое свет? Я не могу прикоснуться к нему, несмотря ни на что.",
    ["我收到了一封详实而可靠的<P_Yellow>举报信</>，控诉你在南大陆秘密加入了邪神教派，还参与了邪恶的献祭仪式，组织了针对平民的恐怖袭击！"] = "Я получил подробное и достоверное письмо с разоблачением <P_Yellow>, </>, в котором вас обвиняют в тайном присоединении к культу злого бога на Южном континенте, участии в злом ритуале жертвоприношения и организации террористических атак против мирных жителей!",
    ["我收购活的老鼠，一只10苏勒。"] = "Скупаю живых крыс, по 10 сулов за штуку.",
    ["我早就注意到这位“学徒”了，也和弗莱队长商量了。"] = "Я уже заметил этого «Ученика» и обсуждал его с капитаном Фраем.",
    ["我早已双手染血，两足深陷于血泊中。"] = "Мои руки давно обагрены кровью, а ноги увязли в пучине резни.",
    ["我明白。但末日将近，我必须足够强大，才能走向我的命运。"] = "Я понимаю. Но апокалипсис близок; Я должен быть достаточно сильным, чтобы идти навстречу своей судьбе.",
    ["我明白了。让我在外面帮你吧，我可以为你指路，你也可以指挥我帮忙。"] = "Я понимаю. Позвольте мне помочь вам со стороны; Я могу направлять вас, а вы можете приказать мне помочь.",
    ["我明白了！我明白了！"] = "Я понимаю! Я понимаю!",
    ["我明白了，你们是想让我帮忙转交这些礼物，对吗？ 他们最近任务确实排得很满……不过我大概知道谁现在有空。"] = "Я поняла: вы хотите, чтобы я помогла передать эти подарки, верно? У них в последнее время и правда все дни забиты заданиями... но я, кажется, знаю, кто сейчас свободен.",
    ["我明白我想守护什么了，“星星”先生。"] = "Я понял, что хочу защищать, господин «Звезда».",
    ["我昨天晚上心情不好，一不小心就喝多了，所以才头晕眼花的，走错了门。"] = "Вчера вечером у меня было плохое настроение, и я случайно выпил слишком много, поэтому у меня закружилась голова, и я пошел не к той двери.",
    ["我是“愚者”先生最忠实的仆从魔镜阿罗德斯，你所见到的只是一个分身，我的本体还陪伴在主人的身边。"] = "Я самый преданный слуга господина Шута, волшебное зеркало Арродес. То, что вы видите перед собой, лишь моё воплощение, моё же подлинное тело по-прежнему находится рядом с господином.",
    ["我是一个心理医生。希望你能睡个好觉。"] = "Я психолог. Надеюсь, ты сможешь хорошо выспаться.",
    ["我是个美食家，其他事和我无关。这道菜告诉我，库克值得再拥有一次机会。"] = "Я гурман, другие вещи меня не касаются. Это блюдо говорит мне, что Кук заслуживает еще одного шанса.",
    ["我是想来问问你，为什么芥末章鱼的肉没了以前的嚼劲？"] = "Я просто хочу вас спросить, почему мясо осьминога васаби не такое жевательное, как раньше?",
    ["我是无辜的……放我出去……"] = "Я невиновен... выпустите меня...",
    ["我是无辜的！放我出去！"] = "Я невиновен! Выпустите меня!",
    ["我是春夜舞会的接引人，莉丝·埃文斯。"] = "Я гид весеннего бала, Лиз Эванс.",
    ["我是来帮梅丽莎取东西的，伦纳德替她找到了毕业论文需要的钟表图纸。"] = "Я здесь, чтобы забрать кое-что для Мелиссы. Леонард нашел чертежи часов, которые ей понадобились для дипломной работы.",
    ["我是郡警察厅的心理学专家，见习督查。"] = "Я эксперт по психологии из окружного управления полиции, инспектор по вопросам испытательного срока.",
    ["我最喜欢躲猫猫了！追上我，才有资格打探我的秘密。"] = "Я больше всего на свете люблю прятки! Сначала догони меня — только тогда получишь право выведать мои тайны.",
    ["我最近琢磨出一种新的鱼干配方，用了点特别的香草和烟熏手法。我是满意得不得了，但光我一个人说好可不行。 "] = "Недавно я придумал новый рецепт сушеной рыбы с использованием специальных трав и техники копчения. Я им очень доволен, но мне недостаточно просто сказать, что это хорошо.",
    ["我有一个朋友托我来这看看。"] = "Мой друг доверил мне приехать сюда и проверить это.",
    ["我有我有。我记得第一句，“龙啸将至”……"] = "У меня есть один, у меня есть один. Я помню первое предложение: «Рев Дракона приближается»…",
    ["我有种预感，有了你的帮助，这瓶一定是完美的“焦糖炸弹”！"] = "Я предчувствую, что с вашей помощью эта бутылочка точно станет идеальной «Карамельной бомбой»!",
    ["我有线索了。"] = "У меня есть подсказка.",
    ["我本以为，不管多隐秘的地方，只要能“开门”，都能任我来去。"] = "Я думал, что каким бы секретным ни было место, пока я могу «открыть дверь», я могу приходить и уходить, когда захочу.",
    ["我来廷根办点事情，顺便看看，弗莱有没有压榨新员工。"] = "Я приехал в Тинген по делам и заодно посмотреть, не гнобит ли Фрай новых сотрудников.",
    ["我来给你来点感觉！"] = "Я дам тебе почувствовать это!",
    ["我来自安魂诗社，这是信仰黑夜女神的虔诚信徒们组成的团体。"] = "Я из Общества поэзии-реквиема; это группа, образованная ярыми верующими в Богиню Вечной Ночи.",
    ["我根本尝不出味道……完蛋了！"] = "Я вообще ничего не чувствую... Все кончено!",
    ["我根本没碰到他！他自己倒的！"] = "Я до него даже не дотронулся! Он сам упал!",
    ["我每天都在这等，想用最漂亮的样子迎接他，但我今天把帽子忘在家里了。"] = "Я жду здесь каждый день, желая встретить его во всей красе, но сегодня я забыла шляпку дома.",
    ["我没事。"] = "Я в порядке.",
    ["我没有恶意。但我需要确定，你会不会对市民造成伤害？"] = "У меня нет дурных намерений. Но мне нужно убедиться, не причините ли вы вреда горожанам.",
    ["我没有过去，更不了解你曾经的传说。"] = "У меня нет прошлого, и я ничего не знаю о ваших прежних легендах.",
    ["我没有骗您，这路上的一切，都和您说的不一样。"] = "Я не обманываю вас: на этом пути всё совсем не так, как вы описывали.",
    ["我没看错吧，章鱼在做菜？"] = "Я вижу вещи, готовится ли осьминог?",
    ["我没钱。"] = "У меня нет денег.",
    ["我父亲去世的前两年，我哪怕只是经过黑荆棘的路口，都会觉得胸口闷。梅丽莎比我坚强……"] = "Первые два года после смерти моего отца даже при одном прохождении перекрестка Чёрный Чертополох у меня сжимало сердце. Мелисса сильнее меня...",
    ["我父亲生前是这附近的街头艺人，最拿手的就是帽子魔术。 他每年纪念日都要为母亲从帽子里变一次鸽子。"] = "При жизни мой отец был здесь уличным фокусником, и лучше всего ему давались трюки со шляпой. На каждую годовщину он доставал из шляпы голубя для мамы.",
    ["我猜中了！女神啊，一位高贵又深情的王子，爱上了一位圆脸的少女，还为她写这么好听的情歌……这真是一个美好的故事，他们一定会很幸福。"] = "Я догадался! Богиня, благородный и ласковый принц влюбился в круглолицую девушку и написал для нее такую ​​милую песню о любви... Это действительно красивая история, они обязательно будут очень счастливы.",
    ["我猜是学术诚信办公室派你来的，走吧，我跟你回去自首。 <P_Yellow>（不同选择将会影响剧情走向）</>"] = "Полагаю, вас послало Управление академической честности. Пойдем, я вернусь с тобой сдаваться. <P_Yellow> (Различные варианты повлияют на направление печати) </>",
    ["我现在也勉强才能挤进去。我和杰姆一样，有时候希望自己快点长大，做得更好，又害怕长大……"] = "Я сейчас едва могу втиснуться. Как и Джем, иногда я надеюсь, что смогу быстро вырасти и добиться большего, но я также боюсь повзрослеть...",
    ["我现在就去找！"] = "Я сейчас найду его!",
    ["我的上一出戏在王国大剧院公演时，就连国王陛下和诸位大臣都对我的台词赞不绝口，怎么会有人不喜欢呢？"] = "Когда премьера моей последней пьесы состоялась в Королевском театре, даже Его Величество король и министры хвалили мои строки. Как они могли кому-то не понравиться?",
    ["我的下半身还卡在墙里，必须先找到它。你能帮我找找吗？它应该就在这附近。"] = "Моя нижняя часть тела все еще застряла в стене, мне нужно сначала ее найти. Можете ли вы помочь мне найти его? Это должно быть где-то здесь.",
    ["我的主人是优雅的绅士，绝不会将垃圾丢入马桶，您的猜测令人感到冒犯！"] = "Мой хозяин — элегантный джентльмен и никогда не выбрасывает мусор в унитаз. Ваши предположения оскорбительны!",
    ["我的女神……杰斯醒醒！快来救人啊！！！"] = "Моя Богиня... Джесс, просыпайся! Приходите и спасите кого-нибудь!!!",
    ["我的女神！我唯一的爱！我愿意把我的全部财产都献给您！"] = "Моя Богиня! Моя единственная любовь! Я готов предложить тебе все свое богатство!",
    ["我的女神，我都要开始怀疑他转不眠者途径了……熬夜可不是什么好习惯，发际线会上移、皮肤松弛，还会健……"] = "О Богиня, я уже начинаю подозревать, что он перешел на путь Бессонного... Засиживаться допоздна — скверная привычка: линия волос отступает, кожа обвисает, а еще начнется забыв...",
    ["我的心？您真的不明白吗？陛下……"] = "Мое сердце? Ты правда не понимаешь? Ваше Величество...",
    ["我的日记，我的抽屉，他都要打开。他说这是他的技艺，他骄傲得很呢。"] = "Мой дневник, мои ящики, он должен открыть их все. Он говорит, что это его ремесло, и он очень гордится этим.",
    ["我的老师告诉我，要想弹奏好《夜访》，我必须相信爱情与牺牲，相信痛苦与谎言。"] = "Мой учитель сказал мне, что для того, чтобы хорошо сыграть «Ночной визит», я должен верить в любовь и жертвенность, верить в боль и ложь.",
    ["我的裤子真破了！我要赶快回去，越快越好！再见！"] = "Мои штаны действительно порваны! Мне нужно вернуться быстро, как можно быстрее! До свидания!",
    ["我的身体就在附近……嗯？从刚才开始，我的衣服一直凉凉的，像是泡在冷水里？"] = "Моё тело рядом... хм? С тех пор моя одежда стала холодной, как будто она пропитана холодной водой?",
    ["我的钱啊——天底下有这样的老师吗！"] = "Мои деньги — есть ли в мире такой учитель!",
    ["我看到了很多人，应该出现的人、无法出现的人……"] = "Я видел много людей: тех, кто должен был появиться, и тех, кто не мог...",
    ["我看见一个工人，他从头到脚被吞了！被黑雾！"] = "Я видел рабочего, он был проглочен с ног до головы! Черным туманом!",
    ["我知道。但我忘不掉。"] = "Я знаю. Но я не могу забыть.",
    ["我知道。你比我预想的，成长得更快。"] = "Я знаю. Ты вырос быстрее, чем я ожидал.",
    ["我知道不对劲，但我只是……呕！不要让我回想那个画面！呕！"] = "Я знаю, что что-то не так, но я просто... Ух! Не заставляйте меня вспоминать эту сцену! Фу!",
    ["我知道了！你就是伦纳德先生在信中提到的那位——“很有天赋的新同事”。"] = "Я знаю! Должно быть, вы тот самый, о котором мистер Леонард упомянул в своем письме, — «очень талантливый новый коллега».",
    ["我知道的，我也信仰“愚者”先生，是他的信徒。"] = "Я знаю, я тоже верю в господина Шута, я его верующий.",
    ["我知道，五年前“0-08”也只有简单的描述。"] = "Я знаю, пять лет назад у «0-08» тоже было лишь краткое описание.",
    ["我知道，我知道，他就爱说傻话……"] = "Знаю, знаю, он просто любил говорить глупости...",
    ["我祈求您——"] = "Я молюсь тебе —",
    ["我祈求您庇佑一位忠实的信徒"] = "Я молюсь о вашей защите для преданного верующего",
    ["我祈求您的帮助"] = "Я молюсь о твоей помощи",
    ["我祈求您的注视"] = "Я молюсь за твой взгляд",
    ["我祈求您的眷顾"] = "Я молю о Твоем благоволении",
    ["我祈求您的眷顾，祈求您眷顾一位您忠实的信徒！"] = "Молю о вашей милости, молю, окажите милость вашему верному последователю!",
    ["我祈祷的时候被人听见了，那个男人教了我一种仪式。"] = "Меня услышали, когда я молился, и этот человек научил меня ритуалу.",
    ["我竟然在跟一面镜子交流……"] = "Я на самом деле общаюсь с зеркалом...",
    ["我经常假装抄小路啊，我的演技这么差吗？"] = "Я часто притворяюсь, что ищу короткие пути, неужели моя игра настолько плоха?",
    ["我给了您极致的欢愉，您却要杀我？"] = "Я даровала вам наивысшее наслаждение, а вы хотите меня убить?",
    ["我给他刻的墓志铭——“戴维，追风雪的人。”"] = "Эпитафию, которую я вырезал для него: «Давид, гонящийся за ветром и снегом».",
    ["我能做的，是留住眼前的美好，阻止可能的悲剧。"] = "Что я могу, так это сохранить красоту перед глазами и предотвратить возможные трагедии.",
    ["我能加入猎龙帮吗？我也想猎龙！凯文老大在哪里，我想找他签个名！"] = "Могу ли я присоединиться к банде охотников на драконов? Я тоже хочу охотиться на драконов! Где босс Кевин? Я хочу получить его автограф!",
    ["我能听见你。"] = "Я слышу тебя.",
    ["我能走到这一步，多亏了一个人，那就是——"] = "Я могу дойти до этого благодаря одному человеку, и это——",
    ["我被委托收集一些有趣的人类对话，为某位作家提供写作灵感。"] = "Мне поручили собрать несколько занятных человеческих бесед, чтобы подарить вдохновение одной писательнице.",
    ["我要上山，找我的妻子戴维。每月我都来，几十年了。"] = "Я собираюсь подняться на гору, чтобы найти свою жену Дэвида. Я приезжаю каждый месяц, вот уже несколько десятилетий.",
    ["我要变帅。不，等一下，我要无任何副作用无代价家庭和睦身体健康版变帅。"] = "Я хочу стать красивым. Нет, подожди, я хочу версию, в которой я стану красивым без побочных эффектов, бесплатно, с гармоничной семьей и хорошим здоровьем.",
    ["我要回去监督她写作了。"] = "Мне пора возвращаться и следить за тем, как она пишет.",
    ["我要带他们回警局了。你因受骗购买的商品，我们会联系店主，协商退货退款，到时候再通知你来取回自己的钱。"] = "Я отвезу их обратно в полицейский участок. Мы свяжемся с владельцем магазина по поводу товаров, которые вы купили после обмана, чтобы договориться о возврате и возмещении средств. Мы уведомим вас, чтобы вы пришли и получили свои деньги обратно.",
    ["我要是梅兰妮，我和山姆相亲相爱还来不及呢。"] = "Будь я на месте Мелани, мы с Сэмом души бы друг в друге не чаяли.",
    ["我觉得我还是不知道比较好……"] = "Пожалуй, мне лучше этого не знать...",
    ["我认为，这是他看到了星空中的秘密。“唯恐惊扰”说明他看到了不该看的东西……"] = "Я думаю, это он видит тайны звездного неба. «Из боязни потревожить» показывает, что он увидел то, чего не должен был видеть...",
    ["我认为，这表达的是一种“敬畏”。 "] = "Я считаю, что это выражает своего рода «трепет».",
    ["我记住你了，你给我等着！"] = "Я запомню тебя, ты только подожди!",
    ["我记得你今天休假吧，怎么有空来公司？你可不要像弗莱那样，从不下班，永不休假，几乎把公司当成家了！"] = "Я помню, ты сегодня в отпуске, почему ты успеваешь прийти в компанию? Не уподобляйтесь Фраю, который никогда не уходит с работы, никогда не делает перерыва и относится к компании почти как к своему дому!",
    ["我记得她第一次吃过你做的菜后，非常亢奋，满餐厅大喊，自己以后一定要成为一个美食家。"] = "Помню, после того, как она впервые попробовала вашу стряпню, она была очень взволнована, кричала на весь ресторан, что в будущем обязательно станет гурманом.",
    ["我记得这家伙，“黑手套”的打手，属于三大黑帮里最暴力的那群人，不过他之前可没有这么疯。"] = "Я помню этого парня. Он бандит «Черных перчаток», одной из самых жестоких группировок среди трех крупнейших банд. Но раньше он не был таким сумасшедшим.",
    ["我记得这束花……塞维亚菊，象征着快乐。"] = "Я помню этот букет... Хризантемы Севии, символизирующие счастье.",
    ["我记得这附近有公共盥洗室，赶紧找找！"] = "Я помню, что рядом есть общественный туалет, надо его найти побыстрее!",
    ["我记得，你和阿斯兰……阿斯兰，那个男人……"] = "Я помню, ты и Аслан... Аслан, этот мужчина...",
    ["我记得，几十年了，这个地方，你的坟墓，就在这里。"] = "Я помню, что на протяжении десятилетий это место, твоя могила, была прямо здесь.",
    ["我讲完啦！"] = "Я закончил рассказывать это!",
    ["我该做些什么？"] = "Что я должен делать?",
    ["我该怎么做？"] = "Что я должен делать?",
    ["我该检查其他地方了……不，我不想……我该检查其他地方了……不，我必须多看几眼……"] = "Мне следует проверить другие места... Нет, я не хочу... Мне следует проверить другие места... Нет, мне нужно еще несколько раз посмотреть...",
    ["我该走了，帮我把这张纸条转交给{{PlayerName}} 。进入历史迷雾消耗了太多灵性，今晚让{{他|她}}在黑荆棘好好休息。"] = "Мне пора идти. Помогите мне передать эту записку {{PlayerName}}. Вход в туман истории отнял слишком много духовности; пусть {{him|her}} хорошо отдохнет сегодня вечером в Блэкторне.",
    ["我跑到门口的时候差点被你的高音震回去。"] = "Я добежал до дверей, и от твоей высокой ноты меня чуть обратно не отшвырнуло.",
    ["我还不想死，呜呜——"] = "Я ещё не хочу умирать, у-у-у...",
    ["我还不知道你的名字。"] = "Я до сих пор не знаю твоего имени.",
    ["我还想体验一次……那种感觉。"] = "Я все еще хочу испытать это еще раз... это чувство.",
    ["我还想在这里走走，我们稍后见，务必小心！"] = "Я хочу еще немного здесь осмотреться. Увидимся позже, и будьте предельно осторожны!",
    ["我还是再看看吧。"] = "Я лучше посмотрю еще раз.",
    ["我还有事要向他问清楚。况且要是把他放在一边，说不定睁眼时又要尖叫，到时候……"] = "Мне ещё нужно у него кое-что выяснить. К тому же, если оставить его в стороне, он может снова закричать, когда проснётся, и тогда…",
    ["我还没有……赞……"] = "Я не... Пра...",
    ["我还看见有一对男女从这边走过去，那个男人的打扮真让我想起曾经轰动了整个廷根市的连环杀手案！"] = "Я также видел, как здесь проходили мужчина и женщина. Одежда этого человека действительно напоминает мне дело о серийном убийце, которое когда-то потрясло весь Тинген-Сити!",
    ["我还给你留了个大的，在被围殴的时候会自动解锁，好好期待下吧。"] = "А еще я припас для тебя кое-что грандиозное: оно откроется само, когда тебя возьмут в кольцо. Так что жди с нетерпением!",
    ["我这次回廷根，是为我的毕业论文寻找一种因蒂斯钟表的图纸。"] = "На этот раз я вернулся в Тинген, чтобы найти чертежи часов Интис для своей дипломной работы.",
    ["我连婚礼计划和孩子的教育计划都准备好了，风暴在上，还有很多计划没做，双方父母的养老计划，度假计划，攒钱计划……"] = "Я даже подготовила план свадьбы и план обучения детей. Бури наверху, у меня еще так много планов, которые я не построил — пенсионный план для обоих наших родителей, план отпуска, план сбережений…",
    ["我都想起来了……我已经不需要消化魔药了，我……已经死了。"] = "Теперь я все помню... Мне больше не нужно переваривать зелье, я... уже мертв.",
    ["我都献给您，只求您高抬贵手。我保证马上滚回老家，再也不会出现在您面前……"] = "Я предлагаю все это тебе, я только прошу тебя проявить милосердие. Обещаю немедленно приползти обратно в родной город и никогда больше не появляться перед тобой...",
    ["我钦佩你对历史学的热诚。"] = "Я восхищаюсь вашей страстью к истории.",
    ["我问他为什么，他说……雪花会融化，但雕塑不会老。"] = "Я спросил его, почему, и он сказал... снежинки растают, но скульптура не состарится.",
    ["我难道听错了？什么奇怪的要求！我不是马车夫。"] = "Я ослышался? Какая странная просьба! Я не водитель кареты.",
    ["我需要你帮个忙：带我去见你们组织里所有去过廷根湖的人。"] = "Мне нужно, чтобы вы оказали мне услугу: отвезли меня к каждому из вашей организации, кто был на озере Тинген.",
    ["我需要考虑一下再做决定。"] = "Мне нужно подумать, прежде чем принять решение.",
    ["我，嘿嘿……随口说的，想吓唬他们。"] = "Я, хе-хе... Я просто сказал это случайно, пытаясь их напугать.",
    ["我？"] = "Мне?",
    ["我？当然是这里的店主了。"] = "Я? Разумеется, владелец этой лавки.",
    ["我？我好像是被马桶冲进来的……"] = "Мне? Кажется, меня смыли через унитаз...",
    ["戒指……你不会是说从天而降的浪漫戒指吧！"] = "Кольцо... ты не имеешь в виду романтическое кольцо, упавшее с неба!",
    ["戒指啊。"] = "Кольцо.",
    ["戒指就在那位女士附近，去问问她。"] = "Кольцо находится рядом с этой дамой; иди спроси ее.",
    ["戒指找不回来也没关系，重要的是您曾经拥有过。"] = "Не имеет значения, если кольцо невозможно найти; важно то, что оно когда-то было у вас.",
    ["戒指被梅格夫人带走了！她多么幸运，能接受花海的祝福！"] = "Кольцо забрала миссис Мэг! Как ей повезло получить благословение цветочного моря!",
    ["戒指？来我这找戒指的，你们不是第一个。"] = "Кольцо? Ты не первый, кто приходит ко мне за кольцом.",
    ["或许我该认清现实，不再挣扎，在这里安静地等待死亡降临吧。"] = "Быть может, пора признать реальность, перестать бороться и просто смиренно ждать прихода смерти.",
    ["或许是受大地力量的影响，这里物产丰富，常年丰收不断，镇上的人时常举行丰收庆典，赞美大地的恩赐。"] = "Быть может, под благотворным влиянием силы Земли этот край изобилует богатствами и щедрыми урожаями круглый год. Жители городка часто устраивают праздники урожая, вознося хвалу дарам Земли.",
    ["或许是因为……"] = "Быть может, потому что...",
    ["或许，也包含着一丝对神国的好奇与宁静的向往？"] = "Может быть, в нем есть и след любопытства к Царствию Божию и стремления к спокойствию?",
    ["戴着兜帽的男人，带回了舞鞋。"] = "Человек в капюшоне принес обратно танцевальные туфли.",
    ["戴维曾说，人生最浪漫的事，就是追逐风和雪。"] = "Дэвид однажды сказал, что самое романтичное в жизни — гоняться за ветром и снегом.",
    ["戴维，你算我的爱人还是哥哥，算我的妻子还是丈夫？"] = "Дэвид, ты считаешь меня моим возлюбленным или моим братом, моей женой или моим мужем?",
    ["戴维，我忘记了，你是什么时候爱上阿斯兰的……"] = "Дэвид, я забыл, когда ты влюбился в Аслана...",
    ["所以……你需要我做什么？"] = "Итак... что мне нужно сделать?",
    ["所以他决定仔细研究手稿，从中学习创作经验……没想到会变成这副模样。"] = "Поэтому он решил внимательно изучить рукопись, чтобы перенять свой творческий опыт... Я не ожидал, что он закончит так.",
    ["所以你才让我帮你排队啊。"] = "Так вот почему ты попросил меня постоять за тебя в очереди.",
    ["所以你真的是自愿的？"] = "Так вы действительно были добровольным участником?",
    ["所以你这脸色苍白，不是因为紧张，是吃鸡蛋吃的？……话说回来，达文西看起来一点都不紧张。"] = "Значит, у тебя бледный цвет лица не из-за нервов, а из-за поедания яиц?...Кстати, да Винчи совсем не выглядит нервным.",
    ["所以你需要我帮你做什么？"] = "Так что же мне нужно для тебя сделать?",
    ["所以我必须要猎龙，我要完成我们的理想，我要让他的名字被人记住！"] = "Итак, я должен охотиться на дракона. Я должен осуществить наш идеал, я должен сделать так, чтобы его имя помнили!",
    ["所以我找了个钱多事少的活。"] = "Так я нашел работу с хорошей оплатой и небольшой работой.",
    ["所以我把所有事情都记录下来，可现在……它们全散了……"] = "Вот я все записал, но теперь... они все разбросаны...",
    ["所以我昨晚是和……<P_Heart>（罗塞尔！！！你的品味也太……）</>"] = "Итак, вчера вечером я был с... <P_Heart> (Розель!!! У тебя слишком уж вкус...!) </>",
    ["所以警局戒严，准备拘捕他？"] = "Значит, в полицейском участке введено военное положение и готовятся его арестовать?",
    ["所以说，抓住人们内心深处最原始、最朴素、最浓烈的感情，才是一部作品成功的关键。"] = "Поэтому уловить самые примитивные, простые и сильные эмоции, глубоко запрятанные в сердцах людей, — залог успеха произведения.",
    ["所以这到底是什么怪物？"] = "Так что же это за монстр?",
    ["所以那晚的吻，只是为了摆脱他们？"] = "Значит, тот поцелуй той ночью был просто для того, чтобы избавиться от них?",
    ["所以，关于出口……"] = "Итак, о выходе...",
    ["所以，要怎么拍？"] = "Итак, как мне позировать?",
    ["手术台上放着一件重要道具……"] = "На операционном столе есть важная подпорка...",
    ["打个招呼，我叫崔佛·墨菲。"] = "Давайте представимся. Я Тревор Мерфи.",
    ["打扰一下，请问刚才那个女孩……"] = "Извините, могу я сейчас спросить об этой девушке...",
    ["打扰到您了吗？我的名字叫艾德。我的笔友，我的宝贝，我的甜心，我的小百合，想要与我见面……"] = "Я вам помешал? Меня зовут Эд. Мой друг по переписке, мое сокровище, моя возлюбленная, моя маленькая лилия хочет встретиться со мной...",
    ["扔了就扔了，明天想起来就找，找不到就算了，总有办法。"] = "Если их выбросить, то их выбросят. Если вспомнишь завтра, поищи их; если вы не можете их найти, пусть будет так. Всегда есть способ.",
    ["找光？"] = "Ищете свет?",
    ["找到了吗？太感谢你了！让我看看……"] = "Вы нашли это? Большое спасибо! Дайте-ка подумать...",
    ["找到你了。"] = "Нашёл тебя.",
    ["找到您需要的线索了吗？"] = "Вы нашли нужные подсказки?",
    ["找过巡警，他滚两下又爬起来，跟没事人一样。 "] = "Я искал патрульного, но он просто перекатился дважды и вскочил, как ни в чем не бывало.",
    ["抛不开啊！"] = "Вы не можете отложить это в сторону!",
    ["抛开性别不谈……"] = "Если оставить в стороне пол...",
    ["报纸是这样写的：令人惊叹！上上周，金梧桐区的怀特女士向该团伙“敞开”自己的钱包，七天恋爱，共被骗100镑。"] = "Газета пишет: Удивительно! На позапрошлой неделе г-жа Уайт из района Голд-Оук «открыла» банде свой бумажник. Семь дней свиданий, и у нее украли в общей сложности 100 фунтов.",
    ["抱、抱歉。您是？"] = "Я-мне жаль. Кто ты?",
    ["抱歉……我……"] = "Извините... я...",
    ["抱歉各位，我之前家里有点事，现在才赶过来，我们开拍吧……等下，你们这是已经拍完了吗？"] = "Простите всех, у меня кое-что случилось дома, поэтому я только что приехал. Начнем снимать... подожди, ты уже закончил?",
    ["抱歉，{{先生|女士}}。我女儿……她看不见。"] = "Прошу прощения, {{господин|госпожа}}. Моя дочь... она ничего не видит.",
    ["抱歉，保护民众是警察的职责。"] = "Извините, защита населения – обязанность полиции.",
    ["抱歉，其实我是警察，办案时意外来到这里，请问你了解附近的情况吗？"] = "Извините, я на самом деле офицер полиции. Я случайно зашёл сюда во время расследования дела. Знаете ли вы что-нибудь о ситуации поблизости?",
    ["抱歉，小家伙，我还有事，帮不了你。"] = "Прости, малышка, у меня дела, и я не могу тебе помочь.",
    ["抱歉，我以为这是别人不要的垃圾。"] = "Извините, я думал, что это мусор, который кому-то не нужен.",
    ["抱歉，我很遗憾。"] = "Простите, мне очень жаль.",
    ["拉姆德小镇有对老夫妻，每天都要和东区的孙女通信……"] = "В Лэмд-Тауне есть пожилая пара, которая каждый день пишет своей внучке в Восточном округе...",
    ["拉姆齐擅长用破碎的笔触营造雾气的流动感。 但是您看……这幅画下笔规整，像是在模仿记忆中的印象，而非捕捉瞬间的朦胧。 "] = "Рамзи славился умением передавать движение тумана прерывистыми мазками. Но взгляните... на этом полотне мазки слишком правильные, будто автор пытался повторить образ из памяти, а не запечатлеть мимолетную дымку.",
    ["拒绝回答问题，惩罚！"] = "Отказ отвечать на вопрос-наказание!",
    ["拜托了——你能找到我的身体，然后想办法把它救出来吗？"] = "Прошу тебя... Ты сможешь найти мое тело и придумать, как его спасти?",
    ["拳击场的角落，有一件重要道具……"] = "В углу боксерского ринга есть важный предмет...",
    ["拳王又怎么样，胆敢对贝儿小姐不敬，我们得给你点颜色瞧瞧！"] = "И что, если ты чемпион по боксу? Если ты посмеешь проявить неуважение к мисс Белль, мы покажем тебе, что к чему!",
    ["拿别人的东西干什么？还他们吧。"] = "Зачем ты забираешь чужие вещи? Верните их.",
    ["拿去，赶紧把这倒霉的契约拿走，别再让我看到你们！"] = "Возьмите их, просто возьмите этот проклятый контракт и скройтесь с моих глаз!",
    ["拿走它吧，年轻人。"] = "Возьмите, молодой человек.",
    ["持续多久了？"] = "Как долго это продолжается?",
    ["按刚才说的路线，我们从佐特兰街到圣赛琳娜教堂，再沿豪尔斯街方向绕回来， 该看的风景差不多都能看到了。 "] = "Согласно только что упомянутому маршруту, мы идем от Заутланд-стрит до собора Святой Селены, а затем возвращаемся по Хаулс-стрит; мы сможем увидеть почти все пейзажи, которые стоит увидеть.",
    ["按照指示，我已经找齐了有关第四纪的历史资料。"] = "По инструкции я нашел все исторические материалы о Четвертой Эпохе.",
    ["接下来做点什么，继续往……嗬！"] = "Что мне делать дальше, продолжай... Ха!",
    ["接下来我会为您祷告，愿女神赐予你安宁。"] = "Дальше я помолюсь за тебя, пусть богиня дарует тебе мир.",
    ["接受福音的点拨后，噩梦再也没有出现了，赞美愚者！"] = "После получения руководства Евангелия кошмары больше никогда не появлялись. Слава Шуту!",
    ["接着……接着……"] = "Тогда... тогда...",
    ["接着，你被神使大人按头，修订了一夜的愚者圣典新章节"] = "Затем вас придавил Посланник, и вы целую ночь пересматривали новую главу Писания шута.",
    ["摄影师，给这个蠢货也拍点照片，我要让所有人知道，这就是冒犯贝儿小姐的下场。"] = "Фотограф, сфотографируй и этого дурака. Я хочу, чтобы все знали, что происходит с теми, кто оскорбляет мисс Белль.",
    ["摄影师，给这群蠢货也拍点照片，我要让所有人知道，这就是与我为敌的下场。"] = "Фотограф, сделай несколько снимков этих кретинов! Пусть каждый знает, что ждет тех, кто посмел перейти мне дорогу.",
    ["收集到猩红遗物后，前往所属势力的固定提交点，交给猎杀管家，即可获得征服声望。"] = "Собрав Алую реликвию, отнесите её в постоянный пункт сдачи своей фракции и передайте Охотничьему управляющему, чтобы получить репутацию завоевания.",
    ["改编不是乱编，戏说不是胡说！你竟敢亵渎罗塞尔大帝的作品！"] = "Адаптация — это не отсебятина, а вольное прочтение — не вздор! Как ты смеешь осквернять труды императора Розеля!",
    ["放开她，兰斯特。 "] = "Отпусти ее, Ланстер.",
    ["放开我，求您了……"] = "Отпусти меня, я прошу тебя...",
    ["放心交给我吧，队长！"] = "Положитесь на меня, капитан!",
    ["放心吧。对了，你叫什么名字？"] = "Не волнуйся. Кстати, как тебя зовут?",
    ["放心，只是拍张照而已。这是我给自己留的一份纪念，也是那只乌鸦想给你的谢礼。"] = "Не волнуйтесь, это просто фотография. Это сувенир, который я храню для себя, а также подарок в знак благодарности, который хотела подарить тебе ворона.",
    ["放心，我猜，这款饮料的配方里有令人腹泻的成分。你们在门口等等，我说不定能帮助这款饮料升级！"] = "Не волнуйтесь, я подозреваю, что рецепт этого напитка содержит ингредиенты, вызывающие диарею. Вы ждете у двери; Возможно, я смогу помочь улучшить этот напиток!",
    ["放心，里面没有太大危险，你也不是个刚入门的非凡者了。"] = "Не волнуйся, внутри нет особой опасности, да и ты уже не новичок среди Потусторонних.",
    ["故事始于狂暴海上的一艘商船，有一个年轻的水手，受到老船长的青睐，马上就要升任船长，但<P_Yellow>船上的会计</>却嫉妒不已，于是编造出一封恶毒的举报信。"] = "История начинается на торговом корабле в море Берсерка. Есть молодой моряк, которого любит старый капитан, и его собираются повысить до капитана, но бухгалтер <P_Yellow> на корабле </> завидует, поэтому он фабрикует злобное письмо с доносом.",
    ["故事开始于一场热闹非凡的订婚仪式，新郎唐泰斯刚刚从南大陆回来，他是商船“法老号”的大副，一个经历过大风大浪的水手。"] = "История начинается с оживленной церемонии помолвки. Жених Дантес только что вернулся с Южного континента. Он первый помощник торгового судна «Фараон», моряк, переживший сильные штормы.",
    ["效果达到了就行。"] = "Лишь бы эффект был достигнут.",
    ["救、救命啊——"] = "П-помогите мне—",
    ["救命啊！老鼠吃人了！"] = "Помощь! Крысы едят людей!",
    ["救活又能怎么样？买一个健康的小孩可比治病便宜多了。更不用说他们已经长得太大，很快就要没用了……"] = "Даже если выживет, что с того? Купить здорового ребенка куда дешевле, чем лечить больного. Не говоря уже о том, что они уже слишком выросли и скоро станут бесполезны...",
    ["教堂……仪式……晋升……"] = "Церковь... ритуал... продвижение...",
    ["教授撕掉了我通宵整理的实验数据，让我今天给他一份新的……"] = "Профессор разорвал экспериментальные данные, которые я собирал всю ночь, и попросил передать ему сегодня новые...",
    ["教材里的东西内容繁杂、晦涩难懂，所以学生们才没有耐心从头学起。"] = "Содержание учебников сложное и неясное, поэтому у учащихся не хватает терпения учиться с самого начала.",
    ["敬畏并非懦弱，恰恰是源于一种深刻的智慧——联系前面的内容，他知晓得越多，越是明白有些宁静不应被打扰。"] = "Трепет – это не трусость; оно проистекает из глубокой мудрости — в связи с предыдущим содержанием, чем больше он знает, тем больше он понимает, что некоторое спокойствие не следует нарушать.",
    ["敲窗<P_Yellow>三下</>，对里面说“<P_Yellow>知识指引我至此</>”，你就能拿到你想要的东西。"] = "Постучите три раза в окно <P_Yellow> </> и скажите внутри «<P_Yellow>Знания привели меня сюда </>», и вы получите то, что хотите.",
    ["文件只是废纸，你才是那份加急“速递”。"] = "Документ — просто макулатура, вы — срочный «экспресс».",
    ["文件要在三点前送到睡莲小镇，地址在封面上。"] = "Документы необходимо доставить в Город Водяных Лилий к трем часам. Адрес указан на обложке.",
    ["文字板叽里咕噜"] = "Неразборчивая надпись на доске",
    ["文章是刊登在《廷根市老实人报》上吗？最近刚好没有看报纸……"] = "Была ли статья опубликована в «Честном человеке Тингена»? Я в последнее время не читаю газет...",
    ["斯嘉丽根本没有什么未婚夫等他回来只是她不结婚的借口！她和梅兰妮在战争时就认识了还一起对付过上门抢劫的混混！"] = "У Скарлетт нет жениха, который ждет ее возвращения; это всего лишь предлог, который она использует, чтобы избежать брака! Они с Мелани знакомы со времен войны и даже объединились, чтобы разобраться с бандитом, который пытался их ограбить!",
    ["斯嘉丽？就是那个号称梅兰妮好姐妹的斯嘉丽？"] = "Скарлетт? Ты имеешь в виду Скарлетт, которая утверждает, что она лучшая подруга Мелани?",
    ["新来的伙伴，你怎么看？"] = "Новый партнер, что думаешь?",
    ["新来的朋友，既然你见解不凡，敢不敢试试我们诗社的“镇社之宝”？这首残诗，我们钻研了数月都没有答案。"] = "Новый друг, поскольку твоя проницательность необыкновенна, осмелишься ли ты попробовать «сокровище» нашего клуба? Мы изучали это неполное стихотворение несколько месяцев и не получили ответа.",
    ["新的方式吗……"] = "Новый способ...",
    ["施佩尔先生把写好的剧本交给了你，你回到舞台上继续表演。"] = "Мистер Шпеер передал вам написанный сценарий, и вы вернулись на сцену, чтобы продолжить выступление.",
    ["施佩尔先生是文艺界的名人，警察厅非常重视，所以特派我来调查此事。"] = "Господин Шпеер — знаменитость в литературном мире, и полицейское управление очень серьёзно относится к этому делу, поэтому меня специально послали расследовать дело.",
    ["施佩尔先生的……灵感剧院？"] = "Театр Вдохновения мистера Шпеера?",
    ["施佩尔先生说不定也被传到了这里，去前面找找看吧。"] = "Возможно, мистера Шпеера тоже перенесло сюда. Давайте пройдём вперёд и поищем его.",
    ["施佩尔先生，我刚才了解到……"] = "Мистер Спир, я только что узнал, что...",
    ["施佩尔先生，演出为什么停下了？"] = "Господин Шпеер, почему остановилось представление?",
    ["施佩尔先生？"] = "Мистер Шпер?",
    ["旁边有一盒破旧的火柴，难道涉及非凡事件？"] = "Рядом лежит коробка старых спичек. Может ли это быть связано с инцидентом Потусторонний?",
    ["无礼，我是愚者教会座下的神使，你应当称呼我神使大人。"] = "Как грубо, я божественный посланник Церкви Шута; вам следует обращаться ко мне как к Лорду Посланнику.",
    ["无论在哪个时代、哪个世界，“善有善报，恶有恶报”永远是所有人都认同的正义观。"] = "Независимо от эпохи и мира, «добро вознаграждается добром, а зло вознаграждается злом» — это концепция справедливости, с которой каждый всегда согласится.",
    ["无论怎样，你已获得你想要的——"] = "Несмотря ни на что, вы получили то, что хотели…",
    ["无赖连滚带爬地跑了，隐约还能听见“扑通”一声——他又摔了一跤。"] = "Подлец уползает прочь, и слышен слабый «стук» — он снова споткнулся.",
    ["既然你已经加入值夜者小队，一起看看最近发生的案件。"] = "Раз уж вы присоединились к «Ночным ястребам», давайте вместе рассмотрим недавние дела.",
    ["既然你懂得，就去帮我们看看到底是真的有鬼，还是有人搞鬼！"] = "Раз ты понимаешь, сходи и выясни: там правда призрак или кто-то устраивает розыгрыш!",
    ["既然口碑这么差，我们干嘛要来这里？"] = "Поскольку репутация такая плохая, почему мы пришли сюда?",
    ["既然怕被发现，为什么不逃走？"] = "Если боялся, что тебя заметят, почему не сбежал?",
    ["既然戒指对您这么重要——我必须找到！第一步，排查花海每个角落；第二步，翻土；第三步，筛土……"] = "Поскольку кольцо так важно для тебя, я должен его найти! Первый шаг: проверьте каждый уголок цветочного моря; второй шаг – перевернуть почву; третий шаг, просеять почву...",
    ["既然老鼠在，钱就在，那老鼠越多，是不是钱就越多？"] = "Раз есть крысы, значит, есть деньги, а больше крыс — больше денег?",
    ["日复一日、年复一年……"] = "День за днём, год за годом...",
    ["早上好，罗珊女士！你在看什么？"] = "Доброе утро, мисс Розанна! Что вы читаете?",
    ["早知道那东西会把他害死，我就该打破砂锅问到底……或者干脆把他绑在猎龙帮。"] = "Если бы я знал, что эта штука убьет его, я должен был докопаться до сути... или просто связать его с бандой охотников на драконов.",
    ["早跟你说了，包赢的。"] = "Я же говорил тебе, это гарантированная победа.",
    ["时间不多，行动起来吧！"] = "Времени мало, за дело!",
    ["时间会改变一切，石头会腐朽，雕塑会朽坏，爬上青苔。"] = "Время все изменит; камень истлеет, скульптуры испортятся и покроются мхом.",
    ["时间差不多喽，还没有做出决定的选手请抓紧时间。"] = "Время почти истекло, участники, которые еще не приняли решение, поторопитесь.",
    ["时间流逝的空镜"] = "Пустое зеркало уходящего времени",
    ["明天后半夜，来墓园找我。记住，不要告诉任何人！"] = "Встретимся на кладбище во второй половине завтрашнего вечера. Помните, никому не говорите!",
    ["明天我们还会一起来的，直到每份心意都送出去。希望他们收到时，能感到一点点开心。善良的{{先生|女士}}，愿女神保佑您。 "] = "Завтра мы снова соберемся вместе, пока все подарки не будут доставлены. Я надеюсь, что они почувствуют себя немного счастливыми, когда получат их. Добрый {{Mr.|Ms.}}, да благословит вас Богиня.",
    ["明天醒来，我可能又会忘记，但没关系，南瓜田还在这里，老查克的烈酒还在卖，柯莱的孙女还在奔跑。 "] = "Когда я проснусь завтра, я, возможно, снова забуду, но это нормально. Тыквенное поле все еще здесь, ликер Старого Чака все еще продается, а внучка Колли все еще бегает.",
    ["春夜沙龙的主人，你可以叫我维拉夫人。"] = "Я владелец салона «Весенняя ночь»; вы можете называть меня мадам Вера.",
    ["春夜舞会侍奉着不幸与美丽的化身，我们相信，唯有经历过灾厄的洗礼，才能绽放出最璀璨的花朵。"] = "Бал Весенней ночи служит олицетворением несчастья и красоты. Мы верим, что только крестившись через несчастье, могут расцвести самые блестящие цветы.",
    ["昨天我在水池前虔诚祷告的时候，水池竟然说话了！"] = "Вчера, когда я истово молился перед фонтаном, фонтан вдруг заговорил!",
    ["昨晚回家的路上，有陌生人一直跟踪我……"] = "Вчера вечером, когда я возвращался домой, незнакомец преследовал меня...",
    ["昨晚，你真美。"] = "Вчера вечером ты была по-настоящему красива.",
    ["是……是爸爸错了。不该什么都想打开。"] = "Это... это вина папы. Я не должен был хотеть открывать все.",
    ["是……是谁在说话？"] = "К-кто... кто это говорит?",
    ["是么，那就好办了。"] = "Это так? Тогда это упрощает задачу.",
    ["是什么发出的声音？"] = "Что издало этот звук?",
    ["是他把讲卫生的观念植入居民心中，让贫民窟的居民，也能相对洁净地生活。"] = "Именно он внедрил в сознание жителей понятие гигиены, позволив даже тем, кто живет в трущобах, жить относительно чисто.",
    ["是伦纳德先生特意为你准备的。"] = "Его подготовил специально для вас мистер Леонард.",
    ["是你制造了梦境？不眠者途径？难不成是教会的神职人员？"] = "Вы создали мечту? Бессонный путь? Может ли это быть член церкви?",
    ["是刚才那位女士留下的，帕子上还残留着她的玫瑰香气。"] = "Его оставила дама, и ее аромат розы все еще сохраняется на платке.",
    ["是口琴！我绝不会听错！四处都回荡着口琴声，却见不到吹琴的人……"] = "Это гармоника! Я не мог ослышаться! Звук гармошки эхом разносится повсюду, но я не вижу человека, играющего на ней...",
    ["是吗？你的表情可不是这么说的。"] = "Это так? Ваше выражение лица говорит об обратном.",
    ["是吗？我倒要看看，大名鼎鼎的侦探阁下能把我怎么样？"] = "Это так? Я хотел бы посмотреть, что знаменитый сыщик сможет со мной сделать.",
    ["是吗？那你在此处不要走动。"] = "Это так? Тогда не двигайся оттуда.",
    ["是吧？我说的没错吧？"] = "Верно? Я ведь не ошибаюсь?",
    ["是啊……那梦里的怪物是怎么回事？"] = "Да... а как насчет монстров во сне?",
    ["是啊，亲手做的，我们约好要一起做新的。 "] = "Да, он сделал его сам, и мы пообещали вместе сделать новый.",
    ["是啊，他改变了整个时代。不过《廷根市老实人报》为什么会突然开始报道罗塞尔大帝的事迹？"] = "Да, он изменил всю эпоху. Но почему «Газета честного человека Тингена» вдруг начала сообщать о деяниях императора Розеля?",
    ["是啊，序列9学徒，开门，短距离传送。"] = "Да, серия 9 «Ученик», «Открытая дверь», телепорт на короткое расстояние.",
    ["是啊，我敢保证，他们一定会幸福地厮守终生，成为街坊邻里间传颂的一段佳话。"] = "Да, я гарантирую, что они обязательно будут жить долго и счастливо и станут историей, передаваемой среди соседей.",
    ["是啊，虽然有很多地方都有点过于自我发挥了，但整体还是很出彩的。"] = "Действительно, хотя многие части были слишком импровизированными, общее исполнение было весьма блестящим.",
    ["是啊，这里永远晴朗，不像贝克兰德总是被阴雨和浓雾覆盖。"] = "Да, здесь всегда солнечно, в отличие от Баклунда, который всегда покрыт дождем и густым туманом.",
    ["是弗莱队长寄来的信……还有一份报纸？"] = "Это письмо, отправленное капитаном Фраем... и газета?",
    ["是我感冒不小心留下的鼻涕。"] = "Это сопли, которые я случайно оставил после простуды.",
    ["是挺像，但不是我的戒指。"] = "Выглядит похоже, но это не мое кольцо.",
    ["是的。"] = "Да.",
    ["是的，从早到晚，不吃不喝，一直像疯了一样自言自语。"] = "Да, с утра до вечера он не ест и не пьет, а только бормочет про себя, как сумасшедший.",
    ["是的，大约发作两到三个小时会暂停一小会儿，然后重新开始……恰好是一部<P_Yellow>戏剧表演的时长</>。"] = "Да, он делает короткую паузу примерно через два-три часа после эпизодов, а затем начинается снова... что соответствует продолжительности театрального представления <P_Yellow> </>.",
    ["是的，她一开门就会被催稿的信件淹没，只有我能从窗户出来，替她收集些素材。"] = "Да, стоит ей только открыть дверь, как ее тут же заваливают письмами от издателей с требованием продолжения. Только я могу выбраться через окно, чтобы собрать для нее материалы.",
    ["是的，它会导致严重的脱发……"] = "Да, это приведет к сильному выпадению волос...",
    ["是的，安魂诗社。在黑夜女神的注视下，我们是祂最忠诚的歌者。"] = "Да, Общество поэзии-реквиема. Под пристальным взглядом Богини Вечной Ночи мы – Ее самые преданные певцы.",
    ["是的，已经处理完毕。"] = "Да, это было решено.",
    ["是的，我是这里的管家弗雷德。宅邸被马桶散发的味道腌渍，休伯特先生不得不临时搬去其他住所。"] = "Да, я здесь дворецкий Фред. Особняк пропитался запахом из туалета, и господину Юберу пришлось временно переехать в другую резиденцию.",
    ["是的，是的，我明白你们的担心，但我们相信，只有亲自尝试才能获得属于自己的知识。"] = "Да-да, я понимаю ваши опасения, но мы считаем, что только попробовав это самостоятельно, вы сможете получить знания, которые принадлежат именно вам.",
    ["是的，梦里的画面有些古怪。"] = "Да, образы во сне были немного странными.",
    ["是的，罗塞尔陛下。今天是举办国家艺术沙龙的日子，展品们都在等待您的鉴赏。"] = "Да, император Розель. Сегодня день Национального художественного салона, и экспонаты ждут вашей оценки.",
    ["是的，美丽而伟大的艾德雯娜.爱德华兹女士！循循善诱的智者，博学多能的导师！"] = "Да, прекрасная и великая мисс Эдвина Эдвардс! Мудрый наставник, который нас направляет, эрудированный и разносторонний педагог!",
    ["是的，这个织茧……很神奇。它指引我来到了这里，让我来这里寻求答案。"] = "Да, этот кокон... удивительный. Он привел меня сюда, чтобы я нашел здесь ответы.",
    ["是的，酒精给的勇气。不然我怎么敢……这样看着您？"] = "Да, смелость, придаваемая алкоголем. Иначе как бы я посмел... так смотреть на тебя?",
    ["是的？"] = "Да?",
    ["是萨拉姐姐教我们的，叫《夜访》，嘿嘿。"] = "Сестра Сара научила нас этому, оно называется «Ночной визит», хе-хе.",
    ["是谁将你变成了怪物。"] = "Кто превратил тебя в монстра?",
    ["是贝克？"] = "Это Бейкер?",
    ["是这扇门吗？"] = "Это эта дверь?",
    ["是龙。"] = "Это дракон.",
    ["是龙吗？真的有龙？龙果然会飞……"] = "Это дракон? Драконы правда существуют? Значит, драконы и впрямь умеют летать...",
    ["是，我在想……把这束花送给<P_Yellow>对面咖啡馆的收银员</>。"] = "Да, я подумываю... подарить этот букет кассиру <P_Yellow> в кафе через дорогу </>.",
    ["晋升序列5？你成长的速度真是令人惊讶。"] = "Повышение до Последовательности 5? Твой рост поистине поражает.",
    ["智慧的闪光，你触碰到了诗的灵魂。"] = "Вспышка мудрости; вы затронули душу стихотворения.",
    ["暂时安静了……好险……"] = "Пока тихо... это было близко...",
    ["更古怪的是，你提前梦到了案件中的女孩。"] = "Еще более странно то, что девушка по делу вам приснилась заранее.",
    ["更多的爱？那……那应该要我怎么做？"] = "Больше любви? Тогда... тогда что мне делать?",
    ["曾经的你数值养成非常令人遗憾，可以说一败涂地。这次，你打算怎么做？"] = "В прошлом ваше численное развитие было очень прискорбным, и можно сказать, что это был полный провал. Что ты собираешься делать на этот раз?",
    ["最后一个是炼钢工厂，关于子弹的线索指向那里。"] = "Последний — сталелитейный завод; подсказки о пулях указывают туда.",
    ["最后一个秘密……"] = "Последний секрет...",
    ["最后一次使用马桶的人是谁？"] = "Кто последним пользовался туалетом?",
    ["最后，老大砍掉它的头，登上最高处，成为了伟大的猎龙人！"] = "И в конце босс снес ему башку, поднялся на самую вершину и стал великим Охотником на драконов!",
    ["最好<P_Yellow>开启灵视</>调查下。"] = "Для расследования лучше всего активировать <P_Yellow> духовное зрение </>.",
    ["最最可怕的是，它会让人上吐下泻……即便如此，我们依旧喝了又喝，喝了又喝，喝了又喝……"] = "Самое страшное, что от него тошнит и понос... но мы все равно пили его снова, и снова, и снова...",
    ["最近半年已经发生不下七起工厂机械失灵事故了。"] = "За последние шесть месяцев на заводе произошло не менее семи несчастных случаев с механическими неисправностями.",
    ["最近发生的事情，让你很不好受吧？"] = "То, что произошло недавно, было для тебя очень тяжелым испытанием, не так ли?",
    ["最近学校里出现了一个<P_Yellow>神秘卖家</>，在期末考试前，向学生们兜售所谓的“内部资料”。"] = "Недавно в школе появился загадочный продавец <P_Yellow> </>, который торгует студентам так называемой «инсайдерской информацией» перед выпускными экзаменами.",
    ["最近廷根降温了，晚上的地面还是很冷的，刚刚差点把我冻得提前爬起来。"] = "В Тингене недавно похолодало, и земля по ночам все еще очень холодная. Я чуть не замерз и только что приполз рано.",
    ["最近有发生和马桶相关的事件吗？"] = "Случались ли в последнее время какие-нибудь происшествия, связанные с унитазом?",
    ["最近有多起类似的失控事件，源头似乎都指向同一个地方……“玫瑰天堂”。我会把情报转告崔佛，你们心里有数就行。"] = "В последнее время было много подобных случаев потери контроля, и источник, кажется, указывает на одно и то же место... «Розовый рай». Я передам информацию Тревору; вам просто нужно это знать.",
    ["有个速递站，在下街附近，她常在那儿休息。"] = "Рядом с Лоуэр-стрит есть курьерская станция, где она часто отдыхает.",
    ["有了……我们去猎龙吧！"] = "Я понял... пойдем охотиться на дракона!",
    ["有了猎龙帮，日子有了奔头。我们认真准备着猎龙事业，直到……"] = "С Бандой Охотников на Драконов у жизни была цель. Мы серьёзно готовились к охоте на драконов, пока...",
    ["有了这个，就能追随大帝的脚步，立案调查，把他们一网打尽了！"] = "Благодаря этому я смогу пойти по стопам Императора, открыть дело для расследования и поймать их всех!",
    ["有事情好好说就是了，我也有错。买点丝瓜吧，我们回家做点汤，边吃边说。"] = "Мы можем просто поговорить как следует; Я тоже ошибался. Купите люфы, пойдем домой и приготовим суп, и мы сможем поговорить, пока едим.",
    ["有人吗？有人能听见我说话吗？"] = "Есть кто-нибудь здесь? Меня кто-нибудь слышит?",
    ["有人在散播这种子弹，还让人按他们的要求去杀人。"] = "Кто-то распространяет эти пули и заставляет людей убивать согласно их требованиям.",
    ["有人病重或受伤，附近病房缺药，我可以最快买到……"] = "Если кто-то серьезно заболел или получил травму, а в ближайшем отделении не хватает лекарств, я могу купить их быстрее всего...",
    ["有人看到了不该看的东西。"] = "Кто-то увидел то, чего не должен был видеть.",
    ["有人说那个女人早死了，也有人说她为爱离开了鲁恩这个伤心地……听起来真像一个幽灵。"] = "Некоторые говорят, что эта женщина давно умерла, а другие говорят, что она покинула Лоэн, место горя, ради любви... Это похоже на привидение.",
    ["有人问是什么歌，他说：“别问。听了你就懂了。”"] = "Когда кто-то спрашивает, что это была за песня, он отвечает: «Не спрашивай. Ты поймешь, как только услышишь».",
    ["有人？过去看看。"] = "Любой? Подойдите и посмотрите.",
    ["有什么不对吗？"] = "Что-то не так?",
    ["有什么事吗，{{PlayerName}}？"] = "Что-то случилось, {{PlayerName}}?",
    ["有什么是我这忠仆能为您效劳的？陛下。"] = "Может ли этот верный слуга что-нибудь сделать для вас, Ваше Величество?",
    ["有传言说，罗塞尔大帝在去世前已经登临了神座，这是他复活归来的征兆。\n有传言说……\n廷根警察局向值夜者小队转交了部分异常案件，作为值夜者小队的新人，你正在展开调查。 "] = "Ходят слухи, что император Розель взошёл на божественный престол перед самой смертью, и это знак его скорого воскрешения.\nХодят слухи, что...\nПолицейское управление Тингена передало Ночным Ястребам несколько необычных дел. Будучи новичком в отряде Ночных Ястребов, вы начинаете расследование. ",
    ["有品味！首先，请先闭上你的眼睛……"] = "А у вас есть вкус! Для начала, пожалуйста, закройте глаза...",
    ["有新工作，你们别闹了。伦纳德，你今天必须把报告交上来。"] = "Есть новая работа, хватит баловаться. Леонард, сегодня ты обязан сдать отчёт.",
    ["有没有找到龙的宝藏？"] = "Вы нашли сокровище дракона?",
    ["有痛觉……梦已经醒了，还是先查看下。"] = "Я чувствую боль... сон закончился, надо сначала его проверить.",
    ["有的时候，它们并没有什么差别，不是吗？"] = "Иногда между ними нет никакой разницы, не так ли?",
    ["有的，朋友，有的。"] = "Конечно, друг мой, конечно.",
    ["有紧急案件？"] = "Есть ли экстренный случай?",
    ["有资格评价戏剧的只能是观众，你应该听听现场观众的真实想法。"] = "Единственные, кто имеет право оценивать пьесу, — это зрители. Вы должны выслушать реальные мысли зрителей на месте.",
    ["有这么厉害吗？以现在的眼光来看，这故事有点老套了。"] = "Неужели это так удивительно? По сегодняшним меркам эта история немного банальна.",
    ["有这件事吗？我忘了。你确定？看着不像……"] = "Это произошло? Я забыл. Вы уверены? Не похоже...",
    ["有道理……你给了我新的思路……"] = "В этом есть смысл... ты навел меня на новую мысль...",
    ["朋友，你这么快就想通了。"] = "Друг, ты так быстро все понял.",
    ["朋友？别忘了，你的手下还偷过我的东西。"] = "Друг? Не забывай, твои подчиненные украли мои вещи.",
    ["朝阳升起时，你们终于完成了一份还算不错的初稿"] = "Когда восходит утреннее солнце, вы, наконец, завершаете вполне приличный первый набросок.",
    ["木桩怎么变得这么矮了？几乎和坐地上一样。"] = "Почему деревянный кол стал таким коротким? Это почти как сидеть на земле.",
    ["末日即将来临，我也要尽快消化魔药，平衡体内的污染。"] = "Конец приближается, и я должен как можно скорее переварить волшебное зелье, чтобы сбалансировать загрязнение моего тела.",
    ["末日将近，你离高序列仍有距离，“愚者”先生从历史中借来神明的神话形态，将其投影于织茧之中，以此为你铸就超越自身的力量。 "] = "Апокалипсис уже близко, а вы все еще находитесь на некотором расстоянии от высоких Последовательностей. Мистер «Шут» позаимствовал мифическую форму божества из истории и спроецировал ее в кокон, тем самым создав для вас силу, превосходящую вашу собственную.",
    ["本店并不出售钢琴……但我想您听到的声音应该来自我们的一个八音盒。"] = "В этом магазине не продаются пианино... но я думаю, что звук, который вы слышали, исходил из одной из наших музыкальных шкатулок.",
    ["本次“幸运蛋”的数字编号是88，获胜者，就是……"] = "Номер «Счастливого яйца» на этот раз — 88! И победителем становится...",
    ["本次百里挑蛋挑战赛，我们的获胜者究竟是谁？看得出这边的女士非常有信心啊，那边的先生也已经激动地跳起来了！"] = "Кто станет победителем конкурса «Одно из ста яиц»? Я вижу, что дама здесь очень уверена в себе, а джентльмен там уже прыгает от волнения!",
    ["杀人？！你快去叫警察，我先去看看情况！"] = "Убийство?! Вы позвоните в полицию, я сначала проверю ситуацию!",
    ["来了个糙汉大叔，大叔也穿着约定配色的衣服！大叔走过去了！大叔和奶奶交涉了一番！"] = "Пришел грубый дядя, на дяде тоже одежда оговоренного цвета! Дядя подошел! Дядя договорился с бабушкой!",
    ["来了个美丽奶奶……奶奶穿着约定配色的衣服！走过去了！把花拿起来了！"] = "Пришла красивая бабушка... на бабушке одежда согласованного цвета! Она подошла! Она собрала цветы!",
    ["来了个美丽少女，不是。"] = "Пришла красивая молодая девушка, нет, это не то.",
    ["来了个美丽阿姨，不是。"] = "Пришла красивая тётя, нет, это не то.",
    ["来了啊。"] = "Ты здесь.",
    ["来了，杰斯。我等会是死在左边还是右边好一点？"] = "Вот я, Джек. Лучше ли мне позже умереть слева или справа?",
    ["来做什么？上一个来挑衅我的人，现在只剩这颗牙了……你要不要也留个纪念？"] = "Зачем ты здесь? У последнего человека, который пришел меня провоцировать, остался только этот зуб... хочешь тоже оставить сувенир?",
    ["来吧，丽埃娜，我该杀你了。"] = "Давай, Лиана, я должен тебя убить.",
    ["来吧，休息吧，安眠吧……"] = "Приди, отдохни, Сон...",
    ["来吧，向祂虔诚地忏悔，让永恒的星空去洗涤你的灵魂。"] = "Придите, покайтесь Ему с благоговением, и пусть вечное звездное небо омоет вашу душу.",
    ["来吧，将卤鹅王国发展为最强盛的王国，令你成为名垂青史的大帝！"] = "Приходите, развивайте Гусиное королевство в самое процветающее королевство и станьте императором, чье имя войдет в историю!",
    ["来吧，库克的手艺你绝对不会失望！下一个就是我了，只要在这里站一会，你会成为今天最快享受到美食的人！"] = "Да ладно, вы не будете разочарованы навыками Кука! Я следующий, просто постойте здесь немного, и вы станете человеком, который сегодня быстрее всех насладится едой!",
    ["来吧，想要什么属性随便填，逆天改命的机会就在你面前。"] = "Давай же, выбирай любые характеристики по душе: шанс бросить вызов судьбе прямо перед тобой.",
    ["来吧，我亲爱的孩子，向祂虔诚地忏悔，让永恒的星空洗涤你的灵魂。"] = "Приди, дитя мое, благоговейно покайся перед Ним, и пусть вечное звездное небо очистит твою душу.",
    ["来呀，陛下，今夜一起享乐吧。"] = "Приходите, Ваше Величество, давайте повеселимся сегодня вечером.",
    ["来喝酒的？还没开张，但可以先给你尝尝。"] = "Здесь выпить? Мы еще не открыты, но сначала я могу дать вам попробовать.",
    ["来来来这边，这几位是“老鼠”吉米、“酒瓶”山姆、“毒蛇”西恩和“疤脸”威利。"] = "Иди, иди сюда. Это «Крыса» Джимми, «Бутылка» Сэм, «Гадюка» Шон и «Лицо со шрамом» Вилли.",
    ["来源于现代值夜者体系的创立者，查尼斯大主教的名字，在每个大城市的黑夜女神教会的中央教堂地下，都有一扇。 "] = "Названы в честь основателя современной системы Ночных Ястребов, архиепископа Чаниса; такие врата сокрыты в подземелье главного собора Церкви Богини Вечной Ночи в каждом крупном городе. ",
    ["来过。他们说可能是老鼠。但老鼠不会翻抽屉。"] = "У них есть. Они сказали, что это могут быть крысы. Но крысы не роются в ящиках.",
    ["来追我呀！"] = "Попробуй догони!",
    ["来，试试。"] = "Давай, попробуй.",
    ["来，请您举起面前的酒杯。"] = "Поднимите, пожалуйста, бокал вина перед собой.",
    ["来，请您拿起我给您的斧子，向这堆瓦砾轰击！"] = "_\n\nПодойди, пожалуйста, возьми топор, который я тебе дал, и разбомби эту кучу обломков!",
    ["来，请您面向喷泉……让水滴洒在你的面颊……"] = "Подойди, пожалуйста, лицом к фонтану... пусть капли воды упадут тебе на щеки...",
    ["杰姆……他的耳朵和脑子都比我厉害，他会告诉我哪里的灰结块了、哪条岔路不能走。"] = "Джем... его уши и мозг лучше моих. Он говорит мне, где скопилась сажа и по каким боковым тропам мне не следует идти.",
    ["杰姆吸了太多的煤灰，他病得厉害，医生说必须在医院住几天才行。"] = "Джем надышался угольной пылью, ему очень плохо, врач сказал, что он должен остаться в больнице на несколько дней.",
    ["杰姆真的能好起来吗？"] = "Сможет ли Джем действительно поправиться?",
    ["杰斯从怀中抽出一把锋利的匕首，在灰暗的灯光下，将匕首尖端刺入了丽埃娜的胸膛。\n一切都发生得如此突然，当你回过神时，丽埃娜已经倒在了杰斯左侧的地上。月光如血静静淌下。"] = "Джейс выхватил из-за пазухи острый кинжал и в тусклом свете вонзил его остриё в грудь Лианы.\nВсё произошло так внезапно, что, когда вы пришли в себя, Лиана уже упала на землю слева от Джейса. Лунный свет безмолвно струился, подобно крови.",
    ["杰斯？你怎么不说话？杰斯？"] = "Джек? Почему ты ничего не говоришь? Джек?",
    ["杰西解开共感手镯，并将魔女带回黑荆棘安保公司..."] = "Джесси развязал браслет эмпатии и вернул ведьму в охранную компанию Чёрный Чертополох...",
    ["枕头边上放着一件重要道具……"] = "Рядом с подушкой есть важный реквизит...",
    ["果然……"] = "Как и ожидалось...",
    ["果然……还是没法丢下你不管啊。"] = "Конечно же... Я все еще не могу оставить тебя одну.",
    ["果然出事了！"] = "Я так и знал: что-то стряслось!",
    ["果然和传说一样，风经过石像附近，会发出类似叹息的声音……"] = "Как гласят легенды, ветер издает звук, похожий на вздох, когда проходит рядом со статуей...",
    ["果然打一顿才能想起来，上次那个……贝克呢？"] = "Как и ожидалось, чтобы запомнить, нужно постараться. Где это... Бейкер из прошлого раза?",
    ["果然搬走了啊……"] = "И вправду переехали...",
    ["果然是罗塞尔推广的爱国卫生运动！运动的具体情况是怎样的？"] = "Так что это действительно была Патриотическая кампания за здоровье, которую продвигала Розель! В чем заключалась специфика кампании?",
    ["果然还是要少加一些糖。"] = "Конечно же, мне все равно нужно добавлять меньше сахара.",
    ["果然，看起来警局的内鬼和黑帮也搭上了线……走！继续查！"] = "Как и ожидалось, крот из полицейского управления, похоже, тоже связался с бандами... Поехали! Продолжайте расследование!",
    ["果然，这不是普通的油画，这是——"] = "Как и ожидалось, это не обычная картина маслом, это…",
    ["某处隐秘空间。有一个可以“愚弄”时间的封印物，被暂时储存在了这里。"] = "Тайное пространство. Здесь временно хранится Запечатанный Артефакт, способный «обманывать» время.",
    ["柠檬是芳香物质，不会引起腹泻。"] = "Лимон — это ароматическое вещество, он не вызывает расстройства желудка.",
    ["柯莱……你和柯莱有什么关系？"] = "Колли... какие у тебя отношения с Колли?",
    ["柯莱？！ "] = "Колли?!",
    ["根据<P_Yellow>对等原则</>，轮到我提出问题了，如果你拒绝或者回答不出，将接受阿罗德斯的<P_Yellow>惩罚</>。"] = "Согласно принципу взаимности <P_Yellow></>, моя очередь задать вопрос. Если вы откажетесь или не сможете ответить, вы получите <P_Yellow>punishment</> от Арродеса.",
    ["根据“红手套”成员的口头描述，外观是一个王冠形状，不过它的力量因为某种原因受到了限制，就这么多。"] = "Согласно словесному описанию участника Red Glove, он имеет форму короны, но его сила по какой-то причине ограничена. Вот и все.",
    ["根据举报，他贪污了下水道治理费用，导致不少生活在下水道流浪者死去了！"] = "По сообщениям, он присвоил средства на обслуживание канализации, в результате чего погибло множество бездомных, живущих в канализации!",
    ["根据校规第九十七条，任何组织和个人都不能在学校宣扬宗教，更不能进行宗教活动！"] = "Согласно статье 97 школьных правил, ни одна организация или частное лицо не имеет права пропагандировать религию в школе, не говоря уже о том, чтобы заниматься религиозной деятельностью!",
    ["根据福音指示，我摘录了这些有关苏尼亚海的历史资料。"] = "По указанию Евангелия я собрал эти исторические материалы, касающиеся Сонского моря.",
    ["案件……请跟我来。"] = "Случай... пожалуйста, следуйте за мной.",
    ["梅丽莎……"] = "Мелисса...",
    ["梅丽莎？"] = "Мелисса?",
    ["梅兰妮知道斯嘉丽的未婚夫是个借口却一直没说，因为她不想斯嘉丽离开廷根，只留下她一个人……"] = "Мелани знала, что жених Скарлетт — всего лишь предлог, но молчала, ведь ей так не хотелось, чтобы Скарлетт покинула Тинген и оставила ее в полном одиночестве...",
    ["梅塞苔丝，这就是你总挂在嘴边的唐泰斯吗？看起来贫穷、粗俗而且……一股臭味！"] = "Мерседес, ты всегда говоришь о том Дантесе? Он выглядит бедным, вульгарным и... от него пахнет!",
    ["梅格夫人就在那！她总坐在那边华丽的长椅上！"] = "Миссис Мэг здесь! Она всегда сидит на той великолепной скамейке!",
    ["梦很美好，但我还有没做完的事，还有想守住的人。"] = "Сон прекрасен, но у меня остались незаконченные дела и люди, которых я хочу защитить.",
    ["检察官先生，这其中一定有什么误会，请您务必要再调查一下事情的真相。"] = "Господин прокурор, должно быть какое-то недоразумение. Пожалуйста, вы должны снова выяснить правду.",
    ["棕色是宁静舒适的典范。避震柔和，骑起来几乎没什么声音。黑夜女神教会提倡的安宁理念，特别适合夜间与住宅区使用。  "] = "Коричневый – образец покоя и комфорта. Амортизация мягкая, при езде практически бесшумно. Концепция мира, пропагандируемая церковью Богини Вечной Ночи, особенно подходит для ночных и жилых помещений.",
    ["植物就快枯萎了，快过去！"] = "Растения вот-вот завянут, поторопитесь!",
    ["欢迎乘坐金秋号跨湖列车。一等座15特里尔，金秋风光一览无遗。先生/女士，要坐车吗？"] = "Добро пожаловать на поезд «Золотая осень», идущий через озеро. Первый класс — 15 Trier, с панорамным видом на золотые осенние пейзажи. Сэр/госпожа, хотите билет?",
    ["欢迎加入“好市民”俱乐部，恭喜你，正式成为廷根阴影里最高效的“清道夫”。"] = "Добро пожаловать в Клуб «Добросовестный гражданин». Поздравляем с официальным званием самого эффективного «уборщика» в тени Тингена.",
    ["欢迎各位参赛选手来到我们“百里挑蛋”挑战赛的现场，我是你们的最最亲爱的主持人芬利，我想死你们了！"] = "Добро пожаловать, участники, на конкурс «Одно из ста яиц»! Я ваш самый дорогой хозяин, Финли, я так по вам скучал!",
    ["欢迎来到我的世界，征服者。    "] = "Добро пожаловать в мой мир, Завоеватель.    ",
    ["欧洛斯先生，我想请问……你为什么要购买这本书？"] = "Господин Орос, я хотел бы спросить... почему вы купили эту книгу?",
    ["欲擒故纵的把戏。不过……既然我在扮演“罗塞尔”，不如将计就计，看看她到底想干什么。"] = "Труднодоступный трюк. Но... поскольку я играю Розель, я мог бы приложить все усилия, чтобы увидеть, чего она хочет.",
    ["歌声里有女神的尊名？她是女神的信徒？"] = "В песне звучит почётное имя Богини? Она последовательница Богини?",
    ["正因为如此，“复仇”才是最具有感染力的剧情，《基督山伯爵》才能成为一本世界名著级别的爽文。"] = "Именно поэтому «Месть» является самым заразительным сюжетом, а «Граф Монте-Кристо» может стать классикой мирового уровня.",
    ["正如你所见，历史学正在走向历史的角落，为了阻止这一切，我开始向学生们售卖“内部资料”。"] = "Как видите, история уходит в уголки истории. Чтобы остановить все это, я начал продавать студентам «инсайдерские материалы».",
    ["正是对你的思念，才让我战胜了狂暴海上的惊涛骇浪，回来与你重逢。"] = "Именно тоска по тебе помогла мне одолеть яростные волны Бушующего моря и вернуться к тебе.",
    ["步入心灵的大海，寻找藏于潜意识中的答案。"] = "Шагните в море разума и найдите ответы, спрятанные в подсознании.",
    ["死不了……我命硬。这种时候我帮不上什么忙。"] = "Я не умер... Я сильный. В такое время я не могу сильно помочь.",
    ["母亲……<P_Heart>（有些警惕）</>你是谁？"] = "Мать... <P_Heart> (несколько бдительно) </> Кто ты?",
    ["每一位愿意走向末日的人，都该有与末日对峙的资格。"] = "Каждый, кто готов идти навстречу апокалипсису, должен иметь право встретиться с ним лицом к лицу.",
    ["每晚。我就像个思春的少女。"] = "Каждую ночь. Я как влюбленная молодая девушка.",
    ["每晚都在？"] = "Каждую ночь здесь?",
    ["比如一个书柜，一个邮筒，一个垃圾桶……"] = "Например, книжный шкаф, почтовый ящик, мусорное ведро...",
    ["比星空更崇高，比永恒更久远的黑夜女神"] = "Богиня вечной ночи, более благородная, чем звездное небо, более вечная, чем вечность.",
    ["比星空更崇高，比永恒更久远的黑夜女神！"] = "Вечная Богиня, более благородная, чем звездное небо, более вечная, чем вечность!",
    ["比星空更崇高，比永恒更久远的黑夜女神， 我在此向您忏悔。我路过这里时，听到有人说——"] = "Богиня вечной ночи, более благородная, чем звезды, и более вечная, чем вечность, я каюсь перед тобой здесь. Когда я проходил мимо, я услышал, как кто-то сказал:",
    ["比起自己生前的姿态，艾拉更想念你的笑容，里埃尔先生。"] = "По сравнению с тем, как вы выглядели при жизни, Элле больше не хватает вашей улыбки, мистер Риел.",
    ["毕竟今夜这一幕都被你瞧见了，就把命也留下来吧！"] = "Раз уж ты увидел эту сцену сегодня вечером, ты тоже можешь оставить здесь свою жизнь!",
    ["毕竟你们年轻人和学生们打交道会更方便些。此外，我们还会付你一笔可观的酬劳。"] = "Ведь вам, молодым, легче иметь дело со студентами. Кроме того, мы заплатим вам щедрое вознаграждение.",
    ["水、水池！水池在说话！鬼啊——"] = "Ф-фонтан! Фонтан говорит! Призрак…",
    ["水手的故事？我很感兴趣，很多年前我也曾在一艘船上当过会计。"] = "История моряка? Мне очень интересно. Много лет назад я тоже работал бухгалтером на корабле.",
    ["水池怎么会说话？它说了什么？"] = "Как мог фонтан говорить? Что там говорилось?",
    ["水箱怎么空了？"] = "Почему резервуар для воды пуст?",
    ["永别了，牢笼！"] = "Прощай, клетка!",
    ["永远不要质疑马西莫对食物的品鉴能力。"] = "Никогда не сомневайтесь в способности Массимо ценить еду.",
    ["求你帮我找找吧，就在旁边的树上！"] = "Умоляю, помоги мне найти его, оно прямо на дереве рядом!",
    ["求你放过库克……带他离开海岸线餐厅，不要被其他人发现……"] = "Пожалуйста, отпустите Кука... заберите его из ресторана \"Берег\", не позволяйте другим узнать...",
    ["求婚也是。有天我说结婚吧，梅格说行，就结完了。之后来花海度假，她喜欢这里的花朵，我们就住下，当了花匠。"] = "Как и предложение. Однажды я сказал: давай поженимся, и Мэг сказала «да», и все. Позже мы приехали в Хуахай на отдых. Ей понравились здешние цветы, поэтому мы остались там и работали садовниками.",
    ["求您……求您……"] = "Я прошу тебя... я прошу тебя...",
    ["求求你，有人陷害我丈夫，他急需文件证明清白。"] = "Пожалуйста, моего мужа кто-то подставил, ему срочно нужен документ, подтверждающий его невиновность.",
    ["污染已经清除了，施佩尔先生应该不久后就会醒来。"] = "Осквернение снято, мистер Шпеер скоро должен очнуться.",
    ["污染清除了，另外，我在下水道里发现了休伯特议员贪污的证据，已经交给相关工作人员。"] = "Искажение устранена. Кроме того, я нашел в канализации доказательства Искажения члена совета Хьюберта и уже передал их соответствующему персоналу.",
    ["污染清除后，她就消失了。我怀疑她一直在利用那些被污染影响的人。"] = "Когда скверна рассеялась, она исчезла. Подозреваю, что она всё это время использовала тех, кто подпал под её разлагающее влияние.",
    ["污染清除，大家也都恢复正常了。不过，维拉夫人呢？"] = "Искажение устранена, и все вернулись к нормальной жизни. А как насчет мадам Веры?",
    ["汪呜——"] = "Гав-тяв—",
    ["汪！汪汪汪！汪！"] = "Гав! Гав-гав-гав! Гав!",
    ["汹涌澎湃的河水……不甘平凡的少年……这就是观众的心声吗？"] = "Бушующая река... мальчик, который отказывается быть обычным... разве этого хочет зритель?",
    ["没、没什么……我先去煮一杯咖啡给队长，你找他的话可以直接去宁静室。"] = "Н-ничего... Сначала я пойду сварю капитану чашку кофе. Если вы ищете его, можете пойти прямо в спальню.",
    ["没事，只是有点晕。担心？啊……很多人这么说过。我的老师，我的房东太太，甚至卖鸡蛋给我的农妇，这只是我与它们相处的方式。"] = "Я в порядке, просто немного кружится голова. Волновался? Ах... многие люди это говорили. Моя учительница, моя хозяйка, даже женщина с фермы, которая продает мне яйца, — именно так я с ними лажу.",
    ["没事，我也在找机会精进我的魔术表演。我们现在就去找米莉安太太吧。"] = "Ничего страшного, я тоже ищу возможности улучшить свое магическое шоу. Давайте прямо сейчас найдем миссис Мириам.",
    ["没人想看到报纸上出现伤亡消息。"] = "Никому не хочется видеть в газетах списки погибших и раненых.",
    ["没人知道曲作者是谁，是女人还是男人，平民还是贵族。但甚至有人在海上听船员弹过，只是船只当天就遭受了袭击。"] = "Никто не знает, кто композитор, женщина это или мужчина, простолюдин или дворянин. Но некоторые люди даже слышали, как моряки играли на ней в море, только для того, чтобы в тот же день корабль подвергся нападению.",
    ["没什么。<P_Heart>（他是不是犯了厨房大忌……灵机一动？）</>"] = "Ничего. <P_Heart> (Он нарушил кухонное табу... внезапная вспышка вдохновения?) </>",
    ["没什么，只是战斗有些激烈。"] = "Ничего, просто битва была немного напряженной.",
    ["没什么，我先前遇见了一个自称财政大臣的孩子，他向我要了一些钱，他也是你的臣民？"] = "Ничего, я раньше встречал ребенка, который утверждал, что он министр финансов, он попросил у меня денег, он тоже ваш подданный?",
    ["没关系的老大，回去后，我们还能继续努力！"] = "Все в порядке, босс. После того, как мы вернемся, мы сможем продолжать усердно работать!",
    ["没关系，你再研究研究，一定能成功调配出媲美你老师水准的饮料！"] = "Ничего страшного, продолжайте исследования, у вас обязательно получится приготовить напиток, который сможет соперничать с уровнем вашего учителя!",
    ["没关系，女神会原谅你的。"] = "Ничего, Богиня Вечной Ночи простит тебя.",
    ["没关系，我想这并不重要，还是让我听听看你们的歌，怎么样？"] = "Ничего страшного, я не думаю, что это важно. Почему бы тебе не дать мне послушать твою песню, как насчет этого?",
    ["没办法了，卡门，我帮你找值夜者吧。"] = "Выхода нет, Кармен. Я обращусь за помощью к Ночным Ястребам.",
    ["没想到你还真懂历史呢。"] = "Я не ожидал, что ты действительно знаешь историю.",
    ["没想到吧，这个精灵就由我罗塞尔本人亲自扮演！"] = "Не ожидали? Этого эльфа отыгрываю лично я, Розель!",
    ["没想到我的邻居竟然是一只会说话的猩猩，你是从马戏团里偷跑出来的吗？"] = "Я не ожидал, что моим соседом окажется говорящая горилла. Ты сбежал из цирка?",
    ["没想到这里竟然住着一只会说话的猩猩，你是从马戏团里偷跑出来的吗？"] = "Я не ожидал, что здесь будет жить говорящая горилла. Ты сбежал из цирка?",
    ["没有。"] = "Никто.",
    ["没有一个廷根的孩子小时候不被母亲拿这件事吓唬过！"] = "В Тингене нет ребенка, которого мать не напугала бы этой историей, когда они были маленькими!",
    ["没有回应……"] = "Никакого ответа...",
    ["没有没有，谈不上伟大……"] = "Нет-нет, я бы не назвал себя великим...",
    ["没有计划就行动，效率会降低百分之四十以上。"] = "Действия без плана снижают эффективность более чем на сорок процентов.",
    ["没有，船长知道会生气的……我只是让他们找点资料，减轻我的工作。"] = "Нет, капитан рассердится, если узнает... Я просто попросил их найти информацию, которая облегчит мою работу.",
    ["没有？连坟墓也没有吗？我……你没有骗我？"] = "Нет? Даже могилы? Я... ты не врешь мне, не так ли?",
    ["没礼貌的家伙，你应该称呼我为——"] = "Грубиян! Ты должен называть меня...",
    ["没礼貌，我可是尊贵的<P_Yellow>超级属性加点精灵</>。"] = "Как грубо, я благородный эльф </> с супер-атрибутами <P_Yellow>.",
    ["没见过，谁也没见过。不过据说她为了等那个男人，和家里决裂搬了出来……啧啧，看样子这回是不用等咯。"] = "Никогда его не видел, никто не видел. Но говорят, что чтобы дождаться этого человека, она порвала связи с семьей и уехала... Тск-цк, похоже, ей больше не придется ждать.",
    ["没这个必要，证据齐全，事实无疑。我以国王和法律的名义，判处你终身监禁！"] = "В этом нет необходимости. Доказательства полны, и факты неоспоримы. Именем короля и закона я приговариваю вас к пожизненному заключению!",
    ["没那么简单，要演出主角唐泰斯的风采，这个人不仅要形象俊朗、身手敏捷，最重要的还要能表现出坚毅不屈、正直果敢的英雄本色。"] = "Это не так просто. Чтобы воплотить в жизнь харизму главного героя Дантеса, этот человек должен быть не только красивым и ловким, но, главное, должен уметь проявлять героические качества настойчивости и принципиальности.",
    ["没钱？那就别在这儿扫了！这把老骨头该进救济院了。"] = "Нет денег? Тогда хватит здесь подметать! Эти старые кости должны быть в богадельне.",
    ["没错……没错……"] = "Это верно... это верно...",
    ["没错。你们这是……"] = "Это верно. Вы двое...",
    ["没错！就是这个角度，就是这个姿势！"] = "Это верно! Вот ракурс, вот поза!",
    ["没错！还敢说贵族的荣誉呢，他的脸面比踩在猪圈里的靴子还肮脏！"] = "Точно! И он еще смеет говорить о дворянской чести? Лицо у него грязнее, чем сапог, наступивший в свинарник!",
    ["没错！这位先生/女士，你一定也想登上宏伟神秘的“黄金梦想号”吧！"] = "Это верно! Сэр/госпожа, вы, должно быть, тоже хотите подняться на борт великолепного и загадочного «Золотого сна», верно!",
    ["没错！马西莫提到过，肉要在煮熟之前，过几次冰。"] = "Это верно! Массимо отметил, что мясо следует несколько раз пропустить через лед, прежде чем оно полностью приготовится.",
    ["没错，他为了这件事赶回了“红手套”。"] = "Правильно, из-за этого он помчался обратно в «Красные перчатки».",
    ["没错，他很奇怪。厨师在灶台工作，难免会沾油烟，而库克身上没有一点气味。"] = "Правильно, он очень странный. У плиты работают повара, маслянистый дым неизбежен, но от повара запаха нет вообще.",
    ["没错，休息是合法的。他已经工作得太久了。"] = "Действительно, отдых легален. Он работал слишком долго.",
    ["没错，你当年为了仕途而追求贵族小姐，掐死了你前妻刚刚诞下的婴儿，埋在了门前的大树下，我已经挖出了那个箱子！"] = "Да, вы тогда преследовали знатную даму ради карьеры, задушили младенца, которого только что родила бывшая жена, и закопали его под деревом перед дверью. Я уже откопал этот ящик!",
    ["没错，可这个斯嘉丽——"] = "Да, но эта Скарлетт...",
    ["没错，它会成为老大荣耀的见证，成为光辉的勋章！"] = "Правильно, станет свидетелем славы шефа и славной медалью!",
    ["没错，我们不该互相伤害。无论过去发生了什么，斯嘉丽，你永远都是我的姐妹。"] = "Правильно, мы не должны были причинять друг другу боль. Что бы ни случилось в прошлом, Скарлетт, ты всегда будешь моей сестрой.",
    ["没错，我在查这里的货。"] = "Это верно. Я исследую товары здесь.",
    ["没错，我曾经是迷途的羔羊，无数个夜晚被可怕的挂科噩梦纠缠。"] = "Да, когда-то я был потерянным ягненком, которого мучили ужасающие кошмары о провале экзаменов на протяжении бесчисленных ночей.",
    ["没错，来，请坐下，然后将您的目光投向这群山……"] = "Именно так. Присаживайтесь и обратите свой взор на эти горы...",
    ["没错，真的走了！我亲眼看着他们拐弯的！"] = "Точно, они и правда ушли! Я своими глазами видел, как они свернули за угол!",
    ["没错，警官，现在我们可以干干净净下班了！"] = "Правильно, офицер, теперь мы можем закончить работу чисто и опрятно!",
    ["没错，贝儿小姐是属于我们所有人的女神，岂能容你染指。"] = "Правильно, мисс Белль — богиня, которая принадлежит всем нам, как мы можем позволить вам тронуть ее пальцем.",
    ["没问题！我这就回去写报告！"] = "Без проблем! Я сейчас вернусь и напишу отчет!",
    ["没问题，毕竟罗塞尔大帝说过——"] = "Без проблем, ведь как говаривал император Розель...",
    ["没问题，距离很近，免费，五分钟回来，等我！"] = "Нет проблем, это совсем рядом, бесплатно, вернусь через пять минут, жди меня!",
    ["没问题，那么开始吧。"] = "Нет проблем, тогда начнем.",
    ["洗手池边放着他们的定情信物……"] = "У раковины лежит их знак любви...",
    ["洛耀，凯里，这里发生了什么？"] = "Ло Яо, Кери, что здесь произошло?",
    ["浪漫……"] = "Романтик...",
    ["海岸线餐厅生意这么好，是因为这个“厨王之王”吗？"] = "Дела в ресторане «Береговая линия» идут так хорошо именно из-за этого «Короля поваров»?",
    ["海岸线餐厅的老板把文章贴在立牌上了。"] = "Владелец ресторана «Береговая линия» прикрепил статью к стенду.",
    ["海蒂！就因为一张《婚后五十年计划表》，你就要和我分开？！"] = "Хайди! Только из-за «Пятидесятилетнего плана после свадьбы» ты хочешь расстаться со мной?!",
    ["深红巨石？到处都是灰色的岩石，很多被雪覆盖了。"] = "Багровый валун? Вокруг одни серые скалы, и большинство занесено снегом.",
    ["湖边一棵枯树下，海莉坐在地上。面前是一个穿褪色蓝布裙的老妇人。几只野猫安静卧在旁边。"] = "Под засохшим деревом на берегу озера Хейли сидела на земле. Перед ней стояла пожилая женщина в выцветшем синем тканевом платье. Рядом спокойно лежало несколько диких кошек.",
    ["演出为什么又停下了？！"] = "Почему спектакль снова остановился?!",
    ["演出还有几分钟就要开场了，没有主演可怎么办？愤怒的观众一定不会放过我的。"] = "Спектакль начнется через несколько минут. Что мне делать без ведущего актера? Разгневанная публика меня точно не отпустит.",
    ["演出马上就要开始了，请你赶紧换上演出的服装登场吧。"] = "Спектакль вот-вот начнется, пожалуйста, поторопитесь, переоденьтесь в костюм для выступления и выходите на сцену.",
    ["火葬炉？你还真打算烧了我？"] = "Крематорий? Ты и правда собрался меня сжечь?",
    ["灯光亮起，演出恢复正常。"] = "Загорится свет, и производительность вернется в норму.",
    ["灯光熄灭，演出再次停下。"] = "Свет гаснет, и представление вновь останавливается.",
    ["灵摆逆时针转动，不是右面，看起来在左面的桌子上。"] = "Маятник вращается против часовой стрелки, а не вправо, похоже, что он лежит на столе слева.",
    ["灵摆逆时针转动，不是左面，看起来在右面的桌子上。"] = "Маятник вращается против часовой стрелки, а не влево, похоже, что он находится на столе справа.",
    ["灵摆逆时针转动，不是左面，看起来就在右面的桌子上了。"] = "Маятник вращается против часовой стрелки, а не влево, похоже, что он находится на столе справа.",
    ["灵摆顺时针转动，在左面的桌子上！"] = "Маятник вращается по часовой стрелке, он на столе слева!",
    ["灵摆顺时针转动，是右面的桌子！"] = "Маятник вращается по часовой стрелке — это стол справа!",
    ["灵摆顺时针转动，是右面！就在这个桌子上了。"] = "Маятник вращается по часовой стрелке, это правая сторона! Это на этом столе.",
    ["烈酒、南瓜种子、老查克、小柯莱…… "] = "Крепкий алкоголь, тыквенные семечки, Олд Чак, Литтл Колли...",
    ["烛火随风摇曳，直至最后一点光芒熄灭。"] = "Огонь свечи мерцает на ветру, пока не погаснет последний кусочек света.",
    ["然后呢？"] = "А потом?",
    ["然后她把光揉成很多很多小球，送给其他怕冷的人、迷路的人、伤心的人。"] = "Затем она смешала свет во множество маленьких шариков и раздала их другим людям, которые боялись холода, потеряли или грустили.",
    ["然后我们全体冲上去，和龙大战了三百回合！"] = "Потом мы все бросились и сражались с драконом триста раундов!",
    ["然后看张开双臂……露出沉醉的神情……好，就是这样！"] = "Потом посмотрите, широко раскинув руки... покажите пьяное выражение лица... хорошо, вот и все!",
    ["然后看镜头……好，就是这样！"] = "Тогда посмотрите на объектив... Хорошо, вот и все!",
    ["然后要说暗号……"] = "Тогда мне нужно сказать кодовое слово...",
    ["然后趁头发还没掉，先下手为强，提前剪光所有头发，从此就再也没有脱发的焦虑了！"] = "Тогда прежде чем волосы выпадут, сделайте первый шаг и заранее отрежьте все волосы. Отныне беспокойства по поводу выпадения волос больше не будет!",
    ["照片啊……说实话，我一般都会拒绝这种请求。不过——如果是你帮忙拍照的话，我会同意的。"] = "Фото... честно говоря, я обычно отказываюсь от таких запросов. Однако, если это вы помогаете фотографировать, я соглашусь.",
    ["熬制后封存数日，再加入各种南方蔬菜。"] = "Варят и запечатывают несколько дней, затем добавляют различные южные овощи.",
    ["爱国卫生运动……是罗塞尔大帝日志里提到过的运动！"] = "Кампания за чистоту и гигиену... Движение, упоминавшееся в дневнике императора Розелля!",
    ["爱情啊，是这世界上最危险的东西。而春夜沙龙，一直在贩卖这种“危险”。"] = "Любовь – самая опасная вещь в этом мире. И Салон «Весенняя ночь» всегда продавал такого рода «опасности».",
    ["父亲会……把我赶出家门……"] = "Отец... выгонит меня из дома...",
    ["父亲六年前去世了，今年……本来是他们第五十年的纪念日。 "] = "Отец умер шесть лет назад, и в этом году... должно было быть их пятидесятилетие.",
    ["父亲，你还记得吗，这棵树，是您种下的。"] = "Отец, ты помнишь? Это дерево посадил ты.",
    ["爸爸也是这样。他说锁匠就是要打开一切，没有什么锁是他打不开的。"] = "Папа тоже такой. Он говорит, что работа слесаря ​​– все открывать, и нет такого замка, который он не смог бы открыть.",
    ["爸爸已经七年没有回来了……好希望明天爸爸就出现在家门口。"] = "Папа не возвращался семь лет... Я очень надеюсь, что завтра папа появится у нас на пороге.",
    ["爸爸每天傍晚都会坐在床边，听我讲故事，然后一字一句记在本子上。"] = "Папа каждый вечер сидел у кровати, слушал, как я рассказываю истории, а затем слово в слово записывал их в свой блокнот.",
    ["爸爸！我想讲个新故事！"] = "Папа! Я хочу рассказать новую историю!",
    ["爸爸，妈妈，发生了什么事？"] = "Папа, мама, что произошло?",
    ["爸爸，我的日记……"] = "Папа, мой дневник...",
    ["爸，还要挖多深呀？"] = "Папа, насколько глубже нам нужно копать?",
    ["特别是《美女与野兽》，堪称全世界最深刻最感人的爱情小说，男人看了沉默！女人看了流泪！"] = "Особенно «Красавица и чудовище», которую можно назвать самым глубоким и трогательным любовным романом в мире; мужчины молчат после прочтения! Женщины плакали после прочтения!",
    ["特殊处理后也能很接近章鱼肉，但绝对不能用冰水浸泡。"] = "После особой обработки оно очень похоже на мясо осьминога, но его ни в коем случае нельзя замачивать в ледяной воде.",
    ["狒狒对卡门的下半身恋恋不舍，好在它不再攻击卡门了。\n恢复自由的卡门很快挣脱……"] = "Бабуин никак не желал расставаться с нижней половиной тела Кармена, но, к счастью, перестал нападать на него.\nОбретя свободу, Кармен поспешно вырвался...",
    ["狗屎，什么邮筒，我是神使，神使！"] = "Дерьмо собачье, какой еще почтовый ящик?! Я божественный вестник, вестник!",
    ["狗屎，你从哪里冒出来的！"] = "Блин, откуда ты вылез!",
    ["猎龙人……瑞尔·比伯？！他也是猎龙帮的人？"] = "Охотник на драконов... Рэй Бибер?! Он тоже член банды охотников на драконов?",
    ["猎龙城是第四纪的古战场遗址……有巨龙身影出没，象征四皇威能……"] = "Город Охотников на Драконов — это древнее поле битвы Четвертой Эпохи… появляются гигантские фигуры драконов, символизирующие силу Четырех Императоров…",
    ["猎龙！猎龙！"] = "Охотьтесь на дракона! Охотьтесь на дракона!",
    ["猜猜法律会站在哪一边？目睹了一切的清醒路人，还是一个危险的醉汉？"] = "Угадайте, на чьей стороне встанет закон? Трезвый прохожий, ставший всем свидетелем, или опасный пьяница?",
    ["猩红遗物——那是这片沙盘中最特殊的战利品，只有真正的战场胜者才能获得。"] = "Алая реликвия — самый особый трофей этой песочницы, его могут получить только истинные победители поля боя.",
    ["猪油炸蔬菜是一道简单菜，能做到多好吃呢？"] = "Жареные овощи на сале – блюдо простое, но насколько оно может быть вкусным?",
    ["王国新闻？内务大臣今天生日，算吗？"] = "Новости Царства? У министра внутренних дел сегодня день рождения, это считается?",
    ["玛尔莎……和那个男孩，他们还好吗？"] = "Марта... и этот мальчик, у них всё хорошо?",
    ["玛尔莎，弗莱队长很感谢你们的礼物，不过从马车下救下你们的，并非他一人，而是一个团队。"] = "Марша, капитан Фрай очень благодарен за твои подарки, но он был не единственным, кто спас тебя из кареты; это была командная работа.",
    ["玩家来到雪山，发现这里已经是暴风雪。"] = "Игрок прибывает на Снежную гору и обнаруживает, что там уже бушует метель.",
    ["玩家离开铁十字街。身后，海莉坐在梧桐树下，野猫围聚，灰鼠蹲在桌上。她翻开一张牌，对面前新来的客人微笑。"] = "Игрок покинул Айрон-Кросс-стрит. Позади нее Хейли сидела под платаном в окружении диких кошек, а на столе сидела на корточках серая крыса. Она перевернула карточку и улыбнулась новому гостю перед ней.",
    ["玩家鼓掌动作复原"] = "Восстановлено действие хлопка игрока.",
    ["现在……该征服我的全部了。"] = "Теперь... пришло время покорить меня всего.",
    ["现在《夜访》成了我弹得最好的一首曲子。"] = "Теперь «Night Visit» стала пьесой, которую я играю лучше всего.",
    ["现在你是导演，可以随意布置<P_Yellow>场景</>和<P_Yellow>道具</>，演员们也会听从你的安排。"] = "Теперь, когда вы являетесь режиссером, вы можете расположить <P_Yellow> сцены </> и <P_Yellow> реквизит </> по своему усмотрению, и актеры будут следовать вашим аранжировкам.",
    ["现在卤鹅王国暂时<P_Yellow>风调雨顺</>，今天还可以进行<P_Yellow>一</>项事务，你打算做什么？"] = "В настоящее время в Гусином королевстве временно <P_Yellow> наблюдается благоприятная погода</>. Вы можете выполнить задачу <P_Yellow>one</> сегодня. Что вы намерены делать?",
    ["现在卤鹅王国暂时<P_Yellow>风调雨顺</>，今天还可以进行<P_Yellow>三</>项事务，你打算做什么？"] = "Сейчас в Королевстве Гуся царит временное <P_Yellow>благополучие</>, и сегодня ещё можно заняться <P_Yellow>тремя</> делами. Чем займёмся?",
    ["现在卤鹅王国暂时<P_Yellow>风调雨顺</>，今天还可以进行<P_Yellow>两</>项事务，你打算做什么？"] = "В настоящее время в Гусином королевстве временно <P_Yellow> наблюдается благоприятная погода</>. Вы можете выполнять задачи <P_Yellow>two</> уже сегодня. Что вы намерены делать?",
    ["现在怎么办？装死？门外那两人一拳打我肚子上，我不就“复活”了？我倒希望自己真的变成个鬼魂……"] = "Что же делать? Притвориться мёртвым? Эти двое за дверью ударят меня в живот, и я сразу «воскресну». Лучше бы я и правда стал призраком...",
    ["现在感受到战斗属性增强的感觉了吧。"] = "Теперь вы можете почувствовать улучшение своих боевых качеств.",
    ["现在我需要……第五纪正神教会典籍与神谕汇编资料。"] = "Теперь мне нужна... коллекция классических произведений и прорицаний Православной Церкви Пятого века.",
    ["现在明白，也不算太晚。"] = "Сейчас еще не поздно это понять.",
    ["现在是寻找戒指时间，请您也加入我的计划。"] = "Теперь пришло время поиска кольца; пожалуйста, присоединяйтесь к моему плану.",
    ["现在更美。让我看看晨光中的你……"] = "Ты теперь еще красивее. Позволь мне взглянуть на тебя в утреннем свете...",
    ["现在的我——是一个顶着人头的恶魔。"] = "Тот человек, которым я являюсь сейчас, — это дьявол с человеческой головой.",
    ["现在裤子也湿了，有人在用凉水浇我！求你快帮帮我吧，我只有一条裤子啊！"] = "Теперь и штаны промокли, кто-то поливает меня холодной водой! Пожалуйста, помоги мне скорее, у меня же только одни штаны!",
    ["现在让我们揭晓谜底，“幸运蛋”的数字编号是……它的第一位数字是8！"] = "Теперь давайте раскроем ответ. Номер «Счастливого яйца»… его первая цифра — 8!",
    ["现在该把你送回去了。记住，碰上事——干就完了！"] = "Теперь пришло время отправить тебя обратно. Помните: когда у вас возникнут проблемы – просто дерзайте!",
    ["现在，一切准备就绪，伯爵已然归来！"] = "Теперь все готово; Граф вернулся!",
    ["理解什么？"] = "Понять что?",
    ["琼！菲尔！去把那个拿出来！"] = "Джоан! Фил! Иди возьми эту штуку!",
    ["瑞尔执意要走，没办法，我只能接替他带领猎龙帮，谁知道……"] = "Рэй наотрез отказался оставаться. Делать было нечего, и мне пришлось возглавить шайку Драконоборцев вместо него. Кто же знал...",
    ["甜蜜？那叫甜腻！喝一口能让人踢正步踢到贝克兰德！"] = "Сладкий? Это приторно! Один глоток может заставить кого-то идти в ногу до самого Баклунда!",
    ["生意？好好好！您说！"] = "Дело? Отлично, отлично! Рассказывайте!",
    ["生日？"] = "День рождения?",
    ["用力不够灵活啊……这样，我喊四十您用适中的力气，我喊八十您用较大的力气，如何！"] = "Ваша сила недостаточно гибкая... Как насчет этого: я прокричу «сорок», а вы примените умеренную силу, я прокричу «восемьдесят», а вы примените большую силу, как насчет этого!",
    ["申请需要一定的功勋，不过你的运气不错。"] = "Для подачи заявки нужно определённое количество заслуг, но вам повезло.",
    ["画面变化，温妮在知识雕塑前默念后，便虚幻一般消失……黑屏……温妮昏倒在一座工厂里。"] = "Сцена меняется; после того, как Винни что-то бормочет перед скульптурой знаний, она исчезает, как призрак... черный экран... Винни теряет сознание на фабрике.",
    ["留给女儿的礼物，是很重要的。"] = "Подарок для дочери — это очень важно.",
    ["疼？你让我心如刀绞，现在却说我弄疼了你？我可以给你一切，公爵夫人的位置，所有财富……"] = "Повредить? Ты разбил мне сердце, а теперь говоришь, что я причиняю тебе боль? Я могу дать тебе все: положение герцогини, все богатство...",
    ["的确……下水道失去了灭鼠投入，老鼠肆虐。工厂废水因为管道无人维护而无法排出，不断发酵出臭气……甚至影响了居民家中的马桶。"] = "Действительно... Канализация потеряла финансирование борьбы с грызунами, и крысы разгуливают безудержно. Заводские сточные воды невозможно слить, потому что трубы не обслуживаются, постоянно бродят и издают неприятный запах... Это коснулось даже туалетов в жилых домах.",
    ["的确没有，这条路虽然不好走，但也没什么石头挡路。"] = "На самом деле его нет. Хотя идти по этой дороге трудно, камней, преграждающих путь, нет.",
    ["盥洗室与下水道的主宰。"] = "Мастер туалетов и канализации.",
    ["盥洗室在另一边。"] = "Туалет находится на другой стороне.",
    ["相信你经过了充分的训练和调教，也会懂得这一切，懂得这门艺术的。"] = "Я верю, что после достаточного обучения и тренировок вы тоже все это поймете и поймете это искусство.",
    ["省省吧，我才不信这一套，你这穷小子爱上的，一定是我们家的金币吧！"] = "Сохраняйте, я вообще в это не верю. То, во что ты, бедный мальчик, влюбился, должно быть, золотые монеты нашей семьи!",
    ["看你的表情，有什么疑问吗？"] = "Судя по выражению твоего лица, у тебя есть вопросы?",
    ["看到这个路牌了吗？我们要顺着它的指向前行。"] = "Вы видите этот дорожный знак? Нам нужно следовать его направлению.",
    ["看到那座雕塑了吗？颜色鲜艳，周围是一片鲜花。"] = "Видишь эту скульптуру? Цвета яркие и окружены полем цветов.",
    ["看医生的钱，我来出吧。你需要多少？"] = "Я заплачу за врача. Сколько вам нужно?",
    ["看在你这么诚心的份上，我就告诉你吧。"] = "Раз ты такой искренний, я тебе скажу.",
    ["看得出来，大家都很期待了，那么让我来揭晓最终答案！"] = "Я вижу, что все с нетерпением ждут этого, поэтому позвольте мне раскрыть окончательный ответ!",
    ["看我！求求你看我一眼！我已经写了一千首情诗，每一首都在歌颂您的美！ "] = "Посмотри на меня! Пожалуйста, посмотрите на меня! Я написал тысячу любовных стихотворений, каждое из которых восхваляет твою красоту!",
    ["看来你发现了不对劲的地方。"] = "Кажется, вы обнаружили что-то неладное.",
    ["看来你已经把中级时尚评鉴全都完成了。不错，时尚协会已经认可你的品味，现在可以去和高级评委聊聊真正的搭配了。"] = "Кажется, вы завершили все промежуточные оценки моды. Неплохо, Ассоциация моды признала ваш вкус. Теперь вы можете пойти и поговорить со старшими судьями о реальном совпадении.",
    ["看来你很满意啊。"] = "Кажется, ты вполне доволен.",
    ["看来，“成为”罗塞尔大帝之后，我获得了一些他的学识。"] = "Похоже, «став» Императором Розелем, я перенял кое-какие из его познаний.",
    ["看来，临时演员还挺专业的。布朗团长，你说呢？"] = "Кажется, временные актеры вполне профессиональны. Капитан Браун, что вы думаете?",
    ["看来，你已经初步了解了这里的战场与规则。征服者的旅途，就从此刻开始。出发吧，入局之人！"] = "Похоже, вы уже получили начальное представление о здешнем поле боя и правилах. Путь Завоевателя начинается с этого мгновения. В путь, вступивший в игру!",
    ["看来，你帮助了不少人……闪电莉莉？"] = "Кажется, ты помог немалому количеству людей... Молния Лили?",
    ["看看他们，多么甜蜜、多么般配！就像奥莱蒂的画作中走出的人物。"] = "Посмотрите на них, какие милые, как гармонично подобраны! Как персонажи, сошедшие с картины Олетти.",
    ["看看你这副样子。一个需要靠揍孩子来显得自己厉害的醉鬼。"] = "Посмотри на себя. Жалкий пьяница, которому нужно избить ребенка, чтобы почувствовать себя сильным.",
    ["看起来他已经疯了。"] = "Похоже, он уже сошел с ума.",
    ["看起来是机械教会的造物，奇怪，教会怎么会扯进来？"] = "Кажется, это творение Механической Церкви. Странно, как могла быть замешана Церковь?",
    ["看！这就是奶奶种的南瓜！ "] = "Смотри! Вот они, тыквы, выращенные бабушкой! ",
    ["看，那盒戒指都是花海捡的。每个被恋人扔掉戒指的人都觉得这辈子完了，但似乎后来都好好的。计划得再好，最后也不一定成。这些就是先例。"] = "Смотри, вся эта коробка с кольцами была подобрана в цветочном море. Каждый, чье кольцо выбросил возлюбленный, думает, что его жизнь окончена, но, похоже, позже у них все наладится. Каким бы хорошим ни был план, в конечном итоге он не всегда срабатывает. Это прецеденты.",
    ["真……真的吗？我……不，不行，不能白拿别人的东西。而且……"] = "Р-правда? Я... нет, я не могу, я не могу брать вещи бесплатно. И...",
    ["真不甘心……给我一点力量或者财富吧……"] = "Я правда не смирилась... Дайте мне немного власти или богатства...",
    ["真可惜……昨晚的您，可比清醒时有趣多了。"] = "Как жаль... Вчера вечером ты был гораздо интереснее, чем когда ты трезвый.",
    ["真可爱，还在犹豫？算了，游戏该结束了。"] = "Такой милый, все еще колеблешься? Забудьте об этом, игра окончена.",
    ["真实世界总让人心碎，但仍有值得留恋的地方。\n第一次喝下美味咖啡，第一次踏足紫藤花下，第一次见到那些人……"] = "Реальный мир всегда разбивает сердце, но и в нём есть то, за что хочется держаться.\nПервая чашка вкусного кофе, первый шаг под цветущей глицинией, первая встреча с этими людьми...",
    ["真是一出伟大的戏剧，这两个小时让我仿佛度过了一生。"] = "Какая великолепная пьеса. Эти два часа ощущались так, словно я прожил целую жизнь.",
    ["真是个可怜的男人。不过，他说的，是真的吗？"] = "Какой жалкий человек. Однако правда ли то, что он сказал?",
    ["真是个狡猾的女人……"] = "Какая коварная женщина...",
    ["真是库克先生！"] = "Это действительно мистер Кук!",
    ["真是本神奇的故事书。"] = "Поистине удивительная книга сказок.",
    ["真有这种好事？会不会有危险……"] = "Неужели правда такое счастье? А не опасно ли это...",
    ["真的假的？"] = "Правда?",
    ["真的假的？龙头在哪里，能不能让我们看看？"] = "Это правда или ложь? Где голова дракона? Можете ли вы показать нам?",
    ["真的可以吗？{{先生|女士}}，你为什么要这样帮我？"] = "Это действительно нормально? {{Mr.|Ms.}}, зачем ты мне так помогаешь?",
    ["真的吗……"] = "Правда?..",
    ["真的吗，我好像是在做梦。要是梦醒了……我和杰姆，还能去哪儿呢？我们已经……回不去了。"] = "Действительно? Я чувствую, что сплю. Если я проснусь... куда еще мы с Джемом сможем пойти? Мы... мы не можем вернуться.",
    ["真的吗，我马上出来……不对，谁信啊！"] = "Действительно? Я сейчас выхожу... погодите, кто бы этому поверил!",
    ["真的？"] = "Действительно?",
    ["真相就是……我是个寡妇，陛下。我的丈夫三年前去世了。从那之后，男人们都觉得我是容易得手的猎物。 "] = "Правда в том... что я вдова, Ваше Величество. Мой муж умер три года назад. С тех пор мужчины видят во мне легкую добычу. ",
    ["真该死！他原本是我的上司，没想到内鬼竟然是他。"] = "Блин! Изначально он был моим начальником. Я никогда не ожидал, что крот окажется именно он.",
    ["真说话了！"] = "Это действительно говорило!",
    ["眼前开始浮现灰雾，玩家来到了源堡。"] = "Перед глазами начал возникать серый туман, и игрок прибыл в Замок Сефиры.",
    ["睡莲小镇？那是郊外啊，只剩二十五分钟了……"] = "Город водяных лилий? Это в пригороде, и осталось всего двадцать пять минут...",
    ["瞧你这点出息，就算再有钱，最重要的还是查清楚当年的真相！"] = "Посмотрите на отсутствие у вас амбиций, даже со всеми этими деньгами, самое главное — узнать правду того года!",
    ["瞧我，这么快就把路忘了。"] = "Посмотри на меня, я так быстро забыл дорогу.",
    ["知识教会的人追得很紧，我的时间不够了，你能帮帮我吗？"] = "Люди из Церкви Знания преследуют меня по горячим следам, а у меня мало времени. Вы можете помочь мне?",
    ["知道为什么东区的乌鸦最近都不叫了吗？因为它们的喉咙里卡着像你这样的蠢货的骨头。"] = "Знаешь, почему вороны в Восточном округе в последнее время не кричали? Потому что в их горлах застряли кости таких идиотов, как ты.",
    ["知道了……"] = "Понятно...",
    ["知道吗？那晚之后，我把沾着您气息的手帕，藏在了枕头下面。"] = "Знаешь ли ты? После той ночи я спрятал носовой платок, испачканный твоим дыханием, под подушку.",
    ["石像能开口说话？！<P_Heart>（举起武器打算应付）</>果然遇到了邪神的污染！"] = "Каменная статуя заговорила?! <P_Heart>(поднимает оружие, готовясь к бою)</> Так и знал, скверна Злого Бога!",
    ["砰！"] = "Хлопнуть!",
    ["破损了吗？也许吧，时间太久了，但颜色一定还在。"] = "Повреждён? Возможно, прошло много времени, но цвета все еще должны быть там.",
    ["确实，我之前在公告板上看过你的讲座海报，但因为报名人数太少被取消了。"] = "Действительно, я раньше видел афишу вашей лекции на доске объявлений, но ее отменили, потому что было слишком мало желающих.",
    ["磨磨蹭蹭多长时间了，我急着开工！烧点烟，正好把那小崽子熏出来。"] = "Как долго ты бездельничаешь? Я спешу на работу! Я просто подожгу немного дыма, чтобы выкурить этого маленького придурка.",
    ["祈求您的庇佑"] = "Я молюсь о твоей защите",
    ["祈求您的恩赐"] = "Молитесь о вашей милости",
    ["神使大人看起来还是很靠谱的"] = "Господин Божественный посланник выглядит весьма надежным",
    ["神明的祝福……哪位神明？"] = "Благословение божества... какого божества?",
    ["神父爷爷……应该是去了女神的神国，那是个很远的地方。"] = "Отец Отец... должно быть, отправился в царство богини, которое находится очень далеко.",
    ["神父爷爷还在的时候，会把这些字装进梦境里，然后对来的人说一句“没关系，女神会原谅你的”，他们就会高高兴兴地离开这里。"] = "Когда Отец еще был здесь, он сохранял эти слова во сне, а потом говорил приходящим: «Все в порядке, Богиня Вечной Ночи простит вас», и они счастливые уходили отсюда.",
    ["神父，您能看见它们吗？"] = "Святой отец, вы их видите?",
    ["神父？不，我只是一个在墓园中为亡者歌唱的人。"] = "Священник? Нет, я всего лишь тот, кто поёт для усопших на кладбище.",
    ["神父？神父？"] = "Отец? Отец?",
    ["神话？"] = "Мифический?",
    ["离开伦堡前，姐姐跑来教会，给过我一枚旅行符咒。无论我们分别多久，都能借助它团聚。可我……可我把它弄丢了……"] = "Перед отъездом из Ленбурга моя сестра сбегала в церковь и подарила мне дорожный талисман. Независимо от того, как долго мы разлучены, мы можем использовать это, чтобы воссоединиться. Но я... я потерял это...",
    ["离开廷根，避开这阵风头！"] = "Покиньте Тинген, избегайте этой бури!",
    ["离开？"] = "Левый?",
    ["穿着我的衣服，梳着我的头发，像我从来没有离开过。"] = "Ношу мою одежду, расчесываю волосы, как будто я никогда не уходил.",
    ["站起来，凯文，站起来，你还能继续……"] = "Встань, Кевин, встань, ты еще можешь продолжать...",
    ["竟然无视阿罗德斯的问题，惩罚！"] = "Фактически игнорировать вопрос Арродеса ​​— наказание!",
    ["竟然还有这么多参考文献？<P_Yellow>《二十年战争中的苏尼亚岛》、《百年恩怨：帝国与家族的想象共同体》、《黑铁纪元：现代国家的政治寓言》</>……"] = "Неужели столько отсылок? <P_Yellow> «Остров Соня в Двадцатилетней войне», «Век обид: воображаемое сообщество империи и семьи», «Эра черного железа: политические аллегории современных государств» </>...",
    ["章鱼主厨餐厅？这太酷了，如果马西莫去了，应该会写出比《厨王之王》更好的文章。"] = "Ресторан шеф-повара «Осьминог»? Это так здорово. Если Массимо уйдет, она сможет написать статью даже лучше, чем «Король поваров».",
    ["笨蛋！老大可不会给我们收尸，保命要紧！"] = "Дурак! Босс не станет хоронить нас, главное - спасти свои шкуры!",
    ["笨蛋，你也暴露了！"] = "Идиот, ты тоже это раскрыл!",
