    ["美人鱼是受黑夜教会保护的灵性生物，部分教堂被允许豢养她们。"] = "Русалки - существа Духовности, находящиеся под защитой Церкви Ночи. Некоторым церквям разрешено держать их у себя.",
    ["美女？"] = "Красота?",
    ["美好故事的结尾，不应该是所有人都得偿所愿，过上更好的生活吗？"] = "Разве не должен конец красивой истории заключаться в том, что каждый получает то, что хочет, и живет лучшей жизнью?",
    ["美食总是需要时间"] = "Хорошая еда всегда требует времени.",
    ["老人家，你在找什么吗？ "] = "Дедушка, вы что-то ищете? ",
    ["老人随手一指，一旁的木桩应声而断。"] = "Старик небрежно указал пальцем, и стоявший рядом деревянный столб с треском переломился.",
    ["老先生……这里没有路牌，会不会被风雪吹倒了？"] = "Сэр... здесь нет дорожного знака. Могло ли его снести ветром и снегом?",
    ["老先生，你一定很思念戴维，但这里没有坟墓。"] = "Сэр, вы, должно быть, очень скучаете по Дэвиду, но могилы здесь нет.",
    ["老先生，这里风雪很大，您怎么一个人在这儿？"] = "Старый джентльмен, здесь очень сильный ветер и снег, почему ты здесь один?",
    ["老大一直有个梦想是猎龙我们准备了好久今天终于能出发因为路费不够所以他们先走留我们找车赶过去这是计划和地图都写在纸上了！"] = "Босс всегда мечтал охотиться на драконов. Мы долго готовились и сегодня наконец отправились в путь. Поскольку транспортных расходов было недостаточно, они уехали первыми, а нам пришлось искать карету, чтобы их догнать. Это план и карта, написанные на бумаге!",
    ["老大不好了！瑞、瑞尔大哥出事了！"] = "Босс, это плохо! Брат Р-Риэль в беде!",
    ["老大小心……盾被击穿了……"] = "Босс, будьте осторожны... щит пробит...",
    ["老大想要学徒非凡特性，我得给他搞到手！"] = "Босс хочет Потустороннюю Характеристику Ученика, и я обязан её достать!",
    ["老头，这条街归我们管。想在这儿扫地，得交钱。"] = "Старик, эта улица принадлежит нам. Если вы хотите подмести здесь, вам придется заплатить.",
    ["老师只是最近精神上出了点问题，我们联系的是心理诊所，为什么警察会来？"] = "Недавно у учителя были проблемы с психикой. Мы обратились в психологическую клинику, так почему же приехала полиция?",
    ["老师，你什么时候回来啊！"] = "Учитель, когда ты вернешься!",
    ["老板总说对我有点失望，他招我做店员，其实是看中我面试时表现的潜力。他希望我入职后能够拼一把，快速成长为销冠……不行，累，太累了。"] = "Босс всегда говорит, что он во мне немного разочарован. Он нанял меня клерком, потому что увидел потенциал, который я показал во время собеседования. Он надеется, что после того, как я присоединюсь, я смогу усердно работать и быстро стать лучшим продавцом... Нет, это утомительно, слишком утомительно.",
    ["老板来了！这是最后的机会了……"] = "Босс здесь! Это последний шанс...",
    ["老老老大！就是{{他|她}}！之前总坏咱们好事的那个！"] = "Бо-босс! Это {{him| her}}! Тот, кто всегда рушит наши планы!",
    ["老身感受到了，从大地深处传来的启示……多谢你，这里还有最后一份馈赠。"] = "Я чувствую это, откровение из глубин земли... Спасибо, вот и последний подарок.",
    ["而且我只是个……普通的、跑得快一点的送货员！"] = "А я просто... обычный курьер, который бегает немного быстрее!",
    ["而且杰姆怎么办？我跑了，雷克斯一定会把气撒在他身上。他跑不动的……"] = "А что насчет Джема? Если я убегу, Рекс обязательно выместит на нем свою злость. Он не может бежать...",
    ["而且还很健康，一般炸物都会增加人体负担，而库克用的猪油都是……"] = "И это тоже здорово. Вообще жареная пища увеличивает нагрузку на организм человека, но сало, которое использует Кук,...",
    ["而且这次得救了，下次呢？哥哥的病不是一天两天了，我们……我们总不能一直指望陌生人的善心。"] = "И даже если на этот раз меня спасут, что будет в следующий раз? Болезнь моего брата – это не однодневное явление, мы... мы не всегда можем рассчитывать на доброту незнакомцев.",
    ["而且，听说老头的三个亲生儿子都不是他的……看来他这私生子可要大赚一笔了。唉，这小子的好日子还在后头呢。"] = "Более того, я слышал, что трое биологических сыновей старика не его... Похоже, его внебрачный сын собирается заработать много денег. Увы, лучшие дни этого мальчика еще впереди.",
    ["而为了这不合常理的爱，男女主角都自愿走向死亡，这让我更加不理解……如果不能共度余生，那么爱情的意义又是什么？"] = "И ради этой неразумной любви главные герои мужского и женского пола добровольно идут навстречу смерти, что заставляет меня понимать еще меньше... Если вы не можете провести остаток жизни вместе, то в чем смысл любви?",
    ["而他们的故事，才刚刚开始……"] = "А их история лишь только начиналась...",
    ["而你……有这样的觉悟吗？"] = "А ты... у тебя есть такая решимость?",
    ["而我们用诗歌抚慰他们，用黑夜包容他们，用安宁解放他们。"] = "И мы утешаем их поэзией, обнимаем их ночью и освобождаем их миром.",
    ["而我们，每天能盼到的最好的事情，就是你这样的人肯把手伸进口袋，丢给我们一点什么，叫我们帮忙拎行李或者牵马、送信。"] = "А для нас лучшее, на что мы можем надеяться каждый день, — это то, что кто-то вроде вас захочет полезть в карман и бросить нам что-нибудь, попросив помочь нести багаж, вести лошадь или доставить письмо.",
    ["而现在，我只想征服你的心。 "] = "И сейчас, я просто хочу покорить твое сердце.",
    ["耽误这么多时间，我如果按自己的计划来，早就找到戒指了！也许在湖心的亭子，也许在许愿树……"] = "Потратив столько времени, если бы я следовал своему плану, я бы уже давно нашел кольцо! Может быть, в беседке посреди озера, может быть, у дерева желаний...",
    ["聪明的女士。您的手帕，物归原主。"] = "Умная юная леди. Ваш платок возвращается к законной владелице.",
    ["聪明的选择。春夜舞会的成员遍布这座城市的每个角落——香水商人、裁缝师、药剂师……"] = "Разумный выбор. Участников Весеннего ночного бала можно встретить в каждом уголке города – торговцев парфюмерией, портных, аптекарей...",
    ["肥肠切口的纹理，恰似盛满蜜意的蜂巢，既保留了柔韧的肌理，又奉上了丰盈的油脂。"] = "Текстура нарезанного кишечника напоминает соты, наполненные сладостью, сохраняя жевательную текстуру, но при этом предлагая насыщенный, сочный жир.",
    ["胆敢撒谎!"] = "Как ты смеешь лгать!",
    ["背后这些学生好像正在聊内部资料，悄悄听一下吧。"] = "Студенты позади, кажется, обсуждают секретные материалы. Давай подслушаем.",
    ["背誓之战……<P_Heart>（我记得最早是费内波特大地教会和知识教会的冲突……）</>"] = "Битва Нарушенной Клятвы... <P_Heart>（Помнится, всё началось с конфликта между Церковью Матери и Церковью Знаний в Фенепоте...）</>",
    ["胡说八道，闭嘴！"] = "Чушь, замолчи!",
    ["能一眼辨别出王室画师拉姆齐作品的真假，并且毫不费力地打倒了好几个序列8的高手。放眼整个因蒂斯，恐怕找不到第二个人。"] = "С первого взгляда определить подлинность картины королевского художника Рамси и без всяких усилий одолеть нескольких мастеров Последовательности 8... Во всем Интисе вряд ли найдется второй такой человек.",
    ["能不能告诉我，到底怎么才能买到内部资料呢？"] = "Можете ли вы сказать мне, как я могу купить инсайдерские материалы?",
    ["能借用一下你的锅和丝瓜吗？让我做一个尝试。"] = "Могу я одолжить твою кастрюлю и мочалку? Позвольте мне попробовать.",
    ["能够为世人所知晓的，只有一个伯爵归来的传说……"] = "Всё, что известно миру — лишь легенда о возвращении графа...",
    ["能带我们去看看吗？ "] = "Можете ли вы отвезти нас посмотреть?",
    ["能继续活下来，真是件好事，不是么？"] = "Возможность продолжать жить – это хорошо, не так ли?",
    ["至于你，我们蒙泰格家族会给你一笔补偿，说吧，你要多少钱才愿意离开我美丽的表妹？"] = "Что касается вас, наша семья Монтего выплатит вам определенную компенсацию. Скажи мне, сколько денег ты хочешь оставить моей прекрасной кузине?",
    ["至于关键台词，不妨致敬一下传奇场面……"] = "Что касается ключевых строк, то почему бы не отдать должное легендарной сцене...",
    ["至少……他刚才妥协了。换以前，他可能会撬门进来吧？"] = "По крайней мере... он только что пошел на компромисс. Раньше он мог бы взломать дверь, верно?",
    ["至少我给了钱。倒是你，你能为他们做什么？养他们一辈子？"] = "Я хотя бы дал им денег. А ты? Что ты можешь для них сделать? Содержать их до конца жизни?",
    ["舞台上出现这行大字：这里竟然有一个（     ）！"] = "На сцене появляется строка большого текста: Здесь действительно есть ()!",
    ["舞台上这是……"] = "Что это на сцене...",
    ["舞台交给你，我倒要看看你能编出什么故事！"] = "Сцена вам предоставлена, я хочу посмотреть, какую историю вы сможете придумать!",
    ["舞弊案？什么情况？"] = "Дело об обмане? Что происходит?",
    ["舞鞋！蒂亚穿着那双舞鞋跳进焚化炉自杀了！夜里舞鞋又出现在了纺织厂里面！"] = "Туфельки! Тия надела эти туфельки и бросилась в мусоросжигатель! А ночью они снова появились на текстильной фабрике!",
    ["船上的会计成了<P_Yellow>银行经理</>，港口的检察官被提拔成了<P_Yellow>王室检察官</>，而贵族青年不仅迎娶了自己美丽的表妹，还当上了王国<P_Yellow>议员</>。"] = "Бухгалтер корабля стал <P_Yellow> менеджером банка </>, прокурор порта был назначен <P_Yellow>Королевским прокурором</>, а молодой дворянин не только женился на своей прекрасной кузине, но и стал <P_Yellow>членом парламента </> королевства.",
    ["艾德蒙·唐泰斯，我是本地的维尔福检察官，现在以法律的名义正式逮捕你！"] = "Эдмон Дантес, я местный прокурор Вильфора. Я официально арестовываю вас именем закона!",
    ["艾米丽是个小作家，她想通过触摸这个世界，把感受到的样子写下来，讲给那些同样看不见的人听。"] = "Эмили — маленькая писательница. Она хочет прикоснуться к миру, записать его ощущения и рассказать об этом тем, кто тоже не видит.",
    ["花海面积庞大，戒指从热气球高度坠落，考虑到重量、风向和抛物线，落点范围可以缩小到东北方向五公亩内。"] = "Цветочное море огромно. Учитывая падение кольца с высоты воздушного шара, учитывая вес, направление ветра и траекторию, зону приземления можно сузить до пяти акров в северо-восточном направлении.",
    ["若是方便的话，可否请那位系银灰围裙的先生过来？他总能把红茶温度控制得像初春溪水一样恰好。"] = "Если вам удобно, не могли бы вы пригласить к себе господина в серебристо-сером фартуке? Он всегда может контролировать температуру черного чая так же точно, как вода в ручье ранней весной.",
    ["英勇的你，独自在下水道中发现了休伯特贪污的证据，这一切顺利得就像一场梦，对吗？"] = "Каким бы героем вы ни были, вы сами обнаружили доказательства Искажения Хьюберта в канализации. Все прошло гладко, как во сне, не так ли?",
    ["茜安不是普通章鱼，八年前，我在迪西海湾救下受伤的她，之后我们一直一起生活。一年前，我因客人投诉失业，她第一次开口说话，说要帮我做菜……"] = "Циан не обычный осьминог. Восемь лет назад я спас ее, когда она была ранена в заливе Тиси, и с тех пор мы живем вместе. Год назад, когда я потерял работу из-за жалоб клиентов, она впервые заговорила и сказала, что хочет помочь мне готовить...",
    ["茜安在你进后厨时弄晕了我，大概是不想让我看到你们打斗的场面。"] = "Циан нокаутировал меня, когда ты вошел на кухню; она, вероятно, не хотела, чтобы я видел, как вы двое ругаетесь.",
    ["荣耀、财富、力量……要多少有多少！"] = "Слава, богатство, власть... сколько захочу!",
    ["荣耀！荣耀！"] = "Слава! Слава!",
    ["莉、莉娜，你要做什么？"] = "Ле-Лена, что ты делаешь?",
    ["莉娅，东西带到了。伦纳德先生让我谢谢你，他很珍视这份心意。他也让我转告你——他和你在同一个地方长大，黑夜教会的孤儿院。 "] = "Лия, вещи доставлены. Мистер Леонард просил меня поблагодарить вас; он очень дорожит этим чувством. Еще он просил меня вам передать — он вырос там же, в приюте «Ночной ястреб».",
    ["莉娅？哦，那个在孤儿院总做噩梦的小姑娘，看来梦境里的小魔术生效了。这是……她手抄的诗？给我的？ "] = "Лия? О, эта маленькая девочка, которой постоянно снятся кошмары в приюте, похоже, маленькое волшебство во сне сработало. Это... стихотворение, которое она скопировала? Для меня?",
    ["莉娜！我的心都是真的，请你……"] = "Лина! Мои чувства искренни, прошу тебя...",
    ["莉娜！我的月光！我从第一次见到你，就被你眼中的星辰吸引。每一个夜晚，我都辗转反侧，你的身影在我脑海中挥之不去。"] = "Лена! Мой лунный свет! С первого раза, когда я увидел тебя, меня привлекли звезды в твоих глазах. Каждую ночь я ворочаюсь, а твоя фигура остается в моей памяти.",
    ["莉娜，看啊，连命运都在为我们祝福！这些陌生人的掌声，就是我对你的爱最好的见证。"] = "Лена, смотри, даже судьба нас благословляет! Аплодисменты этих незнакомцев — лучшее свидетельство моей любви к тебе.",
    ["莉娜？你在看什么？"] = "Лена? На что ты смотришь?",
    ["莉莉，快点！帮我……救救我的丈夫！"] = "Лили, быстрее! Помогите мне... спасите моего мужа!",
    ["蒂亚，可怜的女孩在舞会上丢了人，就被他们赶走，连工作都没了，其他女工也排挤她。"] = "Тия... Бедняжка опозорилась на балу, и ее тут же выставили вон. Она даже работы лишилась, да и другие работницы теперь от нее отвернулись.",
    ["蓝色，迅捷与力量之选！轻便省力，轴承顺滑，由风暴之主教会推动，在码头区与沿海道路特别受欢迎，一路畅行， 最是迅猛。 "] = "Синий, выбор скорости и мощности! Легкие и экономичные, подшипники гладкие, пропагандируемые церковью Повелителя Штормов, особенно популярные в районе доков и прибрежных дорогах, плавные на всем пути, самые быстрые.",
    ["虐待儿童，还有……压榨童工，是吧？如果我没听错的话。"] = "Жестокое обращение с детьми и... эксплуатация детского труда, верно? Если я правильно услышал.",
    ["虫子！滚出！我的！房子！"] = "Баги! Убирайся! Из моего! Дом!",
    ["虽然什么？"] = "Хотя что?",
    ["虽然作为一个鲁恩人，但每次读到大帝的生平，还是忍不住感叹——罗塞尔大帝真是史无前例的天才！"] = "Хоть я и ленец, каждый раз, когда я читаю о жизни императора, я не могу не вздыхать: император Розель поистине беспрецедентный гений!",
    ["虽然很有气势，但实在是太难听了。"] = "Хоть это и очень внушительно, но слушать действительно ужасно.",
    ["虽然情有可原，但毕竟违背了法律和校规，你该接受应有的惩罚。"] = "Хотя есть смягчающие обстоятельства, вы все-таки нарушили закон и школьные правила и должны принять заслуженное наказание.",
    ["虽然战斗力和体能非常强大，但性格很温顺，非常听话。"] = "Хотя его боевая мощь и физическая сила очень высоки, его личность очень нежная и послушная.",
    ["虽然方法有问题，但你是个好老师，我不会向学校举报你。"] = "Хоть метод и проблематичен, но вы хороший учитель, и я не буду отчитываться о вас в школе.",
    ["虽然有防身的手枪，里面却没装子弹。情急之下才躲进了这里，然后就晕过去了……"] = "Хотя у меня есть пистолет для самообороны, в нем нет пуль. Я в панике спряталась здесь, а потом потеряла сознание...",
    ["虽然，偶尔会有些羡慕。"] = "Хотя иногда я немного завидую.",
    ["行动需要有人先潜入内部，确保美人鱼的安全。"] = "Сначала кому-то нужно проникнуть внутрь, чтобы обеспечить безопасность русалки.",
    ["表哥，你怎么能这么说？他是个水手——机敏、强壮而且为人善良，你不该拿贵族的标准去要求他。"] = "Кузен, как ты можешь такое говорить? Он был моряком — умным, сильным и добродушным, и не следует требовать от него аристократических стандартов.",
    ["被看出来了。好吧，其实我是一个由知识构成的幽灵。"] = "Вы заметили. Ну, на самом деле я призрак, созданный из знаний.",
    ["被誉为鲁恩史上最恐怖的开膛手，将重新拾起这把沾满鲜血的利刃，夺走更多的生命！"] = "Известный как самый ужасающий Джек-Потрошитель в истории Лоэна, я снова подниму этот окровавленный клинок и заберу еще больше жизней!",
    ["被遗忘者已然返航，他的桅杆和钩索便是你们的绞刑架！"] = "Забытый вернулся, и его мачты и крюки — твоя виселица!",
    ["装货！老大说，“学徒真好用啊”，明白吗？"] = "Загрузите товар! Босс сказал: «Ученики очень полезны», понимаешь?",
    ["西迦可能在休息区写作。我要去煮咖啡，可以顺便问问。 "] = "Сига, возможно, пишет в гостиной. Я собираюсь сварить кофе, могу спросить ее, пока я этим занимаюсь.",
    ["西迦女士……她教我的方法让我成功避开了麻烦。听说她不光在这里做安保，还是个大作家，我准备了些纸笔……希望她用得上。"] = "Мадам Сига... метод, которому она меня научила, позволил мне успешно избежать неприятностей. Я слышал, что она не только занимается здесь охраной, но и является отличным писателем, поэтому я приготовил бумагу и ручки... Надеюсь, она сможет ими воспользоваться.",
    ["西迦，现在方便吗？一位叫凯尔文的年轻人托我给你带点东西，想感谢你之前的指点。 "] = "Сига, ты сейчас свободен? Молодой человек по имени Кельвин попросил меня принести вам что-нибудь; он хочет поблагодарить вас за ваше предыдущее руководство.",
    ["要不要尝尝我们的丝瓜汤，可以去火气。"] = "Не хотите попробовать наш суп из люффы? Он отлично снимает жар.",
    ["要不要试着给他一次机会？"] = "Может, попробуем дать ему шанс?",
    ["要去<P_Yellow>更高</>的地方……<P_Yellow>更高</>的地方……"] = "Должен перейти на место <P_Yellow> выше </>... место <P_Yellow> выше </>...",
    ["要的就是这种屈辱的感觉，特别是在这个贵族横行霸道的社会，因蒂斯人民一定会产生共鸣的。"] = "Это именно то чувство унижения, которого я хочу, особенно в этом обществе, где свирепствует дворянство; жители Интиса наверняка найдут отклик в этом.",
    ["要知道，所有出事锅炉都在年初通过了质检公司的“优质级”检验。"] = "Знаете ли, все взорвавшиеся котлы в начале года успешно прошли проверку компании по контролю качества с присвоением «Высшей категории».",
    ["要跑？是想“开门”，还是“传送”？"] = "Хотите бежать? Планируете ли вы «Открыть дверь» или «Телепортироваться»?",
    ["见鬼，你在胡说什么？他可是在因蒂斯发了好大一笔财，那封信我还随身带着呢！"] = "Черт возьми, о чем ты говоришь? Он заработал состояние на Интисе, и это письмо до сих пор со мной!",
    ["规划范围是第一步，划分网格是第二步，按可能性排查是第三步……"] = "Планирование объема — это первый шаг, деление сетки — второй шаг, а проверка по вероятности — третий шаг…",
    ["规则很简单：在这首罗塞尔大帝未做完的诗上，补上最后一句——如果你能做得到的话。 "] = "Правила просты: добавьте последнюю строчку к неоконченному стихотворению императора Розеллы — если можете.",
    ["规律？"] = "Образец?",
    ["解决她，就能离开这里……目前只能这样做了。"] = "Разгадайте ее, и я смогу покинуть это место... пока это единственный выход.",
    ["警官，你找到出口了吗？"] = "Офицер, вы нашли выход?",
    ["警察……罗塞尔大帝说过，国家的兴盛与衰败，每个人都有责任。如果不是体能测试无法通过，我们就是同事了。"] = "Полиция... Император Розель сказал, что каждый несет ответственность за взлет и падение страны. Если бы не провал теста по физической подготовке, мы были бы коллегами.",
    ["警察也是一伙的……该死，警局的这帮混蛋到底想干什么！"] = "Полиция с ними заодно... Проклятье, что вообще задумали эти ублюдки из участка?!",
    ["警察押着两个诈骗犯离开了……"] = "Полиция уводит двух мошенников...",
    ["警察来过吗？"] = "Полиция уже приходила?",
    ["警察精神满满地离开了。"] = "Полицейский уходит, полный духа.",
    ["警局已经烂透了，我也不知道该怎么办。"] = "Полицейский участок прогнил насквозь. Я тоже не знаю, что делать.",
    ["警惕陌生人搭话，保持清醒头脑！"] = "Остерегайтесь разговоров с незнакомцами и сохраняйте ясный рассудок!",
    ["警方怀疑马桶与一起案件有关，请让我进入盥洗室探查。"] = "Полиция подозревает, что туалет имеет отношение к делу. Пожалуйста, позвольте мне войти в туалет, чтобы разобраться.",
    ["计划制定完毕，我需要你的帮助！"] = "План сформулирован, нужна ваша помощь!",
    ["让思绪飘向遥远的故乡……天哪！这简直就是大帝本想表达却未能落笔的句子！"] = "Унестись мыслями к далекой родине... Боже мой! Это же именно то, что хотел выразить император, но так и не смог запечатлеть на бумаге!",
    ["让我们忽略这些细节，开始我们的游戏——"] = "Давайте проигнорируем эти детали и начнем нашу игру —",
    ["让我们高呼他的名字——拳王亨利！"] = "Давайте выкрикнем его имя — чемпион по боксу Генри!",
    ["让我在大家面前做菜？真的能有那一天吗？"] = "Разрешите мне приготовить на глазах у всех? Может ли этот день действительно наступить?",
    ["让我帮你一起找吧。 "] = "Позвольте мне помочь вам найти его вместе.",
    ["让我当猎龙帮老大，为什么？你要放弃猎龙？"] = "Позвольте мне быть боссом банды охотников на драконов, почему? Вы отказываетесь от охоты на драконов?",
    ["让我想想……先去圣赛琳娜教堂看看吧，至少可以为杰姆找到医生。"] = "Дай-ка подумать... сначала сходим в собор Святой Селены; по крайней мере, мы сможем найти доктора для Джема.",
    ["让我想想……对了，精妙的比喻、优雅的言辞、崇高的精神……遵循伟大的戏剧法则，我能轻松写出完美的台词。"] = "Дайте подумать... Верно, изысканные метафоры, изящная риторика, благородный дух... Следуя великим законам драматургии, я легко могу написать идеальные строки.",
    ["让我想想，就从……定制梅格夫人的戒指找回计划开始吧！"] = "Дай подумать... Начнем с... составления плана по возвращению кольца миссис Мэг!",
    ["让我改变自己的命运，改变大家的命运，改变——所有人的命运！"] = "Позвольте мне изменить свою судьбу, изменить судьбу всех, изменить — судьбу всех!",
    ["让这位野生非凡者，继续做她的“闪电莉莉”吧！"] = "Пусть этот дикий Потусторонний и дальше будет ее «Молниеносной Лилией»!",
    ["训练？！"] = "Обучение?!",
    ["记住，如果你发现任何王冠形状的物品或者异常事件，不要惊动，不要打扰，立刻回来禀报。"] = "Помните: если вы обнаружите какие-либо объекты в форме короны или аномальные события, не предупреждайте их, не беспокойте их и немедленно сообщите об этом.",
    ["记住，美丽总是需要代价的……但你会发现，这代价是如此值得。"] = "Помните, красота всегда имеет свою цену... но вы обнаружите, что цена того стоит.",
    ["记得带上你的警官证。"] = "Не забудьте взять с собой полицейский значок.",
    ["记者们的嗅觉可真敏锐，是吧？"] = "У репортёров прямо-таки звериное чутьё, правда?",
    ["讲卫生是健康的基础，这就是大帝教给我们的事。"] = "Гигиена – основа здоровья; этому нас учил Император.",
    ["许多年后，陷害他的<P_Yellow>三个恶人</>都成为了响当当的大人物——"] = "Спустя много лет <P_Yellow>трое злодеев</>, подставивших его, стали видными фигурами —",
    ["诈骗……团伙？！"] = "Банда... мошенников?!",
    ["试试他说的方法吧，我记得第一步是……"] = "Давайте попробуем метод, который он упомянул. Я помню, что первый шаг...",
    ["试试反向施展“开门”，既然能进去，就能倒出来。"] = "Попробуйте произнести «Открытую дверь» наоборот; поскольку вы можете войти, вы можете и выйти обратно.",
    ["话音未落，卡门窜出墙壁，如一张薄纸。"] = "Прежде чем слова исчезли, Кармен выскочила из стены, как тонкий лист бумаги.",
    ["该死的！菲尔！怎么会是你！这个案子不是你叫我查的吗……"] = "Блин! Фил! Как это мог быть ты! Разве вы не просили меня расследовать это дело...",
    ["该死的，别踩法阵！"] = "Проклятье, не наступай на магический круг!",
    ["该死！无论如何我都得去看看。它刚才说教堂，我大概知道在哪里了。"] = "Блин! Несмотря ни на что, мне нужно пойти посмотреть. Там только что упоминалась церковь, и мне кажется, я знаю, где она находится.",
    ["该死！演出又停下了，是在故意戏弄我们吗？"] = "Блин! Спектакль снова остановился. Они нас специально дразнят?",
    ["该死，你怎么在棺材里？"] = "Черт подери, почему ты в гробу?!",
    ["该死，安迪的死，那些人的死，都是为了这所谓的晋升？"] = "Проклятье... Смерть Энди, гибель всех тех людей — неужели всё это лишь ради так называемого продвижения?",
    ["该死，我就知道，又是这子弹！警局内部肯定有问题！"] = "Черт побери, я так и знал, опять эта пуля! Должно быть, проблема в отделении полиции!",
    ["该死，竟然中了圈套，坏人怎么这么多！"] = "Черт возьми, я действительно попал в ловушку. Почему так много плохих людей!",
    ["该问些什么呢？"] = "Что мне следует спросить?",
    ["语言学历史学地理学神学符号学不完成论文不拿到学分就不能离开学校啊啊啊啊啊狗屎！"] = "Лингвистика, история, география, теология, семиотика... Если не дописать диссертацию и не набрать баллы, из университета не выпустят, а-а-а-а-а, дерьмо!",
    ["误会，其实我是阿霍瓦郡警察厅的警员，有人说这边出现了连环凶案的杀手，我来抓捕。"] = "Это недоразумение. На самом деле я офицер полицейского управления округа Ахоава. Кто-то сказал, что здесь появился серийный убийца, и я пришел арестовать.",
    ["说到小情人，昨天山姆和梅兰妮吵到大半夜，他干脆挑明了，过去几个月幽会的不是别人……"] = "Говоря о его маленьком любовнике, Сэм и Мелани вчера спорили до полуночи, и он просто дал понять, что человек, с которым он встречался в последние несколько месяцев, был не кем-то другим...",
    ["说到底，罗塞尔大帝发起爱国卫生运动是几百年前的事，现在的鲁恩，下水道系统足够完备，何必继续浪费财力？"] = "В конце концов, император Розель запустил патриотическую кампанию за здоровье сотни лет назад. В нынешнем Лоэне канализационная система достаточно завершена, так зачем продолжать тратить финансовые ресурсы?",
    ["说到底，这个精灵其实就是给主角开挂的“<P_Yellow>系统</>”。只要有了“<P_Yellow>系统</>”，压根用不着什么复杂的写作技巧，就能写出源源不断的爽点。"] = "В конце концов, этот дух — просто читерская «<P_Yellow>система</>» для главного героя. А с «<P_Yellow>системой</>» никакие сложные писательские приемы не нужны, чтобы выдавать сплошное читательское удовольствие.",
    ["说吧。"] = "Продолжать.",
    ["说实话，我也有点搞不清状况。"] = "Честно говоря, я сам немного озадачен этой ситуацией.",
    ["说得好……可要从哪里弄这种东西……"] = "Хорошо сказано... но где же нам взять такие вещи...",
    ["说得好听，刚才逃跑时可不是这样的。"] = "Звучит мило, но все было не так, когда ты только что убегал.",
    ["说得对，就连霍伊河的河水也会改道，我们总有一天也会混出头的！"] = "Хорошо сказано, даже вода реки Хой меняет свое русло. Однажды мы тоже добьемся успеха!",
    ["说明一下你们的名字，以及在向谁祈祷？"] = "Объясните свои имена и кому вы молитесь?",
    ["说来话长，我刚结束一场300镑的大交易，只想快点离开……结果卡住了！"] = "Это долгая история. Я только что завершил сделку на 300 фунтов и просто хотел поскорее уйти... и тут я застрял!",
    ["说的没错。"] = "Хорошо сказано.",
    ["说起来实在荒谬，这出戏竟然没有主演，甚至也找不到剧院经理和舞台总监！"] = "Это просто нелепо: в этой пьесе нет главного героя, да и директора театра с режиссером-постановщиком днем с огнем не сыщешь!",
    ["说起来，动物之间的战斗算是格斗吧，如果足够幸运的话，说不定能从中学到一些格斗技巧。"] = "Кстати говоря, драки между животными считаются боем, верно? Если вам повезет, вы сможете научиться у него некоторым боевым приемам.",
    ["说起来，那个引我进来的声音……画里的夫人，应该就藏在这个世界的某处。"] = "Если подумать, голос, который привел меня... женщина на картине, должно быть, скрывается где-то в этом мире.",
    ["诶，你怎么偷看！都是……客户写的。"] = "Эй, чего ты выглядываешь! Они написаны клиентами.",
    ["诶？什么掉下来了！"] = "Э? Что упало!",
    ["诶？怎么变回人类了？"] = "Э? Как он снова превратился в человека?",
    ["诶？我还打算带你去采购呢！"] = "А? А я собирался взять тебя за покупками!",
    ["请你一定要答应我，作为主演登台，拜托你了！演出马上就要开始，我没有别的办法了。"] = "Пожалуйста, вы должны согласиться выйти на сцену в роли исполнителя главной роли, я вас умоляю! Спектакль вот-вот начнется, и у меня нет другого выбора.",
    ["请允许我走进你的生命，让我们的故事从今晚开始书写。莉娜，我爱你，胜过爱这世间的一切美好！"] = "Пожалуйста, позвольте мне войти в вашу жизнь и позволить нашей истории начать писаться сегодня вечером. Лена, я люблю тебя больше всего прекрасного в этом мире!",
    ["请各位贵宾尽快落座，<P_Yellow>《伯爵归来》</>即将开幕！"] = "Пожалуйста, занимайте свои места как можно скорее, <P_Yellow> «Возвращение графа» </> вот-вот начнется!",
    ["请各位贵宾尽快落座，《伯爵归来》即将开幕！"] = "Уважаемые гости, просим занять свои места, пьеса «Возвращение графа» вот-вот начнется!",
    ["请您抓紧时间。"] = "Пожалуйста, поторопитесь.",
    ["请您放心，我们一会儿就去把杰姆接回来，安置好这两个可怜的孩子。"] = "Пожалуйста, будьте уверены, через некоторое время мы заберем Джема и устроим этих двух бедных детей.",
    ["请拿好，喝了这瓶“焦糖炸弹”，祝您烦恼全炸飞，生活甜到爆！"] = "Ну вот. Выпив эту «Карамельную бомбу», пусть все ваши заботы исчезнут, и пусть ваша жизнь будет настолько сладкой, насколько это возможно!",
    ["请暂别此刻的喧嚣，来到我的身边。"] = "Пожалуйста, оставь этот шум и подойди ко мне.",
    ["请替我谢谢她，这份心意很珍贵。不过，可以告诉她：我和她一样，也是在黑夜教会的孤儿院长大的。诗人……真正的诗人大概不会因为写诗如此头疼。"] = "Пожалуйста, поблагодарите ее от меня; это чувство очень ценно. Однако вы можете ей сказать: я, как и она, выросла в приюте «Ночной Ястреб». Поэт... у настоящего поэта, наверное, не было бы такой головной боли от написания стихов.",
    ["请获胜者到后台领奖。"] = "Победители, пожалуйста, пройдите за кулисы, чтобы забрать свой приз.",
    ["请说"] = "Говорите, пожалуйста.",
    ["请问亨利先生，您有什么获奖感言吗？"] = "Мистер Генри, у вас есть какая-нибудь благодарственная речь?",
    ["请问你在向谁道歉？"] = "Перед кем ты извиняешься?",
    ["请问您有没有看见一枚——"] = "Извините, вы видели…",
    ["请问这里是施佩尔先生的工作坊吗？我奉命来调查情况。"] = "Это мастерская мистера Спира? Мне приказано разобраться в ситуации.",
    ["请问，你是来聆听愚者福音的？"] = "Простите, вы здесь, чтобы послушать Евангели Шута?",
    ["请问，您如何看待波拿巴餐厅副经理杰·杜兰德模仿血腥屠夫作案这件事？"] = "Позвольте поинтересоваться, как вы относитесь к инциденту, когда Ж. Дюран, помощник управляющего рестораном «Бонапарт», подражал Кровавому Мяснику?",
    ["读信"] = "Прочтите письмо",
    ["谁、谁逃跑了？！我们那是锻炼体魄，为猎龙做准备！"] = "Кто, кто сбежал?! Мы просто тренировали свои тела, готовясь к охоте на драконов!",
    ["谁在说话！"] = "Кто это говорит!",
    ["谁在说话？"] = "Кто это говорит?",
    ["谁成想突然就打起仗来，她未婚夫去执行任务，失踪到现在。"] = "Кто бы мог подумать, что вдруг разразится война? Ее жених отправился выполнять задание и до сих пор пропал без вести.",
    ["谁知道呢，也许是什么蒸汽革命纪念日吧……对了，你来找弗莱队长？"] = "Кто знает, может быть, это годовщина Steam Revolution... Кстати, вы пришли увидеть капитана Фрая?",
    ["谁让人家运气好，罗塞尔大帝说过，邻居好比靠近水边的高台，最容易得到月亮的青睐……"] = "Ну так кому-то просто везёт! Сам император Розель говаривал: сосед словно терраса у самой воды — первым ловит благосклонный свет луны...",
    ["谁？"] = "ВОЗ?",
    ["谁？敢插手猎龙帮的事！"] = "ВОЗ? Осмелится вмешаться в дела банды охотников на драконов!",
    ["调味之前，还有几次最关键的步骤，得准备点冰块。"] = "Прежде чем добавлять приправы, необходимо выполнить несколько важных шагов; нам нужно подготовить несколько кубиков льда.",
    ["调教即是训练，训练即是调教，懂得调教的艺术，也懂得了训练的境界。"] = "Дисциплина есть тренировка, тренировка есть дисциплина. Понимание искусства дисциплины также означает понимание сферы обучения.",
    ["谢、谢谢你，好心人……"] = "Э-спасибо, добрый человек...",
    ["谢天谢地，你来了。我感知到你身上的灵性波动了，非凡者朋友，我需要帮助！"] = "Слава Богу, ты здесь. Я почувствовал в тебе духовное колебание, друг Потусторонний, мне нужна помощь!",
    ["谢尔敏将饮料倒进马桶，伴随着冲水……"] = "Шермин выливает напиток в унитаз под звуки смыва...",
    ["谢谢“正义”小姐！我这就去看看。"] = "Спасибо, мисс «Правосудие»! Я сейчас же схожу посмотрю.",
    ["谢谢……耽误好长时间，我得整理订单了！"] = "Спасибо... Я потратил столько времени, мне нужно разобраться с заказами!",
    ["谢谢……能不能请您拍一张伦纳德先生收到礼物时的照片？他念诗时那双绿眼睛的专注神情……令人很难忘记。 "] = "Спасибо... не могли бы вы сфотографировать мистера Леонарда, когда он получит подарок? Сосредоточенный взгляд его зеленых глаз, когда он читает стихи... трудно забыть.",
    ["谢谢。"] = "Спасибо.",
    ["谢谢你。"] = "Спасибо.",
    ["谢谢你们。"] = "Спасибо вам обоим.",
    ["谢谢你的理解，我一定会找到更好的办法，让学生真正爱上历史的。"] = "Спасибо за понимание, я обязательно найду лучший способ заставить студентов по-настоящему полюбить историю.",
    ["谢谢你！你那首歌虽然……虽然那个……"] = "Спасибо! Хотя твоя песня была... хотя это...",
    ["谢谢你！我是103号，侍者叫到的话，你先进去。"] = "Спасибо! У меня номер 103, если официант позовет — заходи первым.",
    ["谢谢你！这束花是？"] = "Спасибо! А что насчет этого букета?",
    ["谢谢你，{{先生|女士}}。艾米丽很少这么开心。"] = "Спасибо, {{Mr.|Ms.}}. Эмили редко бывает такой счастливой.",
    ["谢谢你，事情的经过我已经了解。"] = "Спасибо, я уже понял последовательность событий.",
    ["谢谢你，你也记得他们。"] = "Спасибо, вы тоже их помните.",
    ["谢谢你，勇敢的{{先生|女士}}。"] = "Спасибо, храбрый {{Mr.|Ms.}}.",
    ["谢谢你，帮我从痛苦中解脱出来。"] = "Спасибо, что освободили меня от моей боли.",
    ["谢谢你，罗珊。"] = "Спасибо, Розанна.",
    ["谢谢您……但我想，我还是得把今天的活干完。拿到了钱，才能去看医生。这是最快的方法了。"] = "Спасибо вам... Но я думаю, мне все же нужно закончить сегодняшнюю работу. Только получив деньги, я смогу пойти к врачу. Это самый быстрый способ.",
    ["谢谢您的好意，我先告辞了！"] = "Благодарю за доброту, но мне пора откланяться!",
    ["谢谢您！要不是您，我简直不知道还会发生什么！"] = "Спасибо! Если бы не ты, я не знаю, что бы было!",
    ["谢谢您，魔术师{{先生|女士}}。"] = "Спасибо, Волшебник {{Mr.|Ms.}}.",
    ["谢谢警官，我平时其实很警觉，可面对艾德，就像被黄油遮蔽了心，非要帮他一把……现在只剩后悔，非常后悔。"] = "Спасибо, офицер. Обычно я очень насторожен, но когда я столкнулся с Эдом, мое сердце было покрыто маслом; Мне просто нужно было помочь ему... Теперь я чувствую только сожаление, глубокое сожаление.",
    ["谢谢！哦！我的戒……不对，这不是我的戒指！"] = "Спасибо! Ой! Мой ри... подожди, это не мое кольцо!",
    ["谢谢，我们没什么需要。"] = "Спасибо, нам ничего не нужно.",
    ["豪尔斯街……那里是不是有个挺有名的占卜俱乐部？ "] = "Хаулс-стрит... есть ли там знаменитый клуб гадания?",
    ["貌似没有什么实感？"] = "Кажется, у тебя нет никаких настоящих чувств?",
    ["贝儿小姐……难不成，你竟然有偷窥的癖好？"] = "Мисс Белль... может быть, у вас есть привычка подглядывать?",
    ["贝儿小姐！"] = "Мисс Белль!",
    ["贝儿小姐！是你在里面吗？"] = "Мисс Белль! Ты там?",
    ["贝儿小姐，你愿意……"] = "Мисс Белль, не могли бы вы...",
    ["贝儿小姐，你的意思是……？"] = "Мисс Белль, что вы имеете в виду...?",
    ["贝儿小姐，只要你做我的女人，你就能每天穿最贵的礼服，喝最好的红酒，安心在家做富太太。"] = "Мисс Белль, пока вы станете моей женщиной, вы сможете носить самые дорогие платья, пить лучшее красное вино и комфортно жить дома как богатая леди.",
    ["贝儿小姐，打开门吧，我刚才明明看见你走进去。"] = "Мисс Белль, откройте дверь, я же своими глазами видел, как вы только что вошли.",
    ["贝儿小姐，是你带给了我自由，这点头发又算什么。"] = "Мисс Белль, это вы принесли мне свободу. Что такое маленькие волосы по сравнению с этим?",
    ["贝儿小姐，现在你愿意做我的女人吗？"] = "Мисс Белль, вы теперь будете моей женщиной?",
    ["贝克因为抢劫被打了好几次，西莫还在警察局关着……"] = "Бейкера несколько раз избивали за грабежи, а Сеймур до сих пор заперт в полицейском участке...",
    ["贪财好利的骗子、腐蚀学术的蛀虫、玷污道德的渣滓！这些坏学生要是被我抓到，我一定要拿我的戒尺跟他好好握个手！"] = "Жадные мошенники, академические паразиты, моральные дегенераты! Если я поймаю этих плохих учеников, я обязательно пожму им руку своей линейкой!",
    ["费尔南先生，你曾在战争中当了逃兵，靠着背叛战友和上级获得了战功，但我找到了战争的幸存者，他将在议会上揭发这一切！"] = "Господин Фернан, вы были дезертиром на войне и полагались на предательство своих товарищей и начальства, чтобы получить военные заслуги, но я нашел человека, пережившего войну, и он разоблачит все это в парламенте!",
    ["费尔南先生，等等我——"] = "Господин Фернан, подождите меня...",
    ["资金充足时，这里可没有那么多垃圾。罗塞尔大帝在爱国卫生运动中做出的努力，全都白费了！"] = "Когда есть достаточное финансирование, здесь не так много мусора. Все усилия императора Розеллы, предпринятые в рамках Патриотической кампании за здоровье, пропали даром!",
    ["赞美丝瓜汤！"] = "Слава супу из люфы!",
    ["赞美女神！我的车终于保住了！"] = "Слава Леди! Моя карета наконец-то спасена!",
    ["赞美愚者！"] = "Слава Шуту!",
    ["赞美愚者！<P_Heart>（咦，我怎么也……）</>"] = "Слава Шуту! <P_Heart>(Подожди, а почему я тоже...)</>",
    ["赞美愚者！<P_Heart>（怎么又……）</>"] = "Слава Шуту! <P_Heart>(Почему опять...)</>",
