    ["这位卧底的祖宅，他偶尔往里面藏点货。"] = "Родовой дом агента под прикрытием. Иногда он прятал там какие-то товары.",
    ["这位就是“焦糖炸弹”的创始人谢尔敏先生，他带来了最新改良款饮料，大家一起尝尝吧！"] = "Это основатель компании «Карамельная бомба» господин Шермин. Он принес последнюю улучшенную версию напитка, давайте все попробуем!",
    ["这位达文西先生和这位{{先生|女士}}！"] = "Этот мистер Да Винчи и этот {{мистер|мисс}}!",
    ["这其中应该有什么奥秘……"] = "Наверное, в этом есть какая-то тайна...",
    ["这再明显不过了！这是一种征服！大帝站在凡人所能触及的顶峰，向神明发出宣言。"] = "Это не может быть более очевидным! Это завоевание! Император стоит на вершине, до которой могут добраться смертные, и обращается к богам с заявлением.",
    ["这几天有一个走私美人鱼的团伙经过廷根，教会想趁机剿灭他们。"] = "Эти дни через Тинген проезжает банда, промышляющая контрабандой русалок, и Церковь хочет воспользоваться случаем, чтобы уничтожить их.",
    ["这十四天里，你一直在帮一只乌鸦收集历史痕迹。所以，严格来说，我应该替乌鸦向你当面道个谢。"] = "Все эти четырнадцать дней вы помогали вороне собирать исторические следы. Так что, строго говоря, я должен поблагодарить вас от имени вороны лично.",
    ["这双鞋，想必是诅咒的源头了。"] = "Эта пара обуви, должно быть, является источником проклятия.",
    ["这句话……库克还在迪西海湾时，经常对一个小女孩说。"] = "Это предложение... Кук часто говорил его маленькой девочке, когда еще был в заливе Тиси.",
    ["这只是知识在扮演“你”。"] = "Это просто знание, действующее от имени «вы».",
    ["这只老鼠看起来要和猫打起来了……"] = "Эта мышь выглядит так, будто собирается сразиться с котом...",
    ["这听起来……不太像普通人该碰的东西。"] = "Это звучит... не похоже на то, к чему должен прикасаться обычный человек.",
    ["这和我当年吃到的芥末章鱼一样！也许真的是误会，库克没变。"] = "Это точно такой же осьминог васаби, который я тогда ел! Может быть, это действительно было недоразумение; Кук не изменился.",
    ["这城市烂透了。但总得有人去挖出这些烂肉——哪怕只剩我一个。"] = "Этот город прогнил до глубины души. Но кто-то должен выкопать эту гнилую плоть, даже если я остался один.",
    ["这声音是……"] = "Этот голос...",
    ["这太危险了，你到底惹到了谁？"] = "Это слишком опасно. Кому ты вообще перешёл дорогу?",
    ["这孩子……因为我看了他的日记，他就要这样惩罚自己吗？"] = "Этот мальчик... неужели он наказывает себя только за то, что я заглянул в его дневник?",
    ["这家伙是在看守这里的货吗？"] = "Этот парень охраняет здесь товар?",
    ["这家拍卖行的商品是……"] = "Предметы, представленные в этом аукционном доме,...",
    ["这家臭名昭著的餐厅，他们的招牌菜是……"] = "Фирменным блюдом этого знаменитого ресторана является...",
    ["这小家伙……浑身都湿透了。"] = "Этот малыш... он промок насквозь.",
    ["这小家伙，看起来饿坏了…… "] = "Этот малыш выглядит так, будто умирает от голода...",
    ["这就是宫殿！你懂吧？很华丽很大的那种。"] = "Это дворец! Ты знаешь? Действительно великолепный и огромный вид.",
    ["这就是我找你的原因，我听说你们处理过更棘手的事，你可以把这当作一种认可。"] = "Вот почему я пришел к вам. Я слышал, что ты решаешь более сложные дела. Вы можете воспринимать это как форму признания.",
    ["这就是炼钢工厂？"] = "Это сталелитейный завод?",
    ["这就是马西莫写的文章？居然占了《廷根市老实人报》一整个版面！"] = "Это статья, которую написал Массимо? Фактически, это заняло целую страницу «Честного человека Тингена»!",
    ["这应该就是卡门的身体了……卡门，你自己出得去吗？"] = "Это должно быть тело Кармен... Кармен, ты можешь выбраться сама?",
    ["这座庄园曾是我家族的荣耀所在，纵使如今已被岁月洗礼，依旧充满了迷人的魅力。若不是我的儿子欠下巨额赌债又重病缠身，我也不会以低价出售庄园。"] = "Когда-то это поместье было славой моей семьи. Несмотря на то, что он был вымыт временем, он по-прежнему полон очаровательной привлекательности. Если бы мой сын не имел огромного игрового долга и не был серьезно болен, я бы не продал поместье по низкой цене.",
    ["这怎么能一样……不过，知道连她都会收到退稿信，不知怎么的，反而觉得她更厉害了。 "] = "Как может быть то же самое... но, зная, что даже она получает письма с отказом, я почему-то чувствую, что она еще более удивительна.",
    ["这恐怕不行，我上次一出门就把楼下的威廉先生吓晕了，差点被警察抓走。"] = "Боюсь, это не сработает. В последний раз, когда я выходил на улицу, я напугал мистера Уильяма внизу до тех пор, пока он не потерял сознание, и меня чуть не поймала полиция.",
    ["这才哪到哪，等着瞧吧，接下来的剧情会更加劲爆！"] = "Это только начало, подождите и увидите, следующий сюжет будет еще более взрывным!",
    ["这把剪刀我用了十年了，非常好用，现在送给您。"] = "Я пользуюсь этими ножницами уже десять лет, и они очень полезны. Теперь я дарю их вам.",
    ["这把我要了。"] = "Я возьму это.",
    ["这招好。打不过就遛，遛到对方没力气，你就赢了。"] = "Этот ход хорош. Если вы не можете их победить, измотайте их; как только они исчерпаются, вы выиграете.",
    ["这是……一块香帕？"] = "Это... ароматный носовой платок?",
    ["这是一个连环杀手，从议院治安队跑出来的，手上有十多起命案了。"] = "Это серийный убийца, сбежавший из-под стражи парламентской полиции. На его счету больше десятка смертей.",
    ["这是一种绝对安全的仪式，即使失败也不会有任何人受伤，但我们的教授和警察先生不这么认为。"] = "Это абсолютно безопасный ритуал. Даже если это не удастся, никто не пострадает, но наш профессор и полицейские так не думают.",
    ["这是一起恶性模仿案件，造成了恶劣的影响。我们已将涉案人员缉拿归案，并通知餐厅经理道格拉斯返回廷根接受审查，请市民减少恐慌……"] = "Это порочный случай имитации, который имел плохие последствия. Мы арестовали причастного к делу человека и уведомили менеджера ресторана Дугласа, чтобы тот вернулся в Тинген для проверки. Мы просим граждан уменьшить панику...",
    ["这是什么东西！？"] = "Что это за штука!?",
    ["这是你们的……"] = "Это твой...",
    ["这是刚才的一位先生遗落的。"] = "Ранее это оставил джентльмен.",
    ["这是哪儿……好大的雾……"] = "Где это... столько тумана...",
    ["这是哪儿？"] = "Где это?",
    ["这是哪里……"] = "Где это я...",
    ["这是大事，得让我考虑考虑……"] = "Это большое дело, позвольте мне подумать...",
    ["这是大家都会有的想法，那么，是什么让你选择醒来？"] = "Такая мысль приходит всем. Так что же заставило тебя очнуться?",
    ["这是安魂诗社的邀请函。"] = "Это приглашение в Общество поэзии-реквиема.",
    ["这是怎么做的？丝瓜还能这么好吃！"] = "Как ты это сделал? Люфа действительно может быть такой вкусной!",
    ["这是总部给的调查报告，你可以先看看。"] = "Это отчёт о расследовании от штаб-квартиры, можешь пока ознакомиться.",
    ["这是我们今天的关键人物应得到的奖励。"] = "Это награда, которую заслуживает наша ключевая фигура дня.",
    ["这是我攒了一辈子的积蓄，足足有<P_Yellow>三百万金镑</>……"] = "Это сбережения всей моей жизни, полные <P_Yellow>три миллиона золотых фунтов</>...",
    ["这是我父亲表演用的帽子。小时候，他每次出门前，都会让我和母亲轮流戴一下这顶帽子。他说，这是表演前的准备。"] = "В этой шляпе мой отец выступал на выступлениях. Когда я был ребенком, прежде чем выйти на улицу, он разрешал нам с мамой по очереди носить эту шляпу. Он сказал, что это подготовка к выступлению.",
    ["这是我的戒指，我找了一天的戒指……在我放计划书的口袋里。"] = "Это мое кольцо, кольцо, которое я искал весь день... в кармане, где я храню свой блокнот.",
    ["这是我第一天出来叫卖，一个客人都没有。我该怎么回去跟父亲交差啊。"] = "Это мой первый день в разносе, и у меня не было ни одного покупателя. Как мне отчитаться перед отцом?",
    ["这是昂贵的黄金马桶，除了老爷，还有谁能用？"] = "Это дорогой золотой унитаз. Кроме хозяина, кто еще мог им воспользоваться?",
    ["这是根据《伯爵归来》改编的戏剧，但罗塞尔大帝的手稿有残缺的地方，导致这里缺少一句<P_Yellow>关键台词</>，只要能把它补全，演出一定就能继续。"] = "Это пьеса, адаптированная по мотивам «Возвращения графа», но в рукописи Императора Розеля есть пропуски, из-за чего здесь не хватает одной <P_Yellow>ключевой реплики</>. Если её восполнить, спектакль непременно продолжится.",
    ["这是正式的邀请函。若你愿意加入我们，便接下这封信。"] = "Это официальное приглашение. Если вы готовы присоединиться к нам, возьмите это письмо.",
    ["这是灵性预兆？伦纳德之前说过，你很特殊。"] = "Это духовное предзнаменование? Леонард уже говорил, что ты особенный.",
    ["这是献给勇敢者的专属料理。请慢用！"] = "Это блюдо, посвященное смелым. Пожалуйста, наслаждайтесь!",
    ["这是献给甜蜜伴侣的专属料理。请慢用！"] = "Это блюдо, посвященное сладким спутникам. Пожалуйста, наслаждайтесь!",
    ["这是种……很特别的疗法，似乎有效，只是需要一点点勇气。"] = "Это... весьма своеобразный метод лечения. Кажется, он действует, нужно лишь немного мужества.",
    ["这是秘制的丝瓜汤，不仅鲜美，还能去火气，调理身体呢！"] = "Это секретный суп из люфы. Это не только вкусно, но и помогает облегчить гнев и привести в порядок тело!",
    ["这是秘密。你用灵视检查时，我也用灵视看了你，非凡者！"] = "Это секрет. Когда ты проверил духовным зрением, я тоже посмотрел на тебя духовным зрением, Потусторонний!",
    ["这是积累功勋的好机会，你“无面人”的能力也很适合这次任务，就交给你处理吧。"] = "Это хорошая возможность накопить заслуги. Способности «Безликого» вам подходят для этого задания, так что поручаю его вам.",
    ["这是第几次了？！上次是玫瑰，上上次是蜡烛，这次又是什么？你以为自己是罗塞尔大帝写的情诗男主角吗？！"] = "Сколько раз это?! В прошлый раз это были розы, в прошлый раз — свечи, а что на этот раз? Думаешь, ты главный герой любовного романа, написанного императором Розеллой?!",
    ["这是非凡战斗，正面起冲突的话，很难保证普通人的生存。但里面还有人质，需要我们解救，时间太紧张了……"] = "Это битва Потусторонних: если вступить в прямое столкновение, выживание обычных людей гарантировать невозможно. Но внутри заложники, их нужно спасти, а времени в обрез...",
    ["这束花，是你的吗？"] = "Этот букет твой?",
    ["这条路上的一切，我都看得见呀，我没有摔倒过，也没有坠崖。"] = "Я вижу все на этой дороге; Я никогда не спотыкался и не падал со скалы.",
    ["这样吗？"] = "Так?",
    ["这样啊……那真是太好了……<P_Heart>（身形渐渐消散）</>不用为我难过，万物皆有尽头，我终于也能……回归大地的怀抱……"] = "Я вижу... Это действительно чудесно... <P_Heart>(Фигура постепенно рассеивается)</> Не грусти обо мне, всему есть конец, и я наконец смогу... вернуться в объятия Земли...",
    ["这样就足够了。"] = "Этого достаточно.",
    ["这样的人，整个廷根或许都找不到一个，就算有，谁会愿意放弃自己的头发呢？"] = "Такого человека могло не найтись во всем Тингене, а даже если бы и был, кто захотел бы отказаться от своих волос?",
    ["这样的话，官方或野生非凡者，都很容易锁定你。"] = "В этом случае официальные или дикие Потусторонние могут легко захватить вас.",
    ["这样的话，当你觉得冷的时候，就可以翻开它，让它温暖你的心。"] = "Таким образом, когда вам станет холодно, вы сможете открыть его и позволить ему согреть ваше сердце.",
    ["这样？"] = "Так?",
    ["这根本不重要。"] = "Это совсем не важно.",
    ["这桶黑啤酒我藏了三个月，就等着真英雄来开桶！"] = "Этот бочонок темного пива я прятал три месяца, дожидаясь истинного героя, чтобы распечатать его!",
    ["这棵树……我不记得了……你，你长得很像我儿子……"] = "Это дерево... Я не помню... Ты, ты очень похож на моего сына...",
    ["这次也不是意外，对吗？"] = "Это тоже не был несчастный случай, верно?",
    ["这次他们竟然连一便士都不留给我，太过分了……"] = "На этот раз мне не оставили даже ни копейки. Это слишком...",
    ["这次是我要上厕所。"] = "На этот раз мне нужно в туалет.",
    ["这次没有消失，让我仔细看看……"] = "На этот раз оно не исчезло, позвольте мне взглянуть поближе...",
    ["这次谁敢说话试试！"] = "Посмотрим, кто осмелится заговорить на этот раз!",
    ["这次非常简单，请您前往前方的椅子坐下……哦，请您小心一点！"] = "На этот раз все очень просто: подойдите к стулу впереди и сядьте... О, пожалуйста, будьте осторожны!",
    ["这段戏已经结束了，你怎么还沉浸在这里？醒醒，该下工了。"] = "Эта сцена уже закончилась, почему ты все еще в ней погружен? Просыпайтесь, пора выходить.",
    ["这段旋律并非我的创作，是多年前在贝克兰德偶然听到一个名叫特莉丝的甜美少女轻哼过。"] = "Эта мелодия написана не мной. Много лет назад в Бэкланде я случайно услышал, как её напевала одна милая девушка по имени Трисси.",
    ["这段时间，海岸线餐厅所有的菜都是我做的。这些年我几乎学会了库克每道菜的配比，要复刻不难。"] = "За это время все блюда в ресторане «Береговая линия» были приготовлены мной. За прошедшие годы я почти выучил пропорции каждого блюда, которое готовит Кук, поэтому повторить его нетрудно.",
    ["这段篇章叫做《夜访》。一位贵妇人的追求者，为了纪念自己被爱情俘获的时刻，采用《夜访》的旋律订制它作为礼物。"] = "Это произведение называется «Ночной визит». Жених дворянки заказал его в подарок, используя мелодию «Ночного визита», чтобы отметить момент, когда он был очарован любовью.",
    ["这片能抵御严寒的花也开得好，戴维每次都要摘几朵。"] = "Эти цветы, способные выдержать сильные холода, также хорошо цветут. Дэвид каждый раз выбирал несколько.",
    ["这瓶药不会也有副作用吧？"] = "У этой бутылки тоже нет побочных эффектов, не так ли?",
    ["这真的能骗过他们？"] = "Это правда сможет их обмануть?",
    ["这确实不是拉姆齐的作品。"] = "Это действительно не работа Рамзи.",
    ["这警局门口的氛围似乎有点紧张，发生了什么？"] = "У входа в полицейский участок обстановка кажется какой-то напряжённой. Что произошло?",
    ["这话之前问过一次了，不记得吗？"] = "Я уже спрашивал об этом однажды, ты не помнишь?",
    ["这都不算什么，我这半年每顿两颗，水煮的、煎的……现在别说看见鸡蛋，光是听到“蛋”这个字，我的胃就开始抽抽。"] = "Это ничего. Последние шесть месяцев я ел по две штуки в день: вареные, жареные... теперь, не говоря уже о том, чтобы увидеть яйцо, от одного только слова «яйцо» у меня сводит желудок.",
    ["这都是猎龙帮的秘密，不是什么人都有资格知道的。"] = "Это все секреты банды охотников на драконов; не каждый имеет право знать.",
    ["这里发生了什么事？你是怎么死的？"] = "Что здесь произошло? Как ты умер?",
    ["这里叫恶龙酒吧，我们就成立个猎龙帮！"] = "Это место называется «Бар «Злой Дракон»», давайте сформируем банду охотников на драконов!",
    ["这里就是你说的教堂？他是……"] = "И это та самая церковь, о которой ты говорил? А он...",
    ["这里就是霜陨领主的战场——作为入局者，平时你也可以来到这里，提前熟悉战场环境，占领演练。"] = "Здесь поле битвы Повелителя Падения Инея. Как участник игры, ты можешь приходить сюда в свободное время, чтобы заранее изучить обстановку на поле боя и потренироваться в захвате точек.",
    ["这里很危险！开膛手杰斯就在附近，你们快离开吧！"] = "Здесь опасно! Джейс Потрошитель рядом, пожалуйста, уходите сейчас же!",
    ["这里得小心，有块深红巨石挡路，从旁边绕过去。"] = "Будьте осторожны, путь преграждает темно-красный валун. Обойдите его.",
    ["这里怎么会躲着一个狼人？"] = "Как здесь мог прятаться оборотень?",
    ["这里是……一个梦境？它是用来装什么的？"] = "Это... сновидение? И для чего оно предназначено?",
    ["这里是……黑荆棘？"] = "Это... Чёрные Тернии?",
    ["这里是廷根最大的书店，许多学生会来购买书籍。"] = "Это крупнейший книжный магазин в Тингене, и многие студенты приходят сюда за книгами.",
    ["这里是有什么活动吗？"] = "Есть ли здесь какое-то событие?",
    ["这里的剧本空缺应该填什么呢？该让剧情怎么发展呢？"] = "Что мне заполнить на вакансию в сценарии здесь? Как должен развиваться сюжет?",
    ["这里的风景真好，当年出差到这里，才侥幸躲过了那场大雾霾的灾难，也遇见了你。"] = "Пейзажи здесь действительно хороши. Только потому, что я был здесь в командировке, я, к счастью, избежал катастрофы, вызванной великим смогом, а также встретил вас.",
    ["这里还算隐蔽，视野也很清晰，就在这儿埋伏吧。"] = "Место это довольно скрытное, и обзор чистый, устроим здесь засаду.",
    ["这里进出的货我都熟，唯独没见过这些，多半就是那些子弹了。"] = "Я знаком со всеми товарами, которые приходят и уходят отсюда, но никогда не видел их. Скорее всего, это те самые пули.",
    ["这需要勇气。直面死亡，拥抱黑暗，守护秘密……这些并不容易。"] = "Это требует мужества. Столкнуться со смертью, принять тьму, охранять тайны... это непросто.",
    ["这顶帽子很重要吧？"] = "Эта шляпа очень важна, не так ли?",
    ["这顶帽子是他亲手给我做的，我们还约好等他回来，要重新做一顶呢。"] = "Эту шапку он сшил для меня, и мы даже пообещали, что, когда он вернется, сделаем новую.",
    ["这顶帽子是我母亲亲手做的。我们家的食物、欢笑，还有那些好日子，都是从这顶帽子里变出来的。"] = "Эту шляпу сшила своими руками моя мама. Вся еда, весь смех и все счастливые дни нашей семьи были сотворены словно фокус из этой самой шляпы.",
    ["这，这些老板都没跟我说过……他只叫我送棺材出城，然后对外宣布已经火葬。"] = "Э-это... Хозяин мне ничего такого не говорил... Он только велел вывезти гроб из города и объявить, что тело кремировано.",
    ["进入对方大脑"] = "Войдите в мозг собеседника",
    ["进入盥洗室没多久，他就离开了。我们找遍了宅邸，也没有发现他的踪迹。"] = "Он ушел вскоре после того, как вошел в туалет. Мы обыскали весь особняк, но не смогли найти никаких его следов.",
    ["进去看看，到底是哪里的老鼠在搞鬼。"] = "Пойдём глянем, что за крысы здесь пакостят.",
    ["进来吧，我保证你也会爱上这种“危险”。"] = "Заходите, гарантирую, вы тоже влюбитесь в такую ​​«опасность».",
    ["违禁物品，一概拒绝！不信的话，你随便看！"] = "Контрабанда категорически запрещена! Если вы мне не верите, смело смотрите!",
    ["连环杀手“剥面人”强尼忽然发出了令人胆寒的啸叫。"] = "Серийный убийца «Face-Ripper» Джонни внезапно издает леденящий душу вой.",
    ["连环杀手？"] = "Серийный убийца?",
    ["连续好几篇罗塞尔大帝的报道了，我都要开始怀疑《廷根市老实人报》被因蒂斯暗中收购了……"] = "Это несколько репортажей об императоре Розелле подряд. Я начинаю подозревать, что «Газета честного человека Тингена» была тайно приобретена Интисом...",
    ["退婚流真是网文界的伟大发明，用它来魔改《基督山伯爵》的开头再合适不过了。"] = "Образ «разорванной помолвки» — действительно великое изобретение в мире веб-романов. Он идеально подходит для изменения начала «Графа Монте-Кристо».",
    ["逃走了？哼，她果然另有目的。"] = "Сбежал? Хм, у нее действительно были другие мотивы.",
    ["选在书店见面，还真文雅……把礼物摆好吧。"] = "Встреча в книжном магазине — это довольно элегантно... давайте разложим подарки.",
    ["选项"] = "Параметры",
    ["通过马桶，就能进入知识空间……"] = "Через унитаз можно попасть в Пространство Знаний...",
    ["速度好快，完全看不清从哪里冒出来的……"] = "Так быстро, что я даже не вижу, откуда она выскочила...",
    ["逮捕我，请问这是为什么？我从未有过任何违背法律的行径。"] = "Меня арестовывают? Могу я спросить, почему? Я никогда не совершал никаких действий, противоречащих закону.",
    ["道奇，你怎么样？你还好吗？"] = "Додж, как ты? Ты в порядке?",
    ["道奇，我理解你必须拿到这笔钱。但就这样让你进去还是太危险了，你们平时是怎么做的？"] = "Додж, я понимаю, что ты должен получить эти деньги. Но все равно слишком опасно впускать тебя вот так. Как вы обычно это делаете?",
    ["道奇，没事了，你们不会再受到雷克斯的威胁了。"] = "Додж, теперь все в порядке. Рекс больше не будет угрожать тебе.",
    ["遗产？"] = "Наследование?",
    ["遵命，警官。"] = "Слушаюсь, офицер.",
    ["邀人品尝美食永远都不会麻烦！而且真正的美食是有“花期”的，让更多人在花期内品尝是我的荣幸。"] = "Пригласить людей попробовать вкусную еду – никогда не проблема! А у настоящих деликатесов есть «период цветения», и для меня большая честь позволить большему количеству людей попробовать их в этот период.",
    ["那、那个是？！"] = "Ч-что это такое?!",
    ["那不是很好吗？"] = "Разве это не здорово?",
    ["那么请好好解释，不然明天我主编的桌上会摆着一份全新的评论稿！"] = "Тогда объяснитесь, пожалуйста, внятно, а то завтра у моего главного редактора на столе окажется новенький черновик рецензии!",
    ["那也比一辈子困在码头上强！至少那些水手们、海盗们见识过真正的海上传奇！"] = "Это всё равно лучше, чем застрять в доках на всю жизнь! По крайней мере, эти моряки и пираты стали свидетелями настоящих морских легенд!",
    ["那会影响老师以后的创作吗？剧团里的演员还等着排练呢。"] = "Повлияет ли это на дальнейшее творчество учителя? Актеры в труппе все еще ждут репетиции.",
    ["那你去找吧，找到我失踪很久的结婚戒指，找到了就给你。"] = "Ну так ищи: найди моё давно пропавшее обручальное кольцо, найдёшь — оно твоё.",
    ["那你呢，你也会爱上我吗？"] = "А вы? Ты тоже влюбишься в меня?",
    ["那你呢？你也会长大。"] = "А вы? Ты тоже вырастешь.",
    ["那你怎么会来到海岸线餐厅，还和茜安合作？"] = "Так как же вы пришли в ресторан Coastline и начали сотрудничать с Qian’an?",
    ["那你是谁？"] = "Так кто ты?",
    ["那你说怎么办？"] = "И что ты предлагаешь?",
    ["那倒也是。"] = "Это тоже правда.",
    ["那又如何，我记得生前的一切，还能继续经营书店，和知识打交道。"] = "Ну и что? Я помню все, что было до моей смерти, и могу продолжать управлять книжным магазином и заниматься знаниями.",
    ["那只是表面，实际上，他是猎龙帮的缔造者，也是第一位老大。"] = "Это только на поверхности. На самом деле он основатель банды охотников на драконов, а также первый босс.",
    ["那只章鱼，你也看到了？"] = "Этот осьминог, ты тоже его видел?",
    ["那名黑裙女士已经离开了。"] = "Дама в черном платье уже ушла.",
    ["那块太阳很轻，就像一片羽毛的重量，但却点亮了她的整个梦。"] = "Этот кусочек солнца был очень легким, как перышко, но освещал весь ее сон.",
    ["那天我刚播下种子，知识教会的人就来偷袭了……后勤只有我一个人，所以……"] = "В тот день я только посеял семена, когда люди из Церкви Знания начали скрытую атаку... Я был единственным в логистике, так что...",
    ["那好吧。"] = "Хорошо, тогда.",
    ["那就别计划了，天气好就晒太阳，下雨就睡懒觉，明天的事明天再说。"] = "Тогда прекратите планировать. Если погода хорошая, погрейтесь на солнышке; если идет дождь, спи. Завтрашние заботы оставь на завтра.",
    ["那就好，可以进行下一步了。"] = "Хорошо, можно переходить к следующему шагу.",
    ["那就拍吧……虽然面对镜头总会让我有点不自在。不过你来拍的话，我好像能放松一些——这种时候，总得有个可信赖的人在场。"] = "Тогда возьми... хотя перед камерой мне всегда немного некомфортно. Но если это ты принимаешь его, я, кажется, могу немного расслабиться — в такие моменты должен быть кто-то заслуживающий доверия.",
    ["那就拿起武器，跟上我，去战斗！"] = "Тогда бери свое оружие, следуй за мной и сражайся!",
    ["那就用你的方式，继续“打扫”下去。别让这座城市变得过于“安静”了。"] = "Тогда продолжай «уборку» своим методом. Не позволяй этому городу стать слишком «тихим».",
    ["那就要看谢尔敏先生愿不愿意继续优化配方了……"] = "Все зависит от того, согласится ли мистер Шермин и дальше улучшать рецептуру...",
    ["那座雕像……已经很残破了，甚至缺少一些部件。"] = "Эта статуя... уже сильно сломана, и даже не хватает некоторых частей.",
    ["那当然，这是戴里克主教大人给我布置的任务，编写《愚者圣典》的新章节。"] = "Конечно, епископ Деррик поручил мне написать новую главу «Книги Шута».",
    ["那怎么不进去？"] = "Тогда почему бы тебе не войти?",
    ["那我们先走一步……祝您好运！"] = "Тогда мы пойдём первыми... Удачи вам!",
    ["那我们几个就不打扰你了，有空一起喝酒啊！"] = "Тогда мы больше не будем вас беспокоить. Давайте выпьем вместе, когда у вас будет время!",
    ["那我们暂且在这里停驻片刻。 "] = "Тогда давайте остановимся здесь на мгновение.",
    ["那我就再说一遍——你们猎龙帮，惹到我了。"] = "Тогда я скажу это еще раз: вы, банда охотников на драконов, вы меня спровоцировали.",
    ["那我来帮你起个名字——"] = "Тогда позволь мне дать тебе имя —",
    ["那我要开始表演了！"] = "Тогда я начну представление!",
    ["那我要开始讲啦……从前，有一个住在黑夜里的小女孩。"] = "Тогда я начну рассказывать... Жила-была маленькая девочка, которая жила в темной ночи.",
    ["那我该怎么做？"] = "И что мне делать?",
    ["那我该怎么申请呢，队长？"] = "И как мне подать заявку, капитан?",
    ["那我还是躺回去吧，省得被发现……麻烦帮我把盖子盖上。"] = "Тогда лучше я лягу обратно, чтобы меня не нашли... Помогите, пожалуйста, закрыть крышку.",
    ["那是——罗塞尔大帝的影像！"] = "Это — образ императора Розеллы!",
    ["那是……我父亲的承诺。"] = "Это... обещание моего отца.",
    ["那是一笔不小的数额，在他看来，严重拖累了廷根经济。"] = "Это была немалая сумма, которая, по его мнению, тяжким бременем ложилась на экономику Тингена.",
    ["那是家传戒指！父亲规定，我二十五岁还没用它求婚成功就无法继承家业，可我明天就二十五岁了！"] = "Это семейное кольцо! Отец поставил условие, что если я не сделаю успешное предложение к двадцати пяти годам, я не смогу унаследовать семейный бизнес, а завтра мне исполнится двадцать пять!",
    ["那是我奶奶！她可厉害了，种出了鲁恩最大的南瓜！我们家的南瓜园是全金秋湖最出名的哦！  "] = "Это моя бабушка! Она была потрясающей; она вырастила самые большие тыквы в Лоене! Тыквенная грядка нашей семьи – самая известная на всем озере Золотой Осени!",
    ["那是白天的我，清醒的我，克制的我。但现在……酒精让我诚实。夜晚的我想要别的东西。"] = "Это был я дневного времени, я трезвый, сдержанный. Но теперь... алкоголь делает меня честным. Я ночи хочет чего-то другого.",
    ["那是马西莫对食物的态度足够严谨！"] = "Вот такое строгое отношение Массимо к еде!",
    ["那样幽深的地方，吸引我的目光……上厕所……要用……马桶……"] = "Такое глубокое, темное место, оно притягивает мой взгляд... иду в ванную... надо в туалет...",
    ["那真是太好了，咖啡师先生那边有很多糕点，可以随意挑选。"] = "Это было бы замечательно. У бариста много выпечки; смело выбирайте все, что вам нравится.",
    ["那群猎杀学徒的黑帮，我会把他们全部消灭！"] = "Что касается этой банды, охотящейся на учеников, я уничтожу их всех!",
    ["那肯定！不然泼天的富贵可就便宜他那位小情人了。"] = "Это точно! В противном случае это огромное состояние просто досталось бы его маленькой хозяйке.",
    ["那要从费内波特开始说起了。让老身想想……有个来采风的学者提到过，叫“背誓之战”……"] = "Это восходит к Фенепорту. Дай подумать... О ней упомянул учёный, приехавший собирать народные обычаи, назвав её «Войной нарушенных клятв»…",
    ["那边有个松鼠窝，走吧。"] = "Там беличье гнездо, пойдем.",
    ["那边？什么情况？"] = "Вон там? Что происходит?",
    ["那里发生的一切，<P_Yellow>都不会对现实造成直接的影响</>。"] = "Все, что там происходит, <P_Yellow>не окажет прямого влияния на реальность</>.",
    ["那里面可不是睡觉的好地方。"] = "Там вовсе не подходящее место для сна.",
    ["那，我们先回黑荆棘吧。"] = "Тогда давайте сначала вернемся в Чёрный Чертополох.",
    ["邮筒居然说话了？！"] = "Почтовый ящик действительно заговорил?!",
    ["都不许动！警察办案！"] = "Никому не двигаться! Полицейское расследование!",
    ["醒了？感觉还好吗？"] = "Очнулись? Как самочувствие?",
    ["里奥先生，我找到了休伯特贪污的证据！"] = "Мистер Лео, я нашел доказательства Искажения Хьюберта!",
    ["里面到底在干什么……听起来不太正常。"] = "Что, черт возьми, они там делают... Это звучит ненормально.",
    ["里面还有各种高密级的文献典籍副本，阅读需要一定的权限。另外，在查尼斯门的底层，还保管着一些封印物。 "] = "Внутри также находятся копии различных документов высокого уровня и классики, и для их чтения требуется определенный уровень полномочий. Кроме того, у подножия Врат Чаниса хранится несколько запечатанных артефактов.",
    ["重要公告？"] = "Важное объявление?",
    ["野生非凡者确实需要监管，但我不会带走你。"] = "Дикие Потусторонние нуждаются в присмотре, но я вас не заберу.",
    ["钱放好了，内部资料呢？"] = "Деньги размещены, а где инсайдерские материалы?",
    ["长大不是好事吗？可以做的工作更多了，能赚更多的钱。"] = "Разве взросление — это не хорошо? Вы сможете больше работать и зарабатывать больше денег.",
    ["阅读它，若你心中没有畏惧，那么我们会在午夜的钟声中等待你。愿黑夜庇护你。"] = "Прочитайте это; если у тебя нет страха в сердце, то мы будем ждать тебя при звоне полуночного колокола. Пусть Вечная Ночь защитит тебя.",
    ["队长，你刚刚在通灵？"] = "Капитан, вы только что выполняли Spirit Mediumship?",
    ["队长，打扰一下。玛尔莎和她弟弟想感谢您之前的帮助，这是他们的心意。 "] = "Капитан, извините за беспокойство. Марта и ее брат хотят поблагодарить вас за вашу предыдущую помощь. Это их чувства.",
    ["队长，给你准备的咖啡。另外，廷根警察厅最新的案件档案已经送过来了。"] = "Капитан, вот кофе, который вы просили. Также были доставлены последние материалы дела из полицейского управления Тингена.",
    ["阴暗逼仄的牢房之中，他失去了与外界的所有联系。"] = "В темной и тесной камере он потерял всякую связь с внешним миром.",
    ["阿罗德斯回答1"] = "Арродес Ответ 1",
    ["阿罗德斯回答2"] = "Арродес Ответ 2",
    ["阿罗德斯表现事件段1"] = "Событие Арродес, период 1",
    ["阿罗德斯表现事件段2"] = "Период события Арродес 2",
    ["阿罗德斯表现事件段3"] = "Арродес, период события 3",
    ["阿罗德斯表现时间段"] = "Период сцеживания Арродеса",
    ["阿罗德斯表现时间段1"] = "Арродес, период экспрессии 1",
    ["阿罗德斯表现时间段2"] = "Арродес, период сцеживания 2",
    ["阿罗德斯表现时间段3"] = "Арродес, период сцеживания 3",
    ["阿罗德斯问问题"] = "Арродес задает вопрос",
    ["阿里安娜女士？"] = "Мисс Арианна?",
    ["陛……陛下？"] = "Ваше... Ваше Величество?",
    ["陛下，你已经如此完美了……但您的请求，我都会为您完成，我将为您召唤神秘之镜——"] = "Ваше Величество, вы уже настолько совершенны... Но я выполню все ваши просьбы. Я призову для тебя Зеркало Тайны —",
    ["陛下，您来得比我预想的要快。"] = "Ваше Величество, вы прибыли быстрее, чем я ожидал.",
    ["陛下，您难得便装出巡，是这次的艺术展览不合心意吗？"] = "Ваше Величество, вы редко выходите на улицу в штатском. Художественная выставка на этот раз вам не понравилась?",
    ["陛下，您需要提提神吗？这里有一瓶醒神花露。"] = "Ваше Величество, вам нужно освежиться? Вот бутылка освежающей цветочной росы.",
    ["陛下？"] = "Ваше величество?",
    ["陛下？你在叫我？ "] = "Ваше Величество? Ты звонишь мне?",
    ["陷害？好……那交给我吧！保证及时送到。"] = "В рамке? Хорошо... тогда оставь это мне! Я гарантирую, что он будет доставлен вовремя.",
    ["隐匿贤者的知识灌输……不行，这会撕碎我的大脑，我需要“愚者”先生的帮助！"] = "Вливание знаний Скрытого Мудреца... Нет, это разорвет мой мозг на части. Мне нужна помощь  Шута!",
    ["难以想象！从铁十字街到列车站，只要十分钟！"] = "Это невообразимо! От Айрон-Кросс-стрит до железнодорожного вокзала всего десять минут!",
    ["难以置信，她们两个居然齐心协力甩了山姆，离开了廷根？"] = "Невероятно, но они действительно работали вместе, чтобы бросить Сэма и покинуть Тинген?",
    ["难怪你这么漂亮，让所有男人都疯狂地爱上了你。"] = "Неудивительно, что ты такая красивая, что заставляешь всех мужчин безумно влюбляться в тебя.",
    ["难道你就是消失在切斯庄园的……"] = "Может быть, это ты пропал в Чесс-Мэноре...",
    ["难道您想……解决带来问题的饮料？不可以！虽然它让我们腹泻，但是——"] = "Только не говори мне, что хочешь... решить проблему с выпивкой? Нет! Хоть это и вызывает у нас понос, но...",
    ["难道我真的看不见了？十几年前医生就说我瞎了，可我没瞎呀。"] = "Может быть, я действительно ничего не вижу? Доктор сказал, что я был слеп более дюжины лет назад, но я не слепой.",
    ["难道是我弹得太糟糕……"] = "Может быть я слишком плохо сыграл...",
    ["难道是非凡者死后，与周围的书结合形成的<P_Yellow>非凡物品</>？看来需要进行封印。"] = "Может ли это быть мистический предмет <P_Yellow> </>, образованный сочетанием Потустороннего после смерти и окружающих книг? Кажется, его нужно запечатать.",
    ["难道，今天的经历预示着我要从无尽计划中解脱？也对，我得和海蒂谈谈，还有父亲……但现在有更重要的事……"] = "Может быть, сегодняшний опыт означает мое освобождение от бесконечного плана? Да, мне нужно поговорить с Хайди и отцом... но сейчас есть дела поважнее...",
    ["雷、雷克斯先生，我……我都做完了。"] = "Мистер Рекс, я... я все закончил.",
    ["雷克斯先生！求、求您了！我一个人真的干不了了……"] = "Мистер Рекс! П-пожалуйста! Я правда не смогу сделать это один...",
    ["雷克斯这样是违法的。离开他，你们可以去济贫院，或者教会，至少不会再挨打。"] = "То, что творит Рекс, противозаконно. Уйдите от него. Вы можете отправиться в работный дом или в церковь — там вас хотя бы перестанут избивать.",
    ["需要“星星”先生亲自处理的任务……一定很危险吧。"] = "Миссия, требующая личного выполнения мистером «Старом»… она, должно быть, очень опасна.",
    ["需要用罗塞尔大帝的思路来解决问题……用灵视找找线索吧。"] = "Чтобы решить проблему, нужно использовать образ мышления императора Розеллы... Давайте воспользуемся духовным зрением, чтобы найти подсказки.",
    ["霍纳奇斯的风雪，千年从未停止。当年四皇之战，曾有一位天使在此陨落，祂的力量化作有关战争的记忆碎片，至今散落山脉各处。"] = "Метель Хорнакиса не стихает уже тысячу лет. Во времена войны четырёх императоров здесь пал один Ангел. Его сила превратилась в осколки воспоминаний о войне, которые до сих пор разбросаны по горам.",
    ["静一静，静一静！各位亲爱的工友们，请听我说！"] = "Тише, тише! Дорогие товарищи рабочие, послушайте меня!",
    ["非凡者都要被登记监管，野生非凡者会被带走。"] = "Потусторонние должны быть зарегистрированы и находиться под наблюдением; дикие Потусторонние будут забраны.",
    ["非凡者？那是什么……我不是非凡者……"] = "Потусторонний? Что это... Я не Потусторонний...",
    ["非凡途径又称神之途径，序列4之上步入半神阶段，就能一定程度上展现神话形态。 "] = "Потусторонние пути также известны как божественные пути; как только вы перейдете на стадию полубога выше эпизода 4, вы сможете в определенной степени отобразить мифическую форму.",
    ["非常温暖的故事，我也写完了。"] = "Очень теплая история, я тоже закончила ее писать.",
    ["靠你了，我……已经没有力气了……"] = "Решать тебе, у меня... сил не осталось...",
    ["靠近和使用告解室的人都会不自觉被小道消息吸引，并主动地传播绯闻闲话。时间久了会失眠多梦、精神衰弱，精力不集中，容易出门撞到脑袋。"] = "Любой, кто приближается или пользуется исповедальней, будет неосознанно склонен к сплетням и активно распространять слухи. Со временем они начнут страдать от бессонницы, ночных кошмаров, неврастении, недостатка концентрации и склонны биться головой при выходе из дома.",
    ["音乐声？您还记得它是怎样的吗？"] = "Музыка? Вы еще помните, каково это?",
    ["顺带一提，我交易到的是一份“戏法大师”的配方，如果你愿意帮我，我就把配方告诉你。"] = "Между прочим, я обменял на формулу «Мастера трюков». Если вы готовы мне помочь, я расскажу вам формулу.",
    ["顺路。"] = "Это уже в пути.",
    ["顾客反映太甜腻，可以少加一些……"] = "Посетители жалуются, что слишком приторно, можно класть поменьше...",
    ["顾客希望饮料不会让人腹泻，可以减少这样东西的比例……"] = "Покупатель надеется, что напиток не вызовет диарею, поэтому мы можем уменьшить долю этого ингредиента...",
    ["颜色、材质与配饰的平衡恰到好处，这份审美可不常见。"] = "Баланс цвета, материала и аксессуаров правильный; эта эстетика довольно редка.",
    ["风暴庇佑，我已拥有了无穷无尽的财富和智慧。"] = "Да благословит меня Буря, я уже обладаю бесконечным богатством и мудростью.",
    ["风波平息后，我们回廷根到处打听，<P_Heart>（叹气）</>可他就像蒸发了一样……"] = "После того, как буря утихла, мы вернулись в Тинген, чтобы поспрашивать повсюду, <P_Heart> (вздыхает) </>, но он был словно испарился...",
    ["首先，占用一下你的时间，听我讲一讲我们的道标和救主……"] = "Во-первых, уделите немного времени и послушайте, как я говорю о нашем маяке и спасителе...",
    ["马丁。"] = "Мартин.",
    ["马丁走到家门口，回头看了一眼。路灯下，那个心理医生已经转身走了。他忽然觉得，今晚好像没那么难熬了。"] = "Мартин подошел к входной двери и оглянулся. Под фонарем психиатр уже повернулся и ушел. Он вдруг почувствовал, что сегодняшнюю ночь, возможно, будет не так уж трудно вынести.",
    ["马丁，那天的事不是你的错。你救不了他，但你记得他。这够了。"] = "Мартин, то, что произошло в тот день, не твоя вина. Ты не смог его спасти, но ты помнишь его. Этого достаточно.",
    ["马上就来。"] = "Сию минуту.",
    ["马桶无法抽水，应该是堵住了。"] = "Туалет не смывает воду; он должен быть забит.",
    ["马桶是什么时候故障的？"] = "Когда туалет вышел из строя?",
    ["马桶里传来呓语，维修工神秘失踪……呓语的源头一定就在知识空间内，找到源头物品，就能破除空间！"] = "Из унитаза доносится бредовый шепот, слесарь таинственно исчез... Источник шепота наверняка находится внутри пространства знаний. Найдите источник, и пространство рассеется!",
    ["马西莫冲出餐厅，外面传来呕吐声。"] = "Массимо выбегает из ресторана, и снаружи доносится звук рвоты.",
    ["马西莫女士！好久不见，你不是去利蒙了吗？"] = "Мисс Массимо! Давно не виделись, ты не был в Лимоне?",
    ["马西莫女士，借一步说话。"] = "Мисс Массимо, пожалуйста, пару слов.",
    ["马西莫女士，我过去看看。"] = "Мисс Массимо, я приду и посмотрю.",
    ["马西莫文笔毒辣，但敢于捍卫舌尖上的信念。若是让她发现我已经没有烹饪的能力……"] = "Сочинения Массимо порочны, но она осмеливается защищать свои убеждения относительно вкуса. Если она обнаружит, что я больше не умею готовить...",
    ["马西莫是那个小女孩！"] = "Массимо — вот эта маленькая девочка!",
    ["马西莫的嘴又刁又毒，她骂过的厨师能排到东拜朗，你说呢？"] = "Язык Массимо острый и ядовитый; повара, которых она отругала, могли бы выстроиться в очередь в Восточный Балам, как вы думаете?",
    ["马西莫的文章影响力真是惊人。"] = "Статья Массимо имеет потрясающее влияние.",
    ["马西莫说，两个人做菜，味道的确没受影响。但她希望你记得自己曾经说过的话“人们至少要在美食面前保持诚实”。"] = "Массимо сказал, что на вкус действительно не повлияло приготовление вдвоем. Но она надеется, что вы помните, что однажды сказали: «Люди должны быть честными, по крайней мере, в отношении еды».",
    ["马西莫走了。"] = "Массимо ушел.",
    ["马西莫，有些不对劲，库克的状态，厨房的情况，他的解释……都不太对劲。"] = "Массимо, здесь что-то не так. Состояние Кука, обстановка на кухне, его оправдания... все это очень подозрительно.",
    ["马西莫？那个以嘴毒闻名的美食家？她怎么可能写文章夸别人？"] = "Массимо? Тот гурман, известный своим ядовитым языком? Да разве она станет писать статью, хваля кого-то?",
    ["高处的热气球缓缓降落。"] = "Воздушный шар с высоты медленно опускается.",
    ["高踞马桶圣座的神秘之尊。"] = "Таинственное величие восседало на сиденье унитаза.",
    ["鬼魂？说到这个，门外的人似乎对鬼魂也有些抵触，距离三点钟还有点时间……我倒是有个办法。"] = "Призраки? Кстати, человек за Дверью, похоже, тоже недолюбливает призраков, а до трёх часов ещё есть время... У меня есть одна идея.",
    ["魔女途径的非凡者么……我会让人调查的。你做得很好。 "] = "Путь Потустороннего ведьмы... Я попрошу кого-нибудь провести расследование. Ты хорошо справился.",
    ["魔女预备役怎么不算魔女呢？"] = "Чем обучающаяся ведьма не ведьма?",
    ["魔法？不是没有可能……她有固定工作地点吗？"] = "Магия? Это не невозможно... У нее есть постоянное место работы?",
    ["鲁伯特男爵根本没有生育能力他的儿子女儿私生子都不是自己的孩子！"] = "Барон Руперт бесплоден, его сыновья, дочери и внебрачные дети не принадлежат ему!",
    ["鲁本把自己锁在里面，已经一刻钟了！他有怕黑的毛病，再这样下去会喘不上气的！"] = "Рубен заперся дома четверть часа назад! Он боится темноты; если так будет продолжаться, он не сможет дышать!",
    ["鲁本等这句话很久了呢。"] = "Рубен давно ждал этих слов.",
    ["鲁本！我的孩子，你没事吧？"] = "Рубен! Дитя мое, с тобой все в порядке?",
    ["鲁本，你……"] = "Рубен, ты...",
    ["鲁本？你还好吗？"] = "Рубен? Ты в порядке?",
    ["鸽子在魔术师的帽子里。还有六只没放出来。六只！我都数着呢。"] = "Голубь в шляпе Волшебника. Есть еще шесть, которые не были опубликованы. Шесть! Я считал.",
    ["黄水晶吊坠停在那里，一动不动。\n……占卜受到了影响，无法获得结果……"] = "Цитриновый кулон стоял неподвижно. \n…На гадание влияет и результаты не могут быть получены…",
    ["黄水晶吊坠逆时针转动，速度很快。\n……答案是十分强烈的否定……"] = "Маятник из желтого топаза стремительно закружился против часовой стрелки.\n...Ответ — категорическое «нет»...",
    ["黄水晶吊坠逆时针转动，速度很慢。\n……答案是否定……"] = "Кулон с цитрином очень медленно вращается против часовой стрелки. \n…Ответ — нет…",
    ["黄水晶吊坠顺时针转动，速度很快。\n……答案是十分强烈的肯定……"] = "Кулон с цитрином вращается по часовой стрелке и очень быстро. \n…Ответ – однозначно да…",
    ["黄水晶吊坠顺时针转动，速度很慢。\n……答案是肯定……"] = "Маятник из жёлтого топаза медленно вращается по часовой стрелке.\n...Ответ положительный...",
    ["黄色结实耐骑，齿轮传动特别顺畅，经得起工厂区那些石板路颠簸。蒸汽与机械之神教会的工匠亲自监制，质量最有保证！"] = "Желтый, прочный и удобный в управлении, коробка передач особенно плавна и выдерживает неровности каменных дорог в заводском районе. Качество гарантировано под контролем мастеров церкви Бога пара и машин!",
    ["黑夜女神。祂的祝福能让这件武器承载真正的神话形态。"] = "Богиня Вечной Ночи. Её благословение позволяет этому оружию обрести истинную мифическую форму.",
    ["黑漆漆怪吓人的，“星星”先生，这里是？"] = "Тут жутко темно и страшновато. Господин «Звезда», где это мы?",
    ["鼓手！我听不见你的鼓点！把声音加大！"] = "Барабанщик! Я не слышу твоего ритма! Играй громче!",
    ["鼻涕？！作为厨师居然在灶台留下鼻涕？"] = "Сопли?! Ты повар и посмел оставить сопли прямо на плите?!",
    ["龙的巢穴里有很多宝藏，如果能成功猎龙，我们就能成为英雄和大人物！"] = "В драконьем логове полно сокровищ: если мы одолеем дракона, то станем героями и важными шишками!",
    ["龙相关的传说可真多啊，这一条是猎龙城的……"] = "О драконах ходит много легенд. Это о Городе Охоты на Драконов...",
    ["（从门外传来）警官，老师的情况怎么样了？"] = "(Выходя из-за двери) Офицер, как учитель?",
    ["（低声嘀咕）丝瓜滞销，{{这位善良的先生|这位善良的女士}}，能不能帮帮我，拜托了。"] = "(Бормочет) Люфы не продаются, {{this kind sir|this kind madam}}, ты можешь мне помочь? Пожалуйста.",
    ["（再这样下去这些孩子就要吵起来了，得转移她们的注意力……）"] = "(Если так будет продолжаться, дети начнут спорить, мне придется их отвлекать...)",
    ["（历史迷雾中的那位穿越者前辈，他居然做了这么多事。）"] = "(Этот предшественник-переселенец из «Тумана истории» на самом деле сделал очень много вещей.)",
    ["（叫卖）自家种植，健康又卫生，便宜卖了！"] = "(Хокинг) Выращенные в домашних условиях, здоровые и гигиеничные, продаем дешево!",
